// Dismissal lives in the server session (not localStorage) so it clears itself on
// logout — session.destroy() wipes it — and reappears on the next fresh login even at
// the same balance, rather than staying silenced forever once closed once.
// Players app on the site (see the /app section): for a signed-in player who can use the
// app, site pages carry the app's home-screen tags, so whatever page they "Add to Home
// Screen" from, the icon opens /app — fans and guests keep plain site bookmarks. Launched
// from the home screen, a site page goes straight to /app; ?from=app (More → "Open full
// site") lets that window browse the site for the rest of the visit.
const APP_HOME_TAGS = `<link rel="manifest" href="/app/manifest.webmanifest">
  <meta name="apple-mobile-web-app-capable" content="yes">
  <meta name="mobile-web-app-capable" content="yes">
  <meta name="apple-mobile-web-app-title" content="WKND">
  <script>(function(){try{var sa=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;if(!sa)return;if(/[?&]from=app(&|$)/.test(location.search))sessionStorage.setItem('wknd-site','1');if(sessionStorage.getItem('wknd-site'))return;location.replace('/app');}catch(e){}})();</script>`;
// On a phone's browser: a slim bar pointing to the app (it opens the install steps there).
// Not shown inside the installed app (More → Open full site); closed for the visit with ✕.
function appUseBar() {
  return `<div class="balance-bar rf-bar" id="app-bar" hidden>
  <div class="balance-bar__inner">
    <span class="balance-bar__text"><span>📱 Use the <strong>WKND app</strong> for your games, team and stats.</span></span>
    <a href="/app" class="balance-bar__cta">Open the app</a>
    <button class="balance-bar__close" id="app-bar-close" type="button" aria-label="Dismiss">✕</button>
  </div>
</div>
<script>(function(){var b=document.getElementById('app-bar');try{if(sessionStorage.getItem('wknd-app-bar')||matchMedia('(display-mode: standalone)').matches||navigator.standalone===true)return;}catch(e){}b.hidden=false;
document.getElementById('app-bar-close').addEventListener('click',function(){b.remove();try{sessionStorage.setItem('wknd-app-bar','1');}catch(e){}});})();</script>`;
}

function balanceReminderBar(amount) {
  return `<div class="balance-bar" id="balance-bar" data-amount="${amount}">
  <div class="balance-bar__inner">
    <span class="balance-bar__text"><svg width="13" height="13" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="7" cy="7" r="6"/><path d="M7 4.2v3.3"/><circle cx="7" cy="9.8" r=".2" fill="currentColor"/></svg> You have an outstanding balance of <strong>₱${Number(amount).toLocaleString()}</strong>.</span>
    <a href="/settle-balance" class="balance-bar__cta">Settle now</a>
    <button class="balance-bar__close" id="balance-bar-close" type="button" aria-label="Dismiss">✕</button>
  </div>
</div>
<script>
(function() {
  var bar = document.getElementById('balance-bar');
  var closeBtn = document.getElementById('balance-bar-close');
  if (!bar || !closeBtn) return;
  closeBtn.addEventListener('click', function() {
    fetch('/balance-bar/dismiss', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount: Number(bar.dataset.amount) })
    }).catch(function() {});
    bar.style.display = 'none';
  });
})();
</script>`;
}

// Same dismiss-in-session pattern as balanceReminderBar — reappears on the next fresh
// login rather than being silenced forever. This is deliberately a *separate* bar/dismiss
// key from the balance one (not folded into it) since a player can be on probation with
// zero outstanding balance, and dismissing one shouldn't dismiss the other.
// Homepage strip for Rate & Win: "draw tonight" on draw day, the winner for 3 days after.
function raffleHomeBar() {
  if (!raffleOn()) return '';
  const raffle = ensureRateAndWin();
  if (raffle.status !== 'active') return '';
  const now = Date.now();
  const last = getLatestDrawnRound(raffle.id);
  const open = getOpenRound(raffle.id);
  const bar = (text, cta) => `<div class="balance-bar rf-bar"><div class="balance-bar__inner"><span class="balance-bar__text">${text}</span><a href="/raffle" class="balance-bar__cta">${cta}</a></div></div>`;
  if (last?.status === 'drawn' && now - last.drawn_at < 3 * 86400000) {
    const w = getWinnerForRound(last.id);
    return bar(`🎉 <strong>${escHtml(winnerName(w?.player_name, w?.hide_name))}</strong> won a free run in ${escHtml(raffle.name)} Round ${last.number}. ${last.players} players were in.`, 'Next draw →');
  }
  if (open && open.draws_at > now && new Date(open.draws_at + 8 * 3600000).toISOString().slice(0, 10) === manilaTodayStr()) {
    return bar(`🎟️ <strong>${escHtml(raffle.name)} draw tonight</strong> at ${new Date(open.draws_at).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZone: 'Asia/Manila' })}: a free Papawis run.`, 'Watch live →');
  }
  return '';
}

