function formatName(raw) {
  const parts = String(raw || '').split(',');
  return parts.length >= 2 ? `${parts[1].trim()} ${parts[0].trim()}` : String(raw || '');
}

function escXml(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function svgInitials(raw) {
  const parts = String(raw || '').split(',');
  const last  = (parts[0]?.trim() || '')[0] || '';
  const first = (parts[1]?.trim() || '')[0] || '';
  return (first + last).toUpperCase() || '?';
}

function buildShareAsOfLabel(share) {
  const targetSeason = (share.season === 'alltime' || !share.season)
    ? (getCurrentSeason()?.season ?? null)
    : share.season;
  if (!targetSeason) return { asOfLabel: '', asOfSeason: null, asOfWeek: null };
  const week = getSeasonLatestWeek(targetSeason)?.week ?? null;
  if (!week) return { asOfLabel: '', asOfSeason: targetSeason, asOfWeek: null };
  return {
    asOfLabel:  share.season === 'alltime' ? `THRU S${targetSeason} WK ${week}` : `THRU WK ${week}`,
    asOfSeason: targetSeason,
    asOfWeek:   week,
  };
}

// Mirrors derivePlayerOfTheGameFromState from the admin app.
// Operates on game_player_stats rows (snake_case, `turnover` not `to`).
function derivePotgPlayerId(game, gameStats) {
  if (!gameStats.length) return null;

  const scoreA = Number(game.team_a_score || 0);
  const scoreB = Number(game.team_b_score || 0);
  const winnerTeamId = scoreA === scoreB
    ? null
    : (scoreA > scoreB ? game.team_a_id : game.team_b_id);

  const eligible = gameStats.filter(s => !winnerTeamId || s.team_id === winnerTeamId);
  if (!eligible.length) return null;

  const perScore = (s) => {
    const fgMade = Number(s.fg2m || 0) + Number(s.fg3m || 0) + Number(s.fg4m || 0);
    const fgAtt  = fgMade + Number(s.fg2m_miss || 0) + Number(s.fg3m_miss || 0) + Number(s.fg4m_miss || 0);
    const ftMade = Number(s.ftm || 0);
    const ftAtt  = ftMade + Number(s.ft_miss || 0);
    return (
      Number(s.pts || 0) +
      (0.4 * fgMade) - (0.7 * fgAtt) - (0.4 * (ftAtt - ftMade)) +
      (0.7 * Number(s.reb || 0)) +
      Number(s.stl || 0) +
      (0.7 * Number(s.ast || 0)) +
      (0.7 * Number(s.blk || 0)) -
      (0.4 * Number(s.pf || 0)) -
      Number(s.turnover || 0)
    );
  };

  const maxPts = eligible.reduce((m, s) => Math.max(m, Number(s.pts || 0)), 0);

  let best = null;
  for (const s of eligible) {
    const score = perScore(s) + (Number(s.pts || 0) === maxPts && maxPts > 0 ? 1.25 : 0);
    if (!best || score > best.score || (score === best.score && Number(s.pts || 0) > Number(best.s.pts || 0))) {
      best = { s, score };
    }
  }
  return best?.s.player_id || null;
}

// The winning team's id, or null for a tie.
function winnerTeamIdOf(game) {
  const a = Number(game.team_a_score || 0), b = Number(game.team_b_score || 0);
  return a === b ? null : (a > b ? game.team_a_id : game.team_b_id);
}

// The game's Players of the Game: the POTG (manual pick, else derived), then the co-POTG
// when an admin picked one (winning team only, with a box score line). Every POTG reader goes
// through this — never manual_potg_player_id / co_potg_player_id directly.
function potgIdsFor(game, stats) {
  const main = game.manual_potg_player_id || derivePotgPlayerId(game, stats);
  if (!main) return [];
  const co = String(game.co_potg_player_id || '');
  const win = winnerTeamIdOf(game);
  const ok = co && co !== main && stats.some(s => s.player_id === co && (!win || s.team_id === win));
  return ok ? [main, co] : [main];
}

// A player's POTG writeup for a game: the main one, or the co-POTG's own.
function potgWriteupFor(game, playerId) {
  return playerId && playerId === game.co_potg_player_id ? (game.co_potg_writeup || '') : (game.potg_writeup || '');
}

function extractQuarterScores(game) {
  let log;
  try { log = JSON.parse(game.game_log_json || '[]'); } catch { log = []; }
  // Source 0: the scorer's "End Qn [WHI 36 - BLU 46]" markers — the score at the moment the
  // quarter was closed. A checkpoint can disagree (Oct 4 White–Blue Q2 checkpoint said 33–44;
  // the marker and the admin snapshot both say 36–46), so markers win where they exist.
  const ends = quarterMarkers(log, game);
  const fromMarkers = {};
  for (let q = 1, pa = 0, pb = 0; ends[q]; q++) {
    fromMarkers[q] = { a: ends[q].a - pa, b: ends[q].b - pb };
    pa = ends[q].a; pb = ends[q].b;
  }

  // Source 1: derive per-quarter pts from consecutive periodCheckpoint cumulative totals
  const checkpoints = log
    .filter(e => e.metaType === 'periodCheckpoint' && e.checkpointSnapshot)
    .sort((a, b) => Number(a.quarter) - Number(b.quarter));

  const fromLog = {};
  let prevCumA = 0, prevCumB = 0, prevQ = 0;
  for (const cp of checkpoints) {
    const q = Number(cp.quarter);
    const cumA = Number(cp.checkpointSnapshot.teamAScore || 0);
    const cumB = Number(cp.checkpointSnapshot.teamBScore || 0);
    if (q === prevQ + 1) fromLog[q] = { a: cumA - prevCumA, b: cumB - prevCumB };
    prevCumA = cumA;
    prevCumB = cumB;
    prevQ = q;
  }

  // Source 2: period_snapshots_json locked by admin (fill quarters missing from log)
  let snapshots;
  try { snapshots = JSON.parse(game.period_snapshots_json || '[]'); } catch { snapshots = []; }
  const fromSnaps = {};
  for (const s of snapshots) {
    const q = Number(s.quarter);
    fromSnaps[q] = {
      a: Number(s.quarterStats?.teamA?.pts ?? 0),
      b: Number(s.quarterStats?.teamB?.pts ?? 0),
    };
  }

  const allQs = new Set([...Object.keys(fromMarkers), ...Object.keys(fromLog), ...Object.keys(fromSnaps)].map(Number));
  const maxQ = Math.max(4, ...allQs, 0);

  const scores = [];
  for (let q = 1; q <= maxQ; q++) {
    const src = fromMarkers[q] ?? fromLog[q] ?? fromSnaps[q] ?? null;
    scores.push({ quarter: q, a: src?.a ?? null, b: src?.b ?? null });
  }
  return scores;
}

// min_gp: games needed to appear on the per-game boards (lib/qualification.js) — two thirds of the
// games the player's season team has played, so it grows through the season. A team with no
// count (shouldn't happen once it has a game) falls back to the most any team has played.
function buildLeaderPlayers(season) {
  if (season === 'alltime') return buildLeaderPlayersAllTime();
  const players = getLeaders(season);
  const records = getTeamRecords(season);
  const recordMap = Object.fromEntries(records.map(r => [r.team_id, r]));
  const teamGames = getTeamGameCounts(season);
  const maxTeamGames = Math.max(0, ...Object.values(teamGames));
  return players.map(p => ({
    ...p,
    team_wins: recordMap[p.team_id]?.wins ?? 0, team_losses: recordMap[p.team_id]?.losses ?? 0,
    min_gp: leaderMinGames(teamGames[p.team_id] ?? maxTeamGames),
  }));
}

// Team win/loss records vary by season, so an all-time tiebreak using them wouldn't mean
// anything consistent — leader ranking already falls back to games_played before this anyway.
// Career per-game boards need a full season's worth of games.
function buildLeaderPlayersAllTime() {
  return getLeadersAllTime().map(p => ({ ...p, team_wins: 0, team_losses: 0, min_gp: CAREER_MIN_GP }));
}

// Homepage fallback for the League Leaders carousel during the gap between a new season's
// roster being drafted and its first game being recorded (getLeaders() has nothing to show
// yet — games_played is 0 for everyone). "Moved" is read off the live players.team_id, not
// season_roster's own player_id (every roster row already has a player_id by the time a
// season starts — new registrants get a real players row well before this point — so that
// field can't tell new from returning anymore). Comparing against players.team_id still can,
// since that only gets synced to match once the season actually starts being played:
//   - no live team at all  → genuinely new to the league
//   - live team differs    → moved from that team to this one
//   - live team matches    → unchanged, not a "mover", excluded
function buildRosterMovers(season) {
  if (!season) return [];
  const seasonTeams = getSeasonTeams(season);
  const seasonTeamById = Object.fromEntries(seasonTeams.map(t => [t.id, t]));
  const rosterRows = getSeasonRoster(season).filter(r => r.status === 'confirmed');
  const liveTeams = getAllTeams();
  const liveTeamById = Object.fromEntries(liveTeams.map(t => [t.id, t]));

  const movers = [];
  for (const row of rosterRows) {
    const seasonTeam = seasonTeamById[row.team_id];
    if (!seasonTeam || !row.player_id) continue;
    const player = getPlayerById(row.player_id);
    if (!player) continue;
    // "Team as of their most recent actual game before this season" rather than the live
    // players table — once a season is started, players.team_id already gets synced to
    // match this season's roster (see the "Start Season" flow), which would make every
    // player look "unchanged" here from that point on. Game history is untouched by that
    // sync and, unlike season_roster, goes back to before the draft tool even existed.
    const lastTeamId = getPlayerLastTeamIdBeforeSeason(row.player_id, season);
    const lastTeam = lastTeamId ? liveTeamById[lastTeamId] : null;
    if (lastTeam && lastTeam.name.trim().toUpperCase() === seasonTeam.name.trim().toUpperCase()) continue; // unchanged
    let positions = [];
    try { positions = JSON.parse(row.positions || '[]'); } catch { positions = []; }
    movers.push({
      id: row.player_id,
      // player.name (the site's one canonical display name, curated by admin) rather than
      // row.full_name (whatever the registrant typed on their own signup form) — same source
      // every other page on the site already uses for this player.
      name: player.name,
      position: positions[0] || '',
      teamName: seasonTeam.name,
      fromTeamName: lastTeam ? lastTeam.name : '',
    });
  }
  return movers;
}

// Standings rank by win% (any games played beats none), tiebreak by raw win count.
// Shared by /teams (all four cards) and /teams/:ref (single team's rank badge) so the
// number always agrees between the two pages.
function rankTeamsByRecord(teams, recordMap) {
  const withWl = teams.map(t => {
    const rec = recordMap[t.id] ?? null;
    return { id: t.id, wins: rec?.wins ?? 0, losses: rec?.losses ?? 0 };
  });
  const ranked = [...withWl].sort((a, b) => {
    const gpA = a.wins + a.losses, gpB = b.wins + b.losses;
    const wpA = gpA > 0 ? a.wins / gpA : -1;
    const wpB = gpB > 0 ? b.wins / gpB : -1;
    return wpB - wpA || b.wins - a.wins;
  });
  return Object.fromEntries(ranked.map((t, i) => [t.id, i + 1]));
}

// Resolves a URL ref (pretty slug OR raw entity ID) to a canonical entity ID.
// Returns { id } if the ref was already a slug, or { id, slug } to signal a redirect.
// Returns null if nothing matches.
function resolveRef(type, ref, lookupById, genSlug) {
  const idFromSlug = getEntityForSlug(type, ref);
  if (idFromSlug) return { id: idFromSlug };
  const entity = lookupById(ref);
  if (!entity) return null;
  const slug = genSlug(entity);
  saveSlug(type, entity.id, slug);
  return { id: entity.id, slug };
}

// Date field is stored as "M/D/YYYY h:mm AM" — not lexicographically sortable.
// Always sort with this helper before displaying games or scanning for highlights.
function byDate(games) {
  return [...games].sort((a, b) => new Date(b.date) - new Date(a.date));
}

function buildHighlights(completedGames, playerMap, teamMap, count = 4) {
  // completedGames must already be in date DESC order (caller calls byDate first).
  const results = [];
  for (const g of completedGames) {
    if (!g.potg_writeup && !g.co_potg_writeup) continue;
    const stats = getGameStats(g.id);
    // A co-POTG is their own highlight, with their own writeup.
    for (const [k, pid] of potgIdsFor(g, stats).entries()) {
      if (results.length >= count) break;
      const writeup = potgWriteupFor(g, pid);
      const potgStat = stats.find(s => s.player_id === pid);
      if (!writeup || !potgStat) continue;
      results.push({ game: g, stat: potgStat, player: playerMap[pid] || null, team: teamMap[potgStat.team_id] || null, writeup, co: k > 0 });
    }
    if (results.length >= count) break;
  }
  return results;
}

const app = express();

// One URL per page for search engines: www. goes to the bare domain and a trailing slash
// is dropped (/games/ → /games), both permanently. GET/HEAD only, so webhooks and form
// posts are never redirected.
app.use((req, res, next) => {
  if (req.method !== 'GET' && req.method !== 'HEAD') return next();
  const host = String(req.headers['x-forwarded-host'] || req.headers.host || '').split(':')[0].toLowerCase();
  const qs = req.originalUrl.includes('?') ? req.originalUrl.slice(req.originalUrl.indexOf('?')) : '';
  const trimmed = req.path.length > 1 && req.path.endsWith('/') ? req.path.replace(/\/+$/, '') || '/' : req.path;
  if (host === `www.${SITE_HOST}`) return res.redirect(301, `${SITE_ORIGIN}${trimmed}${qs}`);
  if (trimmed !== req.path) return res.redirect(301, `${trimmed}${qs}`);
  next();
});

// Registered before the session and body-parser middleware: the signature is computed over
// the exact raw bytes, so this route needs the unparsed body, and Resend has no session.
app.post('/webhooks/resend', express.raw({ type: '*/*', limit: '256kb' }), (req, res) => {
  if (!resendWebhookEnabled) return res.status(503).json({ error: 'Webhook not configured.' });
  const raw = Buffer.isBuffer(req.body) ? req.body.toString('utf8') : '';
  if (!verifyResendSignature(raw, req.headers)) return res.status(401).json({ error: 'Invalid signature.' });
  let event;
  try { event = JSON.parse(raw); } catch { return res.status(400).json({ error: 'Invalid JSON.' }); }
  try { handleResendEvent(event); }
  catch (e) { console.error('[resend-webhook]', e.message); return res.status(500).json({ error: 'Failed.' }); }
  res.json({ ok: true });
});

const SessionStore = SqliteStore(session);
app.use(session({
  store: new SessionStore({ client: portalDb, expired: { clear: true, intervalMs: 15 * 60 * 1000 } }),
  secret: SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: 'lax', maxAge: 8 * 60 * 60 * 1000 }
}));
app.use(express.urlencoded({ extended: false }));

// Staging and local dev serve the same pages as prod: keep every response on them out of
// search results (robots.txt below also disallows everything on those hosts).
app.use((req, res, next) => {
  if (!isProdHost(req)) res.set('X-Robots-Tag', 'noindex, nofollow');
  next();
});

app.post('/api/cta/:key', (req, res) => {
  const key = String(req.params.key || '');
  try {
    const skip = !CTA_KEYS[key] || req.session?.impersonating || (req.session?.isAdmin && !req.session?.playerRegId)
      || TRACK_BOT_RE.test(req.get('user-agent') || '');
    if (!skip) {
      bumpCtaClick(manilaTodayStr(), key);
      // Which player's or court's page the click happened on (data-cta-ref on the page).
      const ref = String(req.query.ref || '');
      if (/^(player|court):[\w-]{1,64}$/.test(ref)) bumpCtaRefClick(manilaTodayStr(), key, ref);
    }
    // Opened the community chat from anywhere: /me stops showing its invite tile.
    if (key.endsWith('-gc') && req.session?.playerPlayerId && !req.session?.impersonating) markPlayerCta(req.session.playerPlayerId, 'gc');
  } catch (e) { console.error('[cta]', e.message); }
  res.status(204).end();
});

// Registered ahead of express.static so these two paths hit the minified, cached-in-memory
// version instead of the raw source file — everything else in public/ still goes through
// express.static unchanged. Safe to cache for a full year: the URL is always requested
// with ?v=CSS_VER (mtime-derived), so any real content change gets a new URL rather than
// invalidating this one.
app.get(['/styles.css', '/admin.css', '/auth.css', '/profile.css', '/teams.css', '/players.css', '/papawis.css', '/courts.css', '/join.css'], (req, res) => {
  const file = req.path.slice(1);
  const minified = MINIFIED_CSS[file];
  if (!minified) return res.sendFile(path.join(__dirname, 'public', file));
  res.set('Cache-Control', 'public, max-age=31536000, immutable');
  res.type('text/css').send(minified);
});

// The scorer screen imports the scoring engine. The import carries the app version, so a
// phone that keeps its scripts for offline use never pairs a new scorer with an old engine
// (that crashed the screen on "Loading the scorer"). Read once per start, like APP_VER.
let scorerSrc = null;
app.get('/scorer.js', (req, res) => {
  if (scorerSrc == null) {
    try { scorerSrc = readFileSync(path.join(__dirname, 'public/scorer.js'), 'utf8').replace(/from '\.\/score-engine\.js'/, `from './score-engine.js?v=${APP_VER}'`); }
    catch { return res.status(404).end(); }
  }
  res.set('Cache-Control', 'public, max-age=604800');
  res.type('application/javascript').send(scorerSrc);
});

// Everything else in public/: a week in the browser cache. Font files never change under
// the same name (they're Google's content-hashed filenames), so those get a year.
app.use(express.static(path.join(__dirname, 'public'), {
  maxAge: '7d',
  setHeaders(res, filePath) {
    if (filePath.endsWith('.woff2')) res.set('Cache-Control', 'public, max-age=31536000, immutable');
  },
}));

// Bounces a logged-out visitor to /login with a next= pointing back at whatever page
// they actually asked for, so signing in lands them where they meant to go.
function loginUrl(req) {
  return '/login?next=' + encodeURIComponent(req.originalUrl);
}

// null = unrestricted (the true super-admin login always, plus every elevated player-admin
// before this feature existed / with nothing explicitly set). Otherwise an array of
// ADMIN_SECTIONS keys — see registrations.admin_sections in lib/portal-db.js.
function getAdminAllowedSections(req) {
  if (!req.session?.isAdmin || !req.session?.isElevatedPlayer) return null;
  // expandAdminSections: keys saved before the 2026-10 menu reorganisation still work.
  return expandAdminSections(getRegistrationAdminSections(getRegistration(req.session.playerRegId)));
}

// For routes outside /admin/* that requireAuth's automatic section-redirect never reaches
// (e.g. DELETE /games/:id/comments/:id, the player-profile financial section) but that
// should still be off-limits to an admin restricted to a different section, like a
// marketplace-only shop-admin.
function isAdminWithSection(req, sectionKey) {
  if (!req.session?.isAdmin) return false;
  const allowed = getAdminAllowedSections(req);
  return !allowed || allowed.includes(sectionKey);
}

function requireAuth(req, res, next) {
  if (!req.session?.isAdmin) {
    if (req.session?.playerRegId) return res.redirect('/me');
    return res.redirect(loginUrl(req));
  }
  const allowed = getAdminAllowedSections(req);
  if (allowed) {
    const section = sectionForPath(req.path);
    // A path outside every defined section (shared/cross-cutting routes like
    // /admin/site/settings, /admin/impersonate/:id) is left ungated — trying to reclassify
    // every such route per-section risks breaking something a restricted admin legitimately
    // needs inside a section they DO have (e.g. the Papawis reminders toggle posts to the
    // generic /admin/site/settings, not /admin/papawis/...).
    // /admin/site/settings is checked per setting instead (siteSettingSection), so a Papawis
    // admin can still flip the Papawis switches it posts.
    if (section && !allowed.includes(section.key) && req.path !== '/admin/site/settings') {
      const target = firstAllowedAdminUrl(allowed);
      if (target && target !== req.path) return res.redirect(target);
    }
  }
  next();
}

function requireSuperAdmin(req, res, next) {
  if (req.session?.isAdmin && !req.session?.isElevatedPlayer) return next();
  res.status(403).send(renderAdminPage(req, { title: 'Forbidden', currentPath: '', body: '<p style="padding:40px;color:var(--text-muted)">Super admin access required.</p>' }));
}

// Team heads/coaches are just registered players granted one extra privilege (see
// team_heads in lib/portal-db.js) — they authenticate through the normal player session,
// not the admin one, so this is a third, separate gate from requireAuth/requireSuperAdmin.
// A logged-in player who isn't a head gets a 403 (not redirected to /login — they're
// already logged in, bouncing them there would just loop); a logged-out visitor still
// gets sent to log in first.
function requireHead(req, res, next) {
  if (req.session?.playerPlayerId && getHeadTeamIds(req.session.playerPlayerId).length) return next();
  if (req.session?.playerRegId) {
    return res.status(403).send(renderPage(req, { title: 'Not Authorized', currentPath: '/fines', body: '<div class="container"><div class="page-content"><p style="padding:40px 0;color:var(--text-muted)">This page is only available to team heads/coaches.</p></div></div>' }));
  }
  res.redirect(loginUrl(req));
}

// Who cast a vote / filed a report, for both admin surfaces. A true super admin (the
// shared PORTAL_ADMIN_USER/PASS login) has no individual identity, so votes from that
// login collapse into one 'super_admin' bucket — an elevated player-admin (admin-core.md)
// already has their own player identity, so their votes/reports are individually
// attributed for free, no extra auth work needed.
function currentAdminActor(req) {
  if (req.session?.isElevatedPlayer) {
    return { type: 'admin', id: req.session.playerPlayerId, name: req.session.playerName || 'Admin' };
  }
  return { type: 'admin', id: 'super_admin', name: 'Super Admin' };
}
function currentHeadActor(req) {
  return { type: 'head', id: req.session.playerPlayerId, name: req.session.playerName || 'Team Head' };
}

// One identity resolver for League Polls, used from both /admin/polls (reachable by the
// shared super-admin login, which has no player identity at all) and /polls (reachable only
// by an actual logged-in player). Looks up the real player name via getPlayerById rather than
// trusting req.session.playerName, which (see currentHeadActor above) is only ever set for
// elevated player-admins — a plain head or regular player would otherwise show up as blank.
function currentPollVoterIdentity(req) {
  if (req.session?.playerPlayerId) {
    const player = getPlayerById(req.session.playerPlayerId);
    return {
      id: req.session.playerPlayerId,
      name: player ? displayPlayerName(player.name) : (req.session.playerName || 'Player'),
      isAdmin: !!req.session.isAdmin,
      isHead: getHeadTeamIds(req.session.playerPlayerId).length > 0,
    };
  }
  if (req.session?.isAdmin) return { id: 'super_admin', name: 'Super Admin', isAdmin: true, isHead: false };
  return null;
}
// Tiers cascade upward: admins qualify for every tier, heads qualify for 'heads' and
// 'players', a plain player only qualifies for 'players'. Same rule used for both the
// visibility check (can this viewer see the poll) and the eligibility check (can they vote).
function pollTierQualifies(tier, identity) {
  if (!identity) return false;
  if (identity.isAdmin) return true;
  if (tier === 'players') return true;
  if (tier === 'heads') return identity.isHead;
  return false; // tier === 'admins', and identity isn't one
}
// The one poll that pops up for this viewer, on the site (views/polls.js pollPopup) and in
// the app (views/app/poll.js appPollTakeover): open, switched to "Show as popup", one they can
// see and vote in, and not voted in yet. Newest wins when more than one is switched on. Never
// while an admin is viewing as a player.
function popupPollFor(req) {
  if (req.session?.impersonating) return null;
  const identity = currentPollVoterIdentity(req);
  if (!identity) return null;
  return getAllLeaguePolls().find(p => p.status === 'open' && p.popup
    && pollTierQualifies(p.visibility, identity) && pollTierQualifies(p.voter_eligibility, identity)
    && !getMyLeaguePollVote(p.id, identity.id)) || null;
}
// Not on /polls itself, where the same poll is already on the page.
function pollPopupFor(req, currentPath) {
  const poll = currentPath === '/polls' ? null : popupPollFor(req);
  return poll ? pollPopup({ poll, total: getLeaguePollVotes(poll.id).length }) : '';
}
// /polls is open to any logged-in player or admin — a wider gate than requireHead, since
// the whole point of the 'players' visibility tier is "everyone with an account," not just
// heads/admins.
function requirePollAccess(req, res, next) {
  if (currentPollVoterIdentity(req)) return next();
  res.redirect(loginUrl(req));
}

// Looked up fresh per request (not session-cached) so a super admin revoking this flag
// takes effect immediately, not on the elevated admin's next login.
function canViewSensitiveData(req) {
  if (!req.session?.isElevatedPlayer) return true;
  const self = getRegistration(req.session.playerRegId);
  return !!self?.can_view_sensitive;
}

// Log all mutating admin actions (skip GETs and file uploads)
app.use('/admin', (req, res, next) => {
  if (req.method === 'GET' || !req.session?.isAdmin) return next();
  res.on('finish', () => {
    if (res.statusCode >= 500) return;
    const actor     = req.session.isElevatedPlayer ? (req.session.playerName || 'player-admin') : 'super';
    const actorType = req.session.isElevatedPlayer ? 'admin' : 'super';
    const body      = req.body && typeof req.body === 'object' ? { ...req.body } : {};
    delete body.password; delete body.confirm;
    insertAdminLog({ actor, actorType, method: req.method, path: req.path, details: body });
    // A ledger or Papawis change can settle a balance (lift a ban) or create one.
    // (originalUrl: by 'finish' Express has put the /admin mount back on req.url.)
    if (res.statusCode < 400 && /^\/admin\/(ledger|papawis)\b/.test(req.originalUrl)) setImmediate(() => runBanJobs());
  });
  next();
});

// "View as" — lets a true super admin (never an elevated player-admin — team heads/coaches
// promoted to admin already have their own identity and don't need this) see the site
// exactly as a given player does. Swaps the admin session for that player's session,
// stashing enough to restore it on /admin/stop-impersonating. Read-only is enforced by
// the write-blocking middleware below, not by anything on these two routes themselves.
app.post('/admin/impersonate/:playerId', requireSuperAdmin, express.json(), (req, res) => {
  const reg = getRegistrationByPlayerId(req.params.playerId);
  if (!reg || reg.status !== 'approved') return res.status(400).json({ error: 'This player has no active account to view as.' });
  const player = getPlayerWithTeam(req.params.playerId);
  req.session.impersonating           = true;
  req.session.impersonatingPlayerName = displayPlayerName(player?.name || reg.full_name || '');
  req.session.playerRegId             = reg.id;
  req.session.playerPlayerId          = reg.player_id;
  delete req.session.isAdmin;
  delete req.session.isElevatedPlayer;
  res.json({ ok: true });
});

app.post('/admin/stop-impersonating', (req, res) => {
  if (!req.session?.impersonating) return res.status(400).json({ error: 'Not currently viewing as another player.' });
  const playerId = req.session.playerPlayerId;
  delete req.session.impersonating;
  delete req.session.impersonatingPlayerName;
  delete req.session.playerRegId;
  delete req.session.playerPlayerId;
  req.session.isAdmin = true;
  insertAdminLog({ actor: 'Super Admin', actorType: 'super', method: 'POST', path: req.path, details: { event: 'impersonate_stop', playerId } });
  res.json({ ok: true });
});

// While viewing as another player, every non-GET request is blocked — this is a read-only
// window into their account, not a way to act as them (comment, react, settle balance,
// etc. as someone else with zero attribution). /logout is unaffected since it's a GET.
app.use((req, res, next) => {
  if (!req.session?.impersonating || req.method === 'GET') return next();
  if (req.path === '/admin/stop-impersonating') return next();
  // The app's Log out is a POST; like the site's GET /logout it ends the whole session.
  if (req.path === '/app/logout') return next();
  res.status(403).json({ error: 'Read-only while viewing as another player.' });
});

// Last seen: the first GET of each Manila day by a signed-in player stamps
// registrations.last_seen_at (the session remembers the day, so it's one write a day, not
// one per request). Not while viewing as another player.
app.use((req, res, next) => {
  const regId = req.session?.playerRegId;
  if (regId && req.method === 'GET' && !req.session.impersonating) {
    const today = manilaTodayStr();
    if (req.session.seenDay !== today) {
      try { setRegistrationLastSeen(regId); req.session.seenDay = today; }
      catch (e) { console.error('[last seen]', e.message); }
    }
  }
  next();
});

// Every bell link goes through here (views/layout.js), so a click on one notification is
// recorded (clicked_at) apart from just opening the bell. Only the player's own
// notifications resolve; the target must be a path on this site (no open redirect).
app.get('/n/:id', (req, res) => {
  const playerId = req.session?.playerPlayerId;
  if (!playerId) return res.redirect(loginUrl(req));
  const link = req.session.impersonating
    ? getOwnNotificationLink(req.params.id, playerId)
    : clickNotification(req.params.id, playerId);
  const safe = typeof link === 'string' && link.startsWith('/') && !link.startsWith('//') && !link.startsWith('/\\');
  res.redirect(safe ? link : '/');
});

async function fetchCoverImageBuffer(url) {
  if (!url) return null;
  try {
    if (url.startsWith('data:')) {
      const comma = url.indexOf(',');
      return Buffer.from(url.slice(comma + 1), 'base64');
    }
    const fetchUrl = url.startsWith('/') ? `${ADMIN_URL}${url}` : url;
    const r = await fetch(fetchUrl, { signal: AbortSignal.timeout(5000) });
    if (r.ok) return Buffer.from(await r.arrayBuffer());
  } catch {}
  return null;
}

// Downscale + re-encode an arbitrary source photo (e.g. a pre-crop upload) so it's
// cheap to keep around for future re-crops, without needing full original resolution.
async function compressSourceImage(buffer) {
  const out = await sharp(buffer)
    .rotate()
    .resize(1200, 1200, { fit: 'inside', withoutEnlargement: true })
    .jpeg({ quality: 78, progressive: true })
    .toBuffer();
  return 'data:image/jpeg;base64,' + out.toString('base64');
}

function parseDataUrl(dataUrl) {
  const match = String(dataUrl || '').match(/^data:([^;]+);base64,(.+)$/);
  return match ? Buffer.from(match[2], 'base64') : null;
}

// Rough glyph-width estimate for our bold sans stack — good enough to size pills
// and lay out multi-piece rows without a real text-measurement engine available
// server-side. Always over-pads slightly on purpose (better a little loose than
// clipped).
function estTextW(text, fontSize, letterSpacing = 0) {
  const s = String(text ?? '');
  return s.length * fontSize * 0.7 + Math.max(0, s.length - 1) * letterSpacing;
}

// ── "Share My Stats" story card — vertical 1080×1920 PNG for one player's line in
// one game. Fully transparent canvas, no card/panel background — just text, numbers
// and pills floating directly on it (a soft amber glow + text-stroke carry contrast
// instead of a panel), the way Strava's story stickers work: dropped over whatever
// photo/video the player already picked for their Instagram Story, and deliberately
// compact/tight so most of that photo stays visible. `align` (left/center/right)
// shifts EVERY row's own alignment, not just position — a real content-align control.
// Same SVG-string + sharp pipeline as generateLeaderSvg/generateGameCoverPng above.
// The stat categories a player can pick as their card's hero number. The first
// 5 ("core") are also always what fills the secondary row — picking one of the
// last two (3PM, FG%) as hero still shows the top 4 core stats underneath, it
// just doesn't remove one of them to make room (see SHARE_STAT_CORE_KEYS below).
const SHARE_STAT_DEFS = [
  { key: 'pts',   short: 'PTS', long: 'POINTS' },
  { key: 'reb',   short: 'REB', long: 'REBOUNDS' },
  { key: 'ast',   short: 'AST', long: 'ASSISTS' },
  { key: 'stl',   short: 'STL', long: 'STEALS' },
  { key: 'blk',   short: 'BLK', long: 'BLOCKS' },
  { key: 'fg3m',  short: '3PM', long: '3-POINTERS MADE' },
  { key: 'fgpct', short: 'FG%', long: 'FIELD GOAL %' },
];
const SHARE_STAT_CORE_KEYS = ['pts', 'reb', 'ast', 'stl', 'blk'];

// Curated accent choices for the share card only — NOT a general UI accent
// (the site-wide accent stays amber-only per the design system). Each preset
// pairs its own legible text color for the ribbon/badge, the same {bg, text}
// convention already used by AWARD_OG_BADGE above, since a few of these read
// better with white text than the default's dark navy. Kept in public/share-cards.js, which
// the players app also draws cards with.
const SHARE_ACCENT_PRESETS = SHARE_ACCENTS;
function resolveAccent(key) {
  return SHARE_ACCENT_PRESETS[key] || SHARE_ACCENT_PRESETS.amber;
}

function shareStatValue(stat, key) {
  if (key === 'fg3m') return Number(stat.fg3m) || 0;
  if (key === 'fgpct') {
    // Includes fg4m — overall field goal % must count every make/miss
    // regardless of shot value, same convention as the site's own leader/team
    // FG% queries in lib/portal-db.js (SUM(fg2m+fg3m+fg4m) etc).
    const fgm = (Number(stat.fg2m) || 0) + (Number(stat.fg3m) || 0) + (Number(stat.fg4m) || 0);
    const fga = fgm + (Number(stat.fg2m_miss) || 0) + (Number(stat.fg3m_miss) || 0) + (Number(stat.fg4m_miss) || 0);
    return fga > 0 ? Math.round((fgm / fga) * 100) : 0;
  }
  return Number(stat[key]) || 0;
}
function shareStatDisplay(stat, key) {
  const val = shareStatValue(stat, key);
  return key === 'fgpct' ? `${val}%` : String(val);
}

// Priority order matches "most impressive first": a triple-double outranks a
// double-double, which outranks a plain career high. Career-high check mirrors
// the exact `stat.X >= careerHighs.X && stat.X > 0` pattern already used for the
// POTG writeup prompt (career highs are computed as MAX() over ALL games
// including this one, so "this game IS (one of) the max" is what >= tests for).
function achievementRibbonText(stat, careerHighs) {
  const cats = statCatCount(stat);
  if (cats >= 3) return 'TRIPLE-DOUBLE';
  if (cats >= 2) return 'DOUBLE-DOUBLE';
  if (careerHighs) {
    const hiKeys = SHARE_STAT_CORE_KEYS.filter(k => {
      const v = Number(stat[k]) || 0;
      return v > 0 && v >= (Number(careerHighs[k]) || 0);
    });
    if (hiKeys.length) {
      const shorts = hiKeys.map(k => SHARE_STAT_DEFS.find(d => d.key === k).short);
      return `CAREER HIGH ${shorts.join('/')}`;
    }
  }
  return '';
}

async function generateGameStatCardPng(game, stat, align = 'center', heroKey = 'pts', opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const heroDef = SHARE_STAT_DEFS.find(d => d.key === heroKey) || SHARE_STAT_DEFS[0];
  // Always the top 4 CORE stats minus the hero (if it's one of them) — so
  // picking a bonus stat like 3PM as hero still shows PTS/REB/AST/STL below it
  // rather than needing a 5th slot.
  const secondaryDefs = SHARE_STAT_CORE_KEYS
    .filter(k => k !== heroDef.key)
    .slice(0, 4)
    .map(k => SHARE_STAT_DEFS.find(d => d.key === k));
  const SAFE_X0 = 90, SAFE_X1 = 990; // left/right safe-zone edges content aligns to
  const posX  = align === 'left' ? SAFE_X0 : align === 'right' ? SAFE_X1 : W / 2;
  const anchor = align === 'left' ? 'start' : align === 'right' ? 'end' : 'middle';
  // Left edge for a fixed-width box (pill, stat group, logo) anchored the same way.
  const boxX = (w) => align === 'left' ? SAFE_X0 : align === 'right' ? SAFE_X1 - w : (W - w) / 2;

  // Achievement ribbon (badge toggle) and season-average delta (comparison layout)
  // are both additive rows on top of the same skeleton, not a separate template
  // each — they're just extra entries in the row sequence below.
  const badgeText = opts.badge
    ? achievementRibbonText(stat, getPlayerCareerHighs(stat.player_id))
    : '';
  const hasCmp = typeof opts.comparisonAvg === 'number' && isFinite(opts.comparisonAvg);

  const isTeamA    = stat.team_id === game.team_a_id;
  const myTeamName = String(stat.team_name || '').toUpperCase();
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myColor    = escXml(stat.team_color || '#f59332');
  const chipTextColor = myTeamName === 'WHITE' ? '#10141d' : '#fff';

  const myScore  = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won      = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';

  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  const nameFontSz  = displayName.length > 20 ? 40 : displayName.length > 14 ? 48 : 56;
  const heroDisplay = shareStatDisplay(stat, heroDef.key);
  const heroFontSz  = heroDisplay.length >= 3 ? 190 : 220;

  // Team chip — sized off the FULL chip text (name + number), not just the team
  // name — otherwise the number suffix clips past an under-sized pill. Font bumped
  // from 17→20 (it read as too small/hard to make out at a glance) with the pill's
  // own height and padding grown to match.
  const chipText   = `${myTeamName} · #${stat.number ?? ''}`;
  const chipFsz    = 20;
  const chipH      = 46;
  const chipW      = Math.max(160, Math.round(estTextW(chipText, chipFsz, 2) + 76));
  const chipX      = boxX(chipW);

  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;

  const ribbonFsz  = 22;
  const ribbonH    = 40;
  // Padding matches the team-chip pill's own +76 convention above — a
  // fully-rounded pill needs more flat clearance than a plain rect since the
  // end caps themselves eat into it; a flatter +56 read as too tight.
  const ribbonW    = Math.round(estTextW(badgeText, ribbonFsz, 1.5) + 76);
  const ribbonX    = boxX(ribbonW);

  const heroValNum   = shareStatValue(stat, heroDef.key);
  const cmpAvgDisplay = hasCmp ? (heroDef.key === 'fgpct' ? `${Math.round(opts.comparisonAvg)}%` : opts.comparisonAvg.toFixed(1)) : '';
  const cmpDelta      = hasCmp ? heroValNum - opts.comparisonAvg : 0;
  const cmpDeltaDisplay = hasCmp ? `${cmpDelta >= 0 ? '+' : ''}${cmpDelta.toFixed(1)}` : '';
  const comparisonLine = hasCmp ? `${cmpDeltaDisplay} VS YOUR ${cmpAvgDisplay} SEASON AVG` : '';

  // Ranked best-to-worst by value, not fixed PTS>REB>AST>STL>BLK order — so
  // whichever of the remaining 4 categories this player was next-best at reads
  // left-to-right, same "most outstanding first" idea as the hero pick itself.
  const secondary = secondaryDefs
    .map(d => ({ label: d.short, val: shareStatValue(stat, d.key) }))
    .sort((a, b) => b.val - a.val);
  const colPitch  = 150, groupW = colPitch * secondary.length;
  const groupLeft = boxX(groupW);

  // Brand handle pill — width accounts for the dot+gap PREFIX before the text
  // starts, not just the text itself (that prefix was eating into what was
  // supposed to be the pill's right-side padding). Right padding is kept a
  // bit larger than the left dot-inset on purpose: the dot itself already reads
  // as "space" on the left, so equal raw numbers there looked lopsided.
  const handleText = '@WKNDBASKETBALL';
  const handleFsz  = 20;
  const handleH    = 54;
  const dotR = 7, dotLeftInset = 22, dotToText = 10, rightPad = 34;
  const prefixW     = dotLeftInset + dotR * 2 + dotToText;
  const handleTextW = handleText.length * handleFsz * 0.66 + (handleText.length - 1) * 1.5;
  const handleW     = Math.max(230, Math.round(prefixW + handleTextW + rightPad));
  const handleX     = boxX(handleW);

  // ── Vertical rhythm: every row is placed by a single running cursor with one
  // uniform GAP between rows (instead of hand-picked absolute offsets per row,
  // which drifted out of sync with each other as rows got added/removed for the
  // badge/comparison options — same GAP is reused by generateGameStatGridPng).
  const GAP = 34;
  const cap = (fontSize) => fontSize * 0.73; // approx cap-height for this bold sans stack
  let cursor = 580 + 42 + GAP; // logo top (580) + its box height (42)

  let ribbonTop = null, ribbonTextY = null;
  if (badgeText) {
    ribbonTop = cursor;
    ribbonTextY = ribbonTop + ribbonH / 2 + 7;
    cursor = ribbonTop + ribbonH + GAP;
  }

  const nameY = cursor + cap(nameFontSz);
  cursor = nameY + GAP;

  const chipTop   = cursor;
  const chipTextY = chipTop + chipH / 2 + 7;
  cursor = chipTop + chipH + GAP;

  const contextY = cursor + cap(17);
  cursor = contextY + GAP;

  const glowCy = cursor + cap(heroFontSz) / 2;
  const heroY  = cursor + cap(heroFontSz);
  cursor = heroY + GAP;

  const heroLabelY = cursor + cap(26);
  cursor = heroLabelY + GAP;

  let comparisonY = null;
  if (hasCmp) {
    comparisonY = cursor + cap(20);
    cursor = comparisonY + GAP;
  }

  const secondaryY = cursor + cap(58);
  cursor = secondaryY + GAP;

  const secondaryLabelY = cursor + cap(15);
  cursor = secondaryLabelY + GAP;

  const handleTop = cursor;
  const dotCx       = handleX + dotLeftInset + dotR;
  const dotCy       = handleTop + handleH / 2;
  const handleTextX = handleX + prefixW;
  const handleTextY = handleTop + handleH / 2 + 7;

  const secondaryCols = secondary.map((s, i) => {
    const cx = groupLeft + colPitch * i + colPitch / 2;
    return `<text x="${cx}" y="${secondaryY}" text-anchor="middle" font-family="${COVER_SVG_FONT}" font-size="58" font-weight="900" fill="${accent.bg}" stroke="#000" stroke-width="6" stroke-opacity="0.35" paint-order="stroke fill" filter="url(#txt)">${s.val}</text>
  <text x="${cx}" y="${secondaryLabelY}" text-anchor="middle" font-family="${COVER_SVG_FONT}" font-size="15" font-weight="700" letter-spacing="2.5" fill="#f1f5f9" filter="url(#txt)">${s.label}</text>`;
  }).join('\n');

  // Fully transparent canvas — no panel behind any of this. A soft drop shadow
  // (`#txt`) plus a stroke on the biggest numbers carry legibility instead.
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="6" flood-color="#000000" flood-opacity="0.65"/>
    </filter>
    <radialGradient id="glow" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="${accent.bg}" stop-opacity="0.55"/>
      <stop offset="60%" stop-color="${accent.bg}" stop-opacity="0.18"/>
      <stop offset="100%" stop-color="${accent.bg}" stop-opacity="0"/>
    </radialGradient>
    <filter id="blur" x="-100%" y="-100%" width="300%" height="300%">
      <feGaussianBlur stdDeviation="34"/>
    </filter>
  </defs>

  <ellipse cx="${posX}" cy="${glowCy}" rx="250" ry="190" fill="url(#glow)" filter="url(#blur)"/>

  ${badgeText ? `<rect x="${ribbonX}" y="${ribbonTop}" width="${ribbonW}" height="${ribbonH}" rx="${ribbonH / 2}" fill="${accent.bg}" filter="url(#txt)"/>
  <text x="${ribbonX + ribbonW / 2}" y="${ribbonTextY}" text-anchor="middle" font-family="${COVER_SVG_FONT}" font-size="${ribbonFsz}" font-weight="800" letter-spacing="1.5" fill="${accent.text}">${escXml(badgeText)}</text>` : ''}

  <text x="${posX}" y="${nameY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="${nameFontSz}" font-weight="800" letter-spacing="2" fill="#ffffff" stroke="#000" stroke-width="5" stroke-opacity="0.3" paint-order="stroke fill" filter="url(#txt)">${displayName}</text>

  <rect x="${chipX}" y="${chipTop}" width="${chipW}" height="${chipH}" rx="${chipH / 2}" fill="${myColor}" filter="url(#txt)"/>
  <text x="${chipX + chipW / 2}" y="${chipTextY}" text-anchor="middle" font-family="${COVER_SVG_FONT}" font-size="${chipFsz}" font-weight="800" letter-spacing="1.5" fill="${chipTextColor}">${escXml(chipText)}</text>

  <text x="${posX}" y="${contextY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="17" font-weight="600" fill="#e2e8f0" filter="url(#txt)">${contextText}</text>

  <text x="${posX}" y="${heroY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="${heroFontSz}" font-weight="900" fill="${accent.bg}" stroke="#100701" stroke-width="8" stroke-opacity="0.45" paint-order="stroke fill" filter="url(#txt)">${heroDisplay}</text>
  <text x="${posX}" y="${heroLabelY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="26" font-weight="700" letter-spacing="5" fill="#f1f5f9" filter="url(#txt)">${heroDef.long}</text>

  ${hasCmp ? `<text x="${posX}" y="${comparisonY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="20" font-weight="700" letter-spacing="1" fill="#f1f5f9" filter="url(#txt)">${escXml(comparisonLine)}</text>` : ''}

  ${secondaryCols}

  <rect x="${handleX}" y="${handleTop}" width="${handleW}" height="${handleH}" rx="${handleH / 2}" fill="#0b1220" fill-opacity="0.55" stroke="${accent.bg}" stroke-width="1.5" filter="url(#txt)"/>
  <circle cx="${dotCx}" cy="${dotCy}" r="${dotR}" fill="${accent.bg}"/>
  <text x="${handleTextX}" y="${handleTextY}" font-family="${COVER_SVG_FONT}" font-size="${handleFsz}" font-weight="800" letter-spacing="1.5" fill="#ffffff">${handleText}</text>
</svg>`;

  const svgLayer = await sharp(Buffer.from(svg), { density: 144 })
    .resize(W, H)
    .png()
    .toBuffer();
  const base = await sharp({ create: { width: W, height: H, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } } }).png().toBuffer();
  const layers = [{ input: svgLayer, top: 0, left: 0 }];

  try {
    if (existsSync(COVER_LOGO_PATH)) {
      const logo = await sharp(COVER_LOGO_PATH)
        .ensureAlpha()
        .resize({ width: 150, height: 42, fit: 'inside', withoutEnlargement: true })
        .png()
        .toBuffer();
      const meta = await sharp(logo).metadata();
      layers.push({ input: logo, left: Math.round(boxX(meta.width || 150)), top: 580 });
    }
  } catch {}

  return sharp(base).composite(layers).png({ compressionLevel: 9 }).toBuffer();
}

// "Full stat grid" layout — no single hero, every core category shown at the
// same visual weight (PTS/REB/AST/STL/BLK + FG%), for a good all-around game
// where no one stat is the obvious standout. Same header/handle conventions as
// generateGameStatCardPng but its own template below the context line, since
// there's no hero number to build a layout around.
async function generateGameStatGridPng(game, stat, align = 'center', opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const SAFE_X0 = 90, SAFE_X1 = 990;
  const posX  = align === 'left' ? SAFE_X0 : align === 'right' ? SAFE_X1 : W / 2;
  const anchor = align === 'left' ? 'start' : align === 'right' ? 'end' : 'middle';
  const boxX = (w) => align === 'left' ? SAFE_X0 : align === 'right' ? SAFE_X1 - w : (W - w) / 2;

  const isTeamA    = stat.team_id === game.team_a_id;
  const myTeamName = String(stat.team_name || '').toUpperCase();
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myColor    = escXml(stat.team_color || '#f59332');
  const chipTextColor = myTeamName === 'WHITE' ? '#10141d' : '#fff';

  const myScore  = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won      = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';

  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  const nameFontSz  = displayName.length > 20 ? 40 : displayName.length > 14 ? 48 : 56;

  const chipText   = `${myTeamName} · #${stat.number ?? ''}`;
  const chipFsz    = 20;
  const chipH      = 46;
  const chipW      = Math.max(160, Math.round(estTextW(chipText, chipFsz, 2) + 76));
  const chipX      = boxX(chipW);

  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;

  // Fixed box-score order (not "best stat first" like the default template's
  // secondary row) — this layout's whole point is an even, familiar box-score
  // read, not a highlight ranking.
  const GRID_KEYS = ['pts', 'reb', 'ast', 'stl', 'blk', 'fgpct'];
  const cells = GRID_KEYS.map(k => ({
    label: SHARE_STAT_DEFS.find(d => d.key === k).short,
    val:   shareStatDisplay(stat, k),
  }));
  const colPitch  = 300, groupW = colPitch * 3;
  const groupLeft = boxX(groupW);

  const handleText = '@WKNDBASKETBALL';
  const handleFsz  = 20;
  const handleH    = 54;
  const dotR = 7, dotLeftInset = 22, dotToText = 10, rightPad = 34;
  const prefixW     = dotLeftInset + dotR * 2 + dotToText;
  const handleTextW = handleText.length * handleFsz * 0.66 + (handleText.length - 1) * 1.5;
  const handleW     = Math.max(230, Math.round(prefixW + handleTextW + rightPad));
  const handleX     = boxX(handleW);

  // Same uniform-GAP row cursor as generateGameStatCardPng — see its comment.
  const GAP = 34;
  const cap = (fontSize) => fontSize * 0.73;
  let cursor = 580 + 42 + GAP;

  const nameY = cursor + cap(nameFontSz);
  cursor = nameY + GAP;

  const chipTop   = cursor;
  const chipTextY = chipTop + chipH / 2 + 7;
  cursor = chipTop + chipH + GAP;

  const contextY = cursor + cap(17);
  cursor = contextY + GAP;

  const row1Y = cursor + cap(68);
  cursor = row1Y + GAP;
  const row1LabelY = cursor + cap(16);
  cursor = row1LabelY + GAP;
  const row2Y = cursor + cap(68);
  cursor = row2Y + GAP;
  const row2LabelY = cursor + cap(16);
  cursor = row2LabelY + GAP;

  const glowCy = (row1Y + row2LabelY) / 2;
  const handleTop = cursor;
  const dotCx       = handleX + dotLeftInset + dotR;
  const dotCy       = handleTop + handleH / 2;
  const handleTextX = handleX + prefixW;
  const handleTextY = handleTop + handleH / 2 + 7;

  const gridCells = cells.map((c, i) => {
    const col = i % 3, row = Math.floor(i / 3);
    const cx  = groupLeft + colPitch * col + colPitch / 2;
    const vy  = row === 0 ? row1Y : row2Y;
    const ly  = row === 0 ? row1LabelY : row2LabelY;
    return `<text x="${cx}" y="${vy}" text-anchor="middle" font-family="${COVER_SVG_FONT}" font-size="68" font-weight="900" fill="${accent.bg}" stroke="#000" stroke-width="6" stroke-opacity="0.35" paint-order="stroke fill" filter="url(#txt)">${c.val}</text>
  <text x="${cx}" y="${ly}" text-anchor="middle" font-family="${COVER_SVG_FONT}" font-size="16" font-weight="700" letter-spacing="2.5" fill="#f1f5f9" filter="url(#txt)">${c.label}</text>`;
  }).join('\n');

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="6" flood-color="#000000" flood-opacity="0.65"/>
    </filter>
    <radialGradient id="glow" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="${accent.bg}" stop-opacity="0.45"/>
      <stop offset="60%" stop-color="${accent.bg}" stop-opacity="0.14"/>
      <stop offset="100%" stop-color="${accent.bg}" stop-opacity="0"/>
    </radialGradient>
    <filter id="blur" x="-100%" y="-100%" width="300%" height="300%">
      <feGaussianBlur stdDeviation="34"/>
    </filter>
  </defs>

  <ellipse cx="${posX}" cy="${glowCy}" rx="320" ry="260" fill="url(#glow)" filter="url(#blur)"/>

  <text x="${posX}" y="${nameY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="${nameFontSz}" font-weight="800" letter-spacing="2" fill="#ffffff" stroke="#000" stroke-width="5" stroke-opacity="0.3" paint-order="stroke fill" filter="url(#txt)">${displayName}</text>

  <rect x="${chipX}" y="${chipTop}" width="${chipW}" height="${chipH}" rx="${chipH / 2}" fill="${myColor}" filter="url(#txt)"/>
  <text x="${chipX + chipW / 2}" y="${chipTextY}" text-anchor="middle" font-family="${COVER_SVG_FONT}" font-size="${chipFsz}" font-weight="800" letter-spacing="1.5" fill="${chipTextColor}">${escXml(chipText)}</text>

  <text x="${posX}" y="${contextY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="17" font-weight="600" fill="#e2e8f0" filter="url(#txt)">${contextText}</text>

  ${gridCells}

  <rect x="${handleX}" y="${handleTop}" width="${handleW}" height="${handleH}" rx="${handleH / 2}" fill="#0b1220" fill-opacity="0.55" stroke="${accent.bg}" stroke-width="1.5" filter="url(#txt)"/>
  <circle cx="${dotCx}" cy="${dotCy}" r="${dotR}" fill="${accent.bg}"/>
  <text x="${handleTextX}" y="${handleTextY}" font-family="${COVER_SVG_FONT}" font-size="${handleFsz}" font-weight="800" letter-spacing="1.5" fill="#ffffff">${handleText}</text>
</svg>`;

  const svgLayer = await sharp(Buffer.from(svg), { density: 144 })
    .resize(W, H)
    .png()
    .toBuffer();
  const base = await sharp({ create: { width: W, height: H, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } } }).png().toBuffer();
  const layers = [{ input: svgLayer, top: 0, left: 0 }];

  try {
    if (existsSync(COVER_LOGO_PATH)) {
      const logo = await sharp(COVER_LOGO_PATH)
        .ensureAlpha()
        .resize({ width: 150, height: 42, fit: 'inside', withoutEnlargement: true })
        .png()
        .toBuffer();
      const meta = await sharp(logo).metadata();
      layers.push({ input: logo, left: Math.round(boxX(meta.width || 150)), top: 580 });
    }
  } catch {}

  return sharp(base).composite(layers).png({ compressionLevel: 9 }).toBuffer();
}

// "Minimal corner sticker" layout — a small single-stat badge meant to be
// dropped in one corner of a photo/video (closer to a real Strava sticker)
// rather than spanning the whole frame. Anchored to whichever corner is picked;
// top corners lay out top-to-bottom from a fixed top margin, bottom corners lay
// out bottom-to-top from a fixed bottom margin, so the block always hugs the
// edge it's pinned to. No logo watermark (kept deliberately tiny/minimal).
async function generateGameStatStickerPng(game, stat, corner = 'tl', heroKey = 'pts', opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const heroDef = SHARE_STAT_DEFS.find(d => d.key === heroKey) || SHARE_STAT_DEFS[0];
  const EDGE_X = 64, TOP_Y = 170, BOTTOM_Y = 1750;
  const isRight  = corner === 'tr' || corner === 'br';
  const isBottom = corner === 'bl' || corner === 'br';
  const x       = isRight ? W - EDGE_X : EDGE_X;
  const anchor  = isRight ? 'end' : 'start';
  const pillX   = (w) => isRight ? x - w : x;

  const myTeamName = String(stat.team_name || '').toUpperCase();
  const myColor    = escXml(stat.team_color || '#f59332');
  const chipTextColor = myTeamName === 'WHITE' ? '#10141d' : '#fff';
  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  const nameFontSz  = displayName.length > 18 ? 32 : 38;
  const heroDisplay = shareStatDisplay(stat, heroDef.key);
  const heroFontSz  = 120;

  const chipText = `${myTeamName} · #${stat.number ?? ''}`;
  const chipFsz  = 15, chipH = 32;
  const chipW    = Math.max(120, Math.round(estTextW(chipText, chipFsz, 1.5) + 44));
  const chipXpos = pillX(chipW);

  const handleText = '@WKNDBASKETBALL';
  const handleFsz  = 14;

  let chipTop, nameY, heroY, heroLabelY, handleY;
  if (!isBottom) {
    chipTop    = TOP_Y;
    nameY      = chipTop + chipH + 40;
    heroY      = nameY + 132;
    heroLabelY = heroY + 30;
    handleY    = heroLabelY + 46;
  } else {
    handleY    = BOTTOM_Y;
    heroLabelY = handleY - 46;
    heroY      = heroLabelY - 30;
    nameY      = heroY - 132;
    chipTop    = nameY - chipH - 40;
  }
  const chipTextY = chipTop + chipH / 2 + 5;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="5" flood-color="#000000" flood-opacity="0.7"/>
    </filter>
  </defs>

  <rect x="${chipXpos}" y="${chipTop}" width="${chipW}" height="${chipH}" rx="${chipH / 2}" fill="${myColor}" filter="url(#txt)"/>
  <text x="${chipXpos + chipW / 2}" y="${chipTextY}" text-anchor="middle" font-family="${COVER_SVG_FONT}" font-size="${chipFsz}" font-weight="800" letter-spacing="1.2" fill="${chipTextColor}">${escXml(chipText)}</text>

  <text x="${x}" y="${nameY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="${nameFontSz}" font-weight="800" letter-spacing="1.5" fill="#ffffff" stroke="#000" stroke-width="4" stroke-opacity="0.3" paint-order="stroke fill" filter="url(#txt)">${displayName}</text>

  <text x="${x}" y="${heroY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="${heroFontSz}" font-weight="900" fill="${accent.bg}" stroke="#100701" stroke-width="6" stroke-opacity="0.45" paint-order="stroke fill" filter="url(#txt)">${heroDisplay}</text>
  <text x="${x}" y="${heroLabelY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="18" font-weight="700" letter-spacing="4" fill="#f1f5f9" filter="url(#txt)">${heroDef.long}</text>

  <text x="${x}" y="${handleY}" text-anchor="${anchor}" font-family="${COVER_SVG_FONT}" font-size="${handleFsz}" font-weight="800" letter-spacing="1.2" fill="${accent.bg}" filter="url(#txt)">${handleText}</text>
</svg>`;

  const svgLayer = await sharp(Buffer.from(svg), { density: 144 }).resize(W, H).png().toBuffer();
  const base = await sharp({ create: { width: W, height: H, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } } }).png().toBuffer();
  return sharp(base).composite([{ input: svgLayer, top: 0, left: 0 }]).png({ compressionLevel: 9 }).toBuffer();
}

// "Gauges" layout — a transparent overlay sticker, same "drop over your own
// photo/video" mechanic as the three templates above (no logo either way, this
// one just never had one). Built from a mocked-up reference (a "by the
// numbers" infographic style): faded diagonal accent ticks, name + underline +
// matchup context + team chip header shared byte-for-byte across all three
// alignments (buildHeader below — only the anchor/x position differs, never
// font size or which rows exist, after an earlier version let left/right
// quietly drift smaller than center), a 3-stat "focus" row (which categories
// depends on opts.focus), and an optional ring-gauge row below it (opts.gauges,
// default on) showing the best 3 of 4 possible shooting-% categories now that
// 4-point shots exist — see the attempt-ranked selection further down. When
// gauges are off, the numbers row scales up to fill the space instead of
// leaving a gap.
// Because there's no guaranteed dark background underneath anymore, every
// element needs to hold up against an unknown photo: text gets the same
// stroke + drop-shadow (`#txt`) treatment as the other templates, the gauge's
// unfilled track is translucent white instead of a fixed dark slate (which
// could disappear against a dark photo), and a soft accent glow (`#glow`/
// `#blur`) sits behind the stat rows for contrast, same idea as the hero
// number's glow in generateGameStatCardPng. `align` shifts the whole block's
// x-anchor; content is then vertically centered as one group so it isn't
// top-heavy. No "Hide Zeros" support here (unlike Bottom/Stacked) — the
// dashed ring already reads as an intentional "no attempts" state sitting in
// its own fixed slot, whereas dropping one of these fixed 3-column slots
// would mean re-centering the remaining columns, which isn't worth the
// complexity for what the ring already communicates cleanly on its own.
const GAUGES_FOCUS_DEFS = {
  all:     { keys: ['pts', 'reb', 'ast'], labels: ['POINTS', 'REBOUNDS', 'ASSISTS'] },
  offense: { keys: ['pts', 'ast', 'fg3m'], labels: ['POINTS', 'ASSISTS', 'THREES MADE'] },
  defense: { keys: ['reb', 'stl', 'blk'], labels: ['REBOUNDS', 'STEALS', 'BLOCKS'] },
};
// Translucent white, not a fixed dark hex — this ring sits over an unknown
// photo now, and a fixed dark slate track could disappear entirely against a
// dark photo. White-at-low-opacity plus the drop-shadow filter reads
// consistently against both light and dark backgrounds.
const GAUGES_TRACK_COLOR = '#ffffff';
function gaugesPct(made, att) { return att > 0 ? Math.round((made / att) * 100) : null; }
// What "Hide zeros" drops: a 0 count stat, and a shooting % that's 0 or had no attempts
// (null). 0% used to stay (0 of 2 is a real value), which is what players saw as not hiding.
const isZeroShareStat = s => (s.isPct ? !s.value : Number(s.value) === 0);

// Ranks the 4 possible shooting-% categories (now that 4-point shots exist)
// by attempt volume and returns whichever 3 are most meaningful — a
// percentage backed by more shots says more than one on a couple of token
// attempts. Ties (most commonly: everyone at 0 attempts before any 4s are
// taken) fall back to a fixed priority so the default game still shows
// today's familiar FG%/3PT%/FT% trio unchanged. Display order stays the fixed
// canonical progression (overall → 3PT → 4PT → FT) among whichever 3
// survived, so the row doesn't reshuffle game-to-game just because attempt
// counts changed. Shared by every "Default" template variant that shows a
// shooting readout (gauges grid, stacked list, news deck).
function pickBestShootingStats(stat) {
  const fg2mVal = Number(stat.fg2m) || 0, fg2Miss = Number(stat.fg2m_miss) || 0;
  const fg3mVal = Number(stat.fg3m) || 0, fg3Miss = Number(stat.fg3m_miss) || 0;
  const fg4mVal = Number(stat.fg4m) || 0, fg4Miss = Number(stat.fg4m_miss) || 0;
  const ftmVal  = Number(stat.ftm) || 0,  ftMiss  = Number(stat.ft_miss) || 0;
  const fgMade = fg2mVal + fg3mVal + fg4mVal, fgAtt = fgMade + fg2Miss + fg3Miss + fg4Miss;
  const candidates = [
    { label: 'FIELD GOAL %', shortLabel: 'FG', pct: gaugesPct(fgMade, fgAtt), att: fgAtt, priority: 0 },
    { label: '3-POINT %', shortLabel: '3PT', pct: gaugesPct(fg3mVal, fg3mVal + fg3Miss), att: fg3mVal + fg3Miss, priority: 2 },
    { label: '4-POINT %', shortLabel: '4PT', pct: gaugesPct(fg4mVal, fg4mVal + fg4Miss), att: fg4mVal + fg4Miss, priority: 3 },
    { label: 'FREE THROW %', shortLabel: 'FT', pct: gaugesPct(ftmVal, ftmVal + ftMiss), att: ftmVal + ftMiss, priority: 1 },
  ];
  const chosen = candidates.slice()
    .sort((a, b) => b.att - a.att || a.priority - b.priority)
    .slice(0, 3);
  return candidates.filter(c => chosen.includes(c));
}

// Defense-in-depth for every template that builds one flat stat list by
// combining a count-stat source with pickBestShootingStats (Bottom, Stacked,
// Premium) — keeps the first occurrence of a given label and drops any
// repeat. This exact bug happened once already (Premium briefly iterated
// SHARE_STAT_DEFS's full 7 entries, including its 'fgpct' one, so field goal
// % rendered twice — see that fix's own history), so this isn't purely
// theoretical: a future edit to GAUGES_FOCUS_DEFS/SHARE_STAT_DEFS/whatever
// feeds one of these lists could reintroduce the same class of bug, and this
// makes it fail safe (silently drop the repeat) instead of visibly doubling
// a stat on the actual card.
function dedupeStatsByLabel(list) {
  const seen = new Set();
  return list.filter(s => {
    if (seen.has(s.label)) return false;
    seen.add(s.label);
    return true;
  });
}

async function generateGameStatGaugesPng(game, stat, align = 'center', focus = 'all', opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const font = COVER_SVG_FONT;
  const SAFE_X0 = 90, SAFE_X1 = 990;
  const anchor = align === 'left' ? 'start' : align === 'right' ? 'end' : 'middle';
  const posX = align === 'left' ? SAFE_X0 : align === 'right' ? SAFE_X1 : W / 2;
  const boxX = (w) => align === 'left' ? SAFE_X0 : align === 'right' ? SAFE_X1 - w : (W - w) / 2;

  // Matches the real site's .team-chip convention (padding: 3px 8px @
  // font-size 9.5px, ~0.84x ratio) — the one standard used for every pill on
  // this card, chip and handle alike.
  const pillPad = (fsz) => Math.round(fsz * 0.84);
  const textWidth = (str, fsz) => String(str).length * fsz * 0.72;

  const isTeamA    = stat.team_id === game.team_a_id;
  const myTeamName = String(stat.team_name || '').toUpperCase();
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myColor    = escXml(stat.team_color || accent.bg);
  const chipTextColor = myTeamName === 'WHITE' ? '#10141d' : '#fff';
  const myScore  = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won      = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';

  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  // Extra floor tiers below the original 40px — same reasoning as the
  // Hero/Card/Scoreboard fix: untested until a name actually ran this
  // long, at which point 40px alone ran off the canvas edge entirely.
  const nameFsz = displayName.length > 34 ? 30 : displayName.length > 28 ? 34
    : displayName.length > 24 ? 40 : displayName.length > 18 ? 52 : displayName.length > 13 ? 62 : 72;
  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;
  const chipText = `${myTeamName} · #${stat.number ?? ''}`;
  const chipFsz = 20, chipH = 46;

  const HEADER = { barW: 220, barH: 8 };
  const GAP = {
    safeTop: 220, ticksToName: 34, nameToBar: 24, barToContext: 44,
    contextToChip: 40, chipToNumbers: 56, numLabelGap: 30,
    numbersToGauges: 64, gaugeLabelGap: 36, gaugesToHandle: 70,
    numbersToHandleSolo: 90, // gauges off: numbers row goes straight to the handle pill
  };

  function ticksSvg(startX, y) {
    const n = 11, mid = (n - 1) / 2;
    let out = '';
    for (let i = 0; i < n; i++) {
      const x = startX + i * 20;
      const opacity = (0.4 + 0.6 * (1 - Math.abs(i - mid) / mid)).toFixed(2);
      out += `<line x1="${x}" y1="${y + 14}" x2="${x + 8}" y2="${y - 14}" stroke="${accent.bg}" stroke-width="4" stroke-linecap="round" opacity="${opacity}" filter="url(#txt)"/>`;
    }
    return out;
  }
  const ticksWidth = 10 * 20 + 8;

  function buildHeader() {
    const ticksStartX = align === 'left' ? posX : align === 'right' ? posX - ticksWidth : posX - ticksWidth / 2;
    const ticksY = GAP.safeTop;
    const nameY = ticksY + GAP.ticksToName + nameFsz * 0.78;
    const barY  = nameY + GAP.nameToBar;
    const barX  = align === 'left' ? posX : align === 'right' ? posX - HEADER.barW : posX - HEADER.barW / 2;
    const contextY = barY + GAP.barToContext;
    const chipTopY = contextY + GAP.contextToChip;
    const chipPad  = pillPad(chipFsz);
    const chipW    = textWidth(chipText, chipFsz) + chipPad * 2;
    const chipX    = align === 'left' ? posX : align === 'right' ? posX - chipW : posX - chipW / 2;
    const chipBottomY = chipTopY + chipH;

    const svg = `
    ${ticksSvg(ticksStartX, ticksY)}
    <text x="${posX}" y="${nameY}" text-anchor="${anchor}" font-family="${font}" font-size="${nameFsz}" font-weight="900" fill="#ffffff" stroke="#000" stroke-width="5" stroke-opacity="0.3" paint-order="stroke fill" filter="url(#txt)">${displayName}</text>
    <rect x="${barX}" y="${barY}" width="${HEADER.barW}" height="${HEADER.barH}" fill="${accent.bg}" filter="url(#txt)"/>
    <text x="${posX}" y="${contextY}" text-anchor="${anchor}" font-family="${font}" font-size="17" font-weight="700" fill="#e2e8f0" filter="url(#txt)">${contextText}</text>
    <rect x="${chipX}" y="${chipTopY}" width="${chipW}" height="${chipH}" rx="${chipH / 2}" fill="${myColor}" filter="url(#txt)"/>
    <text x="${chipX + chipW / 2}" y="${chipTopY + chipH / 2 + chipFsz * 0.35}" text-anchor="middle" font-family="${font}" font-size="${chipFsz}" font-weight="800" fill="${chipTextColor}">${escXml(chipText)}</text>`;

    return { svg, ticksY, chipBottomY };
  }

  function numberCol(cx, value, label, fsz, baseY, labelY) {
    return `<text x="${cx}" y="${baseY}" text-anchor="middle" font-family="${font}" font-size="${fsz}" font-weight="900" fill="${accent.bg}" stroke="#000" stroke-width="5" stroke-opacity="0.3" paint-order="stroke fill" filter="url(#txt)">${value}</text>
    <text x="${cx}" y="${labelY}" text-anchor="middle" font-family="${font}" font-size="${fsz * 0.19}" font-weight="700" letter-spacing="1.5" fill="#ffffff" filter="url(#txt)">${escXml(label)}</text>`;
  }

  function gaugeCol(cx, cy, r, pct, label, labelY, numFsz, labelFsz) {
    const c = 2 * Math.PI * r;
    const dash = pct === null ? 0 : (pct / 100) * c;
    const track = pct === null
      ? `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${GAUGES_TRACK_COLOR}" stroke-width="10" stroke-opacity="0.35" stroke-dasharray="4 8" filter="url(#txt)"/>`
      : `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${GAUGES_TRACK_COLOR}" stroke-width="10" stroke-opacity="0.3" filter="url(#txt)"/>
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${accent.bg}" stroke-width="10" stroke-linecap="round" stroke-dasharray="${dash} ${c - dash}" transform="rotate(-90 ${cx} ${cy})" filter="url(#txt)"/>`;
    return `${track}
    <text x="${cx}" y="${cy + numFsz * 0.35}" text-anchor="middle" font-family="${font}" font-size="${numFsz}" font-weight="900" fill="#ffffff" fill-opacity="${pct === null ? '0.55' : '1'}" stroke="#000" stroke-width="3" stroke-opacity="0.25" paint-order="stroke fill" filter="url(#txt)">${pct === null ? '—' : pct}</text>
    <text x="${cx}" y="${labelY}" text-anchor="middle" font-family="${font}" font-size="${labelFsz}" font-weight="700" letter-spacing="1.2" fill="#ffffff" filter="url(#txt)">${escXml(label)}</text>`;
  }

  function handlePillSvg(y) {
    const fsz = 21, text = '@WKNDBASKETBALL', dotR = 6;
    const pad = pillPad(fsz);
    const innerW = dotR * 2 + 14 + textWidth(text, fsz);
    const w = innerW + pad * 2;
    const h = fsz + pad * 1.4;
    const x = align === 'left' ? posX : align === 'right' ? posX - w : posX - w / 2;
    return {
      svg: `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${h / 2}" fill="#0b1220" fill-opacity="0.55" stroke="${accent.bg}" stroke-width="2"/>
    <circle cx="${x + pad + dotR}" cy="${y + h / 2}" r="${dotR}" fill="${accent.bg}"/>
    <text x="${x + pad + dotR * 2 + 14}" y="${y + h / 2 + fsz * 0.35}" font-family="${font}" font-size="${fsz}" font-weight="800" fill="#ffffff">${text}</text>`,
      h,
    };
  }

  const { svg: headerSvg, ticksY, chipBottomY } = buildHeader();

  const isCenter = align === 'center';
  const showGauges = opts.gauges !== false;
  // Numbers alone read as sparse in the space normally shared with the gauge
  // row, so they scale up ~1.5x when gauges are off instead of just leaving
  // the reclaimed space empty.
  const numberFsz = isCenter ? (showGauges ? 88 : 132) : (showGauges ? 68 : 102);
  const gaugeR    = isCenter ? 78 : 60;
  // Column centres for k items (3 normally; fewer once Hide zeros drops some): centred
  // around posX, or packed against the left/right edge, same slot width either way.
  const centersFor = k => {
    if (isCenter) return Array.from({ length: k }, (_, i) => posX + (i - (k - 1) / 2) * 300);
    const slot = 460 / 3;
    const blockLeft = align === 'left' ? SAFE_X0 : SAFE_X1 - k * slot;
    return Array.from({ length: k }, (_, i) => blockLeft + slot / 2 + i * slot);
  };

  const focusDef = GAUGES_FOCUS_DEFS[focus] || GAUGES_FOCUS_DEFS.all;
  let numberItems = focusDef.keys.map((key, i) => ({ value: shareStatValue(stat, key), label: focusDef.labels[i], isPct: false }));
  let gaugeDefs = showGauges ? pickBestShootingStats(stat) : [];
  if (opts.hideZeros) {
    const nz = numberItems.filter(x => !isZeroShareStat(x));
    if (nz.length) numberItems = nz;
    gaugeDefs = gaugeDefs.filter(g => !isZeroShareStat({ isPct: true, value: g.pct }));
  }
  const centers = centersFor(numberItems.length);
  const numBaseY = chipBottomY + GAP.chipToNumbers + numberFsz * 0.78;
  const numLabelY = numBaseY + GAP.numLabelGap;

  const numbers = numberItems.map((x, i) =>
    numberCol(centers[i], x.value, x.label, numberFsz, numBaseY, numLabelY)
  ).join('\n');

  let gauges = '', gaugeLabelY = numLabelY, handleY;
  if (gaugeDefs.length) {
    const gaugeCy = numLabelY + GAP.numbersToGauges + gaugeR;
    gaugeLabelY = gaugeCy + gaugeR + GAP.gaugeLabelGap;
    handleY = gaugeLabelY + GAP.gaugesToHandle;

    const gaugeCenters = centersFor(gaugeDefs.length);
    const gaugeNumFsz = isCenter ? 46 : 36, gaugeLabelFsz = isCenter ? 17 : 14;
    gauges = gaugeDefs.map((g, i) =>
      gaugeCol(gaugeCenters[i], gaugeCy, gaugeR, g.pct, g.label, gaugeLabelY, gaugeNumFsz, gaugeLabelFsz)
    ).join('\n');
  } else {
    handleY = numLabelY + GAP.numbersToHandleSolo;
  }

  const { svg: handleSvg, h: handleH } = handlePillSvg(handleY);

  const contentTop = ticksY - 14;
  const contentBottom = handleY + handleH;
  const vshift = H / 2 - (contentTop + contentBottom) / 2;
  // Soft accent glow centered on the stat row(s) — identical convention to the
  // hero number's glow in generateGameStatCardPng/generateGameStatGridPng: a
  // transparent card has no guaranteed contrast against whatever photo ends up
  // underneath it, so this gives the busiest part of the card some built-in
  // separation from the background regardless of the photo's own brightness.
  const glowCy = (numBaseY + gaugeLabelY) / 2 + vshift;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="6" flood-color="#000000" flood-opacity="0.5"/>
    </filter>
    <radialGradient id="glow" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="${accent.bg}" stop-opacity="0.45"/>
      <stop offset="60%" stop-color="${accent.bg}" stop-opacity="0.14"/>
      <stop offset="100%" stop-color="${accent.bg}" stop-opacity="0"/>
    </radialGradient>
    <filter id="blur" x="-100%" y="-100%" width="300%" height="300%">
      <feGaussianBlur stdDeviation="34"/>
    </filter>
  </defs>
  <ellipse cx="${posX}" cy="${glowCy}" rx="360" ry="300" fill="url(#glow)" filter="url(#blur)"/>
  <g transform="translate(0, ${vshift})">
    ${headerSvg}
    ${numbers}
    ${gauges}
    ${handleSvg}
  </g>
</svg>`;

  // Higher supersampling than the other templates' density:144 (1.5x) — this
  // layout leans on thinner strokes and smaller type (the ticks, gauge rings,
  // 14-17px labels) than the bigger/bolder shapes those use, so it benefits
  // more from extra anti-aliasing headroom before the final downsize to 1080x1920.
  return sharp(Buffer.from(svg), { density: 216 }).resize(W, H).png({ compressionLevel: 9 }).toBuffer();
}

// "Bottom" — the fifth "Default"-family template: a broadcast lower-third /
// news-chyron treatment (solid gradient plate instead of relying on glow/
// shadow alone for contrast, everything left-aligned instead of centered, a
// compact single-line stat "deck" instead of a grid or gauges) — but the
// header itself follows the SAME order and GAP values as the rest of the
// "Default" family (name → underline → context → chip, using
// GAP.nameToBar/barToContext/contextToChip verbatim, context as plain text
// with no tag background) rather than its own bespoke rhythm, so it still
// reads as a sibling of Left/Center/Right instead of a different theme that
// happens to share a dropdown. No diagonal ticks or accent rule up top here —
// an earlier version had a solid bar there standing in for them, but it just
// duplicated the underline bar right below the name. No left/right/center
// variants — a chyron is always bottom-anchored.
async function generateGameStatNewsPng(game, stat, focus = 'all', opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const font = COVER_SVG_FONT;
  const SAFE_X0 = 90, SAFE_X1 = 990;

  const pillPad = (fsz) => Math.round(fsz * 0.84);
  const textWidth = (str, fsz) => String(str).length * fsz * 0.72;

  const isTeamA    = stat.team_id === game.team_a_id;
  const myTeamName = String(stat.team_name || '').toUpperCase();
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myColor    = escXml(stat.team_color || accent.bg);
  const chipTextColor = myTeamName === 'WHITE' ? '#10141d' : '#fff';
  const myScore  = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won      = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';

  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  // Left-aligned single line with no wrap, so long names need to shrink more
  // aggressively than the centered grid's name does — an extra floor tier
  // beyond the grid's own, since this headline has no wrap to fall back on.
  // Even the 36px floor wasn't a true floor — an extreme (if currently
  // hypothetical, no real roster name is this long) name at 36px still ran
  // off the right edge, so there's now one tier below that too.
  const nameFsz = displayName.length > 35 ? 28 : displayName.length > 30 ? 36 : displayName.length > 24 ? 44 : displayName.length > 18 ? 58 : displayName.length > 13 ? 70 : 84;
  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;
  const contextFsz = 17;
  const chipText = `${myTeamName} · #${stat.number ?? ''}`;
  const chipFsz = 20, chipH = 46;

  // Same GAP tokens as generateGameStatGaugesPng's header — this is the part
  // that has to match the rest of the family, not reinvent its own spacing.
  // No ticks-equivalent element up top anymore (a plain solid bar there just
  // duplicated the underline bar right below the name), so headerTop is a
  // single top-clearance value feeding straight into the name, not a
  // ticksToName gap after some other element.
  const GAP = { nameToBar: 24, barToContext: 44, contextToChip: 40, chipToDeck: 56, deckToHandle: 70 };

  const plateTop = 1250;
  const headerTop = plateTop + 110;

  const nameY = headerTop + nameFsz * 0.78;
  const barY  = nameY + GAP.nameToBar;
  const barW  = 220, barH = 8;
  // Plain text, no tag background — matches how Left/Center/Right present
  // their own context line, instead of a broadcast-style colored kicker tag.
  const contextY = barY + GAP.barToContext;

  const chipY = contextY + GAP.contextToChip;
  const chipPad = pillPad(chipFsz);
  const chipW = textWidth(chipText, chipFsz) + chipPad * 2;

  const deckY = chipY + chipH + GAP.chipToDeck;
  const showGauges = opts.gauges !== false;
  const focusDef = GAUGES_FOCUS_DEFS[focus] || GAUGES_FOCUS_DEFS.all;
  let deckStats = focusDef.keys.map((key, i) => {
    const def = SHARE_STAT_DEFS.find(d => d.key === key);
    return { value: shareStatValue(stat, key), label: def ? def.short : focusDef.labels[i], isPct: false };
  });
  if (showGauges) {
    pickBestShootingStats(stat).forEach(g => deckStats.push({ value: g.pct, label: g.shortLabel, isPct: true }));
  }
  deckStats = dedupeStatsByLabel(deckStats);

  // "Hide Zeros" drops a 0-value count stat or a no-attempts (null) shooting
  // stat entirely instead of printing "0 AST" or a dash — a dash reads fine
  // inside a ring gauge (it's still occupying a deliberate visual slot) but
  // looks like filler in a plain inline text line. Falls back to the
  // unfiltered list rather than ever rendering a blank deck.
  if (opts.hideZeros) {
    const filtered = deckStats.filter(d => !isZeroShareStat(d));
    if (filtered.length) deckStats = filtered;
  }

  // Fewer items read as sparse at the original size, so the deck scales up
  // the same way the numbers row does elsewhere when gauges are off — this
  // isn't only for Hide Zeros, it applies whenever the deck ends up shorter
  // (e.g. gauges off leaves just the 3 focus stats).
  const deckTier = deckStats.length <= 3 ? { val: 46, label: 22, gap: 44 }
    : deckStats.length <= 5 ? { val: 38, label: 19, gap: 40 }
    : { val: 32, label: 17, gap: 36 };
  const deckValFsz = deckTier.val, deckLabelFsz = deckTier.label, deckGap = deckTier.gap;
  function deckStat(x, value, label, isPct) {
    const display = isPct ? (value === null ? '—' : `${value}%`) : value;
    const valW = textWidth(String(display), deckValFsz) * 1.1;
    const labelW = textWidth(label, deckLabelFsz);
    return {
      svg: `<text x="${x}" y="${deckY}" font-family="${font}" font-size="${deckValFsz}" font-weight="900" fill="${value === null ? '#ffffff' : accent.bg}" fill-opacity="${value === null ? '0.55' : '1'}">${display}</text>
      <text x="${x + valW + 10}" y="${deckY}" font-family="${font}" font-size="${deckLabelFsz}" font-weight="700" letter-spacing="1" fill="#c3cbd8">${escXml(label)}</text>`,
      width: valW + 10 + labelW,
    };
  }
  let cursor = SAFE_X0;
  const deckSvgs = deckStats.map((d) => {
    const item = deckStat(cursor, d.value, d.label, d.isPct);
    cursor += item.width + deckGap;
    return item.svg;
  });

  const handleY = deckY + GAP.deckToHandle;
  const handleFsz = 19, handleText = '@WKNDBASKETBALL', dotR = 6;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <linearGradient id="plate" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#020817" stop-opacity="0"/>
      <stop offset="55%" stop-color="#020817" stop-opacity="0.85"/>
      <stop offset="100%" stop-color="#020817" stop-opacity="0.96"/>
    </linearGradient>
  </defs>
  <rect x="0" y="${plateTop}" width="${W}" height="${H - plateTop}" fill="url(#plate)"/>
  <text x="${SAFE_X0}" y="${nameY}" font-family="${font}" font-size="${nameFsz}" font-weight="900" fill="#ffffff">${displayName}</text>
  <rect x="${SAFE_X0}" y="${barY}" width="${barW}" height="${barH}" fill="${accent.bg}"/>
  <text x="${SAFE_X0}" y="${contextY}" font-family="${font}" font-size="${contextFsz}" font-weight="700" fill="#e2e8f0">${contextText}</text>
  <rect x="${SAFE_X0}" y="${chipY}" width="${chipW}" height="${chipH}" rx="${chipH / 2}" fill="${myColor}"/>
  <text x="${SAFE_X0 + chipW / 2}" y="${chipY + chipH / 2 + chipFsz * 0.35}" text-anchor="middle" font-family="${font}" font-size="${chipFsz}" font-weight="800" fill="${chipTextColor}">${escXml(chipText)}</text>
  ${deckSvgs.join('\n')}
  <circle cx="${SAFE_X0 + dotR}" cy="${handleY - handleFsz * 0.35}" r="${dotR}" fill="${accent.bg}"/>
  <text x="${SAFE_X0 + dotR * 2 + 10}" y="${handleY}" font-family="${font}" font-size="${handleFsz}" font-weight="700" letter-spacing="1" fill="#8b98ab">${handleText}</text>
</svg>`;

  return sharp(Buffer.from(svg), { density: 216 }).resize(W, H).png({ compressionLevel: 9 }).toBuffer();
}

// "Stacked" — the fourth "Default"-family template: a single-column stat-sheet
// list instead of a grid. A 3-column layout doesn't un-fold cleanly into one
// column, so this isn't a re-flow of generateGameStatGaugesPng's grid — each
// focus stat gets its own full-width row (label left, big number right), and
// each shooting-% stat gets the same row shape plus a thin horizontal progress
// bar standing in for the circular gauge (the ring's fill-amount cue still
// needs to exist somehow once it's not a ring). Always center-anchored — this
// template doesn't have its own left/right variants.
async function generateGameStatStackedPng(game, stat, focus = 'all', opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const font = COVER_SVG_FONT;
  const SAFE_X0 = 90, SAFE_X1 = 990;
  const posX = W / 2, anchor = 'middle';

  const pillPad = (fsz) => Math.round(fsz * 0.84);
  const textWidth = (str, fsz) => String(str).length * fsz * 0.72;

  const isTeamA    = stat.team_id === game.team_a_id;
  const myTeamName = String(stat.team_name || '').toUpperCase();
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myColor    = escXml(stat.team_color || accent.bg);
  const chipTextColor = myTeamName === 'WHITE' ? '#10141d' : '#fff';
  const myScore  = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won      = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';

  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  // Extra floor tiers below the original 40px — same reasoning as the
  // Hero/Card/Scoreboard fix: untested until a name actually ran this
  // long, at which point 40px alone ran off the canvas edge entirely.
  const nameFsz = displayName.length > 34 ? 30 : displayName.length > 28 ? 34
    : displayName.length > 24 ? 40 : displayName.length > 18 ? 52 : displayName.length > 13 ? 62 : 72;
  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;
  const chipText = `${myTeamName} · #${stat.number ?? ''}`;
  const chipFsz = 20, chipH = 46;

  const showGauges = opts.gauges !== false;
  const focusDef = GAUGES_FOCUS_DEFS[focus] || GAUGES_FOCUS_DEFS.all;
  let rows = focusDef.keys.map((key, i) => ({ label: focusDef.labels[i], value: shareStatValue(stat, key), isPct: false }));
  if (showGauges) {
    pickBestShootingStats(stat).forEach(g => rows.push({ label: g.label, value: g.pct, isPct: true }));
  }
  rows = dedupeStatsByLabel(rows);
  // "Hide Zeros" drops a 0-value stat row or a no-attempts (null) shooting
  // row entirely rather than showing "0 ASSISTS" or a dashed bar — falls back
  // to the unfiltered list rather than ever rendering an empty sheet.
  if (opts.hideZeros) {
    const filtered = rows.filter(r => !isZeroShareStat(r));
    if (filtered.length) rows = filtered;
  }

  // Rows scale up the fewer of them there are — same instinct as the grid
  // template's bigger numbers with gauges off, generalized so it also kicks
  // in whenever Hide Zeros thins the list, not just when gauges are off.
  const rowTier = rows.length <= 3 ? { row: 132, val: 72, label: 26 }
    : rows.length <= 5 ? { row: 112, val: 64, label: 24 }
    : { row: 96, val: 56, label: 22 };
  const rowH = rowTier.row, valueFsz = rowTier.val, labelFsz = rowTier.label;

  function ticksSvg(startX, y) {
    const n = 11, mid = (n - 1) / 2;
    let out = '';
    for (let i = 0; i < n; i++) {
      const x = startX + i * 20;
      const opacity = (0.4 + 0.6 * (1 - Math.abs(i - mid) / mid)).toFixed(2);
      out += `<line x1="${x}" y1="${y + 14}" x2="${x + 8}" y2="${y - 14}" stroke="${accent.bg}" stroke-width="4" stroke-linecap="round" opacity="${opacity}" filter="url(#txt)"/>`;
    }
    return out;
  }
  const ticksWidth = 10 * 20 + 8;

  const GAP = { safeTop: 220, ticksToName: 34, nameToBar: 24, barToContext: 44, contextToChip: 40, chipToList: 70, listToHandle: 60 };

  const ticksY = GAP.safeTop;
  const nameY = ticksY + GAP.ticksToName + nameFsz * 0.78;
  const barY  = nameY + GAP.nameToBar;
  const barW  = 220, barH = 8;
  const contextY = barY + GAP.barToContext;
  const chipTopY = contextY + GAP.contextToChip;
  const chipPad  = pillPad(chipFsz);
  const chipW    = textWidth(chipText, chipFsz) + chipPad * 2;
  const chipBottomY = chipTopY + chipH;

  const headerSvg = `
  ${ticksSvg(posX - ticksWidth / 2, ticksY)}
  <text x="${posX}" y="${nameY}" text-anchor="${anchor}" font-family="${font}" font-size="${nameFsz}" font-weight="900" fill="#ffffff" stroke="#000" stroke-width="5" stroke-opacity="0.3" paint-order="stroke fill" filter="url(#txt)">${displayName}</text>
  <rect x="${posX - barW / 2}" y="${barY}" width="${barW}" height="${barH}" fill="${accent.bg}" filter="url(#txt)"/>
  <text x="${posX}" y="${contextY}" text-anchor="${anchor}" font-family="${font}" font-size="17" font-weight="700" fill="#e2e8f0" filter="url(#txt)">${contextText}</text>
  <rect x="${posX - chipW / 2}" y="${chipTopY}" width="${chipW}" height="${chipH}" rx="${chipH / 2}" fill="${myColor}" filter="url(#txt)"/>
  <text x="${posX}" y="${chipTopY + chipH / 2 + chipFsz * 0.35}" text-anchor="middle" font-family="${font}" font-size="${chipFsz}" font-weight="800" fill="${chipTextColor}">${escXml(chipText)}</text>`;

  function statRow(y, label, value, isPct) {
    const baseline = y + rowH / 2 + valueFsz * 0.32;
    const displayValue = isPct ? (value === null ? '—' : `${value}%`) : value;
    // Percentage rows use the progress bar itself as the row's bottom
    // marker instead of also drawing the plain divider every other row
    // gets — the two stacked right on top of each other read as a
    // redundant "double bar" rather than one clean row-end.
    let bottomMarker;
    if (isPct) {
      const barY2 = y + rowH - 10, barTrackW = SAFE_X1 - SAFE_X0;
      const fillW = value === null ? 0 : barTrackW * (value / 100);
      bottomMarker = `<rect x="${SAFE_X0}" y="${barY2}" width="${barTrackW}" height="6" rx="3" fill="#ffffff" fill-opacity="0.18" filter="url(#txt)"/>
      ${value !== null ? `<rect x="${SAFE_X0}" y="${barY2}" width="${fillW}" height="6" rx="3" fill="${accent.bg}" filter="url(#txt)"/>` : ''}`;
    } else {
      bottomMarker = `<line x1="${SAFE_X0}" y1="${y + rowH}" x2="${SAFE_X1}" y2="${y + rowH}" stroke="#ffffff" stroke-opacity="0.14" stroke-width="1.5"/>`;
    }
    return `
    <text x="${SAFE_X0}" y="${baseline}" font-family="${font}" font-size="${labelFsz}" font-weight="700" letter-spacing="1.5" fill="#e2e8f0" filter="url(#txt)">${escXml(label)}</text>
    <text x="${SAFE_X1}" y="${baseline}" text-anchor="end" font-family="${font}" font-size="${valueFsz}" font-weight="900" fill="${value === null ? '#ffffff' : accent.bg}" fill-opacity="${value === null ? '0.55' : '1'}" stroke="#000" stroke-width="4" stroke-opacity="0.3" paint-order="stroke fill" filter="url(#txt)">${displayValue}</text>
    ${bottomMarker}`;
  }

  const listTop = chipBottomY + GAP.chipToList;
  const rowsSvg = rows.map((r, i) => statRow(listTop + i * rowH, r.label, r.value, r.isPct)).join('\n');
  const listBottom = listTop + rows.length * rowH;

  const handleY = listBottom + GAP.listToHandle;
  const handleFsz = 21, handleText = '@WKNDBASKETBALL', dotR = 6;
  const handlePad = pillPad(handleFsz);
  const handleInnerW = dotR * 2 + 14 + textWidth(handleText, handleFsz);
  const handleW = handleInnerW + handlePad * 2, handleH = handleFsz + handlePad * 1.4;
  const handleSvg = `<rect x="${posX - handleW / 2}" y="${handleY}" width="${handleW}" height="${handleH}" rx="${handleH / 2}" fill="#0b1220" fill-opacity="0.55" stroke="${accent.bg}" stroke-width="2"/>
  <circle cx="${posX - handleW / 2 + handlePad + dotR}" cy="${handleY + handleH / 2}" r="${dotR}" fill="${accent.bg}"/>
  <text x="${posX - handleW / 2 + handlePad + dotR * 2 + 14}" y="${handleY + handleH / 2 + handleFsz * 0.35}" font-family="${font}" font-size="${handleFsz}" font-weight="800" fill="#ffffff">${handleText}</text>`;

  const contentTop = ticksY - 14;
  const contentBottom = handleY + handleH;
  const vshift = H / 2 - (contentTop + contentBottom) / 2;
  const glowCy = (chipBottomY + listBottom) / 2 + vshift;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="6" flood-color="#000000" flood-opacity="0.5"/>
    </filter>
    <radialGradient id="glow" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="${accent.bg}" stop-opacity="0.4"/>
      <stop offset="60%" stop-color="${accent.bg}" stop-opacity="0.12"/>
      <stop offset="100%" stop-color="${accent.bg}" stop-opacity="0"/>
    </radialGradient>
    <filter id="blur" x="-100%" y="-100%" width="300%" height="300%">
      <feGaussianBlur stdDeviation="34"/>
    </filter>
  </defs>
  <ellipse cx="${posX}" cy="${glowCy}" rx="380" ry="${(listBottom - chipBottomY) / 2 + 60}" fill="url(#glow)" filter="url(#blur)"/>
  <g transform="translate(0, ${vshift})">
    ${headerSvg}
    ${rowsSvg}
    ${handleSvg}
  </g>
</svg>`;

  return sharp(Buffer.from(svg), { density: 216 }).resize(W, H).png({ compressionLevel: 9 }).toBuffer();
}

// Renders `text` alone, off-canvas, to measure its real rendered pixel width
// at a given font/size/weight/letter-spacing via sharp's trim() — used by
// Premium below instead of a char-count*fontsize guess. That guess (tried
// first) used one flat ratio regardless of name length, which overestimates
// short names at Premium's larger font tiers far more than long names at its
// smaller ones (letter-spacing's fixed per-character contribution is a much
// bigger fraction of a short string's total width), so a gap constant tuned
// against one name length left a visibly oversized gap for others. Actually
// measuring removes the guesswork entirely. A probe costs ~0.2 s at the big sizes, so widths
// are remembered: the same names and words come back on every card.
const TEXT_WIDTHS = new Map();
function measureTextWidth(text, { fontFamily, fontSize, fontWeight = 800, letterSpacing = 7 }) {
  const k = [text, fontFamily, fontSize, fontWeight, letterSpacing].join('|');
  if (!TEXT_WIDTHS.has(k)) {
    if (TEXT_WIDTHS.size > 5000) TEXT_WIDTHS.clear();
    TEXT_WIDTHS.set(k, probeTextWidth(text, { fontFamily, fontSize, fontWeight, letterSpacing }));
  }
  return TEXT_WIDTHS.get(k);
}
async function probeTextWidth(text, { fontFamily, fontSize, fontWeight, letterSpacing }) {
  const canvasW = Math.ceil(text.length * fontSize * 1.3) + 200;
  const canvasH = Math.ceil(fontSize * 2);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${canvasW}" height="${canvasH}">
    <rect width="${canvasW}" height="${canvasH}" fill="#000000"/>
    <text x="100" y="${Math.round(canvasH * 0.7)}" font-family="${fontFamily}" font-size="${fontSize}" font-weight="${fontWeight}" letter-spacing="${letterSpacing}" fill="#ffffff">${text}</text>
  </svg>`;
  try {
    const { info } = await sharp(Buffer.from(svg), { density: 216 })
      .trim({ background: '#000000', threshold: 10 })
      .toBuffer({ resolveWithObject: true });
    return info.width / (216 / 72); // trim already excludes the padding; just descale to user units
  } catch {
    // trim() throws on an all-background image (e.g. empty text) — fall back
    // to the old rough guess rather than let card generation fail outright.
    return text.length * fontSize * 0.64 + letterSpacing * Math.max(0, text.length - 1);
  }
}

// "Premium" — a deliberately different theme from the "Default" family above
// (Left/Center/Right/Bottom/Stacked all share one visual language; this one
// doesn't). Broadcast-graphic composition: the whole content cluster (rotated
// player name + accent line, stat rows, context pill, handle, and the WKND
// watermark itself) lives on the LEFT and is anchored to the BOTTOM of the
// canvas, built upward from the handle line rather than down from a fixed top
// offset. The rotated name and the accent line share one column
// ("PLAYER NAME ------"): the line covers the height of the stats +
// context/handle block MINUS the name's own span, so it stops right where the
// name begins instead of running back through it. WKND (not "POTG" — this
// card is any player's line, not just the player of the game, so that label
// would be wrong here anyway) is rotated with the rest of the column and
// stretched via textLength to exactly cover the height of the stats,
// centered behind the numbers. Stat selection is its own thing, not
// Bottom/Stacked's Focus-driven pick: all 6 common count stats are shown,
// ranked highest value to lowest, then the best-of-4 shooting pick adds up to
// 3 more (9 max) — there was room for the extra 3 once the layout tightened
// up, and showing everything ranked is more useful here than picking 3 by
// category. `focus` is accepted (the route always passes it) but genuinely
// unused — same "control stays visible but has nothing to affect" pattern as
// Stacked already ignoring alignment. Hide Zeros still drops any zero/no-
// attempt entry same as everywhere else. Still a transparent overlay like
// every other template (no baked-in photo) — a left-to-right dark gradient
// scrim + a warm radial glow stand in for a photo's own contrast. The single
// highest stat gets a dedicated "hero" treatment (bigger, accent-colored,
// glowing) — everywhere else, accent only touches the watermark stroke, the
// line, and the context pill, never the (deliberately plain white) numbers.
// opts.side 'right' ("Premium R") mirrors the whole cluster onto the right edge:
// every x goes through mx(), text anchors at its end, and the rotated name and
// WKND keep reading bottom-to-top, so their pivots move by a cap height.
async function generateGameStatPremiumPng(game, stat, focus = 'all', opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const right = opts.side === 'right';
  const mx = x => (right ? W - x : x);
  const anchor = right ? ' text-anchor="end"' : '';
  const font = COVER_SVG_FONT;
  // Premium-only typographic departure from the rest of the family (which all use
  // COVER_SVG_FONT throughout): the big stat numbers in the site's own numerals font
  // (Saira Condensed), their small labels in the site's own body font (Archivo) — see
  // the Design System section of CLAUDE.md. Both fall back to COVER_SVG_FONT so a card
  // still renders correctly wherever the custom fonts aren't registered with the
  // server's font engine (see the fontconfig setup near __dirname above) rather than
  // falling through to an ugly system default.
  const valueFont = `'Saira Condensed', ${font}`;
  const labelFont = `'Archivo', ${font}`;

  const isTeamA = stat.team_id === game.team_a_id;
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myScore = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';
  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;
  const handleText = `@WKNDBASKETBALL`;

  // Jersey number + a separator lead the rotated name now ("#34 · GIANNIS
  // ...") since the handle line no longer carries the number itself.
  const numberPrefix = `#${stat.number ?? ''} · `;
  const displayName = escXml((numberPrefix + formatName(stat.name || '')).toUpperCase());
  const nameFsz = displayName.length > 24 ? 34 : displayName.length > 18 ? 40 : 46;

  // All 6 common count stats, ranked highest value to lowest — not Focus's
  // pick-3-by-category (see this function's own comment for why) — then the
  // best-of-4 shooting stats appended after, unranked among themselves since
  // they're already in a fixed, deliberate display order (see
  // pickBestShootingStats). Excludes SHARE_STAT_DEFS's own 'fgpct' entry (used
  // elsewhere for the Default family's hero-stat picker) — leaving it in
  // double-counted field goal % here: once mislabeled as a plain count
  // (sorted numerically alongside real counts, no null/no-attempt handling),
  // and again correctly from pickBestShootingStats below.
  let STATS = SHARE_STAT_DEFS
    .filter(def => def.key !== 'fgpct')
    .map(def => ({ label: def.short, value: shareStatValue(stat, def.key), isPct: false }))
    .sort((a, b) => b.value - a.value);
  pickBestShootingStats(stat).forEach(g => STATS.push({ label: `${g.shortLabel}%`, value: g.pct, isPct: true }));
  STATS = dedupeStatsByLabel(STATS);
  if (opts.hideZeros) {
    const filtered = STATS.filter(s => !isZeroShareStat(s));
    if (filtered.length) STATS = filtered;
  }

  // Whole content cluster (name+line, stats, context, handle) lives on the
  // left and is anchored to the bottom of the canvas, built upward from
  // there instead of starting from a fixed top offset — mirrors how it
  // reads: bottom-heaviest content (the handle) anchors first, everything
  // else stacks above it.
  const colX = 150; // stat numbers/labels + context/handle
  const nameLineX = 90; // rotated name + accent line share this column

  // Fewer rows (Hide Zeros, or no shooting attempts to add on top of the 6
  // count stats) scale up the same way Bottom/Stacked do, instead of leaving
  // the reclaimed space empty. Extra tiers below 5 exist because the max grew
  // from 6 to 9 (all 6 count stats now, not Focus's pick-3) — the old
  // 6-and-up bucket's sizing was tuned for exactly 6 and would crowd 9. Every
  // tier here is the original sizing scaled up by the same ratio the 8-9 row
  // bucket was bumped by during the redesign, so the relative jump between
  // tiers stays consistent.
  const tier = STATS.length <= 3 ? { row: 274, num: 113, label: 25 }
    : STATS.length <= 5 ? { row: 232, num: 100, label: 23 }
    : STATS.length <= 7 ? { row: 190, num: 82, label: 19 }
    : { row: 158, num: 68, label: 17 };
  const rowH = tier.row, numberFsz = tier.num, labelFsz = tier.label;
  const heroNumberFsz = Math.round(numberFsz * 1.55);

  // Baseline-to-baseline gap between a row's label and the NEXT row's
  // number, reused below for every transition in the column (label-to-next-
  // number between stat rows, hero-to-first-regular-row, AND last-row-to-
  // pill) so the rhythm reads consistently instead of the pill having its
  // own tighter, one-off gap above it.
  const interRowGap = rowH - labelFsz - 20;

  const bottomPad = 90;
  const handleY = H - bottomPad;
  // Rotated elements: the text's own x/y must equal the rotation pivot —
  // rotating around a point other than the text's own anchor swings it to a
  // totally different location instead of pivoting it in place. nameY sits
  // exactly at handleY (not offset below it) so the rotated column's own
  // bottom-most glyphs ("#<number>") land flush with the handle text's own
  // baseline — neither string has descenders, so matching baselines here
  // also matches their visible bottom edges.
  const nameX = nameLineX, nameY = handleY;
  const contextY = handleY - 40;

  // Context pill: text is centered both axes (text-anchor + dominant-baseline)
  // rather than left-aligned against a baseline calculation, so padding stays
  // visually equal on both sides and the text stays vertically centered
  // regardless of the width estimate's accuracy or this particular font's
  // metrics.
  const pillPadX = 8, pillH = 44;
  const pillW = Math.round(contextText.length * 11.2 + pillPadX * 2);
  const pillX = right ? W - colX + pillPadX - pillW : colX - pillPadX;
  const pillY = contextY - pillH + 12;
  const pillCx = pillX + pillW / 2;
  const pillCy = pillY + pillH / 2;

  // Row Y-positions are built bottom-up: the last stat row sits interRowGap
  // above the pill's own top edge (the same gap used between every other
  // pair of rows, so the last row doesn't read closer to the pill than any
  // two stats read to each other), then the REGULAR rows (everything but
  // the hero, STATS[0]) stack upward from there, then the hero goes above
  // THEM using that identical gap formula too — so the hero (a much bigger
  // number, but the same label size) doesn't end up with a mismatched,
  // tighter gap to the row below it.
  const lastLabelY = pillY - interRowGap;
  const lastNumY = lastLabelY - labelFsz - 20;
  const regularStats = STATS.slice(1);
  const regularNumYs = regularStats.map((_, kFromBottom) => lastNumY - kFromBottom * rowH).reverse();
  const heroLabelY = (regularNumYs[0] ?? lastNumY) - interRowGap;
  const heroNumY = heroLabelY - labelFsz - 20;

  const heroDisplay = STATS.length ? (STATS[0].isPct ? (STATS[0].value === null ? '—' : STATS[0].value) : STATS[0].value) : '';
  const heroRow = STATS.length ? `<text x="${mx(colX)}"${anchor} y="${heroNumY}" font-family="${valueFont}" font-size="${heroNumberFsz}" font-weight="900" fill="${accent.bg}" stroke="#000" stroke-width="4" stroke-opacity="0.35" paint-order="stroke fill" filter="url(#glow)">${heroDisplay}</text>
    <text x="${mx(colX)}"${anchor} y="${heroLabelY}" font-family="${labelFont}" font-size="${labelFsz}" font-weight="700" letter-spacing="3" fill="#c3cbd8" filter="url(#txt)">${escXml(STATS[0].label)}</text>` : '';

  const rows = regularStats.map((s, i) => {
    const numY = regularNumYs[i];
    const labelY = numY + labelFsz + 20;
    const display = s.isPct ? (s.value === null ? '—' : s.value) : s.value;
    return `<text x="${mx(colX)}"${anchor} y="${numY}" font-family="${valueFont}" font-size="${numberFsz}" font-weight="900" fill="#ffffff" fill-opacity="${s.isPct && s.value === null ? '0.5' : '1'}" stroke="#000" stroke-width="4" stroke-opacity="0.35" paint-order="stroke fill" filter="url(#txt)">${display}</text>
    <text x="${mx(colX)}"${anchor} y="${labelY}" font-family="${labelFont}" font-size="${labelFsz}" font-weight="700" letter-spacing="3" fill="#c3cbd8" filter="url(#txt)">${escXml(s.label)}</text>`;
  }).join('\n');

  // Accent line covers the remaining space above the name up to the stats —
  // "PLAYER NAME ------" continuing on until it reaches the same level as
  // the hero number, not just matching the name's own short height. A gap
  // keeps it from touching the name, and it's centered on the name's actual
  // glyph strokes rather than the text's baseline pivot: for rotated text
  // the glyphs render on the ascender side of that pivot (i.e. offset to one
  // side once rotated), so the visual center sits half a cap-height away
  // from it, not at the pivot itself. nameWidth is the name's real rendered
  // pixel width (see measureTextWidth above) — a plain char-count*fontsize
  // guess here overestimates by a very different amount depending on name
  // length and font-size tier, which left a visibly oversized gap for short
  // names even after a gap constant was tuned against a long one.
  const statBlockTop = heroNumY - heroNumberFsz * 0.78;
  const nameWidth = await measureTextWidth(displayName, { fontFamily: font, fontSize: nameFsz, fontWeight: 800, letterSpacing: 7 });
  const nameTop = nameY - nameWidth;
  const lineGap = 20;
  const nameCap = nameFsz * 0.72;
  const namePivotX = right ? W - nameX + nameCap : nameX;
  const lineX = mx(nameX - nameCap / 2), lineTop = statBlockTop, lineBottom = nameTop - lineGap;

  // WKND watermark: rotated, big, and pinned flush to the canvas's own
  // bottom-left corner (not the stat block's) — "0 left" means the OUTER
  // edge of the glyphs touches x=0, and since a font's cap-height sits above
  // the baseline, the pivot x has to sit one cap-height in from the edge for
  // that outer edge to land at 0. "0 bottom" means the pivot y (where the
  // text starts, which becomes the BOTTOM after the rotation) sits right at
  // the canvas bottom. Stretched via textLength to cover the full column —
  // stats, the accent line, AND the player name below them — not just the
  // stats on their own.
  const wkndFont = `Georgia, 'Times New Roman', serif`;
  const wkndFsz = 380;
  const wkndSpan = nameY - statBlockTop;
  const wkndCapHeight = wkndFsz * 0.72;
  const wkndX = right ? W - 4 : wkndCapHeight + 4;
  const wkndY = H - 4;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="6" flood-color="#000000" flood-opacity="0.55"/>
    </filter>
    <filter id="glow" x="-60%" y="-60%" width="220%" height="220%">
      <feDropShadow dx="0" dy="0" stdDeviation="14" flood-color="${accent.bg}" flood-opacity="0.65"/>
      <feDropShadow dx="0" dy="2" stdDeviation="6" flood-color="#000000" flood-opacity="0.5"/>
    </filter>
    <linearGradient id="scrim" x1="${right ? 1 : 0}" y1="0" x2="${right ? 0 : 1}" y2="0">
      <stop offset="0%" stop-color="#020817" stop-opacity="0.92"/>
      <stop offset="40%" stop-color="#020817" stop-opacity="0.72"/>
      <stop offset="75%" stop-color="#020817" stop-opacity="0.25"/>
      <stop offset="100%" stop-color="#020817" stop-opacity="0"/>
    </linearGradient>
    <radialGradient id="glowbg" cx="${right ? 85 : 15}%" cy="78%" r="55%">
      <stop offset="0%" stop-color="${accent.bg}" stop-opacity="0.35"/>
      <stop offset="100%" stop-color="${accent.bg}" stop-opacity="0"/>
    </radialGradient>
  </defs>

  <rect x="${right ? W - 480 : 0}" y="0" width="480" height="${H}" fill="url(#scrim)"/>
  <rect x="${right ? W - 480 : 0}" y="0" width="480" height="${H}" fill="url(#glowbg)"/>

  <text x="${wkndX}" y="${wkndY}" transform="rotate(-90 ${wkndX} ${wkndY})" font-family="${wkndFont}" font-size="${wkndFsz}" font-weight="700" textLength="${wkndSpan}" lengthAdjust="spacing" fill="none" stroke="${accent.bg}" stroke-width="3" stroke-opacity="0.26">WKND</text>

  <line x1="${lineX}" y1="${lineTop}" x2="${lineX}" y2="${lineBottom}" stroke="${accent.bg}" stroke-width="2" opacity="0.55"/>

  <text x="${namePivotX}" y="${nameY}" transform="rotate(-90 ${namePivotX} ${nameY})" font-family="${font}" font-size="${nameFsz}" font-weight="800" letter-spacing="7" fill="#ffffff" filter="url(#txt)">${displayName}</text>

  ${heroRow}

  ${rows}

  <rect x="${pillX}" y="${pillY}" width="${pillW}" height="${pillH}" rx="${pillH / 2}" fill="${accent.bg}"/>
  <text x="${pillCx}" y="${pillCy}" text-anchor="middle" dominant-baseline="central" font-family="${font}" font-size="19" font-weight="700" fill="${accent.text}">${contextText}</text>

  <text x="${mx(colX)}"${anchor} y="${handleY}" font-family="${font}" font-size="18" font-weight="700" letter-spacing="1.5" fill="#c3cbd8">${escXml(handleText)}</text>
</svg>`;

  return sharp(Buffer.from(svg), { density: 216 }).resize(W, H).png({ compressionLevel: 9 }).toBuffer();
}

// "Hero" — the fifth "Default"-family template (same COVER_SVG_FONT-only
// typography and bottom-anchored plate convention as Bottom/Stacked, not
// Premium's own broadcast theme): deliberately minimalist, one auto-picked
// stat blown up as large as anything on any template, with generous empty
// space above it instead of a multi-stat deck. Picks the single highest-
// value count stat (same 6-stat pool as Premium, fgpct excluded — see that
// function's own comment for why) rather than anything Focus-driven, since
// there's only room for one number and "whatever this player did best"
// reads better than a fixed category pick that might be their worst stat.
async function generateGameStatHeroPng(game, stat, opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const font = COVER_SVG_FONT;
  const SAFE_X0 = 90;

  const isTeamA = stat.team_id === game.team_a_id;
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myScore = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';
  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;
  const handleText = '@WKNDBASKETBALL';

  const hero = SHARE_STAT_DEFS
    .filter(def => def.key !== 'fgpct')
    .map(def => ({ ...def, value: shareStatValue(stat, def.key) }))
    .sort((a, b) => b.value - a.value)[0];

  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  // Extra floor tiers below the original 40px — same "no wrap to fall back
  // on" reasoning as generateGameStatNewsPng's own 5-tier ladder: a name past
  // ~30 characters at 40px still ran off the right edge entirely untested
  // until it was actually tried.
  const nameFsz = displayName.length > 30 ? 30 : displayName.length > 24 ? 34
    : displayName.length > 20 ? 40 : displayName.length > 14 ? 48 : 56;

  const heroNumberFsz = 280, heroLabelFsz = 28;
  const barW = 220, barH = 8;

  // Bottom-up: the handle anchors first, everything else stacks above it —
  // same pattern as every other template in this file, so reclaiming/losing
  // vertical space (a longer name, a wider hero number) never leaves dead
  // space or overflow at a fixed top offset.
  const bottomPad = 90;
  const handleY = H - bottomPad;
  const contextY = handleY - 40;
  const nameY = contextY - 68;
  const barY = nameY + 24;
  const heroLabelY = nameY - 160;
  const heroNumberY = heroLabelY - heroLabelFsz - 20;
  const plateTop = heroNumberY - heroNumberFsz * 0.85 - 40;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="6" flood-color="#000000" flood-opacity="0.55"/>
    </filter>
    <linearGradient id="plate" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#020817" stop-opacity="0"/>
      <stop offset="55%" stop-color="#020817" stop-opacity="0.85"/>
      <stop offset="100%" stop-color="#020817" stop-opacity="0.96"/>
    </linearGradient>
  </defs>
  <rect x="0" y="${plateTop}" width="${W}" height="${H - plateTop}" fill="url(#plate)"/>

  <text x="${SAFE_X0}" y="${heroNumberY}" font-family="${font}" font-size="${heroNumberFsz}" font-weight="900" fill="${accent.bg}" filter="url(#txt)">${hero.value}</text>
  <text x="${SAFE_X0}" y="${heroLabelY}" font-family="${font}" font-size="${heroLabelFsz}" font-weight="700" letter-spacing="8" fill="#c3cbd8" filter="url(#txt)">${escXml(hero.long)}</text>

  <text x="${SAFE_X0}" y="${nameY}" font-family="${font}" font-size="${nameFsz}" font-weight="900" fill="#ffffff" filter="url(#txt)">${displayName}</text>
  <rect x="${SAFE_X0}" y="${barY}" width="${barW}" height="${barH}" fill="${accent.bg}"/>

  <text x="${SAFE_X0}" y="${contextY}" font-family="${font}" font-size="19" font-weight="700" fill="#e2e8f0" filter="url(#txt)">${contextText}</text>
  <circle cx="${SAFE_X0 + 6}" cy="${handleY - 6}" r="6" fill="${accent.bg}"/>
  <text x="${SAFE_X0 + 22}" y="${handleY}" font-family="${font}" font-size="18" font-weight="700" letter-spacing="1" fill="#8b98ab">${handleText}</text>
</svg>`;

  return sharp(Buffer.from(svg), { density: 216 }).resize(W, H).png({ compressionLevel: 9 }).toBuffer();
}

// "Card" — a portrait trading-card frame with a genuine transparent cutout
// (an SVG mask, not just a decorative outline drawn over an opaque fill — a
// dashed-border-only version of this shipped once already and it wasn't
// actually see-through) for the player's own photo, framed by an opaque
// header (name/number) and footer (curated stats/context/handle). The photo
// window's height is DERIVED from the header/footer heights, not a fixed
// number, so it always exactly fills whatever's left between them regardless
// of card size. The MVP-style corner ribbon is clipped to the card's own
// rounded silhouette (an explicit clipPath, not an accidental rounded-corner
// overlap that only ever worked by coincidence) so it can't spill past the
// card's own edge. opts.hideRibbon drops it entirely — passed by the route
// when the Badge overlay is also being composited on top, since Badge's own
// medal sits in that same corner and (being much bigger) ends up hiding the
// ribbon almost completely anyway; the two also say overlapping things (both
// are "look at this standout stat"), so suppressing the redundant one is the
// right call, not just a collision workaround.
async function generateGameStatTradingCardPng(game, stat, opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const font = COVER_SVG_FONT;

  const isTeamA = stat.team_id === game.team_a_id;
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myScore = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';
  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;
  const handleText = '@WKNDBASKETBALL';

  const ranked = SHARE_STAT_DEFS
    .filter(def => def.key !== 'fgpct')
    .map(def => ({ ...def, value: shareStatValue(stat, def.key) }))
    .sort((a, b) => b.value - a.value);
  const hero = ranked[0];
  // Curated: the top 4 by value — a trading card's back-of-card stat line is
  // a handful of headline numbers, not the full 6-stat sheet Premium shows.
  const curated = ranked.slice(0, 4);

  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  // Same extra-floor-tier fix as Hero/Scoreboard — a name past ~30 characters
  // at 40px ran straight off the card's right edge.
  const nameFsz = displayName.length > 30 ? 28 : displayName.length > 24 ? 32
    : displayName.length > 18 ? 40 : displayName.length > 13 ? 48 : 56;

  const cardMargin = 50;
  const cardX = cardMargin, cardY = cardMargin, cardW = W - cardMargin * 2, cardH = H - cardMargin * 2;
  const cardR = 32;
  const cardBottom = cardY + cardH;

  const headerH = 210;
  const footerH = 320;
  const headerBottom = cardY + headerH;
  const footerTop = cardBottom - footerH;
  const windowY = headerBottom, windowH = footerTop - headerBottom;

  const colCount = curated.length;
  const colW = cardW / colCount;
  const statNumFsz = 46, statLabelFsz = 16;
  const statY = footerTop + 90;
  const statLabelY = statY + statLabelFsz + 16;

  const contextY = footerTop + 210;
  const handleY = cardBottom - 34;

  const ribbonText = `${hero.value} ${escXml(hero.short)}`;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="5" flood-color="#000000" flood-opacity="0.5"/>
    </filter>
    <clipPath id="cardClip">
      <rect x="${cardX}" y="${cardY}" width="${cardW}" height="${cardH}" rx="${cardR}"/>
    </clipPath>
    <mask id="windowMask">
      <rect x="${cardX}" y="${cardY}" width="${cardW}" height="${cardH}" rx="${cardR}" fill="#fff"/>
      <rect x="${cardX}" y="${windowY}" width="${cardW}" height="${windowH}" fill="#000"/>
    </mask>
  </defs>

  <rect x="${cardX}" y="${cardY}" width="${cardW}" height="${cardH}" rx="${cardR}" fill="#0d1424" fill-opacity="0.94" mask="url(#windowMask)"/>
  <rect x="${cardX}" y="${cardY}" width="${cardW}" height="${cardH}" rx="${cardR}" fill="none" stroke="${accent.bg}" stroke-width="3" stroke-opacity="0.7"/>

  <line x1="${cardX}" y1="${windowY}" x2="${cardX + cardW}" y2="${windowY}" stroke="${accent.bg}" stroke-width="2" opacity="0.5"/>
  <line x1="${cardX}" y1="${footerTop}" x2="${cardX + cardW}" y2="${footerTop}" stroke="${accent.bg}" stroke-width="2" opacity="0.5"/>

  ${opts.hideRibbon ? '' : `<g clip-path="url(#cardClip)">
    <g transform="translate(${cardX + cardW - 40}, ${cardY + 40}) rotate(45)">
      <rect x="-140" y="-24" width="280" height="48" fill="${accent.bg}"/>
      <text x="0" y="7" text-anchor="middle" font-family="${font}" font-size="22" font-weight="900" fill="${accent.text}">${ribbonText}</text>
    </g>
  </g>`}

  <text x="${cardX + 36}" y="${cardY + 88}" font-family="${font}" font-size="${nameFsz}" font-weight="900" fill="#ffffff" filter="url(#txt)">${displayName}</text>
  <text x="${cardX + 36}" y="${cardY + 88 + nameFsz * 0.62}" font-family="${font}" font-size="22" font-weight="700" letter-spacing="2" fill="${accent.bg}">#${stat.number ?? ''}</text>

  ${curated.map((s, i) => {
    const cx = cardX + colW * i + colW / 2;
    return `<text x="${cx}" y="${statY}" text-anchor="middle" font-family="${font}" font-size="${statNumFsz}" font-weight="900" fill="#ffffff" filter="url(#txt)">${s.value}</text>
    <text x="${cx}" y="${statLabelY}" text-anchor="middle" font-family="${font}" font-size="${statLabelFsz}" font-weight="700" letter-spacing="2" fill="#c3cbd8">${escXml(s.short)}</text>`;
  }).join('\n')}

  <text x="${cardX + cardW / 2}" y="${contextY}" text-anchor="middle" font-family="${font}" font-size="18" font-weight="700" fill="#c3cbd8">${contextText}</text>
  <text x="${cardX + cardW / 2}" y="${handleY}" text-anchor="middle" font-family="${font}" font-size="16" font-weight="700" letter-spacing="1.5" fill="#8b98ab">${handleText}</text>
</svg>`;

  return sharp(Buffer.from(svg), { density: 216 }).resize(W, H).png({ compressionLevel: 9 }).toBuffer();
}

// "Scoreboard" — an arena-jumbotron-style tinted glass panel with the
// PLAYER'S OWN stats as the hero content (not the game score — the name
// deliberately evokes the venue graphic, not a literal box score readout).
// The panel and its cells use opacity, not a solid fill (a first pass here
// was fully opaque with zero photo transparency), so a photo shows through
// both the margins and — tinted — behind the "glass" itself.
async function generateGameStatScoreboardPng(game, stat, opts = {}) {
  const W = 1080, H = 1920;
  const accent = resolveAccent(opts.accent);
  const font = COVER_SVG_FONT;

  const isTeamA = stat.team_id === game.team_a_id;
  const oppTeamName = String(isTeamA ? game.team_b_name : game.team_a_name || '').toUpperCase();
  const myScore = Number(isTeamA ? game.team_a_score : game.team_b_score);
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score);
  const won = myScore > oppScore;
  const dateShort = game.date
    ? new Date(game.date + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '';
  const contextText = `vs ${escXml(oppTeamName)} · ${won ? 'W' : 'L'} ${myScore}-${oppScore} · ${escXml(dateShort)}`;
  const handleText = '@WKNDBASKETBALL';

  const ranked = SHARE_STAT_DEFS
    .filter(def => def.key !== 'fgpct')
    .map(def => ({ ...def, value: shareStatValue(stat, def.key) }))
    .sort((a, b) => b.value - a.value);
  const hero = ranked[0];
  const secondary = ranked.slice(1, 4);

  const displayName = escXml(formatName(stat.name || '').toUpperCase());
  // Same extra-floor-tier fix as Hero/Card — a 39-character name at 38px
  // rendered with virtually zero margin to the canvas edge (center-anchored,
  // so a slightly longer one would've overflowed both sides at once).
  const nameFsz = displayName.length > 30 ? 26 : displayName.length > 24 ? 30
    : displayName.length > 18 ? 38 : displayName.length > 13 ? 46 : 54;

  const panelX = 60, panelW = W - 120;
  const heroCellH = 420, secondaryRowH = 260;
  const panelH = heroCellH + secondaryRowH;

  const bottomPad = 90;
  const handleY = H - bottomPad;
  const contextY = handleY - 40;
  const panelBottom = contextY - 40;
  const panelTop = panelBottom - panelH;
  const heroCellBottom = panelTop + heroCellH;

  const headerBottom = panelTop - 40;
  const nameY = headerBottom;
  // Real gap from the name's own visual top (baseline minus its cap-height),
  // not a flat multiple of nameFsz that undershot and let "#<number>" touch
  // the name above it.
  const nameVisualTop = nameY - nameFsz * 0.72;
  const numberGap = 18;
  const numberFsz = 26;
  const numberY = nameVisualTop - numberGap;

  const heroNumFsz = 150, heroLabelFsz = 24;
  const heroNumY = panelTop + heroCellH / 2 + heroNumFsz * 0.32;
  const heroLabelY = heroNumY + heroLabelFsz + 22;

  const colW = panelW / secondary.length;
  const secNumFsz = 58, secLabelFsz = 18;
  const secNumY = heroCellBottom + secondaryRowH / 2 - 6;
  const secLabelY = secNumY + secLabelFsz + 18;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="5" flood-color="#000000" flood-opacity="0.5"/>
    </filter>
  </defs>

  <rect x="${panelX}" y="${panelTop}" width="${panelW}" height="${panelH}" rx="16" fill="#020817" opacity="0.72"/>
  <rect x="${panelX}" y="${panelTop}" width="${panelW}" height="${heroCellH}" rx="16" fill="${accent.bg}" opacity="0.16"/>

  <line x1="${panelX}" y1="${heroCellBottom}" x2="${panelX + panelW}" y2="${heroCellBottom}" stroke="${accent.bg}" stroke-width="2" opacity="0.6"/>
  ${secondary.slice(1).map((_, i) => `<line x1="${panelX + colW * (i + 1)}" y1="${heroCellBottom}" x2="${panelX + colW * (i + 1)}" y2="${panelBottom}" stroke="${accent.bg}" stroke-width="2" opacity="0.4"/>`).join('\n')}
  <rect x="${panelX}" y="${panelTop}" width="${panelW}" height="${panelH}" rx="16" fill="none" stroke="${accent.bg}" stroke-width="3" opacity="0.7"/>

  <text x="${W / 2}" y="${numberY}" text-anchor="middle" font-family="${font}" font-size="${numberFsz}" font-weight="800" letter-spacing="2" fill="${accent.bg}" filter="url(#txt)">#${stat.number ?? ''}</text>
  <text x="${W / 2}" y="${nameY}" text-anchor="middle" font-family="${font}" font-size="${nameFsz}" font-weight="900" fill="#ffffff" filter="url(#txt)">${displayName}</text>

  <text x="${W / 2}" y="${heroNumY}" text-anchor="middle" font-family="${font}" font-size="${heroNumFsz}" font-weight="900" fill="#ffffff" filter="url(#txt)">${hero.value}</text>
  <text x="${W / 2}" y="${heroLabelY}" text-anchor="middle" font-family="${font}" font-size="${heroLabelFsz}" font-weight="700" letter-spacing="6" fill="${accent.bg}" filter="url(#txt)">${escXml(hero.short)}</text>

  ${secondary.map((s, i) => {
    const cx = panelX + colW * i + colW / 2;
    return `<text x="${cx}" y="${secNumY}" text-anchor="middle" font-family="${font}" font-size="${secNumFsz}" font-weight="900" fill="#ffffff" filter="url(#txt)">${s.value}</text>
    <text x="${cx}" y="${secLabelY}" text-anchor="middle" font-family="${font}" font-size="${secLabelFsz}" font-weight="700" letter-spacing="2" fill="#c3cbd8">${escXml(s.short)}</text>`;
  }).join('\n')}

  <text x="${W / 2}" y="${contextY}" text-anchor="middle" font-family="${font}" font-size="19" font-weight="700" fill="#e2e8f0" filter="url(#txt)">${contextText}</text>
  <text x="${W / 2}" y="${handleY}" text-anchor="middle" font-family="${font}" font-size="16" font-weight="700" letter-spacing="1.5" fill="#8b98ab">${handleText}</text>
</svg>`;

  return sharp(Buffer.from(svg), { density: 216 }).resize(W, H).png({ compressionLevel: 9 }).toBuffer();
}

// "Badge" — an ADD-ON toggle composited on top of whichever base template
// was actually chosen (see the /api/games/:id/my-stat-card.png route below),
// not a standalone template of its own. Reuses the app's own EXISTING
// achievement logic (statCatCount/qualifyingCats from lib/badges.js,
// achievementRibbonText + getPlayerCareerHighs already used by the POTG
// card) rather than re-deriving double/triple-double or career-high
// detection from scratch — same source of truth, so this can never disagree
// with what the rest of the site already calls a double-double for this
// player. Renders nothing (returns the base PNG untouched) when nothing
// actually qualifies — same "omit the row" convention the existing
// achievement ribbon already uses elsewhere, rather than inventing a
// consolation "your top stat" callout that would make the toggle look like
// it did something when the player didn't actually earn a badge this game.
async function composeStravagantBadgeOverlay(basePng, stat, accent) {
  const cats = statCatCount(stat);
  const careerHighs = getPlayerCareerHighs(stat.player_id);
  const qualifier = achievementRibbonText(stat, careerHighs);
  if (!qualifier) return basePng;

  const font = COVER_SVG_FONT;
  const W = 1080, H = 1920;

  // Double/triple-double: show the actual qualifying categories (whichever
  // ones really hit double digits — could be STL+BLK, not just PTS+REB), not
  // a fixed pair. Career High: show the specific stat(s) that set it, at
  // their actual (possibly single-digit) value.
  let medalStats;
  if (cats >= 2) {
    medalStats = qualifyingCats(stat).slice(0, 3).map(([key, label]) => ({ short: label, value: Number(stat[key]) || 0 }));
  } else {
    const hiKeys = SHARE_STAT_CORE_KEYS.filter(k => {
      const v = Number(stat[k]) || 0;
      return v > 0 && v >= (Number(careerHighs?.[k]) || 0);
    });
    medalStats = hiKeys.length
      ? hiKeys.map(k => { const def = SHARE_STAT_DEFS.find(d => d.key === k); return { short: def.short, value: Number(stat[k]) || 0 }; })
      : [{ short: 'PTS', value: Number(stat.pts) || 0 }]; // qualifier is non-empty here, so this fallback never actually triggers
  }

  const cx = 810, cy = 300, r = 150;
  const ribbonY = cy + 46, ribbonH = 58;

  const statCount = medalStats.length;
  const statFsz = statCount >= 3 ? 40 : 54;
  const labelFsz = statCount >= 3 ? 13 : 15;
  const statY = cy - 30;
  const labelY = statY + labelFsz + 12;
  const spacing = statCount >= 3 ? 76 : 92;
  const startX = cx - (spacing * (statCount - 1)) / 2;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">
  <defs>
    <filter id="txt" x="-30%" y="-30%" width="160%" height="160%">
      <feDropShadow dx="0" dy="2" stdDeviation="4" flood-color="#000000" flood-opacity="0.5"/>
    </filter>
    <radialGradient id="medal" cx="35%" cy="30%" r="75%">
      <stop offset="0%" stop-color="#ffd27a"/>
      <stop offset="55%" stop-color="${accent.bg}"/>
      <stop offset="100%" stop-color="#c96a12"/>
    </radialGradient>
  </defs>

  <circle cx="${cx}" cy="${cy}" r="${r + 10}" fill="#0d1424" opacity="0.5"/>
  <circle cx="${cx}" cy="${cy}" r="${r}" fill="url(#medal)" stroke="#c96a12" stroke-width="4"/>
  <circle cx="${cx}" cy="${cy}" r="${r - 18}" fill="none" stroke="#fff" stroke-width="2" opacity="0.35"/>

  ${medalStats.map((s, i) => {
    const x = startX + spacing * i;
    return `<text x="${x}" y="${statY}" text-anchor="middle" font-family="${font}" font-size="${statFsz}" font-weight="900" fill="#1a1206">${s.value}</text>
    <text x="${x}" y="${labelY}" text-anchor="middle" font-family="${font}" font-size="${labelFsz}" font-weight="800" letter-spacing="1" fill="#4a2f0a">${escXml(s.short)}</text>`;
  }).join('\n')}

  <!-- Straight banner, not curved text on a <textPath> — that never actually
       rendered in this renderer the one time it was tried. -->
  <g>
    <polygon points="${cx - 175},${ribbonY} ${cx - 155},${ribbonY + ribbonH / 2} ${cx - 175},${ribbonY + ribbonH} ${cx - r + 6},${ribbonY + ribbonH} ${cx - r + 6},${ribbonY}" fill="#c96a12"/>
    <polygon points="${cx + 175},${ribbonY} ${cx + 155},${ribbonY + ribbonH / 2} ${cx + 175},${ribbonY + ribbonH} ${cx + r - 6},${ribbonY + ribbonH} ${cx + r - 6},${ribbonY}" fill="#c96a12"/>
    <rect x="${cx - r + 6}" y="${ribbonY}" width="${(r - 6) * 2}" height="${ribbonH}" fill="${accent.bg}"/>
    <text x="${cx}" y="${ribbonY + ribbonH / 2 + 7}" text-anchor="middle" font-family="${font}" font-size="20" font-weight="900" letter-spacing="1" fill="${accent.text}" filter="url(#txt)">${escXml(qualifier)}</text>
  </g>
</svg>`;

  const overlay = await sharp(Buffer.from(svg), { density: 216 }).resize(W, H).png().toBuffer();
  return sharp(basePng).composite([{ input: overlay, top: 0, left: 0 }]).png({ compressionLevel: 9 }).toBuffer();
}

// potgStat: the POTG's stat row, or [POTG, co-POTG] for a game with a co-POTG.
async function generateGameCoverPng(game, potgStat, bgDataUrl) {
  const W = 1200, H = 630;
  if (Array.isArray(potgStat)) {
    if (potgStat.length < 2) potgStat = potgStat[0] || null;
    else return generateGameCoverPng(game, null, bgDataUrl).then(png => addCoPotgToCover(png, game, potgStat));
  }

  // Background
  let base;
  const bgBuf = await fetchCoverImageBuffer(bgDataUrl);
  if (bgBuf) {
    base = await sharp(bgBuf)
      .rotate()
      .resize(W, H, { fit: 'cover', position: 'centre' })
      .png({ compressionLevel: 9 })
      .toBuffer();
  } else {
    base = await sharp({ create: { width: W, height: H, channels: 3, background: { r: 2, g: 8, b: 23 } } })
      .png()
      .toBuffer();
  }

  // Team colors from DB
  const teams  = getAllTeams();
  const teamAR = teams.find(t => t.id === game.team_a_id);
  const teamBR = teams.find(t => t.id === game.team_b_id);
  const colorA = escXml(teamAR?.color || '#4a5263');
  const colorB = escXml(teamBR?.color || '#4a5263');

  const scoreA   = Number(game.team_a_score);
  const scoreB   = Number(game.team_b_score);
  const winA     = scoreA > scoreB;
  const winB     = scoreB > scoreA;
  const teamAName = escXml(String(game.team_a_name || '').toUpperCase());
  const teamBName = escXml(String(game.team_b_name || '').toUpperCase());

  // POTG
  let potgSvgEl   = '';
  let avatarR     = 60;
  const avatarCx  = 88;
  let avatarCy    = 514;
  let avatarOverlay = null;

  if (potgStat) {
    const pts          = Number(potgStat.pts || 0);
    const reb          = Number(potgStat.reb || 0);
    const ast          = Number(potgStat.ast || 0);
    const potgName     = escXml(String(potgStat.name || 'PLAYER').toUpperCase());
    const potgStats    = escXml(`${pts} PTS - ${reb} REB - ${ast} AST`);
    const potgMeta     = escXml(`#${potgStat.number || '–'}  ·  ${potgStat.team_name || ''}`);
    const potgInitials = escXml(svgInitials(potgStat.name || '?'));
    const potgTeamR    = teams.find(t => t.id === potgStat.team_id);
    const potgColor    = escXml(potgStat.team_color || potgTeamR?.color || '#f97316');
    const potgNameSize = potgName.length <= 18 ? 40 : potgName.length <= 24 ? 34 : 28;
    avatarCy           = Math.round(484 + potgNameSize / 2);
    const avatarSize   = avatarR * 2;
    const nameY        = 452 + potgNameSize + 8;

    // Circular avatar from player photo
    if (potgStat.picture_url) {
      try {
        const src = await fetchCoverImageBuffer(potgStat.picture_url);
        if (src) {
          const mask = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${avatarSize}" height="${avatarSize}"><circle cx="${avatarR}" cy="${avatarR}" r="${avatarR}" fill="#fff"/></svg>`);
          avatarOverlay = await sharp(src)
            .rotate()
            .resize(avatarSize, avatarSize, { fit: 'cover', position: 'centre' })
            .composite([{ input: mask, blend: 'dest-in' }])
            .png({ compressionLevel: 9 })
            .toBuffer();
        }
      } catch {}
    }

    potgSvgEl = `
  <circle cx="${avatarCx}" cy="${avatarCy}" r="${avatarR + 12}" fill="${potgColor}" fill-opacity="0.08"/>
  <circle cx="${avatarCx}" cy="${avatarCy}" r="${avatarR + 5}" fill="${potgColor}" fill-opacity="0.12"/>
  <circle cx="${avatarCx}" cy="${avatarCy}" r="${avatarR}" fill="#020817" fill-opacity="0.7"/>
  ${!avatarOverlay ? `<text x="${avatarCx}" y="${avatarCy + 12}" text-anchor="middle" fill="#475569" font-size="34" font-weight="800" font-family="${COVER_SVG_FONT}" filter="url(#txt)">${potgInitials}</text>` : ''}
  <circle cx="${avatarCx}" cy="${avatarCy}" r="${avatarR + 2}" fill="none" stroke="${potgColor}" stroke-width="2" stroke-opacity="0.9"/>
  <text x="180" y="452" fill="#f97316" font-size="13" font-weight="700" font-family="${COVER_SVG_FONT}" filter="url(#txt)">PLAYER OF THE GAME</text>
  <text x="180" y="${nameY}" fill="#ffffff" font-size="${potgNameSize}" font-weight="800" font-family="${COVER_SVG_FONT}" filter="url(#txt)">${potgName}</text>
  <text x="180" y="${nameY + 32}" fill="#e2e8f0" font-size="22" font-weight="700" font-family="${COVER_SVG_FONT}" filter="url(#txt)">${potgStats}</text>
  <text x="180" y="${nameY + 56}" fill="#94a3b8" font-size="15" font-family="${COVER_SVG_FONT}" filter="url(#txt)">${potgMeta}</text>`;
  }

  const overlaySvg = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <defs>
    <filter id="txt" x="-5%" y="-5%" width="110%" height="110%">
      <feDropShadow dx="0" dy="1" stdDeviation="4" flood-color="#000000" flood-opacity="0.9"/>
    </filter>
    <linearGradient id="topFade" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#020817" stop-opacity="0.72"/>
      <stop offset="100%" stop-color="#020817" stop-opacity="0"/>
    </linearGradient>
    <linearGradient id="botFade" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#020817" stop-opacity="0"/>
      <stop offset="100%" stop-color="#020817" stop-opacity="0.94"/>
    </linearGradient>
    <filter id="card" x="-40%" y="-30%" width="180%" height="200%">
      <feDropShadow dx="0" dy="14" stdDeviation="16" flood-color="#000000" flood-opacity="0.72"/>
    </filter>
    <linearGradient id="cardSheen" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#ffffff" stop-opacity="0.12"/>
      <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
    </linearGradient>
    <clipPath id="scoreClip"><rect x="955" y="474" width="200" height="96" rx="12"/></clipPath>
  </defs>
  <rect x="0" y="0" width="${W}" height="160" fill="url(#topFade)"/>
  <rect x="0" y="400" width="${W}" height="230" fill="url(#botFade)"/>
  <rect x="0" y="0" width="600" height="6" fill="${colorA}"/>
  <rect x="600" y="0" width="600" height="6" fill="${colorB}"/>
  <rect x="0" y="6" width="5" height="${H - 12}" fill="${colorA}" opacity="0.65"/>
  <rect x="${W - 5}" y="6" width="5" height="${H - 12}" fill="${colorB}" opacity="0.65"/>
  <rect x="0" y="${H - 6}" width="600" height="6" fill="${colorA}" opacity="0.5"/>
  <rect x="600" y="${H - 6}" width="600" height="6" fill="${colorB}" opacity="0.5"/>
  <text x="129" y="24" text-anchor="middle" fill="${colorA}" font-size="9" font-weight="700" font-family="${COVER_SVG_FONT}" filter="url(#txt)" textLength="155" lengthAdjust="spacingAndGlyphs">SEASON ${escXml(String(game.season || ''))}  ·  ${escXml(game.game_type === 'playoff' ? 'PLAYOFFS' : game.game_type === 'finals' ? 'FINALS' : 'REGULAR SEASON')}</text>
  <rect x="955" y="474" width="200" height="96" rx="12" fill="#040c18" fill-opacity="0.80" filter="url(#card)" stroke="#ffffff" stroke-opacity="0.10" stroke-width="1"/>
  <rect x="955" y="474" width="100" height="96" fill="${colorA}" fill-opacity="${winA ? '0.38' : '0.10'}" clip-path="url(#scoreClip)"/>
  <rect x="1055" y="474" width="100" height="96" fill="${colorB}" fill-opacity="${winB ? '0.38' : '0.10'}" clip-path="url(#scoreClip)"/>
  <rect x="956" y="475" width="198" height="26" rx="11" fill="url(#cardSheen)"/>
  <line x1="963" y1="500" x2="1147" y2="500" stroke="#ffffff" stroke-width="1" stroke-opacity="0.08"/>
  <line x1="1055" y1="482" x2="1055" y2="562" stroke="#ffffff" stroke-width="1" stroke-opacity="0.08"/>
  <text x="1005" y="493" fill="#ffffff" text-anchor="middle" font-size="12" font-weight="700" font-family="${COVER_SVG_FONT}" clip-path="url(#scoreClip)" filter="url(#txt)" opacity="${winA ? '1' : '0.45'}">${teamAName}</text>
  <text x="1105" y="493" fill="#ffffff" text-anchor="middle" font-size="12" font-weight="700" font-family="${COVER_SVG_FONT}" clip-path="url(#scoreClip)" filter="url(#txt)" opacity="${winB ? '1' : '0.45'}">${teamBName}</text>
  <text x="1005" y="548" fill="#ffffff" text-anchor="middle" font-size="48" font-weight="900" font-family="${COVER_SVG_FONT}" clip-path="url(#scoreClip)" filter="url(#txt)" opacity="${winA ? '1' : '0.38'}">${scoreA}</text>
  <text x="1105" y="548" fill="#ffffff" text-anchor="middle" font-size="48" font-weight="900" font-family="${COVER_SVG_FONT}" clip-path="url(#scoreClip)" filter="url(#txt)" opacity="${winB ? '1' : '0.38'}">${scoreB}</text>
  ${potgSvgEl}
  <text x="${W / 2}" y="617" fill="#334155" text-anchor="middle" font-size="11" font-weight="600" font-family="${COVER_SVG_FONT}" filter="url(#txt)">WKNDBASKETBALL.COM</text>
</svg>`);

  // Render SVG at 2× density then resize down — produces much crisper text
  const overlaySvgPng = await sharp(overlaySvg, { density: 144 })
    .resize(W, H)
    .png()
    .toBuffer();

  const layers = [{ input: overlaySvgPng, top: 0, left: 0 }];
  if (avatarOverlay) {
    layers.push({ input: avatarOverlay, left: avatarCx - avatarR, top: avatarCy - avatarR });
  }
  try {
    if (existsSync(COVER_LOGO_PATH)) {
      const logoOverlay = await sharp(COVER_LOGO_PATH)
        .ensureAlpha()
        .resize({ width: 155, height: 44, fit: 'inside', withoutEnlargement: true })
        .png()
        .toBuffer();
      layers.push({ input: logoOverlay, left: 52, top: 34 });
    }
  } catch {}

  return sharp(base).composite(layers).png({ compressionLevel: 9 }).toBuffer();
}

// The cover's bottom-left block for a game with a co-POTG: both avatars overlapping, then
// "CO-PLAYERS OF THE GAME", both last names and each one's line. Same type and colours as
// the single POTG block above, drawn onto a cover rendered without one.
async function addCoPotgToCover(basePng, game, potgStats) {
  const W = 1200, H = 630, R = 48, cy = 520;
  const teams = getAllTeams();
  const cxs = [76, 160];
  const lastOf = s => String(s.name || '').split(',')[0].trim().toUpperCase() || 'PLAYER';
  const colorOf = s => escXml(s.team_color || teams.find(t => t.id === s.team_id)?.color || '#f97316');
  const line = s => `${lastOf(s)}  ${Number(s.pts || 0)} PTS - ${Number(s.reb || 0)} REB - ${Number(s.ast || 0)} AST`;
  const names = escXml(potgStats.map(lastOf).join(' & '));
  const nameSize = names.length <= 22 ? 36 : names.length <= 30 ? 30 : 24;
  const avatars = await Promise.all(potgStats.map(async s => {
    if (!s.picture_url) return null;
    try {
      const src = await fetchCoverImageBuffer(s.picture_url);
      if (!src) return null;
      const mask = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${R * 2}" height="${R * 2}"><circle cx="${R}" cy="${R}" r="${R}" fill="#fff"/></svg>`);
      return await sharp(src).rotate().resize(R * 2, R * 2, { fit: 'cover', position: 'centre' })
        .composite([{ input: mask, blend: 'dest-in' }]).png().toBuffer();
    } catch { return null; }
  }));
  const ring = (s, i) => `
  <circle cx="${cxs[i]}" cy="${cy}" r="${R + 4}" fill="#020817"/>
  <circle cx="${cxs[i]}" cy="${cy}" r="${R}" fill="#020817" fill-opacity="0.7"/>
  ${!avatars[i] ? `<text x="${cxs[i]}" y="${cy + 10}" text-anchor="middle" fill="#475569" font-size="28" font-weight="800" font-family="${COVER_SVG_FONT}" filter="url(#txt)">${escXml(svgInitials(s.name || '?'))}</text>` : ''}`;
  const outline = (s, i) => `<circle cx="${cxs[i]}" cy="${cy}" r="${R + 2}" fill="none" stroke="${colorOf(s)}" stroke-width="2" stroke-opacity="0.9"/>`;
  const x = 236, nameY = 452 + nameSize + 8;
  const svg = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <defs><filter id="txt" x="-5%" y="-5%" width="110%" height="110%"><feDropShadow dx="0" dy="1" stdDeviation="4" flood-color="#000000" flood-opacity="0.9"/></filter></defs>
  ${ring(potgStats[1], 1)}${ring(potgStats[0], 0)}
  <text x="${x}" y="452" fill="#f97316" font-size="13" font-weight="700" font-family="${COVER_SVG_FONT}" filter="url(#txt)">CO-PLAYERS OF THE GAME</text>
  <text x="${x}" y="${nameY}" fill="#ffffff" font-size="${nameSize}" font-weight="800" font-family="${COVER_SVG_FONT}" filter="url(#txt)">${names}</text>
  <text x="${x}" y="${nameY + 30}" fill="#e2e8f0" font-size="17" font-weight="700" font-family="${COVER_SVG_FONT}" filter="url(#txt)">${escXml(line(potgStats[0]))}</text>
  <text x="${x}" y="${nameY + 54}" fill="#e2e8f0" font-size="17" font-weight="700" font-family="${COVER_SVG_FONT}" filter="url(#txt)">${escXml(line(potgStats[1]))}</text>
</svg>`);
  const outlines = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${outline(potgStats[1], 1)}${outline(potgStats[0], 0)}</svg>`);
  const toPng = buf => sharp(buf, { density: 144 }).resize(W, H).png().toBuffer();
  // Back avatar (co-POTG) first, then the POTG's ring + photo on top of it.
  const layers = [{ input: await toPng(svg), top: 0, left: 0 }];
  if (avatars[1]) layers.push({ input: avatars[1], left: cxs[1] - R, top: cy - R });
  const front = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${ring(potgStats[0], 0)}</svg>`);
  layers.push({ input: await toPng(front), top: 0, left: 0 });
  if (avatars[0]) layers.push({ input: avatars[0], left: cxs[0] - R, top: cy - R });
  layers.push({ input: await toPng(outlines), top: 0, left: 0 });
  return sharp(basePng).composite(layers).png({ compressionLevel: 9 }).toBuffer();
}

async function serveCover(req, res) {
  const gameId = req.params.gameId;
  const game = getGameById(gameId);
  if (!game) return res.status(404).end();
  try {
    const stats       = getGameDetailStats(gameId);
    const potgStat    = potgIdsFor(game, stats).map(id => stats.find(s => s.player_id === id)).filter(Boolean);
    const coverRow    = game.has_cover ? getGameCover(gameId) : null;
    const png = await generateGameCoverPng(game, potgStat, coverRow?.social_cover_data_url || null);
    res.set('Content-Type', 'image/png');
    res.set('Cache-Control', 'public, max-age=300');
    res.end(png);
  } catch (err) {
    console.error('serveCover error:', err);
    res.status(500).end();
  }
}

app.get('/api/cover/:gameId.png', serveCover);
app.get('/api/cover/:gameId',     serveCover);

