// SEO override cover images are stored as base64 data: URIs (see compressSeoImage),
// but og:image/twitter:image must be a real fetchable URL — social crawlers don't
// resolve data: URIs — so this decodes and serves the stored image as bytes.
app.get('/api/seo-cover', (req, res) => {
  const override = getSeoOverride(String(req.query.slug || ''));
  const dataUrl = override?.image_url;
  if (!dataUrl) return res.status(404).end();
  const match = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) return res.status(404).end();
  const buf = Buffer.from(match[2], 'base64');
  res.set('Content-Type', match[1]);
  res.set('Cache-Control', 'public, max-age=86400');
  res.end(buf);
});

// ── Sized player photos ──────────────────────────────────────────────────────
// /api/player/:id/photo?w=96|192 serves a downscaled WebP (2–5 KB vs the stored
// 400px JPEG at ~32 KB). Variants are rendered once and kept in memory, keyed by a
// hash of the stored photo, so a replaced photo is picked up on its next request.
// Remote sources (admin-app paths, Facebook CDN links) are fetched once per photo
// instead of on every request; a failed fetch is remembered for 10 minutes so an
// expired link doesn't stall every page that shows it.
const PHOTO_WIDTHS = new Set([96, 192]);
const PHOTO_CACHE_MAX = 600;
const PHOTO_FAIL_TTL = 10 * 60 * 1000;
const photoCache = new Map(); // key → { buf, type } | { failedAt }

function photoVersion(url) {
  return createHash('sha1').update(String(url || '')).digest('hex').slice(0, 10);
}

function photoCacheGet(key) {
  const hit = photoCache.get(key);
  if (!hit) return null;
  if (hit.failedAt && Date.now() - hit.failedAt > PHOTO_FAIL_TTL) { photoCache.delete(key); return null; }
  photoCache.delete(key); photoCache.set(key, hit); // LRU bump
  return hit;
}

function photoCacheSet(key, val) {
  photoCache.set(key, val);
  while (photoCache.size > PHOTO_CACHE_MAX) photoCache.delete(photoCache.keys().next().value);
}

async function loadPhotoVariant(url, w) {
  const ver = photoVersion(url);
  const key = `${ver}:${w || 0}`;
  const hit = photoCacheGet(key);
  if (hit) return { ...hit, ver };
  let src = null, type = 'image/jpeg';
  if (url.startsWith('data:')) {
    const comma = url.indexOf(',');
    type = (url.slice(0, comma).match(/^data:([^;]+)/) || [])[1] || type;
    src  = Buffer.from(url.slice(comma + 1), 'base64');
  } else {
    // Relative paths are served by the admin server, not the portal
    const fetchUrl = url.startsWith('/') ? `${ADMIN_URL}${url}` : url;
    try {
      const upstream = await fetch(fetchUrl, { signal: AbortSignal.timeout(8000) });
      if (upstream.ok) {
        src  = Buffer.from(await upstream.arrayBuffer());
        type = upstream.headers.get('content-type') || type;
      }
    } catch {}
  }
  if (!src) { photoCacheSet(key, { failedAt: Date.now() }); return { failedAt: Date.now(), ver }; }
  let out = { buf: src, type };
  if (w) {
    try {
      const buf = await sharp(src).rotate().resize(w, w, { fit: 'inside', withoutEnlargement: true }).webp({ quality: 80 }).toBuffer();
      out = { buf, type: 'image/webp' };
    } catch {} // undecodable source: fall back to the original bytes
  }
  // Data URLs are already in the DB, so only cache the full-size copy for remote sources.
  if (w || !url.startsWith('data:')) photoCacheSet(key, out);
  return { ...out, ver };
}

// widths: the ?w= values this route accepts (anything else gets the original).
// maxAge: browser cache seconds for un-versioned URLs before revalidating via ETag.
async function sendPlayerPhoto(req, res, url, { widths = PHOTO_WIDTHS, maxAge = 300, onFail = null } = {}) {
  if (!url) return res.status(404).end();
  const w = widths.has(Number(req.query.w)) ? Number(req.query.w) : 0;
  const photo = await loadPhotoVariant(url, w);
  if (photo.failedAt) return onFail ? onFail() : res.status(502).end();
  const etag = `"${photo.ver}-${w}"`;
  res.set('ETag', etag);
  // ?v= is the photo's own hash (photoVersion), so that URL can never go stale. Bare
  // URLs: serve from browser cache briefly, then revalidate (a 304 costs no image bytes).
  res.set('Cache-Control', req.query.v
    ? 'public, max-age=31536000, immutable'
    : `public, max-age=${maxAge}, stale-while-revalidate=86400`);
  if (req.headers['if-none-match'] === etag) return res.status(304).end();
  res.set('Content-Type', photo.type);
  res.end(photo.buf);
}

// Older call sites (crop source, Papawis court/map images, marketplace photos) — same
// cached, ETag'd path as player photos.
function sendPlayerPhotoUrl(res, url) {
  return sendPlayerPhoto(res.req, res, url);
}

// Player photo URL with its version hash baked in, so browsers (and Cloudflare) can keep
// it for a year — a replaced photo gets a new hash, so a new URL. Hashes come from a
// 60-second in-memory snapshot of players.picture_url (rebuilt at once after a photo
// upload); a player missing from it falls back to the bare, short-cached URL.
let _photoVers = { at: 0, writes: -1, map: new Map() };
function playerPhotoVersion(id) {
  const writes = getPlayerPhotoWrites();
  if (Date.now() - _photoVers.at > 60_000 || writes !== _photoVers.writes) {
    const map = new Map();
    for (const r of getAllPlayerPhotoUrls()) if (r.picture_url) map.set(String(r.id), photoVersion(r.picture_url));
    _photoVers = { at: Date.now(), writes, map };
  }
  return _photoVers.map.get(String(id)) || '';
}
setPhotoVersionResolver(playerPhotoVersion);

// No photo yet: their team's jersey with their number (views/utils.js playerJerseySvg).
// Also stands in, briefly cached, when a stored photo can't be loaded (e.g. the admin app
// that hosts /data/player-images is down), so the real photo comes back once it's up.
function sendPlayerJersey(req, res, { failed = false } = {}) {
  const player = getPlayerById(req.params.id);
  if (!player) return res.status(404).end();
  const team = player.team_id ? getTeamById(player.team_id) : null;
  const svg = playerJerseySvg({ color: team ? teamColor(team.name) : '#4a5263', number: player.number });
  if (failed) {
    res.set('Cache-Control', 'no-store');
  } else {
    const etag = `"jersey-${createHash('sha1').update(svg).digest('hex').slice(0, 12)}"`;
    res.set('ETag', etag);
    res.set('Cache-Control', 'public, max-age=300, stale-while-revalidate=86400');
    if (req.headers['if-none-match'] === etag) return res.status(304).end();
  }
  res.type('image/svg+xml').send(svg);
}

app.get('/api/player/:id/photo', async (req, res) => {
  const row = getPlayerPhoto(req.params.id);
  if (!row) return res.status(404).end();
  if (row.picture_url) return sendPlayerPhoto(req, res, row.picture_url, { onFail: () => sendPlayerJersey(req, res, { failed: true }) });
  sendPlayerJersey(req, res);
});

// Best available source to re-crop from: the retained pre-crop original if we have
// one, otherwise the already-cropped square (older photos uploaded before originals
// were retained).
app.get('/api/player/:id/photo-source', async (req, res) => {
  const original = getPlayerPhotoOriginal(req.params.id);
  if (original) return sendPlayerPhotoUrl(res, original);
  const row = getPlayerPhoto(req.params.id);
  await sendPlayerPhotoUrl(res, row?.picture_url);
});

// Head-to-head write-up for the /players compare sheet (and the admin compare page's
// regenerate), in the conyo voice from /admin/ai-writing. ?season=N | career; default is the
// latest completed regular season. Numbers are guarded against the facts like the homepage
// summaries: up to 3 drafts, then 503.
// conyo2 (2026-10-20): the rewritten conyo guide + voice check — cached takes rewrite on view.
const COMPARE_VOICE_VERSION = 'conyo2';
app.get('/api/compare', async (req, res) => {
  const { a, b, force } = req.query;
  if (!a || !b) return res.status(400).json({ error: 'Missing player IDs' });
  try {
    const pA = getPlayerWithTeam(a), pB = getPlayerWithTeam(b);
    if (!pA || !pB) return res.status(404).json({ error: 'Player not found' });
    const seasons = getLeaderSeasons().map(Number).filter(Boolean).sort((x, y) => y - x);
    const qs = String(req.query.season || '');
    const season = qs === 'career' ? null : (seasons.includes(Number(qs)) ? Number(qs) : (seasons[0] ?? null));
    const label = season == null ? 'Career' : `Season ${season}`;
    const lines = getPlayerSeasonLines(season);
    const tA = lines.find(r => r.id === a) || null, tB = lines.find(r => r.id === b) || null;
    const variant = `${COMPARE_VOICE_VERSION}|${season == null ? 'career' : `s${season}`}`;

    const playerData = (p, t) => ({
      name: displayPlayerName(p.name),
      team: p.team_name || '',
      totals: {
        gp: t?.games_played || 0, pts: t?.pts || 0, reb: t?.reb || 0,
        ast: t?.ast || 0, stl: t?.stl || 0, blk: t?.blk || 0, tov: t?.turnover || 0,
        fg2m: t?.fg2m || 0, fg3m: t?.fg3m || 0, fg4m: t?.fg4m || 0, fg2m_miss: t?.fg2m_miss || 0,
        fg3m_miss: t?.fg3m_miss || 0, fg4m_miss: t?.fg4m_miss || 0, ftm: t?.ftm || 0, ft_miss: t?.ft_miss || 0,
      },
    });

    const firstName = p => String(p.first_name || displayPlayerName(p.name)).trim().split(/\s+/)[0];
    const missing = [[pA, tA], [pB, tB]].filter(([, t]) => !t?.games_played).map(([p]) => firstName(p));
    if (missing.length) {
      return res.json({ writeup: `${missing.join(' and ')} ${missing.length > 1 ? "don't" : "doesn't"} have ${label} games yet, so there's nothing to compare.`, playerA: playerData(pA, tA), playerB: playerData(pB, tB) });
    }

    const cached = force !== '1' && getCompareCache(a, b, tA, tB, variant);
    if (cached) {
      incrementCompareViews(a, b);
      return res.json({ writeup: cached, cached: true, playerA: playerData(pA, tA), playerB: playerData(pB, tB) });
    }

    const pg = (t, field) => (t[field] / t.games_played).toFixed(1);
    const pctOf = (made, miss) => (made + miss) > 0 ? `${Math.round(made / (made + miss) * 100)}%` : null;
    const line = (p, t) => {
      const fg = pctOf(t.fg2m + t.fg3m + t.fg4m, t.fg2m_miss + t.fg3m_miss + t.fg4m_miss);
      const tp = pctOf(t.fg3m, t.fg3m_miss), ft = pctOf(t.ftm, t.ft_miss);
      return `${firstName(p)} (${displayPlayerName(p.name)}, ${t.team_name || p.team_name || 'no team'}): ${t.games_played} GP, ${pg(t, 'pts')} PPG, ${pg(t, 'reb')} RPG, ${pg(t, 'ast')} APG, ${pg(t, 'stl')} SPG, ${pg(t, 'blk')} BPG, ${pg(t, 'turnover')} turnovers per game${fg ? `, ${fg} FG` : ''}${tp ? `, ${tp} from three` : ''}${ft ? `, ${ft} FT` : ''}`;
    };
    const facts = `${line(pA, tA)}\n${line(pB, tB)}`;

    // The conyo voice as configured at /admin/ai-writing (falls back if an admin removed it).
    const voice = getVoiceConfig().voices.find(v => v.id === 'conyo') || DEFAULT_VOICES.find(v => v.id === 'conyo');

    // Recent openers, so takes don't all start the same way.
    const currentPair = [a, b].sort().join('|');
    const recentOpeners = getCompareAnalytics()
      .filter(r => r.writeup && r.pair_key !== currentPair)
      .sort((x, y) => (y.created_at || 0) - (x.created_at || 0))
      .slice(0, 8)
      .map(r => r.writeup.split(/(?<=[.!?])\s/)[0])
      .filter(Boolean);

    let prompt = `You write "the conyo take" on a head-to-head comparison of two players in WKND Basketball, a recreational league whose players read every word.

VOICE — ${voice.name}: ${voice.guide}${voice.sample ? `\nExample line in this voice: "${voice.sample}"` : ''}${voiceFlavor(voice, currentPair, 70) ? `\n${voiceFlavor(voice, currentPair, 70)}` : ''}

HOW TO SAY IT: numbers, names and stat words come from the facts in English digits; everything around them is in the voice.

FACTS (${label}, regular season — the only stats you may use):
${facts}

Rules:
- 2-3 sentences, at most 70 words, one paragraph. Say who is better at what, head to head, with light teasing about the stats — never mean, never about anything except basketball.
- Use first names only (the name before the brackets).
- Every number must be copied exactly as it appears in the facts. Never calculate new numbers: no differences, sums, ratios or rounding.
- Don't invent games, plays, history, rankings or records beyond the facts.
- No emojis, hashtags, headings or labels. Output only the paragraph.${recentOpeners.length ? `\n- Open differently from these recent takes:\n${recentOpeners.map(o => `  - "${o}"`).join('\n')}` : ''}`;

    // "Who is better at what" checked in code: the two first names stand in for the teams in
    // comparisonProblems (lib/story-checks.js), one row per stat as the facts print it.
    const pct = (made, miss) => ((made + miss) > 0 ? Math.round(made / (made + miss) * 100) : null);
    const per = (t, k) => Number((t[k] / t.games_played).toFixed(1));
    const shot = t => ({ fg: pct(t.fg2m + t.fg3m + t.fg4m, t.fg2m_miss + t.fg3m_miss + t.fg4m_miss), tp: pct(t.fg3m, t.fg3m_miss), ft: pct(t.ftm, t.ft_miss) });
    const sA = shot(tA), sB = shot(tB);
    const cmp = {
      teams: [firstName(pA), firstName(pB)],
      rows: [
        ...[['pts', 'points per game'], ['reb', 'rebounds per game'], ['ast', 'assists per game'], ['stl', 'steals per game'], ['blk', 'blocks per game']]
          .map(([k, label]) => ({ label, a: per(tA, k), b: per(tB, k), hi: true })),
        { label: 'turnovers per game', a: per(tA, 'turnover'), b: per(tB, 'turnover'), hi: false },
        ...[['fg', 'FG%'], ['tp', '3P%'], ['ft', 'FT%']].filter(([k]) => sA[k] != null && sB[k] != null).map(([k, label]) => ({ label, a: sA[k], b: sB[k], hi: true })),
      ],
    };
    // Write → check → rewrite (lib/writer.js): numbers, claims, banned filler, wrong-way
    // comparisons. Hotter first draft, cooler rewrites (as before).
    let attempt = 0, model = '';
    const out = await runWriter({
      prompt, label: 'compare take', tries: 3,
      generate: async p => {
        const r = await generateText(p, { tier: 'short', maxTokens: 320, temperature: ++attempt === 1 ? 0.9 : 0.75 });
        model = r.model;
        return String(r.text || '').replace(/\s+/g, ' ').trim();
      },
      checks: [
        t => (t.length < 40 ? ['the take is too short'] : []),
        t => (t.split(/\s+/).length > 85 ? [`the take is ${t.split(/\s+/).length} words (at most 70)`] : []),
        t => numberProblems(t, facts),
        t => claimProblems(t, facts),
        { style: true, fn: t => bannedProblems(t) },
        t => comparisonProblems(t, cmp).map(p => `a comparison runs the wrong way: ${p}`),
        { style: true, fn: t => voiceProblems(t, voice) },
      ],
    });
    if (out.problems.length) return res.status(503).json({ error: 'No take passed the checks' });
    setCompareCache(a, b, tA, tB, out.draft, model, variant);
    res.json({ writeup: out.draft, playerA: playerData(pA, tA), playerB: playerData(pB, tB) });
  } catch (err) {
    console.error('compare writeup error:', err.message);
    res.status(503).json({ error: 'AI unavailable' });
  }
});

