// My Team: the team, Up next (the countdown), this season's schedule and results, roster.
app.get('/app/team', requireApp, (req, res) => {
  const me = appMe(req);
  if (!me.team) return sendTab(res, me, { title: 'My Team · WKND', tab: 'team', body: appTeamPage({ me }) });
  const teams = getAllTeams();
  const { next, played, all } = appGames(me);
  const season = String(getPortalCurrentSeason());
  const seasonGames = played.filter(g => String(g.season) === season);
  const regularGames = seasonGames.filter(g => g.game_type !== 'playoff');
  const roster = getAllPlayers()
    .filter(p => p.team_id === me.team.id && p.status === 'active') // as the site's team page
    .map(p => ({
      id: p.id, name: displayPlayerName(p.name || '') || `${p.first_name} ${p.last_name}`.trim(), number: String(p.number ?? ''),
      positions: parsePositions(p.positions).join(' · '), photoUrl: playerPhotoUrl(p.id, 96),
      initials: `${(p.first_name || '').charAt(0)}${(p.last_name || '').charAt(0)}`.toUpperCase(),
      isMe: p.id === me.playerId, isHead: getHeadTeamIds(p.id).includes(me.team.id),
    }))
    .sort((a, b) => (b.isHead - a.isHead) || a.name.localeCompare(b.name));
  let upNext = null;
  if (next) {
    const r = teamResult(next, me.team.id);
    const ymd = gameYmd(next.date);
    const tip = /^\d{2}:\d{2}$/.test(String(next.tip_time || '')) ? next.tip_time : '00:00';
    upNext = {
      kicker: `Up next · ${next.playoff_round || gameTypeLabel(next) || 'Regular season'}`,
      mine: me.team.name, opp: r.oppName, oppColor: teamColorById(teams, r.oppId),
      dateLabel: [manilaDayLabel(ymd), gameTipLabel(next)].filter(Boolean).join(' · '),
      court: next.court_id ? (getPapawisCourtById(next.court_id)?.name || '') : '',
      countTo: Date.parse(`${ymd}T${tip}:00+08:00`),
      // The team card already has the record: here, how the last meeting went.
      foot: (() => {
        const last = played.find(g => teamResult(g, me.team.id).oppId === r.oppId);
        if (!last) return `First meeting with ${r.oppName}`;
        const lr = teamResult(last, me.team.id);
        return `Last met ${shortDate(last.date)} · ${lr.won ? 'W' : 'L'} ${lr.my}–${lr.opp}`;
      })(),
    };
  }
  // The season in date order: results link to the game screen, upcoming games show the day.
  const schedule = all
    // The next game is the Up next card, so it isn't listed again under Coming up.
    .filter(g => String(g.season) === season && !g.under_review && teamSide(g, me.team.id) && (isPlayedGame(g) || ((g.status === 'scheduled' || g.scheduled) && g.id !== next?.id)))
    .sort((x, y) => gameYmd(x.date).localeCompare(gameYmd(y.date)) || String(x.tip_time).localeCompare(String(y.tip_time)))
    .map(g => {
      const r = teamResult(g, me.team.id), done = isPlayedGame(g);
      return { date: shortDate(g.date), opp: r.oppName, oppColor: teamColorById(teams, r.oppId), played: done, won: r.won, my: r.my, oppScore: r.opp,
        when: [manilaDayLabel(gameYmd(g.date)), gameTipLabel(g)].filter(Boolean).join(' · '), href: done ? `/app/games/${encodeURIComponent(g.id)}?from=team` : '' };
    });
  let standing = '';
  try {
    const rows = standingsSectionData(season, all).rows;
    const i = rows.findIndex(r => r.team_id === me.team.id || String(r.team_name || r.name || '').toUpperCase() === String(me.team.name).toUpperCase());
    if (i >= 0 && seasonGames.length) standing = `${ordinal(i + 1)} of ${rows.length}`;
  } catch (e) { console.error('[app team standing]', e.message); }
  sendTab(res, me, { title: 'My Team · WKND', tab: 'team', body: appTeamPage({
    me, season, upNext, schedule, roster,
    // Regular-season record, as the site's standings and team page show it.
    team: { name: me.team.name, color: me.ring, record: regularGames.length ? `${recordIn(regularGames, me.team.id)} in Season ${season}` : '', standing },
  }) });
});
const ordinal = n => `${n}${['th', 'st', 'nd', 'rd'][(n % 100 > 10 && n % 100 < 14) ? 0 : (n % 10 < 4 ? n % 10 : 0)]}`;

// Me: profile, To do (money and season, plus a line to Picks), season averages, games.
app.get('/app/me', requireApp, (req, res) => {
  const me = appMe(req);
  const season = String(getPortalCurrentSeason());
  const log = getPlayerGameLog(me.playerId).filter(g => g.status === 'played');
  // Regular season only, as the site profile's season line (getPlayerStatsByType).
  const inSeason = log.filter(g => String(g.season) === season && g.game_type !== 'playoff');
  const per = k => inSeason.length ? (inSeason.reduce((s, g) => s + (g[k] || 0), 0) / inSeason.length).toFixed(1) : '0.0';
  const games = log.slice(0, 5).map(g => {
    const tid = g.player_team_id;
    const mine = g.team_a_id === tid ? 'a' : 'b';
    const my = Number(mine === 'a' ? g.team_a_score : g.team_b_score), opp = Number(mine === 'a' ? g.team_b_score : g.team_a_score);
    return { date: shortDate(g.date), opp: mine === 'a' ? g.team_b_name : g.team_a_name, won: my > opp, my, oppScore: opp,
      line: `${g.pts || 0}·${g.reb || 0}·${g.ast || 0}`, href: `/app/games/${encodeURIComponent(g.game_id || g.id)}?from=me` };
  });
  // Picks are counted on the Picks tab; here they're one line pointing there, not a list.
  const todos = appAccountTodos(me);
  const open = appOpenPicks(me);
  if (open.length) todos.unshift({ icon: 'picks', title: open.length === 1 ? '1 game to pick' : `${open.length} games to pick`, sub: 'Who wins?', pill: 'Pick', href: '/app/picks', solid: true });
  // Picked by an admin to score a game (the scorer: /app/score).
  const toScore = scorableGameIds(me.playerId).length;
  if (toScore) todos.unshift({ icon: 'ball', title: toScore === 1 ? '1 game to score' : `${toScore} games to score`, sub: getPlayerById(me.playerId)?.is_scorer || !isGameAdminPlayer(me.playerId) ? 'You’re a scorer' : 'Admins can score any game', pill: 'Score', href: '/app/score', solid: true });
  sendTab(res, me, { title: 'Me · WKND', tab: 'me', body: appMePage({
    me, positions: parsePositions(me.player.positions).join(' · '), todos,
    season: { label: `Season ${season} · per game`, gp: inSeason.length, ppg: per('pts'), rpg: per('reb'), apg: per('ast') },
    games,
  }) });
});

// One openPicks() entry shaped for the app's pick cards (views/app/picks.js card, and the
// Home rail's compact one in views/app/feed.js).
function appPickGame(o, g = {}, colorOf) {
  const closeMs = o.closeAt ? Date.parse(o.closeAt) : 0;
  return {
    id: o.id, title: g.playoff_round || gameTypeLabel(g) || 'Regular season', ymd: o.ymd,
    dayLabel: [manilaDayLabel(o.ymd), o.tip].filter(Boolean).join(' · '), tip: o.tip || '',
    closed: !!o.closed, closeAt: closeMs,
    closeLabel: closeMs ? closeLabel(closeMs) : '',
    a: { name: o.a, color: colorOf(o.a), rec: o.recA ? `${o.recA.w}–${o.recA.l}` : '' },
    b: { name: o.b, color: colorOf(o.b), rec: o.recB ? `${o.recB.w}–${o.recB.l}` : '' },
    odds: o.odds ? { pctA: o.odds.pctA, pctB: o.odds.pctB } : null,
    myPick: o.myPick, counts: o.counts || { a: 0, b: 0 },
    faces: (o.faces || []).map(f => ({ ini: f.ini, color: f.color || '', me: !!f.me })),
    stakes: o.stakes, marginGuess: !!o.marginGuess,
  };
}
const appColorOf = teams => name => { const t = teams.find(x => x.name === name); return t ? (t.color || teamColor(t.name)) : teamColor(name); };

// A game's preview before tip-off, from the site's own gamePreview() (same matchup, same
// storyline): records, each team's last 5 results, the last meeting, the season series, the
// go-to scorer on each side in this matchup.
function appPreview(game, sorted, pctx, playerMap, colorOf) {
  const p = gamePreview(game, sorted, playerMap, pctx);
  const m = p.m || {};
  const ymd = gameYmd(game.date);
  const lastFive = name => sorted
    .filter(g => isPlayedGame(g) && gameYmd(g.date) < ymd && (g.team_a_name === name || g.team_b_name === name))
    .slice(0, 5).reverse()
    .map(g => ((g.team_a_name === name) === (Number(g.team_a_score) > Number(g.team_b_score)) ? 'W' : 'L')).join('');
  const lm = (m.lastMeetings || [])[0];
  const last = lm ? {
    text: lm.scoreA === lm.scoreB ? `${lm.scoreA}–${lm.scoreB}` : `${lm.scoreA > lm.scoreB ? m.a : m.b} ${Math.max(lm.scoreA, lm.scoreB)}–${Math.min(lm.scoreA, lm.scoreB)}`,
    date: manilaFormat(Date.parse(`${lm.ymd}T12:00:00+08:00`), { month: 'short', day: 'numeric' }), id: lm.id,
  } : null;
  const watch = (m.scorers || []).map((w, i) => (w ? {
    playerId: w.id, name: w.name, initials: w.name.split(' ').map(x => x.charAt(0)).join('').slice(0, 2).toUpperCase(),
    ring: colorOf(i ? m.b : m.a), photoUrl: playerPhotoUrl(w.id, 96),
    line: `${w.ppg} ppg vs ${w.opp}`, team: w.team,
  } : null));
  const clean = t => String(t || '').replace(/\*\*/g, '');
  return {
    state: p.state, recA: m.recordA ? `${m.recordA.w}–${m.recordA.l}` : '', recB: m.recordB ? `${m.recordB.w}–${m.recordB.l}` : '',
    formA: lastFive(m.a || game.team_a_name), formB: lastFive(m.b || game.team_b_name), last,
    series: m.meetings ? `${m.a} ${m.winsA}–${m.winsB} ${m.b}` : '', firstMeeting: !!m.firstMeeting,
    watch, story: p.story ? { headline: clean(p.story.headline), body: clean(p.story.body) } : null,
  };
}

// Home's live card (views/app/feed.js appLiveNow): every game being scored right now that's
// visible to everyone (never a review), newest play first. Loaded after the screen and again
// every 15 s while Home is open (public/app.js data-block-every), as JSON { html }.
function appLiveNowGames() {
  return portalDb.prepare("SELECT game_id FROM score_games WHERE status = 'live'").all()
    .map(r => getGameById(r.game_id)).filter(g => g && !g.under_review && !isPlayedGame(g))
    .map(g => ({ g, l: liveScoreFor(g) })).filter(x => x.l && !x.l.ended)
    .sort((x, y) => y.l.updatedAt - x.l.updatedAt);
}
// For admins, games being reviewed (by any admin) as well: the reviewed plays, live, admins only.
function appReviewNowGames() {
  return portalDb.prepare("SELECT game_id FROM score_games WHERE status != 'published'").all()
    .map(r => getGameById(r.game_id)).filter(g => g && getScoreGame(g.id)?.settings?.review)
    // From the moment it starts (no plays yet: 0–0, "No plays yet").
    .map(g => ({ g, l: reviewLiveFor(g) || { score: { a: 0, b: 0 }, empty: true }, review: getScoreGame(g.id).settings.review }));
}
app.get('/app/live-now', requireAppData, (req, res) => {
  const me = appMe(req);
  const colorOf = appColorOf(getAllTeams());
  const reviews = canWatchReview(req, me.playerId) ? appReviewNowGames().map(({ g, l, review }) => ({
    id: g.id, href: `/app/games/${encodeURIComponent(g.id)}?review=live`, when: l.empty ? 'No plays yet' : liveWhen(l), line: `${review.name || 'An admin'} is ${review.kind === 'video' ? 're-tracking it from the video' : 'checking the plays'}. Only admins see this.`,
    kicker: 'Review · in progress', media: gameMedia(g), review: true,
    a: { name: g.team_a_name, color: colorOf(g.team_a_name), score: l.score.a }, b: { name: g.team_b_name, color: colorOf(g.team_b_name), score: l.score.b },
  })) : [];
  const cards = appLiveNowGames().map(({ g, l }) => {
    const x = liveExtrasFor(g, me.playerId);
    const run = x?.momentum?.run, odds = x?.odds;
    const nm = t => titleCase(t === 'a' ? g.team_a_name : g.team_b_name);
    const line = run ? `${nm(run.team)} on a ${run.pts}–0 run` : odds ? `${nm(odds.a >= odds.b ? 'a' : 'b')} ${Math.max(odds.a, odds.b)}% to win` : '';
    return { id: g.id, when: liveWhen(l), line, kicker: `Live · ${g.playoff_round || gameTypeLabel(g) || 'Regular season'}`, media: gameMedia(g), a: { name: g.team_a_name, color: colorOf(g.team_a_name), score: l.score.a }, b: { name: g.team_b_name, color: colorOf(g.team_b_name), score: l.score.b } };
  });
  res.set('Cache-Control', 'private, no-store');
  res.json({ html: appLiveNow([...cards, ...reviews]) });
});
// Home's rail (views/app/feed.js appRail): the next game day's games. While picks are open
// they're pick cards; once closed, preview cards with the player's pick; gone after the games.
// Loaded after the screen (it needs the full picks context, ~100 ms) as JSON { html }.
app.get('/app/rail', requireAppData, (req, res) => {
  const me = appMe(req);
  const all = getAllGames();
  const sorted = byDate(all);
  const pctx = buildPicksContext(sorted);
  const opens = picksEnabled() ? openPicks(sorted, pctx, me.playerId) : [];
  const day = opens.map(o => o.ymd).filter(Boolean).sort()[0];
  if (!day) return res.json({ html: '' });
  const colorOf = appColorOf(getAllTeams());
  const gameOf = Object.fromEntries(all.map(g => [g.id, g]));
  const playerMap = Object.fromEntries(getAllPlayers().map(p => [p.id, p]));
  const cards = opens.filter(o => o.ymd === day).map(o => {
    const g = appPickGame(o, gameOf[o.id], colorOf);
    // Being scored: the card shows the live score instead of the preview.
    const l = o.closed && gameOf[o.id] ? liveScoreFor(gameOf[o.id]) : null;
    if (l && !l.ended) return { ...g, live: { a: l.score.a, b: l.score.b, when: liveWhen(l) } };
    return o.closed ? { ...g, preview: appPreview(gameOf[o.id], sorted, pctx, playerMap, colorOf) } : g;
  });
  res.json({ html: appRail({ dayLabel: manilaFormat(Date.parse(`${day}T12:00:00+08:00`), { weekday: 'long' }), cards }) });
});

// ── Picks (Who wins?) ── The site's openPicks() cards for this player, shaped for the app,
// then the Pickmaster board and the player's settled picks. Picks are saved by the site's
// own POST /games/:id/pick (public/app.js), so every rule — open/closed, deadlines, who may
// pick — stays in one place.
app.get('/app/picks', requireApp, (req, res) => {
  const me = appMe(req);
  if (!picksEnabled()) return sendTab(res, me, { title: 'Who wins? · WKND', tab: 'picks', body: appPicksPage({ off: true }) });
  const all = byDate(getAllGames());
  const pctx = buildPicksContext(all);
  const open = openPicks(all, pctx, me.playerId);
  const teams = getAllTeams();
  const colorOf = name => { const t = teams.find(x => x.name === name); return t ? (t.color || teamColor(t.name)) : teamColor(name); };
  const gameOf = Object.fromEntries(all.map(g => [g.id, g]));
  const sp = seasonPicks(pctx, String(getPortalCurrentSeason()));
  const r = sp.records[me.playerId];
  const row = sp.board.rows.find(x => x.playerId === me.playerId);
  const tiedAt = rank => sp.board.rows.filter(y => y.rank === rank).length > 1;
  const record = r ? { wl: `${r.correct}–${r.wrong}`, net: fmtPts(r.net), rank: row?.rank || null, tied: !!row && tiedAt(row.rank) } : null;
  const games = open.map(o => appPickGame(o, gameOf[o.id], colorOf));
  // Pickmaster: the top 10, and the player's own row under a gap when they're further down.
  const players = Object.fromEntries(getAllPlayers().map(p => [p.id, p]));
  const boardRow = (x, gap = false) => ({ rank: x.rank, tied: tiedAt(x.rank), name: displayPlayerName(players[x.playerId]?.name || ''), wl: `${x.correct}–${x.wrong}`, net: fmtPts(x.net), me: x.playerId === me.playerId, gap });
  const board = sp.board.rows.slice(0, 10).map(x => boardRow(x));
  if (row && !board.some(x => x.me)) board.push(boardRow(row, true));
  const past = (r?.results || []).slice().reverse().slice(0, 10).map(x => {
    const g = gameOf[x.gameId];
    if (!g) return null;
    const pick = x.side === 'a' ? g.team_a_name : g.team_b_name;
    return { date: shortDate(g.date), matchup: `${g.team_a_name} vs ${g.team_b_name}`, pick, color: colorOf(pick), correct: !!x.correct };
  }).filter(Boolean);
  sendTab(res, me, { title: 'Who wins? · WKND', tab: 'picks', body: appPicksPage({ record, games, board, past }) });
});

// ── Papawis (views/app/papawis.js) ──
// The site's runs and rules, shaped for the app. Joining, leaving and the free run go
// through the site's own POST /papawis/:id/join | cancel | voucher (public/app.js
// initPapawis), so every rule (bans, unpaid games, probation deposits, the 3-day cancel
// window, the waitlist) lives in one place. The states below mirror views/papawis.js runBlock.
const pwDaysUntil = ymd => Math.round((Date.parse(`${ymd}T00:00:00Z`) - Date.parse(`${manilaTodayStr()}T00:00:00Z`)) / 86400000);
const pwDay = ymd => manilaFormat(Date.parse(`${ymd}T12:00:00+08:00`), { weekday: 'short', month: 'short', day: 'numeric' });
const pwPeso = n => `₱${Number(n).toLocaleString('en-US')}`;
// The calendar block on app rows: "07" / "Nov".
const pwCal = ymd => ({ dayNum: ymd.slice(8, 10), mon: manilaFormat(Date.parse(`${ymd}T12:00:00+08:00`), { month: 'short' }) });
// One sign-up as a seat in the app (views/app/papawis.js): first name under the face, the
// league ring, the Light / Dark side once teams are made.
function pwFace(s, teams, meId) {
  const name = displayPlayerName(s.player_name || ''), guest = !!s.guest_name;
  return { ini: guest ? 'G' : name.split(' ').map(w => w.charAt(0)).join('').slice(0, 2).toUpperCase(),
    first: guest ? String(s.guest_name).split(' ')[0] : name.split(' ')[0],
    color: s.team_id && !guest ? teamColorById(teams, s.team_id) : 'var(--subtle)', me: s.player_id === meId && !guest,
    team: s.team === 'light' || s.team === 'dark' ? s.team : '', pending: s.status === 'pending',
    photoUrl: guest ? '' : playerPhotoUrl(s.player_id, 96), playerId: guest ? '' : s.player_id };
}
function appPapawisRuns(me) {
  if (getSetting('papawis_enabled', '0') !== '1') return [];
  const teams = getAllTeams();
  const banned = !!me.player.banned_at;
  const unpaid = hasUnpaidCompletedPapawis(me.playerId);
  const vouchers = getVouchersForPlayer(me.playerId);
  const freeRun = vouchers.find(v => v.status === 'active') || null;
  const applied = new Set(vouchers.filter(v => v.status === 'reserved').map(v => v.signup_id));
  const runs = getPapawisGames()
    .filter(g => g.status === 'open' && pwDaysUntil(g.date) >= 0)
    .sort((a, b) => `${a.date} ${a.start_time}`.localeCompare(`${b.date} ${b.start_time}`));
  return runs.map(g => {
    const court = getPapawisCourtByName(g.location);
    const dLeft = pwDaysUntil(g.date);
    const scheduled = !isPapawisSignupOpenNow(g);
    const signups = scheduled ? [] : getPapawisSignups(g.id);
    const confirmed = signups.filter(s => s.status === 'confirmed');
    const waitlist = signups.filter(s => s.status === 'waitlist' || s.status === 'pending');
    const max = g.max_slots || 0, filled = confirmed.length, open = Math.max(0, max - filled);
    const full = !scheduled && filled >= max;
    const cancellable = dLeft >= PAPAWIS_CUTOFF_DAYS;
    const mine = scheduled ? null : signups.find(s => !s.guest_name && s.player_id === me.playerId) || null;
    const courtRate = g.court_rate_per_hour ? null : (court?.price_per_hour || null);
    const price = estimatedPapawisPrice(g, Math.max(filled, max), courtRate);
    const opensAt = papawisSignupOpensAtMs(g);
    const startClock = g.start_time ? formatTimeRange(g.start_time, null) : '';
    // What the player can do now, as views/papawis.js decides it (deposits and settling a
    // balance happen on the site for now: shown as information).
    let state;
    if (scheduled) state = { kind: 'scheduled', note: `Sign-ups open ${pwDay(new Date(opensAt + 8 * 3600e3).toISOString().slice(0, 10))} · 8:00 AM` };
    else if (mine?.status === 'confirmed') state = { kind: 'in', slot: confirmed.indexOf(mine) + 1, cancellable, freeApplied: applied.has(mine.id), freeAvailable: !!freeRun && !applied.has(mine.id) };
    else if (mine?.status === 'pending') state = { kind: 'pending' };
    else if (mine?.status === 'waitlist') state = { kind: 'waitlist', pos: waitlist.indexOf(mine) + 1 };
    else if (banned) state = { kind: 'banned' };
    else if (unpaid) state = { kind: 'unpaid' };
    else if (full) state = { kind: 'join-waitlist', waiting: waitlist.length };
    else state = { kind: 'join', open, confirmFirst: !cancellable };
    const face = s => pwFace(s, teams, me.playerId);
    // Teams show once the admin has sent them, as on the site (views/utils.js papawisTeamsSent).
    const teamsOut = papawisTeamsSent(confirmed);
    const opensDay = pwDay(new Date(opensAt + 8 * 3600e3).toISOString().slice(0, 10));
    return {
      id: g.id, title: g.title || `${manilaFormat(Date.parse(`${g.date}T12:00:00+08:00`), { weekday: 'long' })} run`,
      day: pwDay(g.date), today: dLeft === 0, time: formatTimeRange(g.start_time, g.end_time) || g.time_label || '',
      place: g.location || 'Court to be announced', photo: papawisCoverUrl(g, court) || '',
      tipAt: Date.parse(`${g.date}T${g.start_time || '00:00'}:00+08:00`), opensAt, scheduled,
      opensLabel: `${opensDay.split(',')[0]}, 8:00 AM`, opensShort: opensDay.split(',')[0], ...pwCal(g.date),
      filled, max, open, full, waiting: waitlist.length, faces: confirmed.map(face), waitFaces: waitlist.map(face),
      teamsOut, myTeam: teamsOut && mine?.status === 'confirmed' ? (mine.team === 'light' || mine.team === 'dark' ? mine.team : '') : '',
      price: price ? pwPeso(price) : '', priceNote: `Estimate with ${Math.max(filled, max)} players · split after the game`,
      cancelBy: cancellable ? pwDay(addDaysYmd(g.date, -PAPAWIS_CUTOFF_DAYS)) : '', startClock, state,
    };
  });
}
// Every past run, newest first (everything that isn't upcoming, as the site's "Past runs"),
// with the player's own result on each: played / paid / unpaid, or listed on a called-off run.
const pwKind = g => (g.status === 'cancelled' ? 'cancelled' : g.status === 'completed' ? 'played' : 'pending');
function pwMine(kind, signup, price) {
  if (!signup || signup.status !== 'confirmed') return null;
  if (kind === 'cancelled') return 'listed';
  return kind === 'played' && price ? (signup.paid_at ? 'paid' : 'unpaid') : 'played';
}
function appPapawisPast(me) {
  const key = g => `${g.date}T${g.start_time || '00:00'}`;
  const mine = new Map();
  for (const h of getPapawisHistoryForPlayer(me.playerId, 500)) if (!h.guest_name && h.status === 'confirmed') mine.set(h.game_id, h);
  return getPapawisGames()
    .filter(g => !(g.status === 'open' && pwDaysUntil(g.date) >= 0))
    .sort((a, b) => (key(a) < key(b) ? 1 : -1))
    .map(g => {
      const kind = pwKind(g), price = Number(g.price_per_player) || 0;
      return { id: g.id, title: g.title || 'Papawis run', place: g.location || '', ...pwCal(g.date), kind,
        count: g.confirmed_count || 0, max: g.max_slots || 0, price, mine: pwMine(kind, mine.get(g.id), price) };
    });
}

// ── Settle a balance (views/app/settle.js) ──
// The site's own Settle Balance in the app: what's owed (each unpaid Papawis run), the
// GCash details (copy the number, save the QR, open GCash), then the receipt screenshot,
// sent to the site's POST /settle-balance (pending until an admin confirms it, as now).
//
// The QR can carry the amount: the stored GCash QR (gcash_qr_payload) is a QR Ph (EMVCo)
// code, which has a slot for it (tag 54). qrPhWithAmount() adds it and recomputes the
// checksum, so GCash's "Upload QR" fills in both the account and the amount. A payload
// that isn't valid QR Ph is shown as stored.
function emvFields(s) {
  const out = [];
  for (let i = 0; i < s.length;) {
    const id = s.slice(i, i + 2), len = Number(s.slice(i + 2, i + 4));
    if (!/^\d{2}$/.test(id) || !/^\d{2}$/.test(s.slice(i + 2, i + 4))) return null;
    const v = s.slice(i + 4, i + 4 + len);
    if (v.length !== len) return null;
    out.push([id, v]); i += 4 + len;
  }
  return out;
}
function crc16ccitt(str) {
  let crc = 0xFFFF;
  for (const byte of Buffer.from(str, 'utf8')) {
    crc ^= byte << 8;
    for (let k = 0; k < 8; k++) crc = crc & 0x8000 ? ((crc << 1) ^ 0x1021) & 0xFFFF : (crc << 1) & 0xFFFF;
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}
function qrPhWithAmount(payload, amount) {
  const s = String(payload || '').trim();
  const f = emvFields(s);
  if (!f || f[0]?.[0] !== '00' || f[f.length - 1]?.[0] !== '63' || crc16ccitt(s.slice(0, -4)) !== s.slice(-4).toUpperCase()) return null;
  const fields = f.filter(([id]) => id !== '63' && id !== '54').map(([id, v]) => (id === '01' ? ['01', '12'] : [id, v]));
  fields.push(['54', Number(amount).toFixed(2)]);
  fields.sort((a, b) => a[0].localeCompare(b[0]));
  const body = fields.map(([id, v]) => `${id}${String(v.length).padStart(2, '0')}${v}`).join('') + '6304';
  return body + crc16ccitt(body);
}

app.get('/app/settle/qr.png', requireAppData, async (req, res) => {
  const payload = getSetting('gcash_qr_payload', '');
  if (!payload) return res.status(404).end();
  const amount = Number(req.query.amount);
  const withAmount = amount > 0 && amount <= 100000 ? qrPhWithAmount(payload, amount) : null;
  try {
    const png = await QRCode.toBuffer(withAmount || payload, { type: 'png', width: 600, margin: 2 });
    res.set('Cache-Control', 'private, max-age=600').type('png').send(png);
  } catch (e) { console.error('[settle qr]', e.message); res.status(500).end(); }
});

app.get('/app/settle', requireApp, (req, res) => {
  const me = appMe(req);
  const balance = Number(getPlayerFinancials(me.playerId)?.current_balance || 0);
  const runs = getUnpaidPapawisForPlayer(me.playerId).map(r => ({ day: pwDay(r.game_date), amount: Number(r.price_per_player) || 0 }));
  const pending = getPlayerTransactions(me.playerId).filter(t => t.type === 'payment' && t.status === 'pending')
    .map(t => ({ amount: Number(t.amount) || 0, category: t.category || '', when: pwDay(t.date) }));
  const asked = PAYMENT_CATEGORIES.includes(req.query.category) ? req.query.category : '';
  const deposit = asked === 'Papawis Deposit' && balance <= 0;
  const minDeposit = getMaxPapawisPrice();
  const payload = getSetting('gcash_qr_payload', '');
  sendTab(res, me, { title: 'Settle · WKND', tab: 'me', body: appSettlePage({
    back: req.query.from === 'papawis' ? { href: '/app/papawis', label: 'Papawis' } : req.query.from === 'home' ? { href: '/app', label: 'Home' } : { href: '/app/me', label: 'Me' },
    balance, runs, pending, deposit,
    amount: deposit ? (minDeposit || '') : balance > 0 ? balance : '',
    presets: deposit ? depositPresets(minDeposit) : [],
    category: asked || (runs.length ? 'Papawis' : 'Other'), categories: PAYMENT_CATEGORIES,
    gcash: { name: getSetting('gcash_name', ''), number: getSetting('gcash_number', ''), hasQr: !!payload, amountInQr: !!qrPhWithAmount(payload, 1) },
  }) });
});

// Rate your game in the app: where a "Rate …" notification opens. Same data as the site's
// /rate/:kind/:ref (rateScreenData); saving posts to that route (public/app.js initRate).
app.get('/app/rate/:kind/:ref', requireApp, (req, res) => {
  const me = appMe(req);
  const back = appBack(req);
  const send = x => sendTab(res, me, { title: 'Rate your game · WKND', tab: back.tab, body: appRatePage({ back, ...x }) });
  const game = gameRatingsOn() && RATE_KINDS.includes(req.params.kind) ? resolveRateGame(req.params.kind, req.params.ref) : null;
  if (!game) return send({ missing: 'This game isn’t open for ratings.' });
  if (!game.playerIds.includes(me.playerId)) return send({ missing: 'Only players who played this game can rate it.' });
  send({ game, closed: !game.open, ...rateScreenData(game, me.playerId) });
});

