// Which admin section owns each site setting. /admin/site/settings is shared by every page
// that saves a setting, so it checks each key against the admin's sections (a Papawis-only
// admin can flip the Papawis switches but not, say, the GCash number). Unrestricted admins
// skip the check. Keep this in step with where each control lives in the admin.
function siteSettingSection(key) {
  if (/^(papawis_)/.test(key)) return 'papawis';
  if (key === 'marketplace_enabled') return 'marketplace';
  if (key === 'posts_enabled' || key === 'posts_notify_on_publish') return 'content';
  if (/^polls_/.test(key)) return 'community';
  if (/^season_/.test(key)) return 'season';
  if (/^picks_|^home_picks_widget_enabled$/.test(key)) return 'games-stats';
  if (/^(awards_enabled|award_|mvp_)/.test(key)) return 'awards';
  if (key === 'player_reports_enabled' || key === 'raffle_enabled') return 'community';
  if (/^gcash_/.test(key)) return 'finance';
  if (/^app_(open|beta|require_install)$/.test(key)) return 'members';
  return 'site'; // comments, ratings, header, homepage cards, join banner
}

app.post('/admin/site/settings', requireAuth, express.json(), (req, res) => {
  const allowedSections = getAdminAllowedSections(req);
  if (allowedSections) {
    const denied = Object.keys(req.body || {}).filter(k => !allowedSections.includes(siteSettingSection(k)));
    if (denied.length) return res.status(403).json({ error: `Not allowed to change: ${denied.join(', ')}` });
  }
  const staticAllowed = new Set([
    'mvp_race_enabled', 'awards_enabled', 'papawis_enabled', 'papawis_reminders_enabled', 'papawis_slot_alerts_enabled', 'posts_enabled', 'comments_enabled', 'peer_ratings_enabled', 'player_reports_enabled', 'marketplace_enabled', 'mega_menu_enabled', 'home_show_roster_moves',
    'game_ratings_enabled', 'game_rate_email_enabled', 'raffle_enabled',
    'picks_enabled', 'picks_odds_enabled', 'home_picks_widget_enabled', 'mvp_podium_enabled',
    'papawis_court_ratings_enabled', 'papawis_court_votes_enabled', 'papawis_court_requests_enabled', 'papawis_court_partner_enabled',
    // Auto-nudges (lib/broadcast.js): one switch per feature page.
    'picks_auto_remind', 'mvp_podium_auto_remind', 'posts_notify_on_publish', 'polls_notify_on_open', 'season_auto_nudges',
    ...AWARD_SECTION_KEYS.map(k => `award_show_${k}`),
    'reg_open',
    'gcash_name', 'gcash_number', 'gcash_qr_payload',
    'app_open', 'app_beta', 'app_require_install',
  ]);
  const articleKeyRe = new RegExp(`^award_article_(${AWARD_SECTION_KEYS.join('|')})(_[\\w-]+)?_\\d+$`);
  const homeGalleryKeyRe = new RegExp(`^award_home_(${AWARD_SECTION_KEYS.join('|')})_\\d+$`);
  const nextUpKeys = new Set(HOME_NEXTUP_CARDS.map(c => c.key));
  for (const [key, value] of Object.entries(req.body || {})) {
    if (staticAllowed.has(key) || articleKeyRe.test(key) || homeGalleryKeyRe.test(key)) setSetting(key, String(value));
    else if ((key === 'home_nextup_card_1' || key === 'home_nextup_card_2') && nextUpKeys.has(String(value))) setSetting(key, String(value));
    else if (key === 'picks_close_time' && /^([01]\d|2[0-3]):[0-5]\d$/.test(String(value))) setSetting(key, String(value));
    else if (key === 'game_rate_court_reask_days') {
      const n = Math.round(Number(value));
      if (!(n >= 1 && n <= 365)) return res.status(400).json({ error: 'Use a number of days from 1 to 365' });
      setSetting(key, String(n));
    }
    else if (key === 'mvp_reveal_mode' && MVP_REVEAL_MODES.includes(String(value))) setSetting(key, String(value));
    else if (key === 'playoff_mode' && PLAYOFF_MODES.includes(String(value))) { setSetting(key, String(value)); headerInfoCache.at = 0; }
    else if (key === 'playoff_tip_time') {
      const v = String(value || '').trim();
      if (v && !/^([01]\d|2[0-3]):[0-5]\d$/.test(v)) return res.status(400).json({ error: 'Use HH:MM, 24-hour (e.g. 07:00)' });
      setSetting(key, v);
    }
    else if (key === 'mvp_bonus_close') {
      const v = String(value || '').trim();
      if (v && !/^\d{4}-\d{2}-\d{2} ([01]\d|2[0-3]):[0-5]\d$/.test(v)) return res.status(400).json({ error: 'Use YYYY-MM-DD HH:MM' });
      setSetting(key, v);
    }
  }
  res.json({ ok: true });
});

// /admin/ledger season param: missing → the latest ledger season; '' or 'all' → all time.
function ledgerSeasonFromQuery(q, seasons) {
  if (q === undefined) return seasons[0] || '';
  const s = String(q);
  return s === 'all' ? '' : s;
}

app.get('/admin/ledger', requireAuth, (req, res) => {
  // Balances are never season-scoped: always the true all-time running balance. The season
  // pick only changes the fee progress column and "Collected".
  const balMap   = Object.fromEntries(getAllBalances().map(r => [r.player_id, r]));
  const reminders = getLastBalanceReminders();
  // Rostered for the current season, plus anyone with real ledger history (a Papawis-only
  // player who never registered must stay reachable from this list).
  const currentSeasonPlayerIds = getConfirmedSeasonPlayerIds(getPortalCurrentSeason());
  const visiblePlayerIds = new Set([...currentSeasonPlayerIds, ...Object.keys(balMap)]);
  const allPlayers = getAllPlayers();
  const players  = allPlayers.filter(p => visiblePlayerIds.has(p.id));
  const seasons  = getLedgerSeasons();
  const season   = ledgerSeasonFromQuery(req.query.season, seasons);
  const quota    = season ? getSeasonQuota(season) : 0;
  // Fee progress counts Season Fee payments tagged with that season only, the same rule as
  // Finance's getSeasonFeePaid.
  const feePaidByPlayer = {};
  if (season) for (const t of getAllTransactionsBySeason(season)) {
    if (t.season === season && t.category === 'Season Fee' && t.type === 'payment' && t.status === 'confirmed') feePaidByPlayer[t.player_id] = (feePaidByPlayer[t.player_id] || 0) + t.amount;
  }
  // One scope for everything pending: all time. getPendingTransactions is newest first, so
  // the first ref seen per player is their latest pending ref.
  const pendingNewest = getPendingTransactions();
  const latestRefByPlayer = {};
  for (const t of pendingNewest) if (t.reference_no && !latestRefByPlayer[t.player_id]) latestRefByPlayer[t.player_id] = t.reference_no;
  const collected = Number((season ? getSeasonSummary(season) : getAllSummary()).total_paid) || 0;
  // ?player=<id> renders that player's drawer open.
  let open = null;
  const openPlayer = req.query.player ? getPlayerWithTeam(String(req.query.player)) : null;
  if (openPlayer) {
    const transactions = getPlayerTransactions(openPlayer.id);
    const confirmedPay = transactions.filter(t => t.status === 'confirmed' && t.type === 'payment');
    open = {
      player: openPlayer, fin: getPlayerFinancials(openPlayer.id), transactions,
      seasonPaid: season ? confirmedPay.filter(t => t.season === season).reduce((s, t) => s + t.amount, 0) : 0,
      feePaid: feePaidByPlayer[openPlayer.id] || 0,
      standing: balanceStanding(balMap[openPlayer.id], reminders[openPlayer.id]),
    };
  }
  res.send(renderAdminPage(req, {
    title: 'Ledger',
    currentPath: '/admin/ledger',
    body: adminLedgerBody({
      players, allPlayers, balMap, lastActivityMap: getLastTransactionDates(), seasons, season, quota, feePaidByPlayer,
      standingById: Object.fromEntries(Object.values(balMap).map(b => [b.player_id, balanceStanding(b, reminders[b.player_id])])), remindedById: reminders, overdueDays: OVERDUE_DAYS,
      bannedIds: getBannedPlayerIds(),
      pending: [...pendingNewest].reverse(), latestRefByPlayer, collected, colorById: adminTeamColorByPlayer(), query: req.query, open,
    }),
  }));
});

app.get('/admin/ledger/:id', requireAuth, (req, res) => {
  const player = getPlayerWithTeam(req.params.id);
  if (!player) return res.status(404).send(renderAdminPage(req, {
    title: 'Not Found', currentPath: '/admin/ledger',
    body: '<div class="aui-page"><div class="aui-empty"><div class="aui-empty__title">Player not found</div><a class="aui-link" href="/admin/ledger">Back to the ledger</a></div></div>',
  }));
  const seasons = getLedgerSeasons();
  const season  = ledgerSeasonFromQuery(req.query.season, seasons);
  const fin     = getPlayerFinancials(player.id) ?? {};
  const allTxs  = getPlayerTransactions(player.id);
  const txs     = season ? getPlayerTransactionsBySeason(player.id, season) : allTxs;
  const quota   = season ? getSeasonQuota(season) : 0;
  const feePaid = season ? allTxs
    .filter(t => t.season === season && t.category === 'Season Fee' && t.type === 'payment' && t.status === 'confirmed')
    .reduce((s, t) => s + t.amount, 0) : 0;
  const pending = allTxs.filter(t => t.status === 'pending').reverse().map(t => ({ ...t, player_name: player.name }));
  res.send(renderAdminPage(req, {
    title: `${displayPlayerName(player.name)} · Ledger`,
    currentPath: '/admin/ledger',
    body: adminLedgerPlayerBody({ player, fin, transactions: txs, seasons, season, quota, feePaid, pending, colorById: adminTeamColorByPlayer(), query: req.query }),
  }));
});

// A player-submitted proof-of-payment screenshot. Stored as a data:image URL (settle-balance)
// or, for older rows, a link; only image data and http(s)/relative links are ever served.
app.get('/admin/ledger/transaction/:id/screenshot', requireAuth, (req, res) => {
  const tx = getTransactionById(req.params.id);
  const u = String(tx?.screenshot_url || '').trim();
  const m = u.match(/^data:(image\/(?:png|jpe?g|gif|webp));base64,([A-Za-z0-9+/=\s]+)$/i);
  if (m) {
    res.set({ 'Content-Type': m[1].toLowerCase(), 'X-Content-Type-Options': 'nosniff', 'Cache-Control': 'private, max-age=300' });
    return res.send(Buffer.from(m[2], 'base64'));
  }
  // Same-site paths only start with one "/": "//x" and "/\x" (browsers read a backslash as a
  // slash) would be protocol-relative, and stray control characters or spaces get stripped by
  // browsers into the same thing, so none of those are ever redirected to.
  if (!/[\s\x00-\x1f\x7f\\]/.test(u) && (/^https?:\/\/[^/]/i.test(u) || /^\/(?![/\\])/.test(u))) return res.redirect(u);
  res.status(404).send('No screenshot');
});

// Shared by every real "money moved" event below — a confirmed charge or a confirmed
// payment, never a pending one (pending isn't a real event from the player's side yet).
function notifyLedgerEvent({ playerId, type, amount, notes }) {
  const amt = `₱${Number(amount).toLocaleString()}`;
  createNotification({
    playerId,
    type: type === 'charge' ? 'ledger_charge' : 'ledger_payment_confirmed',
    title: type === 'charge' ? `You were charged ${amt}` : `Payment confirmed: ${amt}`,
    body: notes || '',
    link: '/settle-balance',
  });
}

app.post('/admin/ledger/transaction', requireAuth, express.json(), (req, res) => {
  const { player_id, amount, type, payment_method, date, status, notes, reference_no, season, category } = req.body;
  if (!player_id || !amount || !date) return res.status(400).json({ error: 'player_id, amount, and date are required.' });
  const parsed = parseFloat(amount);
  if (isNaN(parsed) || parsed <= 0) return res.status(400).json({ error: 'Amount must be a positive number.' });
  if (!['payment', 'charge'].includes(type)) return res.status(400).json({ error: 'Invalid transaction type.' });
  if (!['confirmed', 'pending'].includes(status)) return res.status(400).json({ error: 'Invalid status.' });
  // A Papawis Deposit is never recorded confirmed directly, even if the admin picked that in
  // the form — the deposit-confirm flow (POST .../confirm-deposit and the ledger confirm
  // route above) is what actually promotes the player's held 'pending' signup into
  // confirmed/waitlist. Recording it confirmed here would show a confirmed deposit on the
  // ledger while their signup stays stuck pending forever, silently.
  const finalStatus = category === 'Papawis Deposit' ? 'pending' : status;
  const id = randomBytes(6).toString('hex');
  recordTransaction({ id, player_id, amount: parsed, type, payment_method: payment_method || '', date, status: finalStatus, notes: notes || '', reference_no: reference_no || '', season: season || '', category: category || '' });
  if (finalStatus === 'confirmed') notifyLedgerEvent({ playerId: player_id, type, amount: parsed, notes });
  res.json({ ok: true, id });
});


app.post('/admin/ledger/transaction/:id/confirm', requireAuth, express.json(), (req, res) => {
  const category = req.body?.category;
  if (category) setTransactionCategory(req.params.id, String(category).trim());
  const tx = getTransactionById(req.params.id);
  const ok = confirmTransaction(req.params.id);
  if (!ok) return res.status(400).json({ error: 'Transaction not found or not pending.' });
  if (tx) notifyLedgerEvent({ playerId: tx.player_id, type: tx.type, amount: tx.amount, notes: tx.notes });
  // A probation deposit can be confirmed from here instead of the Papawis admin page (which
  // scopes to one signup) — this route only knows the player, so promote every signup of
  // theirs still held on 'pending', not just one.
  if (tx && tx.category === 'Papawis Deposit' && tx.type === 'payment') {
    for (const signup of getPendingPapawisSignupsForPlayer(tx.player_id)) {
      const result = promotePapawisPendingSignup(signup.id);
      if (result.status === 'confirmed') {
        const game = getPapawisGame(signup.game_id);
        if (game) createNotification({
          playerId: signup.player_id, type: 'papawis_promoted',
          title: `You're confirmed for ${game.title || 'Papawis'}!`,
          body: 'Your deposit was confirmed and you have a spot.',
          link: `/papawis#pw-game-${game.id}`,
        });
      }
    }
  }
  res.json({ ok: true });
});

app.post('/admin/ledger/transaction/:id/void', requireAuth, (req, res) => {
  const ok = voidTransaction(req.params.id);
  if (!ok) return res.status(400).json({ error: 'Transaction not found, or already voided.' });
  res.json({ ok: true });
});

app.delete('/admin/ledger/transaction/:id', requireAuth, (req, res) => {
  const ok = deleteTransaction(req.params.id);
  if (!ok) return res.status(404).json({ error: 'Transaction not found.' });
  res.json({ ok: true });
});

// Manual balance reminder email + bell for one player (the ledger's bulk action calls this
// once per selected row). Overdue players get the suspension warning: lib/balance-reminders.js.
app.post('/admin/ledger/:id/remind', requireAuth, async (req, res) => {
  try {
    const result = await sendBalanceReminder(String(req.params.id));
    if (result.error === 'no_balance') return res.status(400).json({ error: 'They don’t owe anything.' });
    if (result.error === 'no_email') return res.status(400).json({ error: 'No valid email on file for this player.' });
    if (result.error === 'bounced') return res.status(400).json({ error: 'Their email bounced before, so it wasn’t sent.' });
    res.json({ ok: true, message: result.overdue ? 'Reminder sent, with the suspension warning.' : 'Reminder sent.' });
  } catch (e) {
    console.error('[ledger] balance reminder failed:', e.message);
    res.status(500).json({ error: 'Failed to send.' });
  }
});

app.post('/admin/ledger/bulk-charge', requireAuth, express.json(), (req, res) => {
  const { player_ids, amount, type, payment_method, date, status, notes, season, category, reference_no } = req.body;
  if (!player_ids?.length || !amount || !date) return res.status(400).json({ error: 'Pick at least one player, and fill in the amount and date.' });
  const parsed = parseFloat(amount);
  if (isNaN(parsed) || parsed <= 0) return res.status(400).json({ error: 'Amount must be a positive number.' });
  const txType = type || 'charge';
  if (!['payment', 'charge'].includes(txType)) return res.status(400).json({ error: 'Invalid transaction type.' });
  if (status && !['confirmed', 'pending'].includes(status)) return res.status(400).json({ error: 'Invalid status.' });
  // Same rule as a single add (POST /admin/ledger/transaction): a Papawis Deposit is always
  // recorded pending, so confirming it is what promotes the player's held signup.
  const finalStatus = category === 'Papawis Deposit' ? 'pending' : (status || 'confirmed');
  const ids = [...new Set([].concat(player_ids).map(String).filter(Boolean))];
  for (const pid of ids) {
    const id = randomBytes(6).toString('hex');
    recordTransaction({ id, player_id: pid, amount: parsed, type: txType, payment_method: payment_method || '', date, status: finalStatus, notes: notes || '', reference_no: reference_no || '', season: season || '', category: category || '' });
    if (finalStatus === 'confirmed') notifyLedgerEvent({ playerId: pid, type: txType, amount: parsed, notes });
  }
  const n = ids.length;
  const what = txType === 'charge' ? `Charged ${n} player${n === 1 ? '' : 's'}` : `Recorded ${n} payment${n === 1 ? '' : 's'}`;
  res.json({ ok: true, count: n, message: finalStatus === 'pending' ? `${what}, pending your confirm.` : `${what}.` });
});

app.get('/admin/finance', requireAuth, (req, res) => {
  const seasons = getLedgerSeasons();
  const season  = req.query.season || seasons[0] || '';
  const summary = season ? getSeasonSummary(season) : {};
  const quota   = season ? getSeasonQuota(season) : 0;
  // Balances are never season-scoped, same rule as /admin/ledger: a payment logged without
  // a season (or under another one) still pays down a season-tagged charge, so a
  // season-only sum showed fully paid players as owing.
  const balMap  = Object.fromEntries(getAllBalances().map(r => [r.player_id, r]));
  // "Players Settled" counts everyone actually confirmed for the season being viewed — not
  // every player who's ever existed, which is what was inflating it (see /admin/ledger's
  // own scoping) — a confirmed player without a team yet still owes money and still needs
  // to be tracked here.
  const seasonPlayerIds = season ? getConfirmedSeasonPlayerIds(season) : null;
  const allPlayers = getAllPlayers();
  const players = seasonPlayerIds ? allPlayers.filter(p => seasonPlayerIds.has(p.id)) : allPlayers;
  // The quota-progress *target* (quota × count) is different: it's asking "how much should
  // we collect this season," which only makes sense per team roster slot, so it counts only
  // confirmed players who've actually been assigned a team — not the full confirmed list above.
  const quotaPlayerCount = season ? players.filter(p => p.team_id).length : 0;
  // And the quota-progress numerator has to match that same "season fee" framing — Papawis,
  // Marketplace, etc. are real money in but aren't the season fee, so counting them here would
  // show progress toward the target from payments that have nothing to do with it.
  const quotaPaid = season ? getSeasonFeePaid(season) : 0;
  const pending = getPendingTransactions();
  const categoryTotals = season ? getCategoryTotals(season) : [];
  const teamTotals     = season ? getTeamTotals() : [];
  const recentTx       = getRecentTransactions();
  res.send(renderAdminPage(req, {
    title: 'Finance',
    currentPath: '/admin/finance',
    body: adminFinanceDashBody({ seasons, season, summary, quota, quotaPlayerCount, quotaPaid, balMap, players, allPlayers, pending, categoryTotals, teamTotals, recentTx }),
  }));
});

