app.get('/', (req, res) => {
  const teams = getAllTeams();
  const players = getAllPlayers();
  const games = byDate(getAllGames());

  const playerMap = Object.fromEntries(players.map(p => [p.id, p]));
  const teamMap = Object.fromEntries(teams.map(t => [t.id, t]));

  const completedGames = games.filter(g =>
    !g.scheduled && !g.under_review && (Number(g.team_a_score) + Number(g.team_b_score)) > 0
  );

  const highlights = buildHighlights(completedGames, playerMap, teamMap);
  // MVP Race takes over the hero sidebar while it's switched on (Visibility → MVP Race);
  // falls back to Player Highlights when it's off or the season has no candidates yet.
  const mvpRace = getSetting('mvp_race_enabled', '1') !== '0'
    ? buildHomeMvpRace(getPortalCurrentSeason(), completedGames, req.session?.playerPlayerId || null)
    : null;
  const standings = buildHomeStandings(getPortalCurrentSeason(), games);
  const nextUp = buildHomeNextUp({
    season: getPortalCurrentSeason(), players, games,
    isLoggedIn: !!req.session?.isAdmin || !!req.session?.playerRegId,
  });
  // Homepage carousel is admin-picked (Visibility → "Homepage: New/Traded"), not
  // auto-detected — a season can have real games recorded and still be too early for
  // leaders to feel meaningful, or an admin may just want to spotlight the new roster for a
  // while regardless of what data exists. Only the chosen side's queries actually run.
  const showRosterMoves = getSetting('home_show_roster_moves', '0') === '1';
  const leaderPlayers = showRosterMoves ? [] : buildLeaderPlayers(getPortalCurrentSeason());
  const rosterMovers = showRosterMoves ? buildRosterMovers(getSetting('signup_target_season', '') || getLatestRosterSeason()) : [];

  const isHomepageLoggedIn = !!req.session?.isAdmin || !!req.session?.playerRegId;
  const regBanner = !isHomepageLoggedIn && getSetting('reg_open', '0') === '1'
    ? { ...pickRegistrationBannerMessage(), stats: getCommunityStats() }
    : null;
  // Bottom-of-page closer for guests: a second row from the same AI message pool, re-picked
  // a few times so it doesn't repeat the banner's headline. "What you get" cards next to it
  // only list features that are actually switched on.
  let regCloser = null, memberPerks = null;
  if (regBanner) {
    regCloser = pickRegistrationBannerMessage();
    for (let i = 0; i < 4 && regCloser?.headline === regBanner.headline; i++) regCloser = pickRegistrationBannerMessage();
    memberPerks = {
      papawis:     getSetting('papawis_enabled', '0') === '1',
      marketplace: getSetting('marketplace_enabled', '0') === '1',
      comments:    getSetting('comments_enabled', '0') === '1',
    };
  }

  let signupBanner = null;
  if (req.session?.playerRegId && !req.session?.isAdmin) {
    const sigSeason = getSetting('signup_target_season', '');
    const sigOpen   = getSetting('season_signup_open', '0') === '1';
    if (sigSeason && sigOpen && !getSeasonSignup(req.session.playerRegId, sigSeason)) {
      signupBanner = { season: sigSeason, ...pickSignupBannerMessage() };
    }
  }

  const homePosts = getSetting('posts_enabled', '0') === '1' ? getPublicPosts() : [];

  // "Who wins?" widget for this viewer, plus logged-out versions of it and of Coming up for
  // the AI summaries (the same copy is shown to everyone).
  const viewerId = req.session?.playerPlayerId || null;
  const picksW = homePicksWidget(games, viewerId);
  const picksPublic = viewerId ? homePicksWidget(games, null) : picksW;
  const nextUpPublic = isHomepageLoggedIn
    ? buildHomeNextUp({ season: getPortalCurrentSeason(), players, games, isLoggedIn: false })
    : nextUp;

  // AI summaries above Game headlines / Season race / League leaders / Who wins? / Coming up
  // (stale ones refresh in the background; see getHomeSummaries).
  const summaries = getHomeSummaries(homeSummaryContext({
    season: getPortalCurrentSeason(), games, standings,
    boards: showRosterMoves ? [] : leaderBoards(leaderPlayers),
    picksW: picksPublic, nextUp: nextUpPublic,
  }));

  let awardsGallery = [];
  if (getSetting('awards_enabled', '1') !== '0') {
    const awardSeason = getPortalCurrentSeason();
    if (awardSeason) {
      const seasonAwards = getSeasonAwards(awardSeason);

      const soloItems = HOME_GALLERY_SOLO_TYPES
        .filter(type => getSetting(`award_home_${type}_${awardSeason}`, '0') === '1')
        .map(type => {
          const row = seasonAwards.find(a => a.award_type === type);
          if (!row) return null;
          return {
            kind: 'solo',
            type,
            label: AWARD_OG_BADGE[type].label,
            playerId: row.player_id,
            playerName: row.player_name,
            teamName: row.team_name,
            writeup: getSetting(`award_article_${type}_${awardSeason}`, ''),
            imgUrl: `/api/awards/${awardSeason}/${type}/${encodeURIComponent(row.player_id)}/gallery-image.png`,
          };
        })
        .filter(Boolean);

      // Team/roster awards have no single confirmed player or shared writeup — the hero
      // slide just shows the strip graphic with the award (and for Champions, the winning
      // team) as the title, no excerpt.
      const teamItems = HOME_GALLERY_TEAM_TYPES
        .filter(type => getSetting(`award_home_${type}_${awardSeason}`, '0') === '1')
        .map(type => {
          const rows = seasonAwards.filter(a => a.award_type === type);
          if (!rows.length) return null;
          const label = AWARD_OG_BADGE[type].label;
          const title = type === 'champion' && rows[0].team_name
            ? `${rows[0].team_name} — ${label}`
            : label;
          return {
            kind: 'team',
            type,
            label,
            title,
            imgUrl: `/api/awards/${awardSeason}/${type}/gallery-image.png`,
          };
        })
        .filter(Boolean);

      awardsGallery = [...soloItems, ...teamItems];
    }
  }

  res.send(renderPage(req, {
    title: 'WKND Basketball | Pickup Runs & League in Makati, Mandaluyong, Pasig',
    currentPath: req.path,
    body: homePage({ teams, players, games, highlights, mvpRace, nextUp: withLiveNextUp(nextUp, games), standings, papawisHero: homeHeroPapawis(), regCloser, memberPerks, leaderSeason: getPortalCurrentSeason(), leaderPlayers, rosterMovers, regBanner, signupBanner, posts: homePosts, awardsGallery, summaries, isAdmin: !!req.session?.isAdmin,
      headlineCards: gameCardExtras(headlineGamesOf(games), games, { viewerId: req.session?.playerPlayerId || null, playerMap }),
      picksWidgetHtml: picksWidget(picksW, { summary: summaries.picks || null, isAdmin: !!req.session?.isAdmin }),
      playoffBlock: homePlayoffBlock(getPortalCurrentSeason()) })
  }));
});

