// Regenerated fresh on every request from live DB rows — new games, players, teams,
// and posts show up here automatically the moment they exist, with no separate build
// or regeneration step needed.
app.get('/sitemap.xml', (req, res) => {
  const origin = SITE_ORIGIN;
  const flags  = getFeatureFlags();
  const isoDate = ms => ms ? new Date(ms).toISOString().slice(0, 10) : undefined;

  const urls = [
    { loc: '/',           priority: '1.0', changefreq: 'daily' },
    { loc: '/games',      priority: '0.8', changefreq: 'daily' },
    { loc: '/standings',  priority: '0.8', changefreq: 'daily' },
    { loc: '/playoffs',   priority: '0.6', changefreq: 'weekly' },
    { loc: '/teams',      priority: '0.7', changefreq: 'weekly' },
    { loc: '/players',    priority: '0.7', changefreq: 'weekly' },
    { loc: '/leaders',    priority: '0.7', changefreq: 'daily' },
    { loc: '/roast',      priority: '0.5', changefreq: 'weekly' },
  ];
  if (flags.awards)  urls.push({ loc: '/awards', priority: '0.5', changefreq: 'monthly' });
  if (flags.mvpRace) urls.push({ loc: '/mvp',    priority: '0.5', changefreq: 'weekly' });
  if (flags.mvpRace) urls.push({ loc: '/dpoy',   priority: '0.5', changefreq: 'weekly' });
  if (flags.papawis) urls.push({ loc: '/papawis', priority: '0.5', changefreq: 'weekly' });
  // Court pages: only courts with a live page (something played there, not hidden).
  const courtsLive = liveCourts();
  urls.push({ loc: '/join', priority: '0.8', changefreq: 'monthly' });
  if (courtsLive.length) urls.push({ loc: '/courts', priority: '0.6', changefreq: 'weekly' });
  for (const { court, p } of courtsLive) urls.push({ loc: `/courts/${encodeURIComponent(court.slug)}`, priority: '0.6', changefreq: p.nextRun ? 'daily' : 'weekly' });
  if (flags.posts)   urls.push({ loc: '/posts',   priority: '0.6', changefreq: 'daily' });
  if (picksEnabled()) urls.push({ loc: '/picks',  priority: '0.5', changefreq: 'weekly' }, { loc: '/picks/rules', priority: '0.3', changefreq: 'monthly' });

  for (const t of getAllTeams())   urls.push({ loc: `/teams/${teamSlug(t)}`,     priority: '0.6', changefreq: 'weekly' });
  // Only players with at least one game: an empty profile is a thin page (also noindexed).
  const playedIds = new Set(getAllPlayerCareerTotals().map(r => r.player_id));
  for (const p of getAllPlayers()) if (playedIds.has(p.id)) urls.push({ loc: `/players/${playerSlug(p)}`, priority: '0.5', changefreq: 'weekly' });
  // Each game's page is also its matchup preview (the old /picks/<game> pages redirect there),
  // so upcoming games change daily.
  const upcomingIds = new Set(getUpcomingGames(byDate(getAllGames())).map(g => g.id));
  for (const g of getAllGames()) {
    if (g.under_review) continue;
    urls.push({ loc: `/games/${gameSlug(g)}`, priority: '0.5', changefreq: upcomingIds.has(g.id) ? 'daily' : 'monthly', lastmod: isoDate(Date.parse(g.date)) });
  }
  if (flags.posts) {
    for (const post of getPublicPosts()) {
      urls.push({ loc: `/posts/${post.slug}`, priority: '0.5', changefreq: 'monthly', lastmod: isoDate(post.updated_at) });
    }
  }

  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map(u => `  <url>
    <loc>${origin}${u.loc}</loc>
${u.lastmod ? `    <lastmod>${u.lastmod}</lastmod>\n` : ''}    <changefreq>${u.changefreq}</changefreq>
    <priority>${u.priority}</priority>
  </url>`).join('\n')}
</urlset>
`;
  res.type('application/xml').send(xml);
});

app.get('/games/:ref', (req, res) => {
  const notFound = () => res.status(404).send(
    layout({ title: 'Not Found', currentPath: req.path, body: '<p style="padding:40px;color:var(--text-muted)">Game not found.</p>' })
  );
  // findGameRef also matches slugs nobody has visited yet (sitemap, pasted /picks links).
  const resolved = findGameRef(req.params.ref);
  if (!resolved) return notFound();
  const qs = req.originalUrl.includes('?') ? req.originalUrl.slice(req.originalUrl.indexOf('?')) : '';
  if (resolved.slug) return res.redirect(301, `/games/${resolved.slug}${qs}`);

  const game = getGameById(resolved.id);
  if (!game || game.under_review) return notFound();
  const court = game.court_id ? getPapawisCourtById(game.court_id) : null;

  const allGames = getAllGames();
  const sorted = byDate(allGames);
  const players = getAllPlayers();
  const playerMap = Object.fromEntries(players.map(p => [p.id, p]));
  const currentPlayerId = req.session?.playerPlayerId || null;
  const isFinal = (game.status === 'final' || game.status === 'complete') && Number(game.team_a_score) + Number(game.team_b_score) > 0;
  const ymd = gameYmd(game.date);
  const ctx = seasonContext([...sorted].reverse(), game);
  // Being scored: the live parts only, for public/live-score.js. A review watched live
  // (?review=live, admins, the switch on) shows the same way, the finished game or not.
  const reviewView = req.query.review === 'live' && canWatchReview(req) && reviewLiveOn(game);
  const live = reviewView ? reviewLiveFor(game) : isFinal ? null : liveScoreFor(game);
  const xPass = reviewView ? reviewPass(game) : 'live';
  if (req.get('X-Live')) {
    res.set('Cache-Control', 'private, no-store');
    // The hero's buttons stay put on the page (only its marked parts swap), so none here.
    return res.json(live ? { on: true, ...liveParts({ game, live, ctx, court, gameReaction: { count: 0 }, extras: liveExtrasFor(game, req.session?.playerPlayerId || '', xPass) }) } : { on: false, waiting: reviewView || (!isFinal && liveArmed(game)) });
  }
  const pctx = buildPicksContext(sorted);
  const T = titleCase;

  const commentsEnabled = getSetting('comments_enabled', '0') === '1';
  let comments = [], reactedIds = new Set(), gameReaction = { count: 0, reacted: false }, mentionablePlayers = [];
  if (commentsEnabled) {
    const win = liveWindowOf(game.id);
    comments = getGameComments(game.id).map(c => ({ ...c, during: duringGame(win, c) }));
    reactedIds = getReactedCommentIdsForPlayer(comments.map(c => c.id), currentPlayerId);
    gameReaction = { ...getGameReactionState(game.id, currentPlayerId), reactors: getGameReactors(game.id) };
    // Anyone with a real, working login — not just players in this specific game — so a
    // comment can pull in someone unrelated to the game just to get them talking.
    mentionablePlayers = getPlayersWithAccounts();
  }

  const common = {
    game, court, ymd, ctx, commentsEnabled, comments, reactedIds, gameReaction, mentionablePlayers,
    currentPlayerId, isPlayer: !!req.session?.playerRegId, isAdmin: isAdminWithSection(req, 'games-stats'),
    viewer: req.session?.playerRegId && playerMap[currentPlayerId] ? { id: currentPlayerId, name: playerMap[currentPlayerId].name, team: playerMap[currentPlayerId].team_name } : null,
  };
  const opens = picksEnabled() ? openPicks(sorted, pctx, currentPlayerId) : [];

  // ── Before the final: this page is the matchup preview (formerly /picks/<game>). ──
  if (!isFinal || reviewView) {
    const p = gamePreview(game, sorted, playerMap, pctx);
    const o = opens.find(x => x.id === game.id) || null;
    // The same day's other games, as compact pick cards in the rail (views/pick-card.js).
    const siblings = opens.filter(x => x.id !== game.id && x.ymd === ymd);
    const picks = {
      state: p.state, m: p.m, story: p.story, odds: shownOdds(game.id, p.odds, pctx), o, siblings,
      duel: p.m ? duelScorers(game, p.m, sorted, playerMap) : null,
      pickable: picksEnabled() && p.state !== 'final',
    };
    // Last meetings as the standard game cards (views/games.js gameCard).
    const meetingGames = (p.m?.lastMeetings || []).map(x => sorted.find(g => g.id === x.id)).filter(Boolean);
    picks.meetingCards = { games: meetingGames, ...gameCardExtras(meetingGames, sorted, { viewerId: currentPlayerId, playerMap }) };
    return res.send(renderPage(req, {
      title: live ? `${T(game.team_a_name)} ${live.score.a}–${live.score.b} ${T(game.team_b_name)} · Live | WKND Basketball` : `${T(game.team_a_name)} vs ${T(game.team_b_name)} · ${p.state === 'open' ? 'Who wins?' : 'Preview'} | WKND Basketball`,
      currentPath: req.path,
      metaTags: buildGameOgTags(req, game, court),
      body: gamePage({ ...common, state: 'upcoming', picks, live, extras: live ? liveExtrasFor(game, currentPlayerId || '', xPass) : null, liveArmed: reviewView || liveArmed(game), liveVer: CSS_VER, scoreHref: scoreHrefFor(req, game.id),
        chat: live && !live.ended && !reviewView && liveChatOn() ? liveChatData(game, req) : null,
        ...(reviewView ? { reviewLive: true, liveSrc: `/games/${encodeURIComponent(gameSlug(game))}?review=live` } : {}) }),
    }));
  }

  // ── After the final: recap, flow, performers, box score, picks verdict, the frozen preview. ──
  const stats = getGameDetailStats(game.id);
  const dnpPlayers = getGameDnpPlayers(game.id);
  const potgIds = potgIdsFor(game, stats);
  const potgPlayerId = potgIds[0] || null;
  const quarterScores = extractQuarterScores(game);
  const flow = gameFlow(game);
  const plays = keyPlays(flow, game, quarterScores);
  const won = stats.length ? howItWasWon(game, teamTotals(stats, game.team_a_name, game.team_a_to_team), teamTotals(stats, game.team_b_name, game.team_b_to_team)) : [];
  const history = stats.length ? playerHistory(stats.map(s => s.player_id), game) : {};
  const dc = stats.length ? duelAndCast(stats, game, history, potgIds) : null;
  // The viewer's own line, for the "Your game" strip + Share My Stats buttons.
  const mine = currentPlayerId ? stats.find(s => s.player_id === currentPlayerId) : null;
  const myGame = mine ? {
    stat: mine, badge: badgeFor(mine, history[mine.player_id]),
    vsAvg: history[mine.player_id]?.sGp ? Math.round((Number(mine.pts) - history[mine.player_id].sAvg) * 10) / 10 : null,
  } : null;
  const verdict = dc ? duelVerdict(dc.a, dc.b, game) : '';

  // "Who called it?": the pre-game odds plus pickers and your own pick.
  let called = null;
  if (picksEnabled()) {
    const odds = shownOdds(game.id, pctx.oddsById[game.id] || null, pctx);
    let result = null;
    const gp = getGamePicksWithPlayers(game.id);
    const pg = pctx.byId[game.id];
    const sg = gp.length && pg && seasonPicks(pctx, pg.season).settled.find(g => g.id === game.id);
    if (sg) result = pickResultOf(sg, gp, currentPlayerId, pctx);
    if (odds || result) called = { odds, result };
  }

  // The pre-game preview, merged into the page rather than kept as its own section. Built fresh
  // from games on earlier days (matchupAsOf), so older games without a stored preview get it too:
  //   usual  — each team's per-game averages in their earlier meetings with box scores (Team stats)
  //   watch  — each side's go-to scorer in those meetings, and what they did tonight (Top performers)
  //   series — the last three meetings as game cards, plus every result incl. this one (The series)
  //   story  — the storyline, only where one was stored when picks closed (the recap's footer)
  const asOf = matchupAsOf(game, sorted, playerMap);
  // usual.form: each team's last 5 going in, the Team stats chart's "Before tip-off" state.
  const usual = !asOf.firstMeeting && asOf.boxMeetings ? { rows: asOf.rows, n: asOf.boxMeetings, form: asOf.form } : null;
  const watch = (asOf.scorers || []).map(w => {
    if (!w) return null;
    const line = stats.find(x => x.player_id === w.id);
    return { id: w.id, name: w.name, team: w.team, opp: w.opp, ppg: w.ppg, games: w.games, pts: line ? +line.pts || 0 : null };
  });
  const ymdThis = gameYmd(game.date);
  const pairOf = g => [g.team_a_name, g.team_b_name].sort().join('|') === [game.team_a_name, game.team_b_name].sort().join('|');
  const results = sorted
    .filter(g => pairOf(g) && !g.under_review && (Number(g.team_a_score) + Number(g.team_b_score)) > 0 && gameYmd(g.date) <= ymdThis)
    .sort((x, y) => String(x.date).localeCompare(String(y.date)))
    .map(g => ({ id: g.id, winner: Number(g.team_a_score) > Number(g.team_b_score) ? g.team_a_name : g.team_b_name }));
  const seriesGames = (asOf.lastMeetings || []).map(x => sorted.find(g => g.id === x.id)).filter(Boolean);
  const series = seriesGames.length ? { results, games: seriesGames, ...gameCardExtras(seriesGames, sorted, { viewerId: currentPlayerId, playerMap }) } : null;
  const storyline = getGamePreview(game.id)?.story || null;
  const upNext = opens.filter(x => x.id !== game.id);
  const upNextLabel = upNext.length && upNext.every(x => x.ymd === upNext[0].ymd)
    ? new Date(`${upNext[0].ymd}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }) : '';

  res.send(renderPage(req, {
    // Scoreline first so "wknd blue vs maroon" searches match even when the AI headline
    // doesn't name the teams; the headline alone stays the og:title for share cards.
    title: (() => {
      const scoreline = `${T(game.team_a_name)} ${Number(game.team_a_score)}–${Number(game.team_b_score)} ${T(game.team_b_name)}`;
      const headline = writeupTitle(game.game_writeup);
      const namesTeams = headline && [game.team_a_name, game.team_b_name].every(t => headline.toLowerCase().includes(String(t).toLowerCase()));
      // A headline that already carries the score stands alone (no "81–96 … 81-96" repeat).
      const hasScore = headline && /\d+\s*[-–‑]\s*\d+/.test(headline);
      return seoTitle(namesTeams || hasScore ? headline : headline ? `${scoreline}: ${headline}` : scoreline);
    })(),
    currentPath: req.path,
    metaTags: buildGameOgTags(req, game, court),
    body: gamePage({
      ...common, state: 'final', stats, dnpPlayers, potgPlayerId, coPotg: potgIds.length > 1, quarterScores,
      flow, plays, won, dc, verdict, called, upNext, upNextLabel, myGame, usual, watch, series, storyline,
      shareLocked: shareCardsLocked(req),
      duelHist: dc ? Object.fromEntries([dc.a, dc.b].map(s => [s.player_id, meetingPoints(game, sorted, s.player_id)])) : {},
      // A finished game is an archive: a missing writeup is written on the first page view
      // (any season — at most 2 in flight, so a crawler only queues them), then kept as written
      // (keep). Admin Regenerate is the only rewrite.
      sections: sectionSummaries(gameSectionFacts(game, { stats, dc, won }), { keep: true }),
    }),
  }));
});

// Story-style share card for one player's own line in one game — gated to the
// logged-in player who actually played in it, same pattern as /me/writeup (keyed
// off the session, no ownership param to spoof).
// Premium share templates (lib/share-card-templates.js) are locked while the player owes —
// same signal as the balance reminder bar (player_financials.current_balance > 0) — except
// for admins (Paolo, 2026-10-19). A locked card still renders; the lock is stamped into it.
function shareCardsLocked(req) {
  if (req.session?.isAdmin) return false;
  const pid = req.session?.playerPlayerId;
  return !!pid && (getPlayerFinancials(pid)?.current_balance ?? 0) > 0;
}

// Everything the premium templates draw, from this game and this player's EARLIER games this
// season ("Vs your usual" compares to the average going in; "season high" means so far).
async function premiumShareData(game, stat, playerId, accentKey, key) {
  const isTeamA = stat.team_id === game.team_a_id;
  const myScore = Number(isTeamA ? game.team_a_score : game.team_b_score) || 0;
  const oppScore = Number(isTeamA ? game.team_b_score : game.team_a_score) || 0;
  const oppName = String((isTeamA ? game.team_b_name : game.team_a_name) || '').toUpperCase();
  const date = String(game.date || '').slice(0, 10);
  const earlier = getPlayerGameLog(playerId).filter(g => String(g.season) === String(game.season) && g.status === 'played'
    && g.id !== game.id && (String(g.date).slice(0, 10) < date || (String(g.date).slice(0, 10) === date && String(g.id) < String(game.id))));
  const avg = earlier.length
    ? Object.fromEntries(['pts', 'reb', 'ast', 'stl', 'blk'].map(k => [k, earlier.reduce((a, g) => a + (Number(g[k]) || 0), 0) / earlier.length]))
    : null;
  const pts = Number(stat.pts) || 0;
  const [last = '', first = ''] = String(stat.name || '').split(',').map(x => x.trim());
  const surname = last ? last[0] + last.slice(1).toLowerCase() : '';
  const day = d => new Date(`${date}T00:00:00`).toLocaleDateString('en-US', d);
  return {
    gameId: game.id,
    displayName: formatName(stat.name || ''),
    cardName: [first.split(' ')[0], surname].filter(Boolean).join(' '),
    shortName: `${first ? first[0] + '. ' : ''}${last} #${stat.number ?? ''}`,
    initials: ((first[0] || '') + (last[0] || '')).toUpperCase(),
    number: stat.number ?? '',
    teamName: String(stat.team_name || '').toUpperCase(), teamColor: stat.team_color || '#8a93a4',
    oppName, myScore, oppScore, won: myScore > oppScore,
    mySideScore: myScore, otherSideScore: oppScore, otherTeamName: oppName,
    dateShort: day({ month: 'short', day: 'numeric' }), dateLong: day({ month: 'short', day: 'numeric', year: 'numeric' }),
    stat,
    season: { label: String(game.season ?? ''), games: earlier.length, avg, high: earlier.length > 0 && pts > 0 && pts >= Math.max(...earlier.map(g => Number(g.pts) || 0)) },
    accent: resolveAccent(accentKey),
    photo: key === 'bug' && stat.picture_url ? await fetchCoverImageBuffer(stat.picture_url) : null,
  };
}
// The same facts for the players app, which draws the premium cards on the phone
// (public/share-cards.js phoneDrawer): no accent (picked there), no photo (the phone loads the
// player's own, same origin), only the box-score fields the templates read.
const PHONE_CARD_STATS = ['pts', 'reb', 'ast', 'stl', 'blk', 'turnover', 'minutes', 'fg2m', 'fg3m', 'fg4m', 'fg2m_miss', 'fg3m_miss', 'fg4m_miss', 'ftm', 'ft_miss'];
async function phoneShareData(game, stat, playerId) {
  const { accent, photo, ...d } = await premiumShareData(game, stat, playerId, 'amber', null);
  return { ...d, hideZeros: true, hasPhoto: !!stat.picture_url, stat: Object.fromEntries(PHONE_CARD_STATS.map(k => [k, stat[k] ?? null])) };
}

// Rendered cards, kept 10 min (by bytes, oldest out first) so switching templates in the editor
// is a cache hit: the editor's thumbnails render the full card, which this keeps for the tap that
// follows, and the editors preload every template once the first card shows. The key carries the
// stat line and score, so an edited box score renders fresh. In-flight renders are shared.
const SHARE_CARD_CACHE = new Map();
const SHARE_CARD_CACHE_MAX = 64 * 1024 * 1024, SHARE_CARD_TTL = 10 * 60 * 1000;
let shareCardCacheBytes = 0;
function shareCardCached(key, make) {
  const hit = SHARE_CARD_CACHE.get(key);
  if (hit && Date.now() - hit.at < SHARE_CARD_TTL) return hit.p;
  if (hit) { SHARE_CARD_CACHE.delete(key); shareCardCacheBytes -= hit.bytes; }
  const entry = { at: Date.now(), bytes: 0, p: null };
  entry.p = make().then(png => {
    if (SHARE_CARD_CACHE.get(key) !== entry) return png;
    entry.bytes = png.length; shareCardCacheBytes += png.length;
    for (const [k, e] of SHARE_CARD_CACHE) {
      if (shareCardCacheBytes <= SHARE_CARD_CACHE_MAX) break;
      if (e.bytes) { SHARE_CARD_CACHE.delete(k); shareCardCacheBytes -= e.bytes; }
    }
    return png;
  }, err => { if (SHARE_CARD_CACHE.get(key) === entry) SHARE_CARD_CACHE.delete(key); throw err; });
  SHARE_CARD_CACHE.set(key, entry);
  return entry.p;
}

app.get('/api/games/:id/my-stat-card.png', async (req, res) => {
  const playerId = req.session?.playerPlayerId;
  if (!playerId) return res.status(401).end();
  const game = getGameById(req.params.id);
  if (!game || game.under_review) return res.status(404).end();
  const stat = getGameDetailStats(game.id).find(s => s.player_id === playerId);
  if (!stat) return res.status(404).end();
  try {
    const locked = shareCardsLocked(req);
    const q = ['layout', 'align', 'corner', 'stat', 'focus', 'gauges', 'hidezeros', 'badge', 'accent'].map(k => String(req.query[k] ?? '')).join('|');
    const facts = JSON.stringify([stat, game.date, game.team_a_name, game.team_b_name, game.team_a_score, game.team_b_score]);
    const full = `${playerId}|${game.id}|${q}|${locked ? 1 : 0}|${facts}`;
    // ?thumb=1: a small copy for the editor's template picker (9 of these per open), so it
    // doesn't pull nine full 1080×1920 PNGs. Made from the cached full card.
    const thumb = req.query.thumb === '1';
    const png = thumb
      ? await shareCardCached(`${full}|thumb`, async () => sharp(await shareCardCached(full, () => renderMyStatCard(req, game, stat, playerId, locked))).resize(216).png({ compressionLevel: 9 }).toBuffer())
      : await shareCardCached(full, () => renderMyStatCard(req, game, stat, playerId, locked));
    res.set('Content-Type', 'image/png');
    res.set('Cache-Control', `private, max-age=${thumb ? 600 : 60}`);
    res.end(png);
  } catch (err) {
    console.error('my-stat-card.png error', err);
    res.status(500).end();
  }
});

async function renderMyStatCard(req, game, stat, playerId, locked) {
  const layout  = ['default', 'grid', 'sticker', 'comparison', 'gauges'].includes(req.query.layout) ? req.query.layout : 'gauges';
  // Template dropdown values — left/center/right share generateGameStatGaugesPng
  // (its `align` param), while bottom/stacked are their own bespoke designs
  // (generateGameStatNewsPng/generateGameStatStackedPng) rather than variants
  // of the grid, so they're dispatched separately below despite living in the
  // same "Template" control.
  const align   = ['left', 'center', 'right', 'bottom', 'stacked'].includes(req.query.align) ? req.query.align : 'center';
  const corner  = ['tl', 'tr', 'bl', 'br'].includes(req.query.corner) ? req.query.corner : 'tl';
  const heroKey = SHARE_STAT_DEFS.some(d => d.key === req.query.stat) ? req.query.stat : 'pts';
  const focus   = ['all', 'offense', 'defense'].includes(req.query.focus) ? req.query.focus : 'all';
  const gauges  = req.query.gauges !== '0';
  // Only meaningful for Bottom/Stacked — the grid's dashed ring already
  // handles "no attempts" cleanly, so this isn't wired into
  // generateGameStatGaugesPng (see its own comment for why).
  const hideZeros = req.query.hidezeros === '1';
  const badge   = req.query.badge === '1';
  const accent  = Object.prototype.hasOwnProperty.call(SHARE_ACCENT_PRESETS, req.query.accent) ? req.query.accent : 'amber';
  let png;
  if (SHARE_PREMIUM_KEYS.includes(req.query.align)) {
    const data = { ...await premiumShareData(game, stat, playerId, accent, req.query.align), hideZeros };
    png = await renderPremiumShareCard(req.query.align, data, (text, o) => measureTextWidth(escXml(text), o));
    if (locked) png = await lockOverlay(png);
  } else if (req.query.align === 'premium') {
    // Own branch ahead of the `layout` dispatch below — Premium isn't part
    // of the "Default" family's layout/align matrix at all (it's never in
    // the `align` whitelist above), so it needs its own check rather than
    // falling out of that fallback logic.
    png = await generateGameStatPremiumPng(game, stat, focus, { accent, hideZeros });
  } else if (req.query.align === 'premium-r') {
    png = await generateGameStatPremiumPng(game, stat, focus, { accent, hideZeros, side: 'right' });
  } else if (req.query.align === 'hero') {
    // Same reasoning as Premium's own branch above — Hero isn't part of
    // the align whitelist (it has no left/center/right variants), so it
    // needs its own check ahead of that fallback logic too.
    png = await generateGameStatHeroPng(game, stat, { accent });
  } else if (req.query.align === 'card') {
    // hideRibbon: Badge's own medal (composited below, after this big
    // if/else) lands in the same corner as Card's built-in ribbon and
    // would otherwise bury it — see generateGameStatTradingCardPng's own
    // comment for why dropping the now-redundant one is correct, not a
    // collision hack.
    png = await generateGameStatTradingCardPng(game, stat, { accent, hideRibbon: badge });
  } else if (req.query.align === 'scoreboard') {
    png = await generateGameStatScoreboardPng(game, stat, { accent });
  } else if (layout === 'gauges' && align === 'bottom') {
    png = await generateGameStatNewsPng(game, stat, focus, { accent, gauges, hideZeros });
  } else if (layout === 'gauges' && align === 'stacked') {
    png = await generateGameStatStackedPng(game, stat, focus, { accent, gauges, hideZeros });
  } else if (layout === 'gauges') {
    png = await generateGameStatGaugesPng(game, stat, align, focus, { accent, gauges, hideZeros });
  } else if (layout === 'grid') {
    png = await generateGameStatGridPng(game, stat, align, { accent });
  } else if (layout === 'sticker') {
    png = await generateGameStatStickerPng(game, stat, corner, heroKey, { accent });
  } else {
    const opts = { badge, accent };
    if (layout === 'comparison') {
      // Season average (this season, including the game being shared) for
      // whichever stat is the hero — same field shape as getGameDetailStats
      // rows, so shareStatValue works unmodified against season-log rows too.
      const seasonGames = getPlayerGameLog(playerId).filter(g => g.season === game.season && g.status === 'played');
      const vals = seasonGames.map(g => shareStatValue(g, heroKey));
      opts.comparisonAvg = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
    }
    png = await generateGameStatCardPng(game, stat, align, heroKey, opts);
  }
  // Badge is an add-on toggle applied to whichever template was just
  // generated above, not a template of its own — composited as a
  // post-processing step so every branch above gets it for free instead of
  // each one needing its own copy of this logic. Skipped for the legacy
  // default/comparison layout, which already renders its OWN achievement
  // ribbon inline (via opts.badge, a few lines up) — running both here
  // would draw it twice.
  if (badge && layout !== 'default' && layout !== 'comparison') {
    png = await composeStravagantBadgeOverlay(png, stat, resolveAccent(accent));
  }
  return png;
}

// Save/Copy/Share on the "Stravagant" stat card all happen entirely
// client-side against an already-fetched PNG blob, so without this the
// server (and admin) would have no idea a player ever actually used the
// feature past opening the editor. Fire-and-forget from the client — logging
// failure shouldn't block or surface an error for the save/copy/share the
// player already completed. Same session-gated, no-spoofable-id pattern as
// the PNG route above. In-memory per-(player+game+action) cooldown, not a DB
// one — this is analytics, not something that needs race-proof correctness,
// so a plain Map is enough to stop a rapid double-click from double-logging.
const shareCardActionCooldowns = new Map(); // `${playerId}:${gameId}:${action}` -> ms timestamp
const SHARE_CARD_ACTION_COOLDOWN_MS = 3000;
app.post('/api/games/:id/stat-card-action', express.json(), (req, res) => {
  const playerId = req.session?.playerPlayerId;
  if (!playerId) return res.status(401).end();
  const game = getGameById(req.params.id);
  if (!game || game.under_review) return res.status(404).end();
  const stat = getGameDetailStats(game.id).find(s => s.player_id === playerId);
  if (!stat) return res.status(404).end();

  const action = ['save', 'copy', 'share'].includes(req.body?.action) ? req.body.action : null;
  if (!action) return res.status(400).json({ error: 'Invalid action.' });

  const cooldownKey = `${playerId}:${game.id}:${action}`;
  const lastLogged = shareCardActionCooldowns.get(cooldownKey) || 0;
  if (Date.now() - lastLogged < SHARE_CARD_ACTION_COOLDOWN_MS) return res.json({ ok: true });
  shareCardActionCooldowns.set(cooldownKey, Date.now());

  // Every template the editor offers (views/game.js SSC_TEMPLATES) — this list once held only
  // the five align values, so Premium/Hero/Card/Scoreboard all logged as ''. Logged even when
  // invalid/missing isn't worth failing the request over.
  const template = ['left', 'center', 'right', 'bottom', 'stacked', 'premium', 'premium-r', 'hero', 'card', 'scoreboard', ...SHARE_PREMIUM_KEYS].includes(req.body?.template) ? req.body.template : '';
  const focus    = ['all', 'offense', 'defense'].includes(req.body?.focus) ? req.body.focus : '';
  const accent   = Object.prototype.hasOwnProperty.call(SHARE_ACCENT_PRESETS, req.body?.accent) ? req.body.accent : '';

  logShareCardAction({
    gameId: game.id, playerId, playerName: formatName(stat.name || ''),
    action, template, focus, accent,
  });
  res.json({ ok: true });
});

// ── Game comments + reactions ───────────────────────────────────────────────────
// Mirrors linkifyMentions()'s matching logic in views/game.js, but returns matched player
// ids instead of HTML — used to decide who gets a "you were mentioned" notification.
// Kept in sync manually with the view-layer version, same as the client-side port.
function extractMentionedPlayerIds(body, players) {
  if (!players.length) return [];
  const sorted = [...players].sort((a, b) => b.name.length - a.name.length);
  const pattern = sorted.map(p => p.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  if (!pattern) return [];
  const byName = new Map(sorted.map(p => [p.name, p.id]));
  const re = new RegExp('@(' + pattern + ')(?![A-Za-z0-9])', 'g');
  const found = new Set();
  let m;
  while ((m = re.exec(body))) {
    const id = byName.get(m[1]);
    if (id) found.add(id);
  }
  return [...found];
}

// Posting a comment, shared by the site's game page and the app (games and app announcements).
// target: appThreadTarget() / { kind: 'game', key, game }. parentId: the comment being replied
// to; a reply to a reply goes under the same top-level comment (one level of replies).
// Returns { id } or { error, status }. Banned players can't comment.
const commentLinkOf = t => (t.kind === 'ann' ? `/app?thread=${encodeURIComponent(t.key)}` : `/games/${gameSlug(t.game)}#talk`);
const commentExcerpt = (body, n = 140) => (body.length > n ? body.slice(0, n) + '…' : body);
// One message every 1.5 s and 12 a minute per player (live chat makes fast posting easy).
const commentTimes = new Map();
function commentTooFast(playerId) {
  const now = Date.now(), t = (commentTimes.get(playerId) || []).filter(x => now - x < 60000);
  if (t.length && now - t[t.length - 1] < 1500) return 'Slow down a little.';
  if (t.length >= 12) return 'That’s a lot of messages. Give it a minute.';
  t.push(now); commentTimes.set(playerId, t);
  return '';
}
function postComment(target, playerId, rawBody, parentId) {
  if (getBannedPlayerIds().has(playerId)) return { status: 403, error: 'Commenting is off while your account is banned. Settle your balance and message us.' };
  const body = String(rawBody || '').trim().slice(0, 500);
  if (!body) return { status: 400, error: 'Comment can\'t be empty.' };
  const fast = commentTooFast(playerId);
  if (fast) return { status: 429, error: fast };
  let parent = null;
  if (parentId) {
    parent = getCommentById(String(parentId));
    if (!parent || parent.game_id !== target.key) return { status: 404, error: 'That comment was deleted.' };
    if (parent.parent_id) parent = getCommentById(parent.parent_id) || parent;
  }
  const id = addGameComment({ gameId: target.key, playerId, body, parentId: parent?.id || null });
  const saved = getCommentWithMeta(id);
  if (target.kind === 'game') {
    broadcastToGame(target.game.id, {
      type: 'comment:new',
      comment: {
        id: saved.id,
        parent_id: saved.parent_id || null,
        replyTo: parent ? displayPlayerName(parent.player_name || getPlayerById(parent.player_id)?.name || '') : '',
        player_id: saved.player_id,
        body: saved.body,
        created_at: saved.created_at,
        displayName: displayPlayerName(saved.player_name),
        initials: initials(saved.player_name),
        photoUrl: `/api/player/${encodeURIComponent(saved.player_id)}/photo?w=96`,
        color: teamColor(saved.team_name || ''),
      },
    });
  }
  notifyComment(target, saved, parent);
  return { id };
}

// Who hears about a comment, each person once, never the commenter: an @mentioned player
// ("X mentioned you"); on a reply, the comment's author and everyone else in that reply
// thread ("X replied to your comment" / "X replied in a thread"); then everyone involved
// ("New comment on …"): for a game, its players (after the final) or both teams and its
// pickers (before), plus anyone already in the thread; for an announcement, its commenters.
// A thread you haven't read yet updates one notification instead of stacking more.
function notifyComment(target, saved, parent) {
  const playerId = saved.player_id, body = saved.body;
  const link = commentLinkOf(target);
  const name = displayPlayerName(saved.player_name);
  const told = new Set([playerId]);
  const accounted = getPlayersWithAccounts().map(p => ({ id: p.id, name: displayPlayerName(p.name) }));
  for (const pid of extractMentionedPlayerIds(body, accounted)) {
    if (told.has(pid)) continue;
    told.add(pid);
    createNotification({ playerId: pid, type: 'comment_mention', title: `${name} mentioned you`, body: commentExcerpt(body), link, actorId: playerId });
  }
  if (parent) {
    const author = parent.player_id;
    for (const pid of [author, ...getThreadPlayerIds(parent.id)]) {
      if (told.has(pid)) continue;
      told.add(pid);
      const title = pid === author ? `${name} replied to your comment` : `${name} replied in a thread you're in`;
      const unread = findUnreadNotification(pid, 'comment_reply', link);
      if (unread) refreshNotification(unread.id, { title: pid === author ? `New replies to your comment` : 'New replies in a thread you\'re in', body: `${name}: ${commentExcerpt(body, 100)}`, actorId: playerId });
      else createNotification({ playerId: pid, type: 'comment_reply', title, body: commentExcerpt(body), link, actorId: playerId });
    }
  }
  let involved, about, first;
  if (target.kind === 'game') {
    const game = target.game;
    const isFinal = (game.status === 'final' || game.status === 'complete') && Number(game.team_a_score) + Number(game.team_b_score) > 0;
    involved = [
      ...(isFinal
        ? getGameDetailStats(game.id).map(s => s.player_id)
        : [...getTeamPlayerIdsWithAccounts(game.team_a_id, game.team_b_id), ...getGamePicksWithPlayers(game.id).map(p => p.player_id)]),
      ...getGameCommenterIds(game.id),
    ];
    about = `${titleCase(game.team_a_name)} vs ${titleCase(game.team_b_name)}`;
    first = `${isFinal ? 'New comment' : 'Pre-game chatter'} on ${about}`;
  } else {
    involved = getGameCommenterIds(target.key);
    about = target.ann.title ? `“${commentExcerpt(target.ann.title, 40)}”` : 'an announcement';
    first = `New comment on ${about}`;
  }
  const preview = `${name}: ${commentExcerpt(body, 100)}`;
  for (const pid of new Set(involved)) {
    if (told.has(pid)) continue;
    told.add(pid);
    const unread = findUnreadNotification(pid, 'comment_new', link);
    if (unread) {
      const n = (Number(String(unread.title).match(/^(\d+) new comments/)?.[1]) || 1) + 1;
      refreshNotification(unread.id, { title: `${n} new comments on ${about}`, body: preview, actorId: playerId });
      continue;
    }
    createNotification({ playerId: pid, type: 'comment_new', title: first, body: preview, link, actorId: playerId });
  }
}

// A 🔥 on someone's comment tells its author (one notification per thread until they read it).
function notifyCommentReaction(target, comment, playerId) {
  if (comment.player_id === playerId) return;
  const link = commentLinkOf(target);
  const name = displayPlayerName(getPlayerById(playerId)?.name || '');
  const unread = findUnreadNotification(comment.player_id, 'comment_reaction', link);
  if (unread) {
    if (!unread.title.startsWith(name)) refreshNotification(unread.id, { title: `${name} and others 🔥 your comment`, body: commentExcerpt(comment.body), actorId: playerId });
    return;
  }
  createNotification({ playerId: comment.player_id, type: 'comment_reaction', title: `${name} 🔥 your comment`, body: commentExcerpt(comment.body), link, actorId: playerId });
}

app.post('/games/:id/comments', express.json(), (req, res) => {
  if (getSetting('comments_enabled', '0') !== '1') return res.status(404).json({ error: 'Not found.' });
  const playerId = req.session?.playerPlayerId;
  if (!req.session?.playerRegId || !playerId) return res.status(401).json({ error: 'Log in to comment.' });
  const game = getGameById(req.params.id);
  if (!game) return res.status(404).json({ error: 'Not found.' });
  const r = postComment({ kind: 'game', key: game.id, game }, playerId, req.body?.body, req.body?.parent_id);
  if (r.error) return res.status(r.status).json({ error: r.error });
  res.json({ ok: true, id: r.id });
});

app.post('/games/:id/comments/:commentId/react', express.json(), (req, res) => {
  if (getSetting('comments_enabled', '0') !== '1') return res.status(404).json({ error: 'Not found.' });
  const playerId = req.session?.playerPlayerId;
  if (!req.session?.playerRegId || !playerId) return res.status(401).json({ error: 'Log in to react.' });
  const comment = getCommentById(req.params.commentId);
  if (!comment || comment.game_id !== req.params.id) return res.status(404).json({ error: 'Not found.' });
  const result = toggleCommentReaction(comment.id, playerId);
  broadcastToGame(comment.game_id, { type: 'comment:react', id: comment.id, count: result.count });
  if (result.reacted) { const game = getGameById(comment.game_id); if (game) notifyCommentReaction({ kind: 'game', key: game.id, game }, comment, playerId); }
  res.json({ ok: true, ...result });
});

// Page-level reaction — "liked the game itself," gated behind the same comments_enabled
// flag since it shipped as part of the same social-engagement launch, not a separate toggle.
app.post('/games/:id/react', express.json(), (req, res) => {
  if (getSetting('comments_enabled', '0') !== '1') return res.status(404).json({ error: 'Not found.' });
  const playerId = req.session?.playerPlayerId;
  if (!req.session?.playerRegId || !playerId) return res.status(401).json({ error: 'Log in to react.' });
  const game = getGameById(req.params.id);
  if (!game) return res.status(404).json({ error: 'Not found.' });
  const result = toggleGameReaction(game.id, playerId);
  // The faces + names beside React, rendered once here so every open page swaps in the same HTML.
  const who = reactorsWho(getGameReactors(game.id));
  broadcastToGame(game.id, { type: 'game:react', count: result.count, who });
  res.json({ ok: true, ...result, who });
});

app.delete('/games/:id/comments/:commentId', (req, res) => {
  if (!isAdminWithSection(req, 'games-stats')) return res.status(403).json({ error: 'Admins only.' });
  const comment = getCommentById(req.params.commentId);
  if (!comment || comment.game_id !== req.params.id) return res.status(404).json({ error: 'Not found.' });
  for (const id of deleteGameComment(comment.id)) broadcastToGame(comment.game_id, { type: 'comment:delete', id });
  res.json({ ok: true });
});

