// ── /admin/picks: the whole "Who wins?" picture (views/admin/picks.js) ──────────────────
// Players who could pick (an account they can log in with) but haven't picked every open
// game on the next game day. Shared by the page and the reminder.
function picksMissing(upNext, pctx) {
  const openIds = upNext.filter(u => !u.closed).map(u => u.id);
  if (!openIds.length) return null;
  const accounts = getPlayersWithAccounts();
  const pickedBy = new Map();
  for (const p of pctx.picks) if (openIds.includes(p.game_id)) pickedBy.set(p.player_id, (pickedBy.get(p.player_id) || 0) + 1);
  const list = accounts
    .filter(p => (pickedBy.get(p.id) || 0) < openIds.length)
    .map(p => ({ id: p.id, name: displayPlayerName(p.name) }))
    .sort((x, y) => x.name.localeCompare(y.name));
  return { list, accounts: accounts.length, games: openIds.length };
}

function adminUpNext(games, pctx) {
  return getUpcomingGames(games).map(g => {
    const pg = pctx.byId[g.id] || toPickGame(g, gameYmd);
    const setting = pctx.settings[g.id] || {};
    const teamOf = name => String(name || '').toUpperCase();
    const picks = getGamePicksWithPlayers(g.id).map(p => ({
      id: p.player_id, name: displayPlayerName(p.player_name || ''), team: p.team_name || '', side: p.side, at: p.created_at,
      ownTeamAgainst: !!p.team_name && teamOf(p.team_name) === teamOf(p.side === 'a' ? g.team_b_name : g.team_a_name),
    })).reverse();
    return {
      id: g.id, a: g.team_a_name, b: g.team_b_name, ymd: pg.ymd,
      closed: upcomingPickState(g, pctx).closed,
      odds: pickOddsEnabled() ? computeOdds(pg, pctx.played) : null,
      hideOdds: !!setting.hide_odds,
      override: setting.closed == null ? 'auto' : (setting.closed ? 'closed' : 'open'),
      counts: { a: picks.filter(p => p.side === 'a').length, b: picks.filter(p => p.side === 'b').length },
      picks, closeTime: picksCloseTime(),
    };
  });
}

app.get('/admin/picks', requireAuth, (req, res) => {
  const games = byDate(getAllGames());
  const pctx = buildPicksContext(games);
  const seasons = picksSeasons(pctx);
  const current = String(getPortalCurrentSeason());
  const season = seasons.includes(String(req.query.season)) ? String(req.query.season) : current;
  const isCurrent = season === current;
  const sp = seasonPicks(pctx, season);
  const playerMap = Object.fromEntries(getAllPlayers().map(p => [p.id, p]));
  const teamNames = Object.fromEntries(getAllTeams().map(t => [t.id, t.name]));
  const person = id => ({ id, name: displayPlayerName(playerMap[id]?.name || ''), team: teamNames[playerMap[id]?.team_id] || '' });

  const upNext = isCurrent ? adminUpNext(games, pctx) : [];
  const upDay = upNext[0]?.ymd || null;
  const missing = isCurrent ? picksMissing(upNext, pctx) : null;
  if (missing && upDay) {
    const sent = JSON.parse(getSetting(`picks_reminded_${upDay}`, 'null') || 'null');
    if (sent) { missing.remindedAt = sent.at; missing.remindedCount = sent.count; }
    // Already emailed for this game day: left off the checklist and the counts entirely (no
    // repeat bell either).
    const emailedIds = picksEmailedIds(upDay);
    const remindable = missing.list.filter(p => !emailedIds.has(p.id));
    missing.alreadyEmailed = missing.list.length - remindable.length;
    // Reminder email: who'd get one, and the last send's tally for this game day.
    const reach = picksReminderRecipients(remindable, upDay);
    missing.reachable = reach.recipients.length;
    missing.emailable = reach.emailable.length;
    missing.noValidEmail = reach.skipped.noValidEmail;
    missing.dormant = reach.skipped.dormant + reach.skipped.linkExpired;
    // Per-player status for the pick-who-to-remind checklist: email, bell only (and why),
    // or unreachable (failed the broadcast gates).
    const byId = new Map(reach.recipients.map(r => [r.player.id, r]));
    missing.people = remindable.map(p => {
      const r = byId.get(p.id);
      return { ...p, reach: !r ? 'skip' : r.emailable ? 'email' : 'bell', note: r?.bellOnly || (r ? '' : 'inactive or no valid email') };
    });
    try { missing.emailed = JSON.parse(getSetting(`picks_emailed_${upDay}`, 'null') || 'null'); } catch {}
  }

  const seasonGameIds = new Set(pctx.all.filter(g => g.season === season).map(g => g.id));
  const seasonPickRows = pctx.picks.filter(p => seasonGameIds.has(p.game_id));
  const results = [...sp.settled].reverse().map(g => {
    const gp = getGamePicksWithPlayers(g.id);
    const s = calledItSummary(g, gp);
    return {
      id: g.id, ymd: g.ymd, a: g.a, b: g.b, sa: g.sa, sb: g.sb, winner: g.winner, odds: g.odds,
      total: s.total, pctWinner: s.pctWinner, fansCalled: s.fansCalled, upset: s.upset,
      called: gp.filter(p => p.side === g.winner).map(p => person(p.player_id)),
      missed: gp.filter(p => p.side !== g.winner).map(p => person(p.player_id)),
      settledAt: pctx.settings[g.id]?.settled_at || null,
    };
  });

  const missingIds = new Set((missing?.list || []).map(p => p.id));
  const byPlayer = new Map();
  for (const p of seasonPickRows) {
    const e = byPlayer.get(p.player_id) || { made: 0, last: null };
    e.made++;
    if (!e.last || p.created_at > e.last.at) {
      const g = pctx.byId[p.game_id];
      e.last = { at: p.created_at, ymd: g?.ymd || '', team: g ? (p.side === 'a' ? g.a : g.b) : '' };
    }
    byPlayer.set(p.player_id, e);
  }
  const rankOf = new Map(sp.board.rows.map(r => [r.playerId, r.rank]));
  const pickers = [...byPlayer.entries()].map(([id, e]) => {
    const r = sp.records[id];
    return {
      ...person(id), picks: e.made, settled: r?.picks || 0, correct: r?.correct || 0, net: r?.net || 0, oddsPts: r?.oddsPts || 0,
      streak: r?.streak || 0, upsets: r?.upsets || 0, rank: rankOf.get(id) || null, last: e.last,
      marginGuess: sp.finalsG1 ? (pctx.picks.find(p => p.game_id === sp.finalsG1 && p.player_id === id)?.margin_guess ?? null) : undefined,
      missingNext: missingIds.has(id),
    };
  }).sort((x, y) => (x.rank || 1e9) - (y.rank || 1e9) || y.correct - x.correct || y.picks - x.picks || x.name.localeCompare(y.name));

  const leaderRow = pickmasterLeader(sp.board);
  res.send(renderAdminPage(req, {
    title: 'Who wins? picks',
    currentPath: '/admin/picks',
    body: adminPicksBody({
      season, seasons, isCurrent, upNext, upDay, missing, results, pickers, hasFinalsG1: !!sp.finalsG1,
      query: req.query, teams: getAllTeams(), colorById: adminTeamColorByPlayer(),
      settings: { homeWidget: on('home_picks_widget_enabled'), autoRemind: on('picks_auto_remind'), closeTime: picksCloseTime() },
      minPicks: sp.board.minPicks, oddsOn: pickOddsEnabled(), picksOn: picksEnabled(),
      msg: req.query.reminded
        ? `Reminder sent to ${req.query.reminded} player${req.query.reminded === '1' ? '' : 's'}.${req.query.emailing ? ` Emailing ${req.query.emailing} of them now; refresh in a minute for the tally.` : ''}`
        : req.query.tested ? `Test email sent to ${ADMIN_TEST_EMAIL}.`
        : req.query.test_error ? `Test email failed: ${req.query.test_error}`
        : '',
      kpi: {
        picks: seasonPickRows.length, pickers: byPlayer.size, accounts: getPlayersWithAccounts().length,
        callers: sp.callers, oddsOn: pickOddsEnabled(), minPicks: sp.board.minPicks,
        upsets: results.filter(r => r.odds?.fav && r.odds.fav !== r.winner).length,
        // Odds are judged on every finished game with odds, picked or not.
        oddsRecord: { called: results.filter(r => r.odds?.fav && r.odds.fav === r.winner).length, of: results.filter(r => r.odds?.fav).length },
        leader: leaderRow ? { ...person(leaderRow.playerId), net: leaderRow.net, correct: leaderRow.correct, wrong: leaderRow.wrong, level: leaderRow.level, decidedBy: leaderRow.decidedBy } : null,
      },
    }),
  }));
});

// In-app nudge (bell notification, no email) to everyone who hasn't picked every open game
// on the next game day. Remembers when it went out so the page can say so.
app.post('/admin/picks/remind', requireAuth, express.urlencoded({ extended: false }), (req, res) => {
  // back=home: sent from the Engagement Home, so go back there with a toast.
  const home = req.body?.back === 'home';
  const nothing = () => res.redirect(home ? `/admin?toast=${encodeURIComponent('Nobody left to remind.')}` : '/admin/picks');
  if (!picksEnabled()) return nothing();
  const games = byDate(getAllGames());
  const pctx = buildPicksContext(games);
  const upNext = adminUpNext(games, pctx);
  const missing = picksMissing(upNext, pctx);
  if (!missing?.list.length) return nothing();
  // The page's checklist posts the chosen players as `ids`; only those get reminded.
  const chosen = new Set([].concat(req.body?.ids || []).map(String));
  const emailedIds = picksEmailedIds(upNext.find(u => !u.closed)?.ymd);
  const targets = missing.list.filter(p => chosen.has(p.id) && !emailedIds.has(p.id));
  if (!targets.length) return nothing();
  const open = upNext.filter(u => !u.closed);
  const matchups = open.map(u => `${titleCase(u.a)} vs ${titleCase(u.b)}`).join(' and ');
  const dayStr = new Date(`${open[0].ymd}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const reach = picksReminderRecipients(targets, open[0].ymd);
  if (!reach.recipients.length) return nothing();
  const recipients = req.body?.email === '1' ? reach.emailable : [];
  const bellTitle = `Who wins? ${matchups}`;
  const bellBody = `Make your pick${open.length === 1 ? '' : 's'} before ${fmtCloseTime(picksCloseTime())} on ${dayStr}.`;
  const campaignId = startCampaign({
    kind: 'pick_reminder', title: bellTitle, body: bellBody, link: '/picks', segment: `not_picked:${open[0].ymd}`,
    channels: recipients.length ? 'bell+email' : 'bell', createdBy: req.session?.playerName || 'admin',
  });
  for (const { player: p } of reach.recipients) {
    createNotification({ playerId: p.id, type: 'pick_reminder', title: bellTitle, body: bellBody, link: '/picks', broadcastId: campaignId });
  }
  finishCampaign(campaignId, { bells: reach.recipients.length });
  setSetting(`picks_reminded_${open[0].ymd}`, JSON.stringify({ at: Date.now(), count: reach.recipients.length }));
  // "Also email them": the emailable ones (the rest still got the bell above). Sent in the
  // background — the page shows the tally from picks_emailed_<day> once it's done.
  if (recipients.length) setImmediate(() => sendPicksEmails(recipients, { campaignId, bells: reach.recipients.length }).catch(e => console.error('[picks email] send failed:', e.message)));
  if (home) return res.redirect(`/admin?toast=${encodeURIComponent(`Pick reminder sent: ${reach.recipients.length} bell${reach.recipients.length === 1 ? '' : 's'}${recipients.length ? `, ${IS_DEV ? 1 : recipients.length} email${(IS_DEV ? 1 : recipients.length) === 1 ? '' : 's'} going out now` : ''}`)}`);
  const nEmail = recipients.length ? (IS_DEV ? 1 : recipients.length) : 0;
  res.redirect(`/admin/picks?toast=${encodeURIComponent(`Reminder sent to ${reach.recipients.length} player${reach.recipients.length === 1 ? '' : 's'}.${nEmail ? ` Emailing ${nEmail} now.` : ''}`)}`);
});

// ── "Who wins?" reminder email (copy: lib/picks-email.js, template: lib/mailer.js) ──────
// Everything the email needs for the next game day's open games, or null when none are open.
function picksEmailContext() {
  const games = byDate(getAllGames());
  const pctx = buildPicksContext(games);
  const open = adminUpNext(games, pctx).filter(u => !u.closed);
  if (!open.length) return null;
  const playerMap = Object.fromEntries(getAllPlayers().map(p => [p.id, p]));
  const emailGames = open.map(u => ({
    id: u.id, a: u.a, b: u.b, odds: u.hideOdds ? null : u.odds,
    story: matchupStoryFacts(matchupAsOf(games.find(g => g.id === u.id), games, playerMap)),
  }));
  return {
    pctx, open, emailGames, playerMap, ymd: open[0].ymd,
    dayLabel: new Date(`${open[0].ymd}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }),
    closeLabel: fmtCloseTime(picksCloseTime()),
    sp: seasonPicks(pctx, getPortalCurrentSeason()),
  };
}

// One AI draft per game day, reused for every recipient (and for the preview, so what the
// admin reads is what goes out). Rewritten when the facts behind it change, or on request.
async function ensurePicksDraft(c, { rewrite = false } = {}) {
  const input = { games: c.emailGames, dayLabel: c.dayLabel, closeLabel: c.closeLabel };
  const { key } = picksEmailFacts(input);
  if (!rewrite) {
    try {
      const stored = JSON.parse(getSetting(`picks_email_draft_${c.ymd}`, '') || 'null');
      if (stored && stored.key === key) return stored;
    } catch {}
  }
  const draft = { ...(await writePicksEmail(input, factCheckHomeSummary)), key, at: Date.now() };
  setSetting(`picks_email_draft_${c.ymd}`, JSON.stringify(draft));
  return draft;
}

// The email for one player: their own pick status per game, their record, the race.
function picksEmailFor(c, draft, playerId, regId = '') {
  const mine = new Map(c.pctx.picks.filter(p => p.player_id === playerId).map(p => [p.game_id, p.side]));
  const games = c.open.map(u => ({
    id: u.id, a: titleCase(u.a), b: titleCase(u.b), colA: teamColor(u.a), colB: teamColor(u.b),
    odds: !u.hideOdds && u.odds?.fav ? { fav: u.odds.fav, pctA: u.odds.pctA, pctB: u.odds.pctB } : null,
    myPick: mine.has(u.id) ? titleCase(mine.get(u.id) === 'a' ? u.a : u.b) : null,
  }));
  const { board: { rows }, records } = c.sp;
  const r = records[playerId];
  const rank = rows.find(x => x.playerId === playerId)?.rank;
  const me = !r ? "You haven't had a pick settled yet. Your first final puts you on the board."
    : `You're #${rank} of ${rows.length} on ${fmtPts(r.net)} (${r.correct}–${r.wrong})${r.streak >= 2 ? `, ${r.streak} in a row` : ''}.`;
  return picksReminderEmail({
    name: c.playerMap[playerId]?.name || '', copy: draft, games, dayLabel: c.dayLabel, closeLabel: c.closeLabel,
    board: rows.slice(0, 5).map(x => ({ rank: x.rank, name: displayPlayerName(c.playerMap[x.playerId]?.name || ''), record: `${fmtPts(x.net)} (${x.correct}–${x.wrong})` })),
    me, prizeLine: PICKS_PRIZE_LINE,
    url: `${(process.env.LIVE_URL || 'https://wkndbasketball.com').replace(/\/$/, '')}/picks`,
    unsubscribeUrl: regId ? picksUnsubscribeUrl(regId) : '',
  });
}

// Who the reminder reaches out of a list of players: the shared broadcast gates
// (lib/broadcast-recipients.js — valid email first, active, approved). Everyone in
// `recipients` gets the bell; `emailable` drops anyone unsubscribed from pick emails, who
// once marked our email as spam, or whose inbox is already on the list — and anyone already
// emailed for this game day (`ymd`), so "Remind again" only emails the new names. The list is
// keyed by game day, so it starts fresh once the next game day's picks open.
function picksReminderRecipients(players, ymd) {
  const { recipients, skipped } = selectBroadcastRecipients(players.map(p => p.id), { optOutColumn: 'picks_email_optout' });
  const already = picksEmailedIds(ymd);
  for (const r of recipients) {
    if (r.emailable && already.has(r.player.id)) { r.emailable = false; r.bellOnly = 'already emailed for this game day'; }
  }
  return { recipients, emailable: recipients.filter(r => r.emailable), skipped };
}

function picksEmailedIds(ymd) {
  try { return new Set(ymd ? JSON.parse(getSetting(`picks_emailed_ids_${ymd}`, '[]') || '[]') : []); } catch { return new Set(); }
}

// campaign: { campaignId, bells } from startCampaign(), so each email carries the campaign
// id and the campaign row gets the final email count.
async function sendPicksEmails(recipients, { campaignId = '', bells = 0 } = {}) {
  const c = picksEmailContext();
  if (!c) return;
  const draft = await ensurePicksDraft(c);
  // Outside production every email is redirected to the admin inbox (lib/mailer.js), so a
  // full send would land dozens of copies there — one is enough to see it.
  // Drop anyone emailed since the page was loaded (a double submit, two admins at once).
  const emailedIds = picksEmailedIds(c.ymd);
  const fresh = recipients.filter(r => !emailedIds.has(r.player.id));
  const list = IS_DEV ? fresh.slice(0, 1) : fresh;
  if (!list.length) return;
  let sent = 0, failed = 0, first = true;
  for (const { player, reg, email } of list) {
    // Stay under Resend's rate limit (about 2 requests a second).
    if (!first) await new Promise(r => setTimeout(r, 600));
    first = false;
    const unsub = picksUnsubscribeUrl(reg.id);
    try {
      const ok = await sendMail({
        to: email, ...picksEmailFor(c, draft, player.id, reg.id), ref: reg.id, broadcastId: campaignId,
        headers: { 'List-Unsubscribe': `<${unsub}>`, 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' },
      });
      if (ok) { sent++; emailedIds.add(player.id); }
    } catch (e) {
      failed++;
      console.error(`[picks email] ${email}: ${e.message}`);
    }
  }
  setSetting(`picks_emailed_ids_${c.ymd}`, JSON.stringify([...emailedIds]));
  setSetting(`picks_emailed_${c.ymd}`, JSON.stringify({ at: Date.now(), sent, failed, of: list.length, source: draft.source }));
  finishCampaign(campaignId, { bells, emails: sent });
}

// Preview exactly what a player would get (the first player still missing picks, else any
// account), with the draft's source on top. Writes the draft on first view.
app.get('/admin/picks/email/preview', requireAuth, async (req, res) => {
  const c = picksEmailContext();
  if (!c) return res.send(renderAdminPage(req, { title: 'Pick email', currentPath: '/admin/picks', body: '<p class="text-sm text-slate-400 p-6">No open games on the next game day, so there\'s no reminder to preview.</p>' }));
  const draft = await ensurePicksDraft(c);
  const sample = picksMissing(c.open, c.pctx)?.list[0] || getPlayersWithAccounts()[0];
  const email = picksEmailFor(c, draft, sample?.id || '', '');
  res.send(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pick email preview</title></head>
<body style="margin:0;background:#0b0f17;font-family:Arial,sans-serif">
  <div style="max-width:520px;margin:0 auto;padding:16px 0 12px;color:#94a3b8;font-size:13px;line-height:1.5">
    <a href="/admin/picks" style="color:#94a3b8">← Back to picks</a>
    <div style="margin-top:8px"><b style="color:#e2e8f0">Subject:</b> ${escHtml(email.subject)}</div>
    <div>Preview for <b style="color:#e2e8f0">${escHtml(displayPlayerName(c.playerMap[sample?.id]?.name || ''))}</b> · copy: <b style="color:${draft.source === 'ai' ? '#22c55e' : '#f59332'}">${draft.source === 'ai' ? 'AI, passed all checks' : 'template (AI not used)'}</b>${draft.note ? ` · ${escHtml(draft.note)}` : ''}</div>
    <form method="post" action="/admin/picks/email/rewrite" style="display:inline-block;margin-top:8px"><button style="padding:6px 12px;border-radius:6px;border:1px solid #334155;background:#0d1424;color:#e2e8f0;cursor:pointer">↺ Rewrite with AI</button></form>
    <form method="post" action="/admin/picks/email/test" style="display:inline-block;margin:8px 0 0 6px"><button style="padding:6px 12px;border-radius:6px;border:1px solid #334155;background:#0d1424;color:#e2e8f0;cursor:pointer">Send a test to ${escHtml(ADMIN_TEST_EMAIL)}</button></form>
  </div>
  ${email.html}
  <div style="height:40px"></div>
</body></html>`);
});

