app.post('/admin/games/:id/save', requireAuth, jsonSmall, (req, res) => {
  const game = getGameById(req.params.id);
  if (!game) return res.status(404).json({ error: 'Not found' });
  const b = req.body;
  const potgPick = b.potg_player_id !== undefined ? String(b.potg_player_id) : game.manual_potg_player_id;
  // Co-POTG: winning team only, never the POTG themself. 'None' clears it and its writeup.
  const coPick = b.co_potg_player_id !== undefined ? String(b.co_potg_player_id || '') : game.co_potg_player_id;
  if (coPick) {
    const stats = getGameStats(game.id);
    const win = winnerTeamIdOf(game);
    const line = stats.find(s => s.player_id === coPick);
    const main = potgPick || derivePotgPlayerId(game, stats);
    if (!line || (win && line.team_id !== win)) return res.status(400).json({ error: 'The co-player of the game must be on the winning team.' });
    if (coPick === main) return res.status(400).json({ error: 'Pick a different player for co-player of the game.' });
  }
  updateGameAll(game.id, {
    game_writeup:         b.game_writeup     !== undefined ? String(b.game_writeup)     : game.game_writeup,
    potg_writeup:         b.potg_writeup     !== undefined ? String(b.potg_writeup)     : game.potg_writeup,
    manual_potg_player_id: potgPick,
    co_potg_player_id:    coPick,
    co_potg_writeup:      !coPick ? '' : b.co_potg_writeup !== undefined ? String(b.co_potg_writeup) : game.co_potg_writeup,
    youtube_url:          b.youtube_url      !== undefined ? String(b.youtube_url)       : game.youtube_url,
    under_review:         b.status           !== undefined ? (b.status === 'draft' ? 1 : 0) : game.under_review,
    date:                 b.date             !== undefined ? String(b.date)              : game.date,
  });
  if (b.game_type !== undefined) setGameType(game.id, String(b.game_type));
  if (b.overtime !== undefined) setGameOvertime(game.id, Number(b.overtime) || 0);
  if (b.court_id !== undefined) {
    const courtId = String(b.court_id || '');
    if (courtId && !getPapawisCourtById(courtId)) return res.status(400).json({ error: 'Unknown court' });
    // "Every game on this day": same game day as this game's (possibly just-changed) date.
    const ymd = gameYmd(b.date !== undefined ? String(b.date) : game.date);
    const ids = b.court_whole_day && ymd ? getAllGames().filter(g => gameYmd(g.date) === ymd).map(g => g.id) : [game.id];
    setGamesCourt(ids, courtId);
  }
  if (b.tip_time !== undefined) setGamesTipTime([game.id], String(b.tip_time || ''));
  settleGamePicks(game.id);
  res.json({ ok: true });
});

// One-field correction to an already-imported box score line (e.g. fixing a mistyped rebound
// count) without re-importing the whole game. old_value is read server-side, not trusted from
// the client, and stamped onto req.body before responding so the generic admin-action logger
// at the top of this file (which reads req.body on res 'finish') records a self-describing
// "field: old -> new" entry instead of just the new value.
app.post('/admin/games/:id/stats/:playerId', requireAuth, jsonSmall, (req, res) => {
  const game = getGameById(req.params.id);
  if (!game) return res.status(404).json({ error: 'Not found' });
  const { field, value } = req.body || {};
  if (!EDITABLE_STAT_FIELDS.has(field)) return res.status(400).json({ error: 'Invalid stat field' });
  const existing = getGamePlayerStat(game.id, req.params.playerId);
  if (!existing) return res.status(404).json({ error: 'No stat line for this player in this game' });
  req.body.old_value = existing[field];
  const updated = updateGamePlayerStat(game.id, req.params.playerId, field, value);
  res.json({ ok: true, pts: updated.pts });
});

