// Mirrors a wknd-stats export's Team A/B sides: teamA*/teamB* keys trade places at every depth
// (scores, team turnovers, quarterStats, period + checkpoint snapshots) and each play's isTeamA
// flips. Player stats are keyed by player id, so they need nothing. Play text like
// "[WHI 99 - BLU 90]" is left as recorded; lib/game-detail.js reads those scores by team tag,
// not position, so a reversed file's text still lands on the right side.
function swapExportSides(v) {
  if (Array.isArray(v)) return v.map(swapExportSides);
  if (!v || typeof v !== 'object') return v;
  const out = {};
  for (const [k, val] of Object.entries(v)) {
    const key = k.startsWith('teamA') ? 'teamB' + k.slice(5) : k.startsWith('teamB') ? 'teamA' + k.slice(5) : k;
    out[key] = k === 'isTeamA' && typeof val === 'boolean' ? !val : swapExportSides(val);
  }
  return out;
}

app.post('/admin/games/:id/import', requireAuth, jsonLarge, (req, res) => {
  const game = getGameById(req.params.id);
  if (!game) return res.status(404).json({ error: 'Not found' });

  let payload = req.body;
  if (payload?.type !== 'wknd-game-log') {
    return res.status(400).json({ error: 'Invalid file. Export the game from the wknd-stats admin app.' });
  }

  if (!payload.game) return res.status(400).json({ error: 'Missing game data in export file.' });

  const upper = s => String(s || '').trim().toUpperCase();
  const gameA = upper(game.team_a_name), gameB = upper(game.team_b_name);
  // A file exported with the teams the other way round is flipped to match this game.
  const swapped = upper(payload.game.teamAName) === gameB && upper(payload.game.teamBName) === gameA && gameA !== gameB;
  if (swapped) {
    payload = swapExportSides(payload);
    console.log(`[import] game=${game.id} export had teams reversed, swapped sides`);
  }
  const g = payload.game;

  const nameA = upper(g.teamAName);
  const nameB = upper(g.teamBName);
  if (nameA !== gameA || nameB !== gameB) {
    return res.status(400).json({
      error: `Team mismatch: export is ${g.teamAName} vs ${g.teamBName}, this game is ${game.team_a_name} vs ${game.team_b_name}.`
    });
  }

  const rawDnp = Array.isArray(payload.dnpPlayers) ? payload.dnpPlayers : [];
  const dnpPlayerIds = rawDnp.map(p => (typeof p === 'string' ? p : String(p?.id || p?.player_id || ''))).filter(Boolean);

  const logJson   = Array.isArray(payload.gameLog) ? payload.gameLog : [];
  const snapshots = Array.isArray(payload.periodSnapshots) ? payload.periodSnapshots : [];
  console.log(`[import] game=${game.id} log_events=${logJson.length} snapshots=${snapshots.length} log_json_kb=${Math.round(JSON.stringify(logJson).length/1024)}`);
  const t0 = Date.now();
  try {
    importGameResults(game.id, {
      teamAScore:      Number(g.teamAScore || 0),
      teamBScore:      Number(g.teamBScore || 0),
      periodSnapshots: snapshots,
      gameLog:         logJson,
      dnpPlayerIds,
      playerStats:     (typeof g.playerStats === 'object' && g.playerStats) ? g.playerStats : {},
      season:          game.season,
      teamATeamTurnovers: Number(g.teamATeamTurnovers || 0),
      teamBTeamTurnovers: Number(g.teamBTeamTurnovers || 0),
    });
    console.log(`[import] done in ${Date.now() - t0}ms`);
    res.json({ ok: true, swapped, teamAScore: Number(g.teamAScore), teamBScore: Number(g.teamBScore) });
    afterGameImport(game, Object.keys((typeof g.playerStats === 'object' && g.playerStats) ? g.playerStats : {}));
  } catch (err) {
    console.error('Import error:', err);
    res.status(500).json({ error: 'Import failed: ' + err.message });
  }
});

// What follows a game's box score landing, from a wknd-stats file or the scorer's Publish
// (lib/scorer-publish.js): settle picks, ask for ratings, recompute the players' ratings. All
// after the response, non-blocking.
function afterGameImport(game, playerIds) {
  setImmediate(() => settleGamePicks(game.id));
  setImmediate(() => askLeagueCourtRatings(game.id));
  setImmediate(() => {
    try {
      const season = String(game.season ?? '');
      const ctx    = buildSharedContext(season);
      for (const pid of playerIds) computeAndSave(pid, season, ctx);
    } catch (e) {
      console.error('[import] auto-recompute error:', e.message);
    }
  });
}

