// ── /games: upcoming matchups, POTG marquee, season tiles ─────────────────────
// Dates are stored either as "YYYY-MM-DD" or the older "M/D/YYYY h:mm AM" — normalise to
// YYYY-MM-DD before comparing against manilaTodayStr().
function gameYmd(raw) {
  const s = String(raw || '');
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const d = new Date(s);
  return isNaN(d) ? '' : `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
function addDaysYmd(ymd, days) {
  const d = new Date(`${ymd}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}
const isPlayedGame = g => !g.scheduled && !g.under_review && (Number(g.team_a_score) + Number(g.team_b_score)) > 0;
const titleCase = s => String(s || '').toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
// Search results cut titles at ~60 characters: keep the brand suffix only when it fits.
const seoTitle = (base, suffix = ' — WKND Basketball') => (base + suffix).length <= 60 ? base + suffix : base;
// "BANLAO, Ian" → "Ian Banlao" for <title>s (the on-page LASTNAME style reads as shouting in search results).
const searchPlayerName = raw => {
  const [last = '', first = ''] = String(raw || '').split(',').map(x => x.trim());
  // Unicode-aware (titleCase's \b splits "NUÑEZ" into "NuñEz").
  const tc = s => s.toLowerCase().replace(/(^|[\s'-])(\p{L})/gu, (_, p, c) => p + c.toUpperCase());
  return first ? `${first} ${tc(last)}` : tc(last);
};
const shortDay = ymd => (ymd ? new Date(`${ymd}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '');

// "Upcoming" = still scheduled, dated today or later, within the next 14 days. The date
// check matters: stale scheduled rows that were never played must not sit in "Up next".
const UPCOMING_WINDOW_DAYS = 14;
function getUpcomingGames(games) {
  const today = manilaTodayStr();
  const until = addDaysYmd(today, UPCOMING_WINDOW_DAYS);
  return games
    .filter(g => (g.status === 'scheduled' || g.scheduled) && !g.under_review)
    .map(g => ({ g, ymd: gameYmd(g.date) }))
    .filter(x => x.ymd && x.ymd >= today && x.ymd <= until)
    .sort((x, y) => x.ymd.localeCompare(y.ymd) || String(x.g.id).localeCompare(String(y.g.id)))
    .slice(0, 2)
    .map(x => x.g);
}

// Per-game team averages over a set of games. Points use every game's final score; the
// box-score lines (shooting, rebounds...) only the games that actually have player stats —
// a "stats pending" final can count toward points and wins without dragging the rest to 0.
function teamAveragesOver(gameList, teamName, statsById, toById) {
  const t = { gp: 0, pts: 0, box: 0, reb: 0, ast: 0, stl: 0, blk: 0, to: 0, fgm: 0, fga: 0, t3: 0, t3a: 0, ftm: 0, fta: 0 };
  for (const g of gameList) {
    const side = g.team_a_name === teamName ? 'a' : g.team_b_name === teamName ? 'b' : null;
    if (!side) continue;
    t.gp++;
    t.pts += Number(g[`team_${side}_score`]) || 0;
    const rows = (statsById[g.id] || []).filter(s => s.team_id === g[`team_${side}_id`]);
    if (!rows.length) continue;
    t.box++;
    for (const s of rows) {
      const fgm = (+s.fg2m || 0) + (+s.fg3m || 0) + (+s.fg4m || 0);
      t.fgm += fgm;
      t.fga += fgm + (+s.fg2m_miss || 0) + (+s.fg3m_miss || 0) + (+s.fg4m_miss || 0);
      t.t3 += +s.fg3m || 0; t.t3a += (+s.fg3m || 0) + (+s.fg3m_miss || 0);
      t.ftm += +s.ftm || 0; t.fta += (+s.ftm || 0) + (+s.ft_miss || 0);
      t.reb += +s.reb || 0; t.ast += +s.ast || 0; t.stl += +s.stl || 0; t.blk += +s.blk || 0; t.to += +s.turnover || 0;
    }
    t.to += Number(toById[g.id]?.[side]) || 0;
  }
  const per = (v, n) => (n ? Math.round((v / n) * 10) / 10 : null);
  const pct = (m, a) => (a ? Math.round((m / a) * 1000) / 10 : null);
  return {
    gp: t.gp, box: t.box,
    pts: per(t.pts, t.gp), fg: pct(t.fgm, t.fga), t3m: per(t.t3, t.box), t3p: pct(t.t3, t.t3a), ft: pct(t.ftm, t.fta),
    reb: per(t.reb, t.box), ast: per(t.ast, t.box), stl: per(t.stl, t.box), blk: per(t.blk, t.box), to: per(t.to, t.box),
  };
}

// [key, label, higherIsBetter, suffix used in the AI facts]
const MATCHUP_STATS = [
  ['pts', 'Points', true], ['fg', 'FG%', true, '%'], ['t3m', '3PT made', true], ['t3p', '3PT%', true, '%'], ['ft', 'FT%', true, '%'],
  ['reb', 'Rebounds', true], ['ast', 'Assists', true], ['stl', 'Steals', true], ['blk', 'Blocks', true], ['to', 'Turnovers', false],
];

function gameTagLabel(g) {
  if (g.game_type === 'finals') return 'Finals';
  if (g.game_type === 'playoff') return 'Playoffs';
  return '';
}

// Everything the matchup card needs for one upcoming game. Head-to-head covers every
// meeting since the league began (all seasons, playoffs included); when the two teams have
// never met, the comparison falls back to each team's current-season games.
function buildMatchup(game, ctx) {
  const A = game.team_a_name, B = game.team_b_name;
  const pair = g => (g.team_a_name === A && g.team_b_name === B) || (g.team_a_name === B && g.team_b_name === A);
  const meetings = ctx.played.filter(pair); // newest first
  const winsOf = name => meetings.filter(g => {
    const aWin = Number(g.team_a_score) > Number(g.team_b_score);
    return (aWin ? g.team_a_name : g.team_b_name) === name;
  }).length;
  const seasonGames = ctx.played.filter(g => String(g.season) === String(ctx.season));
  const recordOf = name => {
    const mine = seasonGames.filter(g => g.team_a_name === name || g.team_b_name === name);
    const w = mine.filter(g => (g.team_a_name === name) === (Number(g.team_a_score) > Number(g.team_b_score))).length;
    return { w, l: mine.length - w };
  };

  const firstMeeting = meetings.length === 0;
  const basis = firstMeeting ? seasonGames : meetings;
  for (const g of basis) ctx.loadGame(g.id);
  const avgA = teamAveragesOver(firstMeeting ? basis.filter(g => g.team_a_name === A || g.team_b_name === A) : basis, A, ctx.statsById, ctx.toById);
  const avgB = teamAveragesOver(firstMeeting ? basis.filter(g => g.team_a_name === B || g.team_b_name === B) : basis, B, ctx.statsById, ctx.toById);
  const rows = MATCHUP_STATS
    .filter(([k]) => avgA[k] != null && avgB[k] != null)
    .map(([k, label, hi, suffix = '']) => ({ key: k, label, a: avgA[k], b: avgB[k], hi, suffix }));

  // Form check (views/form-check.js): each team's last 5 games with box scores, any opponent,
  // any season. ctx.played only holds games before this one (matchupAsOf), so a frozen preview
  // keeps the form it had at tip-off.
  const byDateDesc = [...ctx.played].sort((x, y) => gameYmd(y.date).localeCompare(gameYmd(x.date)));
  const lastFive = name => {
    const out = [];
    for (const g of byDateDesc) {
      if (out.length === 5) break;
      if (g.team_a_name !== name && g.team_b_name !== name) continue;
      ctx.loadGame(g.id);
      const side = g.team_a_name === name ? 'a' : 'b';
      if ((ctx.statsById[g.id] || []).some(s => s.team_id === g[`team_${side}_id`])) out.push(g);
    }
    return out;
  };
  const fiveA = lastFive(A), fiveB = lastFive(B);
  const form = {
    a: teamAveragesOver(fiveA, A, ctx.statsById, ctx.toById), b: teamAveragesOver(fiveB, B, ctx.statsById, ctx.toById),
    nA: fiveA.length, nB: fiveB.length,
  };

  // Go-to scorer per team in this matchup: highest points per game over the meetings they
  // played (at least 2 when there have been 2+ box scores, so one hot night doesn't win it).
  const scorers = [];
  if (!firstMeeting) {
    for (const [name, opp] of [[A, B], [B, A]]) {
      const per = new Map();
      for (const g of [...meetings].reverse()) { // oldest first, for the per-game bars
        const side = g.team_a_name === name ? 'a' : 'b';
        for (const s of (ctx.statsById[g.id] || []).filter(s => s.team_id === g[`team_${side}_id`])) {
          const p = per.get(s.player_id) || { id: s.player_id, games: [], pts: 0, reb: 0, ast: 0, fgm: 0, fga: 0 };
          const fgm = (+s.fg2m || 0) + (+s.fg3m || 0) + (+s.fg4m || 0);
          p.games.push({ pts: +s.pts || 0, ymd: gameYmd(g.date), tag: gameTagLabel(g) });
          p.pts += +s.pts || 0; p.reb += +s.reb || 0; p.ast += +s.ast || 0;
          p.fgm += fgm; p.fga += fgm + (+s.fg2m_miss || 0) + (+s.fg3m_miss || 0) + (+s.fg4m_miss || 0);
          per.set(s.player_id, p);
        }
      }
      const boxCount = meetings.filter(g => (ctx.statsById[g.id] || []).length).length;
      const minGames = Math.min(2, boxCount);
      const best = [...per.values()].filter(p => p.games.length >= minGames)
        .sort((x, y) => y.pts / y.games.length - x.pts / x.games.length)[0];
      if (!best) { scorers.push(null); continue; }
      const player = ctx.playerMap[best.id];
      const top = best.games.reduce((m, x) => (x.pts > m.pts ? x : m), best.games[0]);
      const n = best.games.length;
      scorers.push({
        id: best.id, name: displayPlayerName(player?.name || ''), rawName: player?.name || '', number: player?.number ?? '', team: name, opp, hasPhoto: !!player?.picture_url,
        ppg: Math.round((best.pts / n) * 10) / 10, rpg: Math.round((best.reb / n) * 10) / 10, apg: Math.round((best.ast / n) * 10) / 10,
        fg: best.fga ? Math.round((best.fgm / best.fga) * 1000) / 10 : null, games: n,
        series: best.games.map(x => x.pts), dates: best.games.map(x => x.ymd), best: { pts: top.pts, label: top.tag ? `${top.tag} · ${shortDay(top.ymd)}` : shortDay(top.ymd) },
      });
    }
  }

  const lastMeetings = meetings.slice(0, 3).map(g => {
    ctx.loadGame(g.id);
    const stats = ctx.statsById[g.id] || [];
    const aIsA = g.team_a_name === A;
    const [potgId, coId] = potgIdsFor(g, stats);
    const line = id => {
      const s = id && stats.find(x => x.player_id === id);
      return s ? { name: displayPlayerName(ctx.playerMap[id]?.name || ''), pts: +s.pts || 0, reb: +s.reb || 0, ast: +s.ast || 0 } : null;
    };
    const potg = line(potgId);
    return {
      id: g.id, ymd: gameYmd(g.date), season: g.season, tag: gameTagLabel(g), hasCover: !!g.has_cover,
      scoreA: Number(aIsA ? g.team_a_score : g.team_b_score), scoreB: Number(aIsA ? g.team_b_score : g.team_a_score),
      potg: potg ? { ...potg, co: line(coId) } : null,
    };
  });

  return {
    game, ymd: gameYmd(game.date), a: A, b: B, firstMeeting,
    winsA: winsOf(A), winsB: winsOf(B), meetings: meetings.length,
    boxMeetings: meetings.filter(g => (ctx.statsById[g.id] || []).length).length,
    recordA: recordOf(A), recordB: recordOf(B), season: ctx.season,
    rows, form, scorers, lastMeetings,
    slides: meetings.filter(g => g.has_cover).slice(0, 4).map(g => g.id),
  };
}

// POTG marquee: the latest Players of the Game, newest first.
// Each item also carries its season count ("2nd POTG this season"), counted over the
// season's games up to and including that one (played is newest first).
function buildPotgMarquee(played, playerMap, count = 8) {
  const out = [];
  const potgByGame = new Map();
  const potgOf = g => {
    if (!potgByGame.has(g.id)) potgByGame.set(g.id, potgIdsFor(g, getGameStats(g.id)));
    return potgByGame.get(g.id);
  };
  // A co-POTG gets their own card, right after the POTG.
  function* entries() {
    for (const [i, g] of played.entries()) for (const [k, pid] of potgOf(g).entries()) yield { g, i, pid, co: k > 0 };
  }
  for (const { g, i, pid, co } of entries()) {
    if (out.length >= count) break;
    const s = getGameStats(g.id).find(x => x.player_id === pid);
    if (!s) continue;
    const player = playerMap[pid];
    const team = s.team_id === g.team_a_id ? g.team_a_name : g.team_b_name;
    // Points always, then up to two of the bigger other lines.
    const extras = [['reb', 'REB', 5], ['ast', 'AST', 5], ['stl', 'STL', 3], ['blk', 'BLK', 3]]
      .map(([k, u, min]) => ({ n: +s[k] || 0, u, score: (+s[k] || 0) / min }))
      .filter(x => x.score >= 1).sort((x, y) => y.score - x.score).slice(0, 2);
    const aWin = Number(g.team_a_score) > Number(g.team_b_score);
    const [w, l, ws, ls] = aWin ? [g.team_a_name, g.team_b_name, g.team_a_score, g.team_b_score] : [g.team_b_name, g.team_a_name, g.team_b_score, g.team_a_score];
    const tag = gameTagLabel(g);
    let tally = 0;
    for (const og of played.slice(i)) if (String(og.season) === String(g.season) && potgOf(og).includes(pid)) tally++;
    out.push({
      gameId: g.id, playerId: pid, name: displayPlayerName(player?.name || ''), rawName: player?.name || '', number: player?.number, team, hasPhoto: !!player?.picture_url,
      meta: `${shortDay(gameYmd(g.date))} · S${g.season}${tag ? ` ${tag}` : ''}`,
      day: shortDay(gameYmd(g.date)), season: g.season, tag, co,
      stats: [{ n: +s.pts || 0, u: 'PTS' }, ...extras.map(x => ({ n: x.n, u: x.u }))],
      line: { pts: +s.pts || 0, reb: +s.reb || 0, ast: +s.ast || 0 },
      ws, ls, winner: w, loser: l, tally,
      result: `${titleCase(w)} ${ws}–${ls} ${titleCase(l)}`,
      writeup: String(potgWriteupFor(g, pid)).replace(/\*\*/g, '').trim(),
    });
  }
  return out;
}

// Four season tiles: biggest win, closest finish, most team points, best single game.
function buildSeasonTiles(seasonPlayed, playerMap) {
  if (!seasonPlayed.length) return [];
  const margin = g => Math.abs(Number(g.team_a_score) - Number(g.team_b_score));
  const line = g => {
    const aWin = Number(g.team_a_score) > Number(g.team_b_score);
    const [w, l, ws, ls] = aWin ? [g.team_a_name, g.team_b_name, g.team_a_score, g.team_b_score] : [g.team_b_name, g.team_a_name, g.team_b_score, g.team_a_score];
    return { text: `${titleCase(w)} ${ws}–${ls} ${titleCase(l)} · ${shortDay(gameYmd(g.date))}`, ws, ls };
  };
  const biggest = seasonPlayed.reduce((m, g) => (margin(g) > margin(m) ? g : m));
  const closest = seasonPlayed.reduce((m, g) => (margin(g) < margin(m) ? g : m));
  const high = seasonPlayed.reduce((m, g) => (Math.max(+g.team_a_score, +g.team_b_score) > Math.max(+m.team_a_score, +m.team_b_score) ? g : m));
  const highSide = +high.team_a_score >= +high.team_b_score ? 'a' : 'b';
  let bestGame = null;
  for (const g of seasonPlayed) {
    for (const s of getGameStats(g.id)) {
      if (!bestGame || (+s.pts || 0) > bestGame.pts) bestGame = { pts: +s.pts || 0, playerId: s.player_id, g, team: s.team_id === g.team_a_id ? g.team_a_name : g.team_b_name };
    }
  }
  const c = line(closest);
  const tiles = [
    { label: 'Biggest win', value: `+${margin(biggest)}`, sub: line(biggest).text, href: `/games/${encodeURIComponent(biggest.id)}` },
    { label: 'Closest finish', value: `${c.ws}–${c.ls}`, sub: c.text, href: `/games/${encodeURIComponent(closest.id)}` },
    { label: 'Most points', value: String(high[`team_${highSide}_score`]), sub: `${titleCase(high[`team_${highSide}_name`])} · ${shortDay(gameYmd(high.date))}`, href: `/games/${encodeURIComponent(high.id)}` },
  ];
  if (bestGame && bestGame.pts > 0) {
    tiles.push({ label: 'Best single game', value: `${bestGame.pts} PTS`, sub: `${displayPlayerName(playerMap[bestGame.playerId]?.name || '')} · ${titleCase(bestGame.team)}, ${shortDay(gameYmd(bestGame.g.date))}`, href: `/players/${encodeURIComponent(bestGame.playerId)}`, accent: true });
  }
  return tiles;
}

// ── Matchup storylines (AI) ───────────────────────────────────────────────────
// Same pattern as the homepage summaries: facts reduce to a key, the stored story (setting
// games_matchup_story_<gameId>) only shows while the key still matches, a stale/missing one
// is written in the background, never awaited by the page. Every number must appear in
// the facts, banned words are rejected in code, then a temperature-0 fact check.
// v2: comparisons are checked in code (lib/story-checks.js) — bumping regenerates every stored story.
// v3 (2026-10-10): player-number check — rewrites the stored storylines once.
// v4 (2026-10-20): major highlights (previewHighlights) must be mentioned; key carries them.
const MATCHUP_STORY_VERSION = 4;
// previewHighlights runs a few queries and matchupStoryFacts runs on every /games view, so
// each game's list is kept for 5 minutes.
const previewHlCache = new Map();
function cachedPreviewHighlights(m) {
  const hit = previewHlCache.get(m.game.id);
  if (hit && Date.now() - hit.at < 5 * 60 * 1000) return hit.list;
  let list = [];
  try { list = previewHighlights(m); } catch (err) { console.error('previewHighlights error:', err.message); }
  previewHlCache.set(m.game.id, { at: Date.now(), list });
  return list;
}
// A finished game's highlights, kept per game + score + box-score size (a re-import or a stat
// correction changes them): the homepage builds its facts on every view.
const gameHlCache = new Map();
function cachedGameHighlights(g) {
  const stats = getGameDetailStats(g.id);
  const k = `${g.id}|${g.team_a_score}-${g.team_b_score}|${stats.length}|${stats.reduce((t, s) => t + (Number(s.pts) || 0) + (Number(s.reb) || 0) + (Number(s.fg3m) || 0), 0)}`;
  const hit = gameHlCache.get(g.id);
  if (hit && hit.k === k) return hit.list;
  let list = [];
  // The full row: list queries leave out the play-by-play the comeback/game-winner need.
  try { list = gameHighlights(getGameById(g.id) || g, stats); } catch (err) { console.error('gameHighlights error:', err.message); }
  gameHlCache.set(g.id, { k, list });
  return list;
}
// A short, stable signature of a list of strings, for story keys.
const sig = list => { let h = 5381; for (const ch of list.join('|')) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0; return h.toString(36); };
const matchupStoryInFlight = new Set();
let matchupStoryCooldownUntil = 0;

function matchupStoryFacts(m) {
  const T = titleCase;
  const meetLines = m.lastMeetings.map(x => {
    const aWin = x.scoreA > x.scoreB;
    return `${aWin ? T(m.a) : T(m.b)} ${Math.max(x.scoreA, x.scoreB)}-${Math.min(x.scoreA, x.scoreB)} on ${shortDay(x.ymd)} (Season ${x.season}${x.tag ? ` ${x.tag}` : ''})`;
  });
  const statLines = m.rows.map(r => `- ${r.label}: ${T(m.a)} ${r.a.toFixed(1)}${r.suffix}, ${T(m.b)} ${r.b.toFixed(1)}${r.suffix}${r.hi ? "" : " (fewer is better)"}`);
  const scorerLines = m.scorers.filter(Boolean).map(s => `${s.name} (${T(s.team)}) ${s.ppg.toFixed(1)} points per game against ${T(s.opp)} over ${s.games} games, scoring ${s.series.join(', ')} in those games, oldest first`);
  const basis = m.firstMeeting
    ? `The two teams have not met before. Per-game averages below are each team's Season ${m.season} games against anyone.`
    : `Head to head since Season 3: ${m.meetings} meetings, ${T(m.a)} has won ${m.winsA}, ${T(m.b)} has won ${m.winsB}.\nMost recent meetings, newest first: ${meetLines.join('; ')}.\nPer-game averages in their meetings${m.boxMeetings < m.meetings ? ` (box-score stats exist for ${m.boxMeetings} of the ${m.meetings} meetings; points cover all of them)` : ''}:`;
  const facts = `Upcoming game: ${T(m.a)} vs ${T(m.b)}, Season ${m.season}.
Season ${m.season} records so far: ${T(m.a)} ${m.recordA.w}-${m.recordA.l}, ${T(m.b)} ${m.recordB.w}-${m.recordB.l}.
${basis}
${statLines.join('\n')}${scorerLines.length ? `\nTop scorers in this matchup: ${scorerLines.join('; ')}.` : ''}`;
  // Major highlights: up to 2 the storyline must mention (60–90 words has room for two).
  const highlights = cachedPreviewHighlights(m);
  const musts = mustMentions(highlights, 2);
  const hlBlock = highlightsBlock(highlights, musts);
  const key = `v${MATCHUP_STORY_VERSION}|${m.game.id}|${m.recordA.w}-${m.recordA.l}|${m.recordB.w}-${m.recordB.l}|${m.lastMeetings.map(x => `${x.id}:${x.scoreA}-${x.scoreB}`).join(',')}|${m.meetings}|h${sig(highlights.map(h => h.text))}`;
  return {
    key, facts: hlBlock ? `${facts}\n\n${hlBlock}` : facts, section: 'matchup preview', musts,
    // For other writers (the picks email): the facts with the highlights as plain lines, no
    // MUST-MENTION instruction block.
    baseFacts: highlights.length ? `${facts}\n\nHighlights (verified):\n${highlights.map(h => `- ${h.text}`).join('\n')}` : facts,
    // For the wrong-way comparison check: team names as the copy writes them, per-game rows.
    teams: [T(m.a), T(m.b)],
    rows: m.rows.map(r => ({ label: r.label, a: r.a, b: r.b, hi: !!r.hi })),
    // For the "player's number passed off as a team edge" check.
    scorers: m.scorers.filter(Boolean).map(s => ({ name: s.name, ppg: s.ppg })),
  };
}

// The storyline: writeHeadlineCopy with its own shape (a full-sentence headline, a 3-4
// sentence body) and the matchup's extra checks (wrong-way comparisons, a player's average
// passed off as a team edge).
async function generateMatchupStory(gameId, f) {
  return writeHeadlineCopy(f, {
    label: `Matchup story (${gameId})`, tries: 4, maxTokens: 500,
    intro: 'You write the storyline for an upcoming game on the WKND Basketball games page — a recreational league whose players read every word.',
    headline: { max: 110, period: true, bold: 'key' },
    body: { sentences: 'one paragraph of 3-4', words: 90, extra: "Aim for 60-90 words. Explain what has decided this matchup so far and what to watch next time they meet. Don't repeat the headline." },
    rules: [
      `- No gaps of your own (no "6 more", no "12 combined") — compare with words like "more" or "fewer" instead. Before writing "more", "fewer", "higher", "lower", "out-rebounds", "outscores", "edge" or "advantage" about a team, check that team's number in the facts really is the bigger (or smaller) one. For stats marked "fewer is better", the lower number is the advantage.`,
      `- A single game's margin is not an "edge" or a "lead" in the series. Per-game averages describe the meetings overall; never attach them to a single game.`,
      `- A player's points per game belongs to that player. Never present it as a team's edge, lead or margin, and name the player whenever you use it.`,
      `- Don't invent injuries, quotes or lineups. Don't predict a winner as certain.`,
    ],
    checks: [
      t => playerNumberProblems(t, f.scorers).map(p => `${p} — a player's points per game belongs to that player; name the player`),
      t => comparisonProblems(t, f).map(p => `a comparison runs the wrong way: ${p}`),
    ],
    save: ({ headline, body }) => setSetting(`games_matchup_story_${gameId}`, JSON.stringify({ key: f.key, headline, body, at: Date.now() })),
  });
}

// The stored storyline for a game, only while it still matches these facts.
// any: the last storyline written for this game whatever its facts key — for freezing a
// preview that closed before a fresh one was written (a version bump invalidates every key).
function storedMatchupStory(gameId, key, { any = false } = {}) {
  let s = null;
  try { s = JSON.parse(getSetting(`games_matchup_story_${gameId}`, '') || 'null'); } catch {}
  return s && (any || s.key === key) && s.headline ? { headline: s.headline, body: s.body } : null;
}

function getMatchupStories(matchups) {
  const out = {};
  for (const m of matchups) {
    const f = matchupStoryFacts(m);
    const stored = storedMatchupStory(m.game.id, f.key);
    if (stored) {
      out[m.game.id] = stored;
    } else if (aiAvailable() && !matchupStoryInFlight.has(m.game.id) && Date.now() >= matchupStoryCooldownUntil) {
      matchupStoryInFlight.add(m.game.id);
      generateMatchupStory(m.game.id, f)
        .catch(err => { console.error(`Matchup story (${m.game.id}) failed:`, err.message); matchupStoryCooldownUntil = Date.now() + HOME_SUMMARY_COOLDOWN_MS; })
        .finally(() => matchupStoryInFlight.delete(m.game.id));
    }
  }
  return out;
}

// ── Matchup previews (/picks/<game>), stored in game_previews ─────────────────
// The matchup as it stood before tip-off: only games dated before this one count, and
// records are for the game's own season. /games, /picks/<game>, the reminder email and the
// storyline facts all build it this way, so the story key matches everywhere — and a
// finished game rebuilds to exactly the numbers it had before it was played.
function matchupAsOf(game, games, playerMap) {
  const ymd = gameYmd(game.date);
  const ctx = buildGamesContext(games.filter(g => g.id !== game.id && gameYmd(g.date) < ymd), playerMap);
  if (game.season != null && game.season !== '') ctx.season = game.season;
  return buildMatchup(game, ctx);
}

// 'open' (picks open), 'closed' (picks closed or game day passed, no result yet), 'final',
// or 'later' (scheduled past the upcoming window — preview only, no picks yet).
function previewState(game, games, pctx) {
  const pg = pctx.byId[game.id] || toPickGame(game, gameYmd);
  if (pg.played) return 'final';
  if (getUpcomingGames(games).some(g => g.id === game.id)) return upcomingPickState(game, pctx).closed ? 'closed' : 'open';
  const ymd = gameYmd(game.date);
  return ymd && ymd < manilaTodayStr() ? 'closed' : 'later';
}

// The preview for one game. While picks are open it's rebuilt on every view (and saved when
// something changed); from close onward the saved copy is frozen and served as is. Odds are
// stored raw — the odds switch and per-game "hide odds" apply when rendering.
function gamePreview(game, games, playerMap, pctx) {
  const ymd = gameYmd(game.date);
  const state = previewState(game, games, pctx);
  const stored = getGamePreview(game.id);
  // An admin re-opening picks (or a postponed game) unfreezes it.
  if (stored?.frozen && stored.ymd === ymd && stored.matchup && (state === 'final' || state === 'closed')) {
    return { state, m: { ...stored.matchup, game }, story: stored.story, odds: stored.odds, frozen: true };
  }
  const freeze = state === 'final' || state === 'closed';
  const m = matchupAsOf(game, games, playerMap);
  // Frozen: the last storyline written for these exact facts (none is written now).
  // Live: the same background generation /games triggers.
  const story = freeze
    ? (storedMatchupStory(game.id, matchupStoryFacts(m).key) || storedMatchupStory(game.id, null, { any: true }))
    : (getMatchupStories([m])[game.id] || null);
  const odds = computeOdds(pctx.byId[game.id] || toPickGame(game, gameYmd), pctx.played);
  const { game: _game, ...matchup } = m;
  const changed = !stored || stored.frozen || stored.ymd !== ymd || JSON.stringify([stored.matchup, stored.story, stored.odds]) !== JSON.stringify([matchup, story, odds]);
  if (freeze || changed) saveGamePreview({ gameId: game.id, ymd, matchup, story, odds, frozen: freeze });
  return { state, m, story, odds, frozen: freeze };
}

// Odds as shown: none when the odds switch is off or this game's odds are hidden.
const shownOdds = (gameId, odds, pctx) => (pickOddsEnabled() && !pctx.settings[gameId]?.hide_odds ? odds : null);

// Slugs are saved the first time a game is opened by id, so a slug nobody has visited yet
// (sitemap, a pasted link) is matched against the games list.
function findGameRef(ref) {
  const r = resolveRef('game', ref, id => getGameById(id), g => gameSlug(g));
  if (r) return r;
  const g = getAllGames().find(x => gameSlug(x) === ref);
  if (!g) return null;
  saveSlug('game', g.id, ref);
  return { id: g.id };
}
// A game's page is its matchup preview before tip-off (formerly /picks/<game>, which now redirects).
const previewHref = game => `/games/${encodeURIComponent(gameSlug(game))}`;

function buildGamesContext(games, playerMap) {
  const played = games.filter(isPlayedGame);
  const statsById = {}, toById = {};
  return {
    played, playerMap, season: getPortalCurrentSeason(), statsById, toById,
    loadGame(id) {
      if (statsById[id]) return;
      statsById[id] = getGameStats(id);
      const full = getGameById(id);
      toById[id] = { a: full?.team_a_to_team || 0, b: full?.team_b_to_team || 0 };
    },
  };
}

// ── "Who wins?" picks: odds, cut-off, records (pure logic lives in lib/picks.js) ──────
// Picks are on by default (they shipped live before these switches existed); odds and the
// game-day cut-off are admin settings on /admin/picks (Who wins? settings).
const picksEnabled = () => getSetting('picks_enabled', '1') !== '0';
const pickOddsEnabled = () => getSetting('picks_odds_enabled', '1') !== '0';
const picksCloseTime = () => {
  const v = getSetting('picks_close_time', PICKS_CLOSE_DEFAULT);
  return /^\d{2}:\d{2}$/.test(v) ? v : PICKS_CLOSE_DEFAULT;
};

// Everything the picks surfaces need, built once per request. Odds for every played game are
// its pre-game odds (computeOdds only looks at earlier dates), so records and "upset" calls
// stay fixed after the fact.
function buildPicksContext(games) {
  const all = games.map(g => toPickGame(g, gameYmd));
  const played = all.filter(g => g.played);
  return {
    all, played,
    byId: Object.fromEntries(all.map(g => [g.id, g])),
    // Odds switched off = no odds anywhere, including "upset" (which is judged against them).
    oddsById: pickOddsEnabled() ? Object.fromEntries(played.map(g => [g.id, computeOdds(g, played)])) : {},
    picks: getAllGamePicks(),
    settings: getAllGamePickSettings(),
  };
}

// Odds that score "Beat the Odds" points: the preview frozen at pick close when there is one
// (so a later box-score fix can't move anyone's points), else the pre-game odds. Scored even
// with the global odds switch off; a game with its odds hidden scores ±1 like a toss-up.
function scoringOdds(settled, pctx) {
  return Object.fromEntries(settled.map(g => {
    if (pctx.settings[g.id]?.hide_odds) return [g.id, null];
    const stored = getGamePreview(g.id);
    return [g.id, (stored?.frozen && stored.odds) || computeOdds(g, pctx.played)];
  }));
}

function seasonPicks(pctx, season) {
  const settled = settleGames(pctx.played.filter(g => g.season === String(season)), pctx.oddsById);
  const pickedIds = new Set(pctx.picks.map(p => p.game_id));
  const pickable = settled.filter(g => pickedIds.has(g.id));
  const records = buildPickRecords(pctx.picks, pickable, scoringOdds(pickable, pctx));
  addPodiumBonus(records, season);
  // Tiebreak step 5 only counts once Finals Game 1 has a final.
  const finalsG1 = finalsGame1Id(pctx.all, season);
  const guesses = marginGuessDiffs(pctx.picks, settled.find(g => g.id === finalsG1));
  return { settled, pickable, records, finalsG1, board: pickLeaderboard(records, guesses), callers: callerRecords(settled, pctx.picks) };
}

// Pickmaster: the MVP podium bonus (+1 per exact spot, from the ballot frozen at the bonus
// cut-off) once the race is revealed. Everyone with a player account can earn it, admins
// included: while the race is locked only the super-admin login (no player account) sees scores. It goes into net (points and ranks include it, /picks/rules) and
// r.bonus (the board's tag); the tiebreakers read correct/streak/odds, so they stay
// game-picks-only. A bonus-only player gets an empty record so they're on the board.
function addPodiumBonus(records, season) {
  if (!mvpPodiumEnabled()) return;
  const bonus = listMvpBonusBallots(season);
  if (!bonus.length || isMvpLocked(season)) return;
  const podium = mvpTop3(season);
  if (podium.length < 3) return;
  for (const b of bonus) {
    const pts = podiumPoints(b, podium);
    if (!pts) continue;
    const r = records[b.player_id] ||= { picks: 0, correct: 0, wrong: 0, net: 0, pct: 0, streak: 0, best: 0, upsets: 0, oddsPts: 0, results: [] };
    r.net += pts;
    r.bonus = pts;
  }
}

// Closed/odds state for one upcoming game.
function upcomingPickState(game, pctx) {
  const g = pctx.byId[game.id] || toPickGame(game, gameYmd);
  const setting = pctx.settings[game.id];
  const closed = picksClosedFor(g, setting, { todayYmd: manilaTodayStr(), nowHm: manilaHmNow(), closeTime: picksCloseTime() });
  const odds = pickOddsEnabled() && !setting?.hide_odds ? computeOdds(g, pctx.played) : null;
  return { closed, odds };
}

// After-game "you called it" notifications — once per game (claimGamePickSettle), only once
// the result is public. Called from every route that can make a result final or public.
// "Your stat card is ready" — once per game, to every player in the box score with a login,
// as soon as a final has its stats and is public. Recent games only, so re-saving an old
// game doesn't ping anyone. The link opens the Share My Stats editor (?share=1).
function notifyStatCards(gameId) {
  try {
    const game = getGameById(gameId);
    if (!game || game.under_review || !(game.status === 'final' || game.status === 'complete')) return;
    const ymd = gameYmd(game.date);
    if (!ymd || ymd < addDaysYmd(manilaTodayStr(), -7)) return;
    const stats = getGameDetailStats(gameId);
    if (!stats.length || getSetting(`stat_cards_notified_${gameId}`, '')) return;
    setSetting(`stat_cards_notified_${gameId}`, String(Date.now()));
    const accounts = new Set(getPlayersWithAccounts().map(p => p.id));
    const link = `/games/${encodeURIComponent(gameSlug(game))}?share=1`;
    for (const s of stats) {
      if (!accounts.has(s.player_id)) continue;
      const opp = String(s.team_name || '').toUpperCase() === String(game.team_a_name).toUpperCase() ? game.team_b_name : game.team_a_name;
      const best = [['reb', 'REB'], ['ast', 'AST'], ['stl', 'STL'], ['blk', 'BLK']]
        .map(([k, l]) => ({ v: Number(s[k]) || 0, l })).filter(x => x.v > 0).sort((a, b) => b.v - a.v)[0];
      const line = `${Number(s.pts) || 0} PTS${best ? ` · ${best.v} ${best.l}` : ''}`;
      createNotification({ playerId: s.player_id, type: 'stat_card', title: 'Your stat card is ready', body: `${line} vs ${titleCase(opp)}. Share it to your story →`, link });
    }
  } catch (err) {
    console.error(`[stat cards] notify ${gameId} failed:`, err.message);
  }
}

function settleGamePicks(gameId) {
  // Same moments a result becomes final/public — also when players' stat cards are ready.
  notifyStatCards(gameId);
  try {
    const game = getGameById(gameId);
    if (!game) return;
    const g = toPickGame(game, gameYmd);
    if (!g.played) return;
    const gamePicks = getGamePicksWithPlayers(gameId);
    if (!gamePicks.length || !claimGamePickSettle(gameId)) return;
    const pctx = buildPicksContext(getAllGames());
    const { records, settled } = seasonPicks(pctx, g.season);
    const sg = settled.find(x => x.id === gameId);
    const upset = !!(sg?.odds?.fav && sg.odds.fav !== sg.winner);
    const winner = titleCase(g.sa > g.sb ? g.a : g.b), loser = titleCase(g.sa > g.sb ? g.b : g.a);
    const score = `${Math.max(g.sa, g.sb)}–${Math.min(g.sa, g.sb)}`;
    for (const p of gamePicks) {
      const r = records[p.player_id];
      if (!r) continue;
      const ok = p.side === (g.sa > g.sb ? 'a' : 'b');
      const season = `Season picks: ${r.correct} of ${r.picks}`;
      createNotification({
        playerId: p.player_id, type: 'pick_result',
        title: ok ? `You called it — ${winner} beat ${loser} ${score}` : `${winner} beat ${loser} ${score}`,
        body: ok
          ? `${upset ? 'You called the upset! ' : ''}${season}${r.streak >= 2 ? ` · ${r.streak} in a row` : ''}`
          : `Your ${loser} pick missed. ${season}.`,
        link: previewHref(game),
      });
    }
  } catch (err) {
    console.error(`[picks] settle ${gameId} failed:`, err.message);
  }
}

// Logged-in players see who picked each side, picked or not (Paolo, 2026-10-08; kept after
// the 2026-10-13 pick card review). Guests see the faces but never the sides (pickFacesFlat).
const canSeeFaces = viewerId => !!viewerId;

// The pick card's faces (views/pick-card.js): everyone who picked, one list, you first then
// newest first. Guests see the faces too (2026-10-13) but never which side anyone took:
// `side` is only included for logged-in viewers.
function pickFacesFlat(game, viewerId) {
  const withSides = canSeeFaces(viewerId);
  const out = getGamePicksWithPlayers(game.id).map(p => {
    const name = displayPlayerName(p.player_name || '');
    const f = { id: p.player_id, name, ini: initials(name), color: teamColor(p.team_name), me: !!viewerId && p.player_id === viewerId };
    if (withSides) { f.side = p.side; f.sideColor = teamColor(p.side === 'a' ? game.team_a_name : game.team_b_name); }
    return f;
  }).reverse();
  return out.sort((x, y) => Number(y.me) - Number(x.me));
}
// The stakes line on the pick card: where you stand in the Pickmaster race and where this
// pick alone would put you. Rank is shared by points (lib/picks.js pickLeaderboard), so
// rank-if = 1 + everyone else above that total, with "T" when someone else is level.
// Hidden until the season has 2+ settled pick days (early ranks swing wildly) and for anyone
// not on the board yet. bto: the Beat the Odds points a right pick on each side would earn.
function pickStakes(sp, viewerId, odds) {
  if (!viewerId) return null;
  const days = new Set(sp.pickable.map(g => g.ymd)).size; // settled game days that had picks
  const me = sp.board.rows.find(r => r.playerId === viewerId);
  if (days < 2 || !me) return null;
  const others = sp.board.rows.filter(r => r.playerId !== viewerId);
  const rankAt = n => `${others.some(r => r.net === n) ? 'T' : '#'}${others.filter(r => r.net > n).length + 1}`;
  const pts = n => (n > 0 ? `+${n}` : String(n));
  return {
    now: rankAt(me.net), net: pts(me.net), right: rankAt(me.net + 1), wrong: rankAt(me.net - 1),
    bto: odds ? { a: oddsPoints('a', true, odds).toFixed(2), b: oddsPoints('b', true, odds).toFixed(2) } : null,
  };
}

// "Remind me": one bell + email the evening before game day (7 PM Manila), for players who
// asked and still haven't picked every open game that day. Stored per game day in settings.
const PICK_REMIND_HM = '19:00';
const pickRemindKey = ymd => `pick_remind_${ymd}`;
function pickRemindList(ymd) {
  try { return new Set(JSON.parse(getSetting(pickRemindKey(ymd), '[]') || '[]')); } catch { return new Set(); }
}
function pickRemindAt(ymd) { return `${addDaysYmd(ymd, -1)}T${PICK_REMIND_HM}:00+08:00`; }
function pickRemindState(ymd, viewerId) {
  if (!viewerId || !ymd) return null;
  const at = pickRemindAt(ymd);
  if (Date.parse(at) <= Date.now()) return null; // too late to schedule one
  const day = new Date(`${addDaysYmd(ymd, -1)}T00:00:00Z`).toLocaleDateString('en-US', { weekday: 'short', timeZone: 'UTC' });
  return { on: pickRemindList(ymd).has(viewerId), label: `${day} ${fmtCloseTime(PICK_REMIND_HM)}` };
}

// The result card (views/pick-card.js pickResultCard) for one settled game: the final, the
// pre-game odds (as scored: the copy frozen at pick close when there is one), the pickers'
// split, everyone's pick (public after the final), your pick and what it earned.
function pickResultOf(g, gp, viewerId, pctx) {
  const s = calledItSummary(g, gp, viewerId);
  const hidden = !!pctx.settings[g.id]?.hide_odds;
  const frozen = getGamePreview(g.id);
  const odds = hidden ? null : (frozen?.frozen && frozen.odds) || g.odds || null;
  const counts = { a: gp.filter(p => p.side === 'a').length, b: gp.filter(p => p.side === 'b').length };
  const faces = gp.map(p => {
    const name = displayPlayerName(p.player_name || '');
    return {
      id: p.player_id, name, ini: initials(name), color: teamColor(p.team_name), me: !!viewerId && p.player_id === viewerId,
      side: p.side, sideColor: teamColor(p.side === 'a' ? g.a : g.b), right: p.side === g.winner,
    };
  }).reverse().sort((x, y) => Number(y.me) - Number(x.me) || Number(y.right) - Number(x.right));
  const mine = viewerId ? gp.find(p => p.player_id === viewerId) : null;
  const ok = mine ? mine.side === g.winner : null;
  const isG1 = g.type === 'finals' && finalsGame1Id(pctx.all, g.season) === g.id;
  const commentsOn = getSetting('comments_enabled', '0') === '1';
  return {
    id: g.id, a: g.a, b: g.b, sa: g.sa, sb: g.sb, ymd: g.ymd, winner: g.winner, odds, upset: s.upset,
    // g is the pick-shaped game (a / b), previewHref wants a games row.
    href: previewHref({ id: g.id, team_a_name: g.a, team_b_name: g.b }), counts, total: s.total, called: s.calledIt.length, faces,
    myPick: mine?.side || null,
    points: mine ? { net: ok ? 1 : -1, bto: odds ? oddsPoints(mine.side, ok, odds) : null } : null,
    margin: isG1 && mine?.margin_guess != null ? { guess: mine.margin_guess, actual: Math.abs(g.sa - g.sb), side: mine.side } : null,
    talk: commentsOn, talkCount: commentsOn ? (getGameCommentCounts([g.id])[g.id] || 0) : 0,
  };
}

// When picks close for an upcoming game, as an ISO time (Manila), for the card's countdown.
// null when an admin is holding picks open (no deadline to count down to).
function pickCloseAt(pg, setting) {
  if (setting?.closed === 0 || !pg.ymd) return null;
  return `${pg.ymd}T${picksCloseTime()}:00+08:00`;
}

// Every upcoming game's pick state for one viewer — the /picks "Open picks" cards, the
// homepage widget and the profile card all render this through openPickCard().
function openPicks(games, pctx, viewerId) {
  const upcoming = getUpcomingGames(games);
  if (!upcoming.length) return [];
  const ids = upcoming.map(g => g.id);
  const counts = getGamePickCounts(ids);
  const mine = getPlayerGamePicks(ids, viewerId);
  const playerMap = Object.fromEntries(getAllPlayers().map(p => [p.id, p]));
  const commentsOn = getSetting('comments_enabled', '0') === '1';
  const talkCounts = commentsOn ? getGameCommentCounts(ids) : {};
  const bySeason = {};
  const spOf = season => (bySeason[season] ??= seasonPicks(pctx, season));
  // MVP podium cross-link: how many of the locked ten play in this game, while the bonus is open.
  const cur = getPortalCurrentSeason();
  const podiumTen = cur && mvpPodiumEnabled() && isMvpLocked(cur) && mvpBallotState(cur, null).bonusOpen ? mvpLockLite(cur) : [];
  return upcoming.map(g => {
    const pg = pctx.byId[g.id] || toPickGame(g, gameYmd);
    const { closed, odds } = upcomingPickState(g, pctx);
    const myPick = mine[g.id] || null;
    const isFinalsG1 = pg.type === 'finals' && finalsGame1Id(pctx.all, pg.season) === g.id;
    const seasonPlayed = pctx.played.filter(x => x.season === pg.season);
    const recordOf = t => {
      const list = seasonPlayed.filter(x => x.a === t || x.b === t);
      const w = list.filter(x => (x.a === t) === (x.sa > x.sb)).length;
      return { w, l: list.length - w };
    };
    const meetings = pctx.played.filter(x => (x.a === pg.a && x.b === pg.b) || (x.a === pg.b && x.b === pg.a));
    const winsOf = t => meetings.filter(x => (x.sa > x.sb ? x.a : x.b) === t).length;
    return {
      id: g.id, a: g.team_a_name, b: g.team_b_name, ymd: pg.ymd, tip: gameTipLabel(g), season: pg.season, href: previewHref(g),
      mvpCases: String(pg.season) === String(cur) ? podiumTen.filter(p => [String(g.team_a_name).toUpperCase(), String(g.team_b_name).toUpperCase()].includes(p.team)).length : 0,
      counts: counts[g.id], myPick, closed, odds, closeHm: picksCloseTime(),
      closeAt: pickCloseAt(pg, pctx.settings[g.id]),
      // Finals Game 1 carries the margin-guess tiebreaker; the guess is only ever sent to its owner.
      // seed: the odds' projected margin, so the −/+ stepper starts near a sensible number.
      marginGuess: isFinalsG1 ? {
        mine: myPick ? (pctx.picks.find(p => p.game_id === g.id && p.player_id === viewerId)?.margin_guess ?? null) : null,
        seed: Math.max(1, Math.round(Math.abs(odds?.margin || 0))) || 5,
      } : null,
      faces: pickFacesFlat(g, viewerId),
      // After picking, a "Talk trash" button to the game's pre-game chatter (comments on).
      talk: commentsOn, talkCount: talkCounts[g.id] || 0,
      recA: recordOf(pg.a), recB: recordOf(pg.b),
      h2h: { a: winsOf(pg.a), b: winsOf(pg.b), meetings: meetings.length },
      // Stakes line + Remind me (logged in only; see pickStakes / pickRemindState).
      stakes: myPick || !closed ? pickStakes(spOf(pg.season), viewerId, odds) : null,
      // Sent even when you have a pick: the button stays in the card (hidden) so removing
      // your pick brings it back.
      remind: closed ? null : pickRemindState(pg.ymd, viewerId),
      // The 'full' card's tabs: Go-to scorers (duelScorers) and Form check, from the same
      // as-of-tip-off matchup.
      ...(() => {
        const m = matchupAsOf(g, games, playerMap);
        return { formCheck: formCheckOf(m), duel: duelScorers(g, m, games, playerMap) };
      })(),
    };
  });
}

// The viewer's last few settled picks, newest first (profile card, homepage widget).
function recentPickResults(pctx, season, viewerId, n = 3) {
  if (!viewerId) return [];
  const settled = new Map(seasonPicks(pctx, season).settled.map(g => [g.id, g]));
  return pctx.picks
    .filter(p => p.player_id === viewerId && settled.has(p.game_id))
    .map(p => ({ p, g: settled.get(p.game_id) }))
    .sort((x, y) => y.g.ymd.localeCompare(x.g.ymd) || String(y.g.id).localeCompare(String(x.g.id)))
    .slice(0, n)
    .map(({ p, g }) => ({
      id: g.id, ymd: g.ymd, a: g.a, b: g.b, sa: g.sa, sb: g.sb, side: p.side,
      ok: p.side === g.winner, upset: !!(g.odds?.fav && g.odds.fav !== g.winner),
    }));
}


// The two players in the pre-game duel (views/duel.js), for the pick card's face-off and the
// game page's Players to watch: each side's go-to scorer in this matchup, or — no meetings
// with box scores yet — the team's top scorer this season. m: matchupAsOf (or a frozen copy).
function duelScorers(game, m, games, playerMap) {
  return [[m.a, m.b], [m.b, m.a]].map(([team, opp], i) => (m.scorers?.[i] ? { ...m.scorers[i], basis: 'h2h' } : seasonTopScorer(game, team, opp, games, playerMap)));
}

// A player's points in each earlier meeting of these two teams, all seasons, oldest first —
// the recap duel's bars, with tonight added as the last one (views/game.js duelPerformer).
function meetingPoints(game, games, playerId) {
  const ymd = gameYmd(game.date);
  const pair = [game.team_a_name, game.team_b_name].sort().join('|');
  const earlier = games
    .filter(g => g.id !== game.id && isPlayedGame(g) && !g.under_review && gameYmd(g.date) < ymd && [g.team_a_name, g.team_b_name].sort().join('|') === pair)
    .sort((x, y) => gameYmd(x.date).localeCompare(gameYmd(y.date)));
  const series = [], dates = [];
  for (const g of earlier) {
    const s = getGameStats(g.id).find(x => x.player_id === playerId);
    if (s) { series.push(+s.pts || 0); dates.push(gameYmd(g.date)); }
  }
  return { series, dates };
}

// A team's highest points-per-game player this season, before this game (at least 2 games
// once there are 2+ box scores, same rule as the matchup's go-to scorer).
function seasonTopScorer(game, team, opp, games, playerMap) {
  const ymd = gameYmd(game.date);
  const list = games
    .filter(g => isPlayedGame(g) && String(g.season) === String(game.season) && gameYmd(g.date) < ymd && (g.team_a_name === team || g.team_b_name === team))
    .sort((x, y) => gameYmd(x.date).localeCompare(gameYmd(y.date)));
  const per = new Map();
  let boxCount = 0;
  for (const g of list) {
    const side = g.team_a_name === team ? 'a' : 'b';
    const rows = getGameStats(g.id).filter(s => s.team_id === g[`team_${side}_id`]);
    if (rows.length) boxCount++;
    for (const s of rows) {
      const p = per.get(s.player_id) || { id: s.player_id, games: [], pts: 0, reb: 0, ast: 0, fgm: 0, fga: 0 };
      const fgm = (+s.fg2m || 0) + (+s.fg3m || 0) + (+s.fg4m || 0);
      p.games.push({ pts: +s.pts || 0, ymd: gameYmd(g.date) });
      p.pts += +s.pts || 0; p.reb += +s.reb || 0; p.ast += +s.ast || 0;
      p.fgm += fgm; p.fga += fgm + (+s.fg2m_miss || 0) + (+s.fg3m_miss || 0) + (+s.fg4m_miss || 0);
      per.set(s.player_id, p);
    }
  }
  const minGames = Math.min(2, boxCount);
  const best = [...per.values()].filter(p => p.games.length >= minGames).sort((x, y) => y.pts / y.games.length - x.pts / x.games.length)[0];
  if (!best) return null;
  const player = playerMap[best.id];
  const n = best.games.length;
  const top = best.games.reduce((a, x) => (x.pts > a.pts ? x : a), best.games[0]);
  return {
    id: best.id, name: displayPlayerName(player?.name || ''), number: player?.number ?? '', team, opp, hasPhoto: !!player?.picture_url,
    ppg: Math.round((best.pts / n) * 10) / 10, rpg: Math.round((best.reb / n) * 10) / 10, apg: Math.round((best.ast / n) * 10) / 10,
    fg: best.fga ? Math.round((best.fgm / best.fga) * 1000) / 10 : null, games: n,
    series: best.games.map(x => x.pts), dates: best.games.map(x => x.ymd), best: { pts: top.pts, label: shortDay(top.ymd) }, basis: 'season',
  };
}

// Homepage "Who wins?" widget (views/picks-widget.js). Game day and the day after show the
// results ("Who called it?"); otherwise the next game day's picks; nothing when there's
// neither. Admin switch: Visibility → home_picks_widget_enabled (on by default).
function homePicksWidget(games, viewerId) {
  if (!picksEnabled() || getSetting('home_picks_widget_enabled', '1') === '0') return null;
  const pctx = buildPicksContext(games);
  const season = String(getPortalCurrentSeason());
  const sp = seasonPicks(pctx, season);
  const r = viewerId ? sp.records[viewerId] : null;
  const myRow = viewerId ? sp.board.rows.find(x => x.playerId === viewerId) : null;
  // Top 8 of each board for the race card (results mode shows 5, open mode 8 to fill the
  // column beside the pick cards); ranks shared on a tie show as "T1".
  const person = picksPerson(Object.fromEntries(getAllPlayers().map(p => [p.id, p])), Object.fromEntries(getAllTeams().map(t => [t.id, t.name])));
  const topOf = (rows, rankKey) => rows.slice(0, 8).map(x => ({
    ...x, ...person(x.playerId), tied: rows.filter(y => y[rankKey] === x[rankKey]).length > 1,
  }));
  const base = {
    isPlayer: !!viewerId, season, minPicks: sp.board.minPicks,
    me: r ? { ...r, ...person(viewerId), playerId: viewerId, rank: myRow?.rank || null, oddsRank: myRow?.oddsRank || null,
      tied: !!myRow && sp.board.rows.filter(y => y.rank === myRow.rank).length > 1,
      oddsTied: !!myRow && sp.board.oddsRows.filter(y => y.oddsRank === myRow.oddsRank).length > 1 } : null,
    boards: { pts: topOf(sp.board.rows, 'rank'), odds: pickOddsEnabled() ? topOf(sp.board.oddsRows, 'oddsRank') : null, size: sp.board.rows.length },
    recent: recentPickResults(pctx, season, viewerId, 6),
    leader: (() => {
      const top = sp.board.rows[0];
      if (!top) return null;
      return { name: displayPlayerName(getPlayerById(top.playerId)?.name || ''), net: top.net, correct: top.correct, wrong: top.wrong, picks: top.picks, tied: sp.board.rows.filter(r => r.rank === 1).length };
    })(),
  };
  const today = manilaTodayStr();
  const lastDay = sp.pickable.length ? sp.pickable[sp.pickable.length - 1].ymd : null;
  const results = () => {
    const cards = sp.pickable.filter(g => g.ymd === lastDay).map(g => {
      const gp = getGamePicksWithPlayers(g.id);
      const s = calledItSummary(g, gp, viewerId);
      s.calledIt = s.calledIt.map(p => ({ id: p.player_id, name: displayPlayerName(p.player_name || ''), team: p.team_name || '' }));
      // The card itself (views/pick-card.js pickResultCard); the summary fields feed the AI block.
      s.result = pickResultOf(g, gp, viewerId, pctx);
      return s;
    });
    return { ...base, mode: 'results', ymd: lastDay, cards };
  };
  if (lastDay && lastDay >= addDaysYmd(today, -1)) return results();
  const open = openPicks(games, pctx, viewerId);
  if (open.length) {
    return { ...base, mode: 'open', ymd: open[0].ymd, closeTime: picksCloseTime(), games: open };
  }
  if (lastDay && lastDay >= addDaysYmd(today, -6)) return results();
  return null;
}

// Everything the /games result card (views/games.js gameCard) shows beyond the game row:
// comment/reaction counts, the pre-game odds label and the top scorer. Shared so every place
// that shows game cards — /games, team pages, homepage headlines, game pages — shows the same
// card. Odds come from the lib/picks.js model over games dated before each one, so they also
// cover games from before picks existed (none for a season's opening week).
// statsByGame: optional { id: stats } already loaded by the caller.
function gameCardExtras(cardGames, allGames, { viewerId = null, playerMap = null, statsByGame = null } = {}) {
  const ids = cardGames.map(g => g.id);
  const commentsEnabled = getSetting('comments_enabled', '0') === '1';
  const socialByGame = {}, oddsByGame = {}, topScorerByGame = {};
  if (!ids.length) return { commentsEnabled, socialByGame, oddsByGame, topScorerByGame };
  if (commentsEnabled) {
    const commentCounts = getGameCommentCounts(ids), reactionCounts = getGameReactionCounts(ids);
    const reactedIds = getReactedGameIdsForPlayer(ids, viewerId);
    const latest = getLatestCommentsForGames(ids);
    for (const id of ids) socialByGame[id] = { commentsCount: commentCounts[id] || 0, reactCount: reactionCounts[id] || 0, reacted: reactedIds.has(id), latest: latest[id] || null };
  }
  if (pickOddsEnabled()) {
    const want = new Set(ids);
    const playedPick = allGames.map(g => toPickGame(g, gameYmd)).filter(g => g.played);
    for (const g of playedPick) {
      if (!want.has(g.id)) continue;
      const o = computeOdds(g, playedPick);
      if (o?.fav) oddsByGame[g.id] = { fav: o.fav, pct: o.fav === 'a' ? o.pctA : o.pctB, upset: o.fav !== (g.sa > g.sb ? 'a' : 'b') };
    }
  }
  const pm = playerMap || Object.fromEntries(getAllPlayers().map(p => [p.id, p]));
  const topOf = rows => rows.reduce((m, s) => ((+s.pts || 0) > (m ? +m.pts || 0 : -1) ? s : m), null);
  for (const g of cardGames) {
    const stats = statsByGame?.[g.id] || getGameStats(g.id);
    const top = topOf(stats);
    if (!top) continue;
    // No cover photo yet: the winning team's top scorer's profile photo stands in on the card
    // (the card falls back to its matchup art when there's no photo). Replaced by the cover
    // as soon as one is uploaded; nothing is stored.
    const winTeamId = Number(g.team_a_score) > Number(g.team_b_score) ? g.team_a_id : g.team_b_id;
    const winTop = g.has_cover ? null : topOf(stats.filter(s => s.team_id === winTeamId));
    topScorerByGame[g.id] = {
      name: displayPlayerName(pm[top.player_id]?.name || ''), pts: +top.pts || 0,
      standIn: winTop && pm[winTop.player_id]?.picture_url ? winTop.player_id : null,
    };
  }
  return { commentsEnabled, socialByGame, oddsByGame, topScorerByGame };
}

app.get('/games', (req, res) => {
  const players = getAllPlayers();
  const games = byDate(getAllGames());
  const playerMap = Object.fromEntries(players.map(p => [p.id, p]));
  const ctx = buildGamesContext(games, playerMap);
  const currentSeason = ctx.season;

  // Season filter: ?season=3, ?season=all; defaults to the current season.
  const seasons = [...new Set(ctx.played.map(g => String(g.season)).filter(Boolean))].sort((a, b) => Number(b) - Number(a));
  const qSeason = String(req.query.season || '');
  const season = qSeason === 'all' ? 'all' : (seasons.includes(qSeason) ? qSeason : (seasons.includes(String(currentSeason)) ? String(currentSeason) : (seasons[0] || 'all')));
  const listGames = games.filter(g => (g.status === 'final' || g.status === 'complete') && !g.under_review && (season === 'all' || String(g.season) === season));

  const { commentsEnabled, socialByGame, oddsByGame, topScorerByGame } = gameCardExtras(listGames, games, { viewerId: req.session?.playerPlayerId || null, playerMap });

  const upcoming = getUpcomingGames(games);
  const matchups = upcoming.map(g => matchupAsOf(g, games, playerMap));
  const stories = getMatchupStories(matchups);

  // "Who wins?" on the Up next cards: odds + closed state + faces. The full preview, the
  // "Who called it?" results and the Pickmaster race live on /picks.
  const viewerId = req.session?.playerPlayerId || null;
  let picks = null;
  if (picksEnabled()) {
    const pctx = buildPicksContext(games);
    // ymd + closeHm: the pick box footer's "closes Sun 6:00 AM"
    const closeHm = picksCloseTime();
    const pickStates = Object.fromEntries(upcoming.map(g => [g.id, { ...upcomingPickState(g, pctx), ymd: gameYmd(g.date), closeHm }]));
    picks = {
      states: pickStates,
      // The shared pick card's data, same as /picks and the homepage (openPicks).
      opens: Object.fromEntries(openPicks(games, pctx, viewerId).map(o => [o.id, o])),
    };
  }
  const previewHrefs = Object.fromEntries(upcoming.map(g => [g.id, previewHref(g)]));

  const potg = buildPotgMarquee(ctx.played, playerMap, 8);
  const seasonPlayed = season === 'all' ? ctx.played : ctx.played.filter(g => String(g.season) === season);
  const tiles = buildSeasonTiles(seasonPlayed, playerMap);

  // The homepage's "The story" summary (Game headlines block) doubles as this page's intro.
  const summary = getHomeSummaries(homeSummaryContext({
    season: currentSeason, games, standings: buildHomeStandings(currentSeason, games), boards: [],
  })).headlines || null;

  res.send(renderPage(req, {
    title: 'Games | WKND Basketball',
    currentPath: req.path,
    body: gamesPage({
      games: listGames, season, seasons, currentSeason, seasonPlayedCount: seasonPlayed.length,
      summary, isAdmin: !!req.session?.isAdmin, isPlayer: !!req.session?.playerPlayerId,
      tiles, potg, matchups, stories, picks, previewHrefs,
      recapDay: ctx.played.length ? gameYmd(ctx.played[0].date) : null,
      commentsEnabled, socialByGame, topScorerByGame, oddsByGame,
    }),
  }));
});

// "Who wins?" — one pick per logged-in player per game, only while the game is upcoming.
// The Finals Game 1 tiebreaker guess: "my side wins by N" (1–MARGIN_MAX), or null to clear.
// Needs an existing pick on that game, and picks still open.
// "Remind me" on a pick card: toggle tonight's-before-game-day reminder for that game day.
app.post('/picks/remind', express.json(), (req, res) => {
  const playerId = req.session?.playerPlayerId;
  if (!playerId) return res.status(401).json({ error: 'Log in first.' });
  if (!picksEnabled()) return res.status(404).json({ error: 'Picks are off right now.' });
  const ymd = String(req.body?.ymd || '');
  const games = byDate(getAllGames());
  if (!getUpcomingGames(games).some(g => gameYmd(g.date) === ymd)) return res.status(400).json({ error: 'No picks open for that day.' });
  if (Date.parse(pickRemindAt(ymd)) <= Date.now()) return res.status(400).json({ error: 'Too late for a reminder. Picks close soon.' });
  const list = pickRemindList(ymd);
  const on = req.body?.on !== false;
  if (on) list.add(playerId); else list.delete(playerId);
  setSetting(pickRemindKey(ymd), JSON.stringify([...list]));
  res.json({ ok: true, on, label: pickRemindState(ymd, playerId)?.label || '' });
});

// Send due "Remind me" reminders: from 7 PM the evening before game day until picks close,
// once per game day, to players who asked and still have an open game left to pick.
function runPickReminders() {
  if (!picksEnabled()) return;
  const games = byDate(getAllGames());
  const pctx = buildPicksContext(games);
  const open = openPicks(games, pctx, null).filter(o => !o.closed);
  const days = [...new Set(open.map(o => o.ymd))];
  for (const ymd of days) {
    if (Date.parse(pickRemindAt(ymd)) > Date.now() || getSetting(`pick_remind_sent_${ymd}`, '')) continue;
    const asked = [...pickRemindList(ymd)];
    setSetting(`pick_remind_sent_${ymd}`, String(Date.now()));
    if (!asked.length) continue;
    const dayGames = open.filter(o => o.ymd === ymd);
    const still = asked.filter(id => { const picks = getPlayerGamePicks(dayGames.map(o => o.id), id); return dayGames.some(o => !picks[o.id]); });
    if (!still.length) continue;
    const matchups = dayGames.map(o => `${titleCase(o.a)} vs ${titleCase(o.b)}`).join(' and ');
    const dayStr = new Date(`${ymd}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
    const reach = picksReminderRecipients(still.map(id => ({ id })), ymd);
    const bell = { title: `Your reminder: who wins? ${matchups}`, body: `You asked us to remind you. Picks close ${fmtCloseTime(picksCloseTime())} on ${dayStr}.`, link: '/picks' };
    // The players asked for this one, so it's a campaign outside the caps.
    const campaignId = startCampaign({ kind: 'pick_remind_me', ...bell, segment: `asked:${ymd}`, channels: reach.emailable.length ? 'bell+email' : 'bell', createdBy: 'auto' });
    for (const { player: p } of reach.recipients) {
      createNotification({ playerId: p.id, type: 'pick_reminder', ...bell, broadcastId: campaignId });
    }
    finishCampaign(campaignId, { bells: reach.recipients.length });
    if (reach.emailable.length) sendPicksEmails(reach.emailable, { campaignId, bells: reach.recipients.length }).catch(e => console.error('[pick reminders] email failed:', e.message));
    console.log(`[pick reminders] ${ymd}: ${reach.recipients.length} bell(s), ${reach.emailable.length} email(s)`);
  }
}
setInterval(() => { try { runPickReminders(); } catch (e) { console.error('[pick reminders] failed:', e.message); } }, 5 * 60 * 1000);

// ── Auto-nudges (admin redesign plan, step 2, 2026-10-15) ──────────────────────────────
// Automatic group sends through lib/broadcast.js (dedupe, caps of 1 group email a day and 3
// a week per player, 600 ms pacing, unsubscribe respected). Each one has a switch on its
// feature's admin page, on by default:
//   • picks_auto_remind        6 PM the day before game day: everyone still missing picks
//                              (skips anyone who asked for their own "Remind me", and runs
//                              only if no admin has already sent a reminder for that day)
//   • mvp_podium_auto_remind   once per season, when the podium ballot is locked and open
//   • posts_notify_on_publish  a bell when a post goes public (published, or scheduled and due)
//   • polls_notify_on_open     a bell when a poll for players opens
//   • season_auto_nudges       when season sign-ups open: everyone not signed up; 3 days later,
//                              last season's players who still haven't signed up
// Live site only (AUTO_NUDGES_IN_DEV=1 runs it elsewhere for testing, and lib/broadcast.js
// still sends just one email there), between 9 AM and 9 PM Manila.
const AUTO_PICK_REMIND_HM = '18:00';
const SEASON_RETURNING_AFTER_DAYS = 3;
let autoNudgesRunning = false;
const manilaYmdOf = ms => new Date(ms).toLocaleDateString('en-CA', { timeZone: 'Asia/Manila' });
const nudgeOn = key => getSetting(key, '1') === '1';

async function autoPickReminder() {
  if (!picksEnabled() || !nudgeOn('picks_auto_remind')) return;
  const games = byDate(getAllGames());
  const pctx = buildPicksContext(games);
  const upNext = adminUpNext(games, pctx);
  const open = upNext.filter(u => !u.closed);
  if (!open.length) return;
  const ymd = open[0].ymd;
  const dayBefore = manilaYmdOf(Date.parse(`${ymd}T00:00:00+08:00`) - 86400000);
  if (Date.now() < Date.parse(`${dayBefore}T${AUTO_PICK_REMIND_HM}:00+08:00`)) return;
  if (getSetting(`picks_reminded_${ymd}`, '')) return; // an admin already reminded this game day
  const dedupeKey = `auto_picks:${ymd}`;
  if (getBroadcastByDedupe(dedupeKey)) return;
  const missing = picksMissing(upNext, pctx);
  if (!missing?.list.length) return;
  const asked = pickRemindList(ymd);
  const reach = picksReminderRecipients(missing.list.filter(p => !asked.has(p.id)), ymd);
  if (!reach.recipients.length) return;
  const matchups = open.filter(u => u.ymd === ymd).map(u => `${titleCase(u.a)} vs ${titleCase(u.b)}`).join(' and ');
  const dayStr = new Date(`${ymd}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const c = picksEmailContext();
  const draft = c ? await ensurePicksDraft(c) : null;
  const emailed = picksEmailedIds(ymd);
  const result = await sendBroadcast({
    kind: 'pick_reminder', dedupeKey, segment: `not_picked:${ymd}`,
    title: `Who wins? ${matchups}`, body: `Make your pick${open.length === 1 ? '' : 's'} before ${fmtCloseTime(picksCloseTime())} on ${dayStr}.`, link: '/picks',
    recipients: reach.recipients,
    email: c && draft ? async r => {
      emailed.add(r.player.id);
      return { ...picksEmailFor(c, draft, r.player.id, r.reg.id), headers: unsubscribeHeaders(picksUnsubscribeUrl(r.reg.id)) };
    } : null,
  });
  setSetting(`picks_emailed_ids_${ymd}`, JSON.stringify([...emailed]));
  setSetting(`picks_reminded_${ymd}`, JSON.stringify({ at: Date.now(), count: result.bell, email: result.email, auto: true }));
  console.log(`[auto-nudges] pick reminder ${ymd}: ${result.bell} bell(s), ${result.email} email(s), ${result.capped || 0} over the email cap`);
}

async function autoPodiumNudge() {
  if (!nudgeOn('mvp_podium_auto_remind')) return;
  const season = getPortalCurrentSeason();
  const st = mvpBallotState(season, null);
  if (!st.enabled || !isMvpLocked(season) || st.closed) return;
  if (getSetting(`mvp_podium_reminded_${season}`, '')) return; // already reminded (by hand or before)
  const dedupeKey = `auto_podium:${season}`;
  if (getBroadcastByDedupe(dedupeKey)) return;
  const missing = mvpPodiumMissing(season);
  if (!missing.length) return;
  const faces = shuffled(mvpLockLite(season)).map(p => ({ name: displayPlayerName(p.name), color: teamColor(p.team) }));
  const url = `${(process.env.LIVE_URL || 'https://wkndbasketball.com').replace(/\/$/, '')}/mvp#ballot`;
  const result = await sendBroadcast({
    kind: 'mvp_podium_reminder', dedupeKey, segment: `no_ballot:${season}`,
    title: 'Call the MVP podium: up to +3 Pickmaster points', body: st.bonusOpen && st.bonusAt ? `Bonus closes ${st.bonusAt}` : 'Pick who finishes 1st, 2nd and 3rd', link: '/mvp#ballot',
    recipients: missing,
    email: async r => ({ ...podiumReminderEmail({ name: r.player.name, faces, closeLabel: st.bonusOpen ? st.bonusAt : '', url, unsubscribeUrl: picksUnsubscribeUrl(r.reg.id) }), headers: unsubscribeHeaders(picksUnsubscribeUrl(r.reg.id)) }),
  });
  setSetting(`mvp_podium_reminded_${season}`, JSON.stringify({ at: Date.now(), bell: result.bell, email: result.email, auto: true }));
  console.log(`[auto-nudges] podium ${season}: ${result.bell} bell(s), ${result.email} email(s)`);
}

// Posts and polls already public when this first ran are remembered, not announced.
function publishSeen() { try { return new Set(JSON.parse(getSetting('auto_publish_seen', '[]') || '[]')); } catch { return new Set(); } }
async function autoPublishNotices() {
  const seen = publishSeen();
  const posts = getSetting('posts_enabled', '0') === '1' ? getPublicPosts() : [];
  const polls = getAllLeaguePolls().filter(p => p.status === 'open' && p.visibility === 'players');
  const fresh = [...posts.map(p => ({ key: `post:${p.id}`, p, type: 'post' })), ...polls.map(p => ({ key: `poll:${p.id}`, p, type: 'poll' }))].filter(x => !seen.has(x.key));
  if (!fresh.length) return;
  for (const x of fresh) {
    seen.add(x.key);
    setSetting('auto_publish_seen', JSON.stringify([...seen]));
    if (x.type === 'post' && !nudgeOn('posts_notify_on_publish')) continue;
    if (x.type === 'poll' && !nudgeOn('polls_notify_on_open')) continue;
    const { recipients } = selectBroadcastRecipients();
    const result = x.type === 'post'
      ? await sendBroadcast({ kind: 'post_published', dedupeKey: x.key, segment: 'active_players', title: `New on WKND: ${x.p.title}`, body: 'Tap to read it.', link: `/posts/${x.p.slug}`, recipients })
      : await sendBroadcast({ kind: 'poll_opened', dedupeKey: x.key, segment: 'active_players', title: `New poll: ${x.p.question}`, body: 'Cast your vote.', link: '/polls', recipients });
    console.log(`[auto-nudges] ${x.key}: ${result.bell} bell(s)`);
  }
}

async function autoSeasonNudges() {
  if (!nudgeOn('season_auto_nudges') || getSetting('season_signup_open', '0') !== '1') return;
  const sig = getSetting('signup_target_season', '');
  if (!sig) return;
  const openedKey = `season_signup_opened_at_${sig}`;
  let openedAt = Number(getSetting(openedKey, '0'));
  if (!openedAt) { openedAt = Date.now(); setSetting(openedKey, String(openedAt)); }
  const signedUp = new Set(getSeasonSignups(sig).map(s => s.player_id).filter(Boolean));
  const deadline = getSetting('season_signup_deadline', '').trim();
  const signupUrl = `${(process.env.LIVE_URL || 'https://wkndbasketball.com').replace(/\/$/, '')}/season-signup`;
  const emailFor = (heading, lines, subject) => async r => ({
    ...leagueNudgeEmail({ name: r.player.name, subject, heading, lines, cta: 'Sign up', url: signupUrl, unsubscribeUrl: leagueUnsubscribeUrl(r.reg.id), label: `Season ${sig}` }),
    headers: unsubscribeHeaders(leagueUnsubscribeUrl(r.reg.id)),
  });
  // 1. Sign-ups are open: every active member who hasn't signed up.
  const openKey = `season_open:${sig}`;
  if (!getBroadcastByDedupe(openKey) && !getSetting(`season_open_nudged_${sig}`, '')) {
    const { recipients } = selectBroadcastRecipients(undefined, { optOutColumn: 'league_email_optout', exclude: id => signedUp.has(id) });
    setSetting(`season_open_nudged_${sig}`, String(Date.now()));
    if (recipients.length) {
      const result = await sendBroadcast({
        kind: 'season_signup_open', dedupeKey: openKey, segment: `not_signed_up:${sig}`,
        title: `Season ${sig} sign-ups are open`, body: deadline ? `Sign up by ${deadline}.` : 'Sign up to play this season.', link: '/season-signup', recipients,
        email: emailFor('Season {name}, sign-ups are open', [`Season ${sig} of WKND Basketball is taking sign-ups now.`, deadline ? `Sign up by ${deadline} to be considered for a team.` : 'Sign up early to be considered for a team.'], `WKND Season ${sig}: sign-ups are open`),
      });
      console.log(`[auto-nudges] season ${sig} open: ${result.bell} bell(s), ${result.email} email(s)`);
    }
    return; // the follow-up waits for a later run
  }
  // 2. A few days later: last season's players who still haven't signed up.
  const retKey = `season_returning:${sig}`;
  if (Date.now() - openedAt < SEASON_RETURNING_AFTER_DAYS * 86400000 || getBroadcastByDedupe(retKey) || getSetting(`season_returning_nudged_${sig}`, '')) return;
  const prev = getCurrentSeason()?.season;
  const prevIds = prev ? getSeasonPlayerStats(prev).map(p => p.id).filter(id => id && !signedUp.has(id)) : [];
  setSetting(`season_returning_nudged_${sig}`, String(Date.now()));
  if (!prevIds.length) return;
  const { recipients } = selectBroadcastRecipients(prevIds, { optOutColumn: 'league_email_optout' });
  if (!recipients.length) return;
  const result = await sendBroadcast({
    kind: 'season_returning', dedupeKey: retKey, segment: `returning_not_signed_up:${sig}`,
    title: `Your Season ${sig} spot is waiting`, body: deadline ? `You played last season. Sign up by ${deadline} to keep your spot in the mix.` : 'You played last season. Sign up to be in the mix again.', link: '/season-signup', recipients,
    email: emailFor('{name}, we want you back', [`You played Season ${prev}. Season ${sig} sign-ups are open and we haven’t seen yours yet.`, deadline ? `Sign up by ${deadline}.` : 'It takes a couple of minutes.'], `WKND Season ${sig}: we haven’t seen your sign-up`),
  });
  console.log(`[auto-nudges] season ${sig} returning: ${result.bell} bell(s), ${result.email} email(s)`);
}

// The very first run remembers what's already out (public posts, open polls, a season whose
// sign-ups are already open) so deploying this doesn't announce old news.
function seedAutoNudges() {
  if (getSetting('auto_nudges_seeded', '')) return;
  const seen = publishSeen();
  for (const p of getPublicPosts()) seen.add(`post:${p.id}`);
  for (const p of getAllLeaguePolls()) seen.add(`poll:${p.id}`);
  setSetting('auto_publish_seen', JSON.stringify([...seen]));
  const sig = getSetting('signup_target_season', '');
  if (sig && getSetting('season_signup_open', '0') === '1') {
    setSetting(`season_open_nudged_${sig}`, 'seeded');
    setSetting(`season_returning_nudged_${sig}`, 'seeded');
  }
  setSetting('auto_nudges_seeded', String(Date.now()));
}

async function runAutoNudges() {
  if (IS_DEV && process.env.AUTO_NUDGES_IN_DEV !== '1') return;
  const h = manilaHourNow();
  if (h < 9 || h >= 21 || autoNudgesRunning) return;
  autoNudgesRunning = true;
  try {
    seedAutoNudges();
    for (const [name, fn] of [['picks', autoPickReminder], ['podium', autoPodiumNudge], ['publish', autoPublishNotices], ['season', autoSeasonNudges]]) {
      try { await fn(); } catch (e) { console.error(`[auto-nudges] ${name} failed:`, e.message); }
    }
  } finally {
    autoNudgesRunning = false;
  }
}
setTimeout(() => { runAutoNudges(); }, 90 * 1000);
setInterval(() => { runAutoNudges(); }, 5 * 60 * 1000);

// ── Message players (/admin/reach) ───────────────────────────────────────────────────────
// The composer and the Sent log (views/admin/reach.js). Segments are worked out here, and
// every send goes through sendBroadcast (caps, unsubscribes, broadcasts row) like the
// automatic nudges. Pick-related segments respect the picks email opt-out; the rest the
// league one.
const REACH_LINKS = [
  { value: '/picks', label: 'Who wins? picks (/picks)', cta: 'Make your picks' },
  { value: '/papawis', label: 'Papawis (/papawis)', cta: 'See the run' },
  { value: '/mvp', label: 'MVP race (/mvp)', cta: 'See the race' },
  { value: '/season-signup', label: 'Season sign-up', cta: 'Sign up' },
  { value: '/games', label: 'Games (/games)', cta: 'See the games' },
  { value: '/', label: 'Homepage', cta: 'Open WKND' },
  { value: '__other__', label: 'Other link…', cta: 'Open' },
];

function reachSegments({ team = '', ids = [] } = {}) {
  const active = getActivePlayers();
  const activeIds = active.map(p => p.id);
  const segs = [{ key: 'all', label: 'All active members', help: 'Logged in within 90 days', pool: activeIds }];

  let notPicked = null, dayStr = '';
  if (picksEnabled()) {
    const games = byDate(getAllGames());
    const pctx = buildPicksContext(games);
    const upNext = adminUpNext(games, pctx);
    const open = upNext.filter(u => !u.closed);
    if (open.length) {
      dayStr = new Date(`${open[0].ymd}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      notPicked = picksMissing(upNext, pctx)?.list.map(p => p.id) || [];
    }
  }
  segs.push(notPicked
    ? { key: 'notpicked', label: `Haven’t picked (${dayStr})`, help: 'Still missing a pick', pool: notPicked, optOut: 'picks_email_optout' }
    : { key: 'notpicked', label: 'Haven’t picked', help: 'No picks open right now', disabled: true });

  const season = getPortalCurrentSeason();
  const st = mvpBallotState(season, null);
  if (st.enabled && isMvpLocked(season) && !st.closed) {
    const voted = new Set(listMvpBallots(season).filter(b => b.p1 && b.p2 && b.p3).map(b => b.player_id));
    segs.push({ key: 'podium', label: 'No podium ballot', help: 'While the ballot is open', pool: activeIds.filter(id => !voted.has(id)), optOut: 'picks_email_optout' });
  } else segs.push({ key: 'podium', label: 'No podium ballot', help: 'The ballot isn’t open', disabled: true });

  segs.push({ key: 'regulars', label: 'Papawis regulars', help: `Played ${REGULAR_MIN_GAMES} of the last ${REGULAR_WINDOW} runs`, pool: getFrequentPapawisPlayers(REGULAR_WINDOW, REGULAR_MIN_GAMES).map(r => r.player_id) });

  const teamName = getAllTeams().find(t => t.id === team)?.name || '';
  segs.push({ key: 'team', label: 'One team', help: teamName ? `${teamName}, current roster` : 'Pick the team below', pool: team ? active.filter(p => p.team_id === team).map(p => p.id) : [], segLabel: teamName ? `Team ${teamName}` : 'One team' });

  const sig = getSetting('signup_target_season', '');
  if (sig && getSetting('season_signup_open', '0') === '1') {
    const signedUp = new Set(getSeasonSignups(sig).map(s => s.player_id).filter(Boolean));
    segs.push({ key: 'signup', label: `Not signed up for Season ${sig}`, help: 'Sign-ups are open', pool: activeIds.filter(id => !signedUp.has(id)) });
  } else segs.push({ key: 'signup', label: 'Not signed up', help: 'Season sign-ups are closed', disabled: true });

  segs.push({ key: 'slipping', label: 'Slipping away', help: 'Regulars not seen for 21+ days', pool: getQuietRegulars({ quietDays: 21, limit: 200 }).map(r => r.player_id) });

  const known = new Set(active.map(p => p.id));
  segs.push({ key: 'pick', label: 'Choose players', help: 'Pick names one by one', pool: ids.filter(id => known.has(id)), segLabel: `${ids.length} chosen player${ids.length === 1 ? '' : 's'}` });
  return segs;
}

// Who a segment reaches: the shared gates, then the email caps.
function reachCounts(s) {
  if (!s || s.disabled) return { bell: 0, email: 0, bellOnly: 0, capped: 0, skipped: 0, recipients: [] };
  const { recipients, skipped } = selectBroadcastRecipients(s.pool, { optOutColumn: s.optOut || 'league_email_optout' });
  const emailable = recipients.filter(r => r.emailable);
  const under = emailable.filter(r => underEmailCaps(r.email));
  const skippedTotal = skipped.noValidEmail + skipped.inactive + skipped.notApproved + skipped.linkExpired + skipped.dormant + skipped.excluded;
  return { bell: recipients.length, email: under.length, bellOnly: recipients.length - emailable.length, capped: emailable.length - under.length, skipped: skippedTotal, recipients };
}

function reachParams(src) {
  const ids = (Array.isArray(src.ids) ? src.ids : String(src.ids || '').split(',')).map(s => String(s).trim()).filter(Boolean);
  // Bell only unless Bell + email is chosen.
  return { seg: String(src.seg || 'all'), team: String(src.team || ''), ids, ch: src.ch === 'both' ? 'both' : 'bell' };
}

const REACH_KIND_LABELS = {
  admin_message: 'Message', pick_reminder: 'Pick reminder', pick_remind_me: 'Picks: asked to be reminded',
  mvp_podium_reminder: 'Podium reminder', mvp_podium_resend: 'Podium reminder, resend', season_results: 'Season results',
  papawis_announce: 'Papawis announcement', papawis_slot: 'Papawis slot alert', post_published: 'Post published',
  poll_opened: 'Poll opened', season_signup_open: 'Season sign-ups open', season_returning: 'Season: last season’s players',
  quiet_nudge: 'Slipping-away nudge',
};
function reachSegLabel(seg) {
  const [k, v] = String(seg || '').split(':');
  const day = v && /^\d{4}-\d{2}-\d{2}$/.test(v) ? new Date(`${v}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : v;
  return ({
    not_picked: `Haven’t picked (${day})`, asked: `Asked to be reminded (${day})`, no_ballot: 'No podium ballot',
    active_players: 'All active', not_signed_up: `Not signed up (Season ${v})`, returning_not_signed_up: `Last season, not signed up (Season ${v})`,
    season: `Season ${v} players`, slipping: 'Slipping away',
  })[k] || seg || '—';
}

app.get('/admin/reach', requireAuth, (req, res) => {
  const p = reachParams(req.query);
  const teams = getAllTeams().filter(t => getActivePlayers().some(pl => pl.team_id === t.id)).map(t => ({ id: t.id, name: t.name, color: t.color || teamColor(t.name) }));
  const team = p.team || teams[0]?.id || '';
  const segs = reachSegments({ team, ids: p.ids });
  const seg = segs.find(s => s.key === p.seg && !s.disabled) ? p.seg : 'all';
  const colors = adminTeamColorByPlayer();
  const pickOptions = getActivePlayers().map(pl => ({ id: pl.id, name: displayPlayerName(pl.name), color: colors[pl.id] || '' }));
  const myReg = req.session?.playerRegId ? getRegistration(req.session.playerRegId) : null;
  res.send(renderAdminPage(req, {
    title: 'Message players',
    body: adminReachComposeBody({
      segments: segs.map(s => ({ key: s.key, label: s.label, help: s.help, disabled: !!s.disabled, n: s.disabled ? 0 : reachCounts(s).bell })),
      seg, teams, team, pickOptions, picked: p.ids, ch: p.ch,
      counts: reachCounts(segs.find(s => s.key === seg)), links: REACH_LINKS,
      sentCount: getRecentBroadcasts(500).length, isDev: IS_DEV, myEmail: myReg?.email || ADMIN_NOTIFY_EMAIL,
    }),
  }));
});

app.get('/admin/reach/count', requireAuth, (req, res) => {
  const p = reachParams(req.query);
  const s = reachSegments({ team: p.team, ids: p.ids }).find(x => x.key === p.seg);
  const { recipients, ...counts } = reachCounts(s);
  res.json({ ...counts, label: s?.segLabel || s?.label || '' });
});

// The link a send points at: a page on this site (path) or a full URL on it.
function reachLink(body) {
  let link = String(body.link || '/');
  if (link === '__other__') {
    const raw = String(body.link_other || '').trim();
    const live = (process.env.LIVE_URL || 'https://wkndbasketball.com').replace(/\/$/, '');
    link = raw.startsWith(live) ? raw.slice(live.length) || '/' : raw;
  }
  // A path on this site only: no "//" (protocol-relative) and no backslash, which browsers
  // read as "/" (so "/\evil.example" would leave the site).
  if (!/^\/[^\s\\]*$/.test(link) || link.includes('//')) return null;
  return link;
}

function reachMessage(body) {
  const title = String(body.title || '').trim().slice(0, 90);
  const text = String(body.body || '').trim().slice(0, 400);
  const link = reachLink(body);
  const cta = String(body.cta || '').trim().slice(0, 40) || 'Open WKND';
  if (!title) return { error: 'Add a headline first.' };
  if (!link) return { error: 'That link isn’t a page on the site. Use a path like /games.' };
  return { title, text, link, cta, firstLine: text.split('\n')[0] || '' };
}

function reachEmail(m, r, optOut) {
  const live = (process.env.LIVE_URL || 'https://wkndbasketball.com').replace(/\/$/, '');
  const unsub = optOut === 'picks_email_optout' ? picksUnsubscribeUrl(r.reg.id) : leagueUnsubscribeUrl(r.reg.id);
  return {
    ...leagueNudgeEmail({ name: r.player.name, subject: m.title, heading: m.title, lines: m.text.split(/\n+/).filter(Boolean), cta: m.cta, url: `${live}${m.link}`, unsubscribeUrl: unsub, label: 'League update' }),
    headers: unsubscribeHeaders(unsub),
  };
}

app.post('/admin/reach/send', requireAuth, express.json(), (req, res) => {
  const m = reachMessage(req.body || {});
  if (m.error) return res.status(400).json({ error: m.error });
  const p = reachParams(req.body || {});
  const s = reachSegments({ team: p.team, ids: p.ids }).find(x => x.key === p.seg);
  if (!s || s.disabled) return res.status(400).json({ error: 'That group isn’t available right now.' });
  const { recipients } = reachCounts(s);
  if (!recipients.length) return res.status(400).json({ error: 'Nobody in that group can be reached.' });
  // A double-click (or a resend of the same message to the same group) within 10 minutes is ignored.
  const dedupeKey = `manual:${createHash('sha1').update(JSON.stringify([m.title, m.text, m.link, p.seg, p.team, [...p.ids].sort(), p.ch])).digest('hex').slice(0, 16)}:${Math.floor(Date.now() / 600000)}`;
  if (getBroadcastByDedupe(dedupeKey)) return res.status(409).json({ error: 'That exact message just went to this group.' });
  const optOut = s.optOut || 'league_email_optout';
  const withEmail = p.ch === 'both';
  const emails = withEmail ? recipients.filter(r => r.emailable && underEmailCaps(r.email)).length : 0;
  // Outside the live site sendBroadcast sends one email at most (to the admin inbox).
  const emailsOut = IS_DEV ? Math.min(emails, 1) : emails;
  // Bells are written straight away; emails go out 0.6 s apart in the background.
  sendBroadcast({
    kind: 'admin_message', dedupeKey, segment: s.segLabel || s.label, createdBy: req.session?.playerName || 'Admin',
    title: m.title, body: m.firstLine, link: m.link, recipients,
    email: withEmail ? async r => reachEmail(m, r, optOut) : null,
  }).then(r => console.log(`[reach] "${m.title}": ${r.bell} bell(s), ${r.email} email(s), ${r.capped || 0} capped, ${r.failed || 0} failed`))
    .catch(e => console.error(`[reach] send failed: ${e.message}`));
  const n = recipients.length;
  res.json({ ok: true, message: withEmail && emailsOut ? `Sent ${n} bell${n === 1 ? '' : 's'}. ${emailsOut} email${emailsOut === 1 ? '' : 's'} going out over the next ${Math.max(1, Math.ceil(emailsOut * 0.6 / 60))} min.` : `Sent ${n} bell${n === 1 ? '' : 's'}.` });
});

app.post('/admin/reach/test', requireAuth, express.json(), async (req, res) => {
  const m = reachMessage(req.body || {});
  if (m.error) return res.status(400).json({ error: m.error });
  const myReg = req.session?.playerRegId ? getRegistration(req.session.playerRegId) : null;
  const to = myReg?.email || ADMIN_NOTIFY_EMAIL;
  if (myReg?.player_id) createNotification({ playerId: myReg.player_id, type: 'admin_message', title: `[Test] ${m.title}`, body: m.firstLine, link: m.link });
  const fake = { player: { name: myReg?.full_name || 'Admin' }, reg: { id: myReg?.id || 'test' } };
  const ok = req.body?.ch === 'bell' ? true : await sendMail({ to, ...reachEmail(m, fake, 'league_email_optout'), subject: `[Test] ${m.title}` });
  if (!ok) return res.status(500).json({ error: 'The test email didn’t go out.' });
  res.json({ ok: true, message: req.body?.ch === 'bell' ? (myReg?.player_id ? 'Test bell sent to you.' : 'No player account to ring; nothing sent.') : `Test sent to ${to}${myReg?.player_id ? ', bell too' : ''}.` });
});

app.get('/admin/reach/sent', requireAuth, (req, res) => {
  const list = getRecentBroadcasts(500);
  const stats = getBroadcastStats();
  const rows = list.map(b => {
    const st = stats[b.id] || {};
    return {
      id: b.id, title: b.title || '', kindLabel: REACH_KIND_LABELS[b.kind] || b.kind, segLabel: reachSegLabel(b.segment),
      by: b.created_by === 'auto' ? 'Automatic' : (!b.created_by || b.created_by.toLowerCase() === 'admin' ? 'Admin' : b.created_by), auto: b.created_by === 'auto',
      bell: st.bells ?? b.bell_count ?? 0, taps: st.taps || 0,
      email: st.sent ?? b.email_count ?? 0, opened: st.opened || 0, clicked: st.clicked || 0,
      created_at: b.created_at,
      whenLabel: new Date(b.created_at).toLocaleString('en-US', { timeZone: 'Asia/Manila', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }),
    };
  });
  res.send(renderAdminPage(req, { title: 'Sent log', body: adminReachSentBody({ rows, query: req.query, sentCount: list.length }) }));
});

// League-emails unsubscribe (season nudges and other league news). GET asks first, so link
// scanners can't unsubscribe anyone; POST does it, for the button and one-click unsubscribe.
function leagueUnsubPage(req, { title, bodyHtml }) {
  return renderPage(req, { title, currentPath: '/', body: `<div class="container"><div class="page-content"><div class="card card--lg papawis-unsub">${bodyHtml}</div></div></div>` });
}
app.get('/emails/unsubscribe', (req, res) => {
  const regId = String(req.query.r || ''), token = String(req.query.t || '');
  if (!verifyLeagueUnsubscribe(regId, token)) {
    return res.status(400).send(leagueUnsubPage(req, { title: 'Link expired', bodyHtml: '<h1 class="papawis-unsub__title">This unsubscribe link isn\'t valid</h1><p class="papawis-unsub__text">Message a league admin and we\'ll take you off the list.</p>' }));
  }
  res.send(leagueUnsubPage(req, {
    title: 'Unsubscribe',
    bodyHtml: `<h1 class="papawis-unsub__title">Stop league update emails?</h1>
      <p class="papawis-unsub__text">You won't get emails about season sign-ups and other league news. Picks and Papawis emails have their own unsubscribe links, and bell notifications on the site keep working.</p>
      <form method="post" action="/emails/unsubscribe?r=${encodeURIComponent(regId)}&amp;t=${encodeURIComponent(token)}">
        <button type="submit" class="pw-btn pw-btn--primary">Unsubscribe</button>
      </form>`,
  }));
});
app.post('/emails/unsubscribe', express.urlencoded({ extended: false }), (req, res) => {
  const regId = String(req.query.r || ''), token = String(req.query.t || '');
  if (!verifyLeagueUnsubscribe(regId, token)) return res.status(400).send('Invalid link');
  setLeagueEmailOptout(regId, true);
  res.send(leagueUnsubPage(req, { title: 'Unsubscribed', bodyHtml: '<h1 class="papawis-unsub__title">You\'re unsubscribed</h1><p class="papawis-unsub__text">No more league update emails. You can still find everything on the site.</p>' }));
});

app.post('/games/:id/pick/margin', express.json(), (req, res) => {
  const playerId = req.session?.playerPlayerId;
  if (!playerId) return res.status(401).json({ error: 'Log in to pick.' });
  const game = getGameById(req.params.id);
  if (!picksEnabled()) return res.status(404).json({ error: 'Picks are off right now.' });
  if (!game || !getUpcomingGames([game]).length) return res.status(400).json({ error: 'Picks are closed for this game.' });
  const pctx = buildPicksContext(getAllGames());
  if (upcomingPickState(game, pctx).closed) return res.status(400).json({ error: 'Picks are closed for this game.' });
  if (finalsGame1Id(pctx.all, String(game.season)) !== game.id) return res.status(400).json({ error: 'The margin guess is only on Finals Game 1.' });
  const raw = req.body?.margin;
  const margin = raw === null || raw === '' ? null : Number(raw);
  if (margin !== null && !(Number.isInteger(margin) && margin >= 1 && margin <= MARGIN_MAX)) {
    return res.status(400).json({ error: `Enter a whole number from 1 to ${MARGIN_MAX}.` });
  }
  if (!setGamePickMargin(game.id, playerId, margin)) return res.status(400).json({ error: 'Pick a side first.' });
  res.json({ ok: true, margin });
});

app.post('/games/:id/pick', express.json(), (req, res) => {
  const playerId = req.session?.playerPlayerId;
  if (!playerId) return res.status(401).json({ error: 'Log in to pick.' });
  const game = getGameById(req.params.id);
  if (!picksEnabled()) return res.status(404).json({ error: 'Picks are off right now.' });
  if (!game || !getUpcomingGames([game]).length) return res.status(400).json({ error: 'Picks are closed for this game.' });
  if (upcomingPickState(game, buildPicksContext([game])).closed) return res.status(400).json({ error: 'Picks are closed for this game.' });
  const side = req.body?.side === 'a' || req.body?.side === 'b' ? req.body.side : null;
  setGamePick(game.id, playerId, side);
  // Faces come back after a cancel too: the list and the row, drawn by the page's own helper.
  const faces = pickFacesFlat(game, playerId);
  res.json({ ok: true, side, counts: getGamePickCounts([game.id])[game.id], faces, facesHtml: pickFacesRow({ faces, closed: false }, true) });
});

// ── /picks: full Pickmaster race, game-day history, upsets, per-player pick history ─────
// Seasons offered = any season with a pick on one of its games, plus the current one.
function picksSeasons(pctx) {
  const pickedIds = new Set(pctx.picks.map(p => p.game_id));
  const seasons = new Set(pctx.all.filter(g => pickedIds.has(g.id)).map(g => g.season));
  seasons.add(String(getPortalCurrentSeason()));
  return [...seasons].filter(Boolean).sort((a, b) => Number(b) - Number(a));
}

function picksPerson(playerMap, teamNames) {
  return id => ({ id, name: displayPlayerName(playerMap[id]?.name || ''), team: teamNames[playerMap[id]?.team_id] || '' });
}

app.get('/picks', (req, res) => {
  if (!picksEnabled()) return res.status(404).send(renderPage(req, { title: 'Not Found', currentPath: '/picks', body: '<div class="container"><p style="padding:40px;color:var(--text-muted)">Page not found.</p></div>' }));
  const pctx = buildPicksContext(byDate(getAllGames()));
  const seasons = picksSeasons(pctx);
  const season = seasons.includes(String(req.query.season)) ? String(req.query.season) : String(getPortalCurrentSeason());
  const viewerId = req.session?.playerPlayerId || null;
  const pd = buildPicksPageData(season, viewerId, pctx);
  const isCurrent = season === String(getPortalCurrentSeason());
  const games = byDate(getAllGames());
  const open = isCurrent ? openPicks(games, pctx, viewerId) : [];
  // Open picks carry the homepage's "Who wins?" writeup — the same stored copy, written for
  // logged-out readers. Only while the homepage is previewing picks (not showing results).
  const openW = open.length ? homePicksWidget(games, null) : null;
  const openSummary = openW?.mode === 'open' ? homeSummaryBlock('picks', { picksW: openW }) : null;

  res.send(renderPage(req, {
    title: `Who wins? picks · Season ${season} — WKND Basketball`,
    currentPath: '/picks',
    body: picksPage({
      ...pd, seasons,
      isPlayer: !!viewerId, viewerId,
      // This week's games, current season only — /picks is where you pick.
      open, openSummary,
      closeTime: picksCloseTime(),
      isAdmin: !!req.session?.isAdmin,
      podium: picksPodiumStrip(season, viewerId),
      // The facts never use the viewer's own pick, so the copy is the same for everyone.
      sections: sectionSummaries(picksSectionFacts(pd), { keep: season !== String(getPortalCurrentSeason()) }),
    }),
  }));
});

// /picks for one season: game days (newest first, both games of a day together), both
// boards, caller records, upsets, picker count. viewerId only marks the viewer's own pick.
function buildPicksPageData(season, viewerId = null, pctx = buildPicksContext(byDate(getAllGames()))) {
  season = String(season);
  const sp = seasonPicks(pctx, season);
  const playerMap = Object.fromEntries(getAllPlayers().map(p => [p.id, p]));
  const person = picksPerson(playerMap, Object.fromEntries(getAllTeams().map(t => [t.id, t.name])));
  const summaries = [...sp.pickable].reverse().map(g => {
    const gp = getGamePicksWithPlayers(g.id);
    const s = calledItSummary(g, gp, viewerId);
    s.calledIt = s.calledIt.map(p => person(p.player_id));
    // The game day's result card (views/pick-card.js pickResultCard).
    s.result = pickResultOf(g, gp, viewerId, pctx);
    return s;
  });
  const days = [];
  for (const s of summaries) {
    const last = days[days.length - 1];
    if (last && last.ymd === s.game.ymd) last.games.push(s);
    else days.push({ ymd: s.game.ymd, games: [s] });
  }
  const seasonGameIds = new Set(pctx.all.filter(g => g.season === season).map(g => g.id));
  return {
    season, days,
    pickers: new Set(pctx.picks.filter(p => seasonGameIds.has(p.game_id)).map(p => p.player_id)).size,
    board: sp.board.rows.map(r => ({ ...r, ...person(r.playerId) })),
    oddsBoard: sp.board.oddsRows.map(r => ({ ...r, ...person(r.playerId) })),
    callers: sp.callers,
    upsets: summaries.filter(s => s.upset),
    oddsOn: pickOddsEnabled(),
  };
}

// One player's picks for a season. ?partial=1 returns just the sheet (opened in a dialog on
// /picks); otherwise a full page, so the link works without JS and can be shared. Picks on
// games not played yet stay private to the player themselves.
app.get('/picks/players/:id', (req, res) => {
  if (!picksEnabled()) return res.status(404).send('Not found');
  const player = getPlayerById(req.params.id);
  if (!player) return res.status(404).send(renderPage(req, { title: 'Not Found', currentPath: '/picks', body: '<div class="container"><p style="padding:40px;color:var(--text-muted)">Player not found.</p></div>' }));
  const pctx = buildPicksContext(byDate(getAllGames()));
  const seasons = picksSeasons(pctx);
  const season = seasons.includes(String(req.query.season)) ? String(req.query.season) : String(getPortalCurrentSeason());
  const sp = seasonPicks(pctx, season);
  const isSelf = req.session?.playerPlayerId === player.id;
  const settledById = Object.fromEntries(sp.settled.map(g => [g.id, g]));

  const rows = pctx.picks
    .filter(p => p.player_id === player.id && pctx.byId[p.game_id]?.season === season)
    .map(p => {
      const g = pctx.byId[p.game_id];
      const s = settledById[g.id];
      if (s) {
        const pickPct = s.odds ? (p.side === 'a' ? s.odds.pctA : s.odds.pctB) : null;
        const correct = p.side === s.winner;
        return { g, side: p.side, state: correct ? 'ok' : 'miss', pickPct, upset: correct && !!s.odds?.fav && s.odds.fav !== s.winner };
      }
      if (g.played) return null; // a draft/under-review result — not public yet
      const o = pickOddsEnabled() && !pctx.settings[g.id]?.hide_odds ? computeOdds(g, pctx.played) : null;
      return { g, side: isSelf ? p.side : null, state: 'open', pickPct: isSelf && o ? (p.side === 'a' ? o.pctA : o.pctB) : null, upset: false };
    })
    .filter(Boolean)
    .sort((x, y) => y.g.ymd.localeCompare(x.g.ymd) || String(y.g.id).localeCompare(String(x.g.id)));

  const record = sp.records[player.id] || null;
  const rank = sp.board.rows.find(r => r.playerId === player.id)?.rank || null;
  const teamNames = Object.fromEntries(getAllTeams().map(t => [t.id, t.name]));
  const props = {
    player: { id: player.id, name: displayPlayerName(player.name || ''), team: teamNames[player.team_id] || '', slug: getSlugForEntity('player', player.id) || player.id },
    season, seasons, record, rank, ranked: sp.board.rows.length, minPicks: sp.board.minPicks, rows, isSelf, oddsOn: pickOddsEnabled(),
  };
  if (req.query.partial === '1') return res.send(picksPlayerSheet(props));
  res.send(renderPage(req, {
    title: `${props.player.name}'s picks · Season ${season} — WKND Basketball`,
    currentPath: '/picks',
    body: picksPlayerPage(props),
  }));
});

