// What /standings shows for a season (rows in seeding order: wins, two-team ties on
// head-to-head, then quotient — the same order as the /playoffs bracket).
function standingsSectionData(season, allGames = getAllGames()) {
  season = String(season);
  const standings = getSeasonStandings(season);
  const seeded = computeSeeds(standings, buildSeasonH2HMap(standings, season));
  const rows = [...seeded, ...standings.filter(s => !seeded.includes(s))];
  const seasonRegular = allGames.filter(g => String(g.season) === season && g.game_type === 'regular' && !g.under_review);
  return {
    season, isCurrent: season === String(getPortalCurrentSeason()), rows,
    // 'final' too: a score entered without a box score (Oct 18 White-Black) is a played game, as every
    // other list treats it; the standings sections' table was a game behind the lock line.
    games: seasonRegular.filter(g => (g.status === 'complete' || g.status === 'final') && Number(g.team_a_score) + Number(g.team_b_score) > 0),
    scheduled: seasonRegular.filter(g => g.status === 'scheduled' || g.scheduled === 1),
    teamStats: getTeamSeasonStats(season),
  };
}

// What /playoffs shows for a season: playoff + finals games with their recap headline and
// player of the game (name + stat line), the season awards, regular-season progress.
function playoffsSectionData(season) {
  season = String(season);
  const standings = getSeasonStandings(season);
  const h2h = buildSeasonH2HMap(standings, season);
  const seasonGames = getAllGames().filter(g => String(g.season) === season && !g.under_review);
  const games = seasonGames.filter(g => g.game_type === 'playoff' || g.game_type === 'finals').map(g => {
    const done = (g.status === 'complete' || g.status === 'final') && (Number(g.team_a_score) + Number(g.team_b_score)) > 0;
    const stats = done ? getGameStats(g.id) : [];
    // A co-POTG shows as "A & B", each with their own line.
    const ids = done ? potgIdsFor(g, stats) : [];
    const names = ids.map(id => getPlayerById(id)).filter(Boolean).map(p => displayPlayerName(p.name));
    const lines = ids.map(id => stats.find(x => x.player_id === id)).filter(Boolean)
      .map(s => `${Number(s.pts) || 0} points, ${Number(s.reb) || 0} rebounds, ${Number(s.ast) || 0} assists`);
    return {
      ...g, recapTitle: parseWriteup(g.game_writeup || '').title, potgName: names.join(' & '), potgShared: names.length > 1,
      potgLine: lines.length > 1 ? names.map((n, i) => `${n} ${lines[i] || ''}`.trim()).join('; ') : lines[0] || '',
    };
  });
  const person = type => {
    const a = getSeasonAwards(season).find(x => x.award_type === type && x.player_id);
    const p = a ? getPlayerById(a.player_id) : null;
    if (!p) return null;
    const name = displayPlayerName(p.name);
    return { id: p.id, name, number: p.number ?? '', initials: initials(name) };
  };
  const regularDone = seasonGames.filter(g => g.game_type === 'regular' && g.status === 'complete').length;
  const regularLeft = seasonGames.filter(g => g.game_type === 'regular' && (g.status === 'scheduled' || g.scheduled === 1)).length;
  return {
    season, isCurrent: season === String(getPortalCurrentSeason()), standings, h2h, games,
    awards: { finalsMvp: person('finals_mvp'), mvp: person('mvp') },
    regular: { played: regularDone, expected: Math.max(regularDone + regularLeft, standings.length * (standings.length - 1)) },
  };
}

const PLAYOFF_HERO_PHOTOS = 4;

// Homepage playoff hero (views/playoff-hero.js) for playoff mode's 'playoffs' / 'finals'
// phases: the undecided series whose next game comes first (the Finals in the 'finals'
// phase), the other live semi as the "Also" strip, and a cover photo from an earlier
// meeting of the two teams (any season), else a recent cover of either team. null when
// no series is live (e.g. the mode is forced on before the bracket exists).
function buildPlayoffHero(season, phase) {
  const pd = playoffsSectionData(season);
  const m = playoffsModel({ standings: pd.standings, games: pd.games, h2h: pd.h2h });
  const played = g => (g.status === 'complete' || g.status === 'final') && (Number(g.team_a_score) + Number(g.team_b_score)) > 0;
  const ymd = d => String(d || '').slice(0, 10);
  const series = (label, high, low, games, need, st, format) => (high && low && !st.winner
    ? { label, high, low, need, st, format, next: games.find(g => !played(g)) || null }
    : null);
  const semis = [
    series('Semifinal 1', m.s1, m.s4, m.semi1, { high: 1, low: 2 }, m.st1, 'Twice to beat'),
    series('Semifinal 2', m.s2, m.s3, m.semi2, { high: 1, low: 2 }, m.st2, 'Twice to beat'),
  ].filter(Boolean);
  const finals = series('Finals', m.fHigh, m.fLow, m.finalsGames, { high: 2, low: 2 }, m.fin, 'Best of 3');
  const live = (phase === 'finals' || !semis.length ? [finals] : semis).filter(Boolean)
    .sort((a, b) => (ymd(a.next?.date) || '9999').localeCompare(ymd(b.next?.date) || '9999'));
  if (!live.length) return null;

  const side = (s, key) => ({ team: { id: s[key].id, name: s[key].name }, seed: m.seedOf(s[key]), wins: key === 'high' ? s.st.hw : s.st.lw, need: s.need[key] });
  const main = live[0], other = live[1] || null;
  const H = main.high.name, L = main.low.name;
  const hl = main.need.high - main.st.hw, ll = main.need.low - main.st.lw;
  const n = main.st.played.length;
  const b = s => `<b>${escHtml(s)}</b>`;
  const line = main.label === 'Finals'
    ? (hl === 1 && ll === 1 ? `Game ${n + 1} decides the title.`
      : hl === 1 ? `${b(H)} is one win from the title.`
      : ll === 1 ? `${b(L)} is one win from the title.`
      : 'First to two wins takes the title.')
    : (n === 0 ? `${b(H)} needs one win to reach the Finals. ${b(L)} has to beat them twice. Lose and go home.`
      : `Game ${n + 1} decides it: the winner goes to the Finals.`);

  // The photos (up to PLAYOFF_HERO_PHOTOS, crossfading): played meetings of these two teams
  // with a cover, in random order, topped up with recent covers of either team.
  const ids = new Set([main.high.id, main.low.id]);
  const covered = getAllGames().filter(g => g.has_cover && !g.under_review && played(g));
  const shuffle = list => list.map(g => [Math.random(), g]).sort((a, b) => a[0] - b[0]).map(([, g]) => g);
  const meetings = shuffle(covered.filter(g => pairKey(g.team_a_id, g.team_b_id) === pairKey(main.high.id, main.low.id)));
  const recent = covered.filter(g => !meetings.includes(g) && (ids.has(g.team_a_id) || ids.has(g.team_b_id)))
    .sort((a, b) => ymd(b.date).localeCompare(ymd(a.date))).slice(0, 6);
  const picked = [...meetings, ...shuffle(recent)].slice(0, PLAYOFF_HERO_PHOTOS);
  const day = d => new Date(`${ymd(d)}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
  const photos = picked.map(pg => ({
    id: pg.id, href: `/games/${encodeURIComponent(gameSlug(pg))}`,
    caption: `${pg.team_a_name} vs ${pg.team_b_name} · ${day(pg.date)}${String(pg.season) !== String(season) ? `, S${pg.season}` : ''}`,
  }));

  // The next game's own tip-off time; without one, the Playoffs panel's tip-off time, else
  // the picks cut-off.
  const tip = /^\d{2}:\d{2}$/.test(main.next?.tip_time || '') ? main.next.tip_time
    : /^\d{2}:\d{2}$/.test(getSetting('playoff_tip_time', '')) ? getSetting('playoff_tip_time', '') : getSetting('picks_close_time', PICKS_CLOSE_DEFAULT);
  const [th, tm] = tip.split(':').map(Number);
  const tipLabel = `${th % 12 || 12}${tm ? `:${String(tm).padStart(2, '0')}` : ''} ${th < 12 ? 'AM' : 'PM'}`;

  return {
    season, label: main.label, gameNo: n + 1, format: main.format, line, photos, tipLabel,
    high: side(main, 'high'), low: side(main, 'low'),
    next: main.next ? { id: main.next.id, date: ymd(main.next.date) || null, href: `/games/${encodeURIComponent(gameSlug(main.next))}`, live: liveMini(main.next) } : null,
    also: other ? {
      label: other.label, high: side(other, 'high'), low: side(other, 'low'), date: ymd(other.next?.date) || null,
      href: other.next ? `/games/${encodeURIComponent(gameSlug(other.next))}` : '/playoffs',
    } : null,
    picksHref: picksEnabled() ? '/picks' : null,
  };
}

// The homepage's playoff-mode block above the hero grid: the scoreboard while a series is
// live, the champion hero in champion week, '' otherwise.
function homePlayoffBlock(season) {
  const phase = season ? playoffModeState(season).phase : null;
  if (!phase) return '';
  try {
    if (phase === 'champion') {
      const pd = playoffsSectionData(season);
      return championHero({ season, standings: pd.standings, games: pd.games, h2h: pd.h2h, awards: pd.awards });
    }
    return playoffScoreboard(buildPlayoffHero(season, phase), manilaTodayStr());
  } catch (err) {
    console.error('[playoff hero]', err.message);
    return '';
  }
}

// Applies to every request from here on, ahead of any route's own express.json() — a
// route-level limit override (e.g. /settle-balance's 20mb) never actually took effect
// while this ran first with Express's 100kb default and rejected the request before the
// route-specific parser ever got a chance to run.
app.use(express.json({ limit: '20mb' }));

// ── Roster endpoint (consumed by wknd-stats before each live game) ────────────
app.get('/api/roster', (req, res) => {
  const key = req.headers['x-api-key'] || req.query.key;
  if (ROSTER_API_KEY && key !== ROSTER_API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const teams   = getAllTeams();
  const players = getAllPlayers();
  const season  = getPortalCurrentSeason();

  // player_details is the canonical, admin-curated height — not the raw registrations table,
  // which can go stale once an admin corrects a height directly (see computeSyncDiff above).
  const heightMap = Object.fromEntries(getAllPlayerHeights().map(r => [r.player_id, r.height]));

  const fmtHeight = h => {
    const n = parseInt(h, 10);
    return isNaN(n) ? null : `${n}cm`;
  };

  const roster = {
    season,
    gameTypes: ['regular', 'playoff', 'finals'],
    teams: teams.map(t => ({
      id:    t.id,
      name:  t.name,
      color: t.color,
    })),
    players: players.map(p => ({
      id:         p.id,
      name:       p.name,
      firstName:  p.first_name,
      lastName:   p.last_name,
      number:     p.number,
      teamId:     p.team_id,
      positions:  (() => { try { return JSON.parse(p.positions || '[]'); } catch { return []; } })(),
      pictureUrl: p.picture_url || '',
      status:     p.status,
      height:     fmtHeight(heightMap[p.id]) ?? null,
    })),
  };

  res.json(roster);
});

// ── Leader share cards ────────────────────────────────────────────────────────
// A share stores the card exactly as the page shows it (cardSnapshot), found by rebuilding
// the same page model the button sat on — so the shared/downloaded images can't disagree
// with the card. Older shares (no card_json) get one rebuilt from their stored top 10.
function findShareCard(season, categoryId, mode) {
  try {
    const current = getPortalCurrentSeason();
    const isAll = season === 'alltime';
    let model;
    if (mode === 'roast' || mode === 'disaster') {
      model = buildRoastModel({ season, players: mode === 'roast' ? buildLeaderPlayers(season) : [], gameRecords: getGameRecords(), currentSeason: current });
    } else if (mode === 'rec') {
      model = buildLeadersModel({ stats: 'rec', season, currentSeason: current, gameRecords: getGameRecords() });
    } else if (mode === 'pg' || mode === 'tot' || mode === 'po-pg') {
      const players = mode === 'po-pg' ? (isAll ? [] : getPlayoffLeaders(season)) : isAll ? buildLeaderPlayersAllTime() : buildLeaderPlayers(season);
      model = buildLeadersModel({ stats: mode === 'po-pg' ? 'po' : mode, season, currentSeason: current, players });
    }
    for (const sec of model?.sections || []) {
      const item = sec.items.find(m => m && m.cat.id === categoryId && m.mode === mode);
      if (item) return cardSnapshot(item);
    }
  } catch (err) { console.error('findShareCard failed:', err.message); }
  return null;
}

function shareCardOf(share) {
  try { if (share.card_json) return JSON.parse(share.card_json); } catch {}
  let top = [];
  try { top = JSON.parse(share.top10_json || '[]'); } catch {}
  const up = s => String(s || '').toUpperCase();
  const lead = { id: share.player_id, name: share.player_name, number: getPlayerById(share.player_id)?.number ?? '', team: up(share.team_name), gp: 0, value: share.stat_fmt };
  if (share.mode === 'rec' || share.mode === 'disaster') {
    const f = top[0] || {};
    const day = f.game_date ? new Date(`${String(f.game_date).slice(0, 10)}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '';
    return {
      kind: 'record', title: share.stat_title, sub: '', badge: '', badgeOn: false, lead,
      game: { id: f.game_id || '', line: f.game_opp ? `vs ${up(f.game_opp)} · ${f.game_result || ''}` : '', when: day },
      foot: top[1] ? `Next ${share.mode === 'disaster' ? 'worst' : 'best'}: ${top[1].stat_fmt} — ${displayPlayerName(top[1].player_name)}` : '',
    };
  }
  return {
    kind: 'board', size: 'lg', title: share.stat_title, sub: '', key: share.stat_label, lead,
    rest: top.slice(1, 5).map(p => ({ id: p.player_id, name: p.player_name, team: up(p.team_name), delta: '', value: p.stat_fmt })),
  };
}

// The leader's photo for the images, or their jersey when they have none / it won't load.
async function leaderCardPhoto(id) {
  const row = getPlayerPhoto(id);
  const buf = row?.picture_url ? await fetchCoverImageBuffer(row.picture_url) : null;
  if (buf) return buf;
  const player = getPlayerById(id);
  if (!player) return null;
  const team = player.team_id ? getTeamById(player.team_id) : null;
  return sharp(Buffer.from(playerJerseySvg({ color: team ? teamColor(team.name) : '#4a5263', number: player.number }))).resize(384, 384).png().toBuffer();
}

let leaderCardLogo;
async function leaderCardLogoPng() {
  if (leaderCardLogo === undefined) {
    try { leaderCardLogo = existsSync(COVER_LOGO_PATH) ? await sharp(COVER_LOGO_PATH).ensureAlpha().resize({ width: 300, height: 80, fit: 'inside' }).png().toBuffer() : null; }
    catch { leaderCardLogo = null; }
  }
  return leaderCardLogo;
}

// Rendered images, keyed by share + what's drawn, so repeat link previews don't redraw.
const leaderCardCache = new Map();
async function leaderShareImage(share, kind) {
  const card = shareCardOf(share);
  const { asOfWeek } = buildShareAsOfLabel(share);
  const scope = share.mode === 'disaster' || share.season === 'alltime' ? 'All seasons' : `Season ${share.season}`;
  const footer = ['WKNDBASKETBALL.COM', share.season === 'alltime' || share.mode === 'disaster' ? '' : `SEASON ${share.season}`, asOfWeek ? `WEEK ${asOfWeek}` : ''].filter(Boolean).join(' · ');
  const key = `${share.id}|${kind}|${createHash('sha1').update(JSON.stringify(card) + footer).digest('hex')}`;
  if (leaderCardCache.has(key)) return leaderCardCache.get(key);
  const fonts = { text: OG_TEXT, num: OG_NUM };
  const png = kind === 'wide'
    ? await renderLeaderWidePng(card, { loadPhoto: leaderCardPhoto, fonts, logo: await leaderCardLogoPng(), scopeLine: [scope, asOfWeek && scope !== 'All seasons' ? `thru week ${asOfWeek}` : ''].filter(Boolean).join(' · ') })
    : await renderLeaderCardPng(card, { loadPhoto: leaderCardPhoto, fonts, footer });
  if (leaderCardCache.size > 200) leaderCardCache.delete(leaderCardCache.keys().next().value);
  leaderCardCache.set(key, png);
  return png;
}

app.post('/api/leaders/share', (req, res) => {
  const { season, category_id, mode, player_id, player_name, team_id,
          team_name, team_color, stat_label, stat_title, stat_value, stat_fmt } = req.body || {};
  if (!season || !category_id || !mode || !player_id) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Compute top entries + leader photo server-side for the share image
  let top10 = [];
  let leaderPlayer = null;

  // 'disaster' = the roast's single-game disasters: same shape as records, own categories.
  if (mode === 'rec' || mode === 'disaster') {
    const recCat       = (mode === 'rec' ? RECORD_CATS : DISASTER_CATS).find(c => c.id === category_id);
    const recFmt       = recCat?.fmt || (v => String(Math.round(v)));
    const allRecs      = getGameRecords();
    const filteredRecs = season === 'alltime' ? allRecs : allRecs.filter(r => String(r.season) === String(season));
    if (recCat) {
      top10 = filteredRecs
        .map(r => ({ r, v: Number(recCat.fn(r) || 0) }))
        .filter(x => x.v > 0)
        .sort((a, b) => b.v - a.v)
        .slice(0, 5)
        .map(x => {
          const ctx = recordContext(x.r);
          return {
            player_id:   x.r.player_id,
            player_name: x.r.name,
            team_name:   String(x.r.team_name || '').toUpperCase(),
            team_color:  teamColor(String(x.r.team_name || '').toUpperCase()),
            stat_value:  x.v,
            stat_fmt:    recCat.show ? recCat.show(x.r) : recFmt(x.v),
            game_id:     String(x.r.game_id || ''),
            game_date:   String(x.r.date || ''),
            game_opp:    ctx.opp,
            game_result: ctx.result,
            is_playoff:  ctx.isPO,
            is_finals:   ctx.isFinals,
          };
        });
    }
    leaderPlayer = getPlayerPhoto(player_id);
  } else if (mode === 'roast') {
    const cat        = ROAST_CATS.find(c => c.id === category_id);
    const fmt        = cat?.fmt || (v => v.toFixed(1));
    const allPlayers = buildLeaderPlayers(season);
    leaderPlayer     = allPlayers.find(p => p.id === player_id);
    top10 = cat
      ? allPlayers
          .map(p => ({ p, v: cat.fn(p) }))
          .filter(x => x.v !== null && x.v !== undefined && !isNaN(x.v))
          .sort((a, b) => cat.asc ? a.v - b.v : b.v - a.v)
          .slice(0, 10)
          .map(x => ({
            player_id:   x.p.id,
            player_name: x.p.name,
            team_name:   x.p.team_name,
            team_color:  teamColor(String(x.p.team_name || '').toUpperCase()),
            stat_value:  x.v,
            stat_fmt:    fmt(x.v),
          }))
      : [];
  } else {
    // po-pg / po-tot are playoff boards: rank playoff stats, not the regular season's.
    const isPo       = String(mode).startsWith('po-');
    const perGame    = mode === 'pg' || mode === 'po-pg';
    const allCats    = perGame ? PER_GAME : TOTALS;
    const cat        = allCats.find(c => c.id === category_id);
    const defaultFmt = perGame ? fmtPerGame : fmtTotals;
    const fmt        = cat?.fmt || defaultFmt;
    const allPlayers = isPo ? getPlayoffLeaders(season) : buildLeaderPlayers(season);
    leaderPlayer     = allPlayers.find(p => p.id === player_id);
    top10 = cat
      ? allPlayers
          .filter(p => !perGame || qualifiesPerGame(p))
          .map(p => ({ p, v: cat.fn(p) }))
          .filter(x => x.v > 0)
          .sort((a, b) => b.v - a.v || b.p.games_played - a.p.games_played || (b.p.team_wins || 0) - (a.p.team_wins || 0))
          .slice(0, 10)
          .map(x => ({
            player_id:   x.p.id,
            player_name: x.p.name,
            team_name:   x.p.team_name,
            team_color:  teamColor(String(x.p.team_name || '').toUpperCase()),
            stat_value:  x.v,
            stat_fmt:    fmt(x.v),
          }))
      : [];
  }

  // The card as the page shows it right now; its value wins over the one the button sent.
  const card = findShareCard(String(season), String(category_id), String(mode));
  const id = upsertShare({
    id: randomBytes(4).toString('hex'),
    season, category_id, mode, player_id, player_name, team_id,
    team_name, team_color, stat_label, stat_title,
    stat_value: Number(stat_value), stat_fmt: card && card.lead.id === String(player_id) ? card.lead.value : stat_fmt,
    top10,
    player_picture_url: leaderPlayer?.picture_url || '',
    created_at: Date.now(),
    card,
  });
  const url = `${getRequestOrigin(req)}/leaders/share/${id}`;
  res.json({ id, url });
});

app.get('/leaders/share/:id', (req, res) => {
  const share = getShare(req.params.id);
  if (!share) return res.status(404).send(
    layout({ title: 'Not Found', currentPath: '/leaders', body: '<p style="padding:40px;color:var(--text-muted)">Share link not found.</p>' })
  );
  const origin      = getRequestOrigin(req);
  const displayName = formatName(share.player_name);
  const isRecShare  = share.mode === 'rec';
  const isAlltime   = share.season === 'alltime';
  const scopeText   = isAlltime ? 'All-Time' : `Season ${share.season}`;
  const { asOfSeason, asOfWeek } = buildShareAsOfLabel(share);
  const asOfDesc    = asOfWeek
    ? (isAlltime ? ` Updated through Season ${asOfSeason}, Week ${asOfWeek}.` : ` Updated through Week ${asOfWeek}.`)
    : '';
  const isRoastShare = share.mode === 'roast';
  const isDisaster   = share.mode === 'disaster';
  const title       = isDisaster
    ? `${displayName} · ${share.stat_title} — The Roast · WKND Basketball`
    : isRecShare
    ? `${displayName} · ${share.stat_label} ${scopeText} Record — WKND Basketball`
    : isRoastShare
      ? `${displayName} · ${share.stat_title} — The Roast · WKND Basketball`
      : `${displayName} · ${share.stat_label} Leader (${scopeText}) — WKND Basketball`;
  const desc        = isDisaster
    ? `${displayName}'s ${share.stat_fmt} is The Roast's "${share.stat_title}" — all in good fun.${asOfDesc}`
    : isRecShare
    ? `${displayName} holds the ${isAlltime ? 'all-time' : `Season ${share.season}`} ${share.stat_title} record with ${share.stat_fmt}.${asOfDesc}`
    : isRoastShare
      ? `${displayName} earned the "${share.stat_title}" award — ${share.stat_fmt} ${share.stat_label}.${asOfDesc}`
      : `${displayName} leads the WKND League in ${share.stat_title} with ${share.stat_fmt}${share.mode === 'pg' || share.mode === 'po-pg' ? ' per game' : ' total'}${String(share.mode).startsWith('po-') ? ' in the playoffs' : ''}.${asOfDesc}`;
  const imageUrl    = `${origin}/api/leaders/share/${share.id}/image.png`;
  const pageUrl     = `${origin}/leaders/share/${share.id}`;
  const metaTags = [
    `<meta name="description" content="${escAttr(desc)}">`,
    `<meta property="og:type" content="website">`,
    `<meta property="og:site_name" content="WKND Basketball">`,
    `<meta property="og:title" content="${escAttr(title)}">`,
    `<meta property="og:description" content="${escAttr(desc)}">`,
    `<meta property="og:url" content="${escAttr(pageUrl)}">`,
    `<meta property="og:image" content="${escAttr(imageUrl)}">`,
    `<meta property="og:image:type" content="image/png">`,
    `<meta property="og:image:width" content="1200">`,
    `<meta property="og:image:height" content="630">`,
    `<meta name="twitter:card" content="summary_large_image">`,
    `<meta name="twitter:title" content="${escAttr(title)}">`,
    `<meta name="twitter:description" content="${escAttr(desc)}">`,
    `<meta name="twitter:image" content="${escAttr(imageUrl)}">`,
  ].join('\n  ');
  res.send(renderPage(req, {
    title,
    currentPath: '/leaders',
    metaTags,
    body: leaderSharePage({ share, card: shareCardOf(share) }),
  }));
});

app.get('/api/leaders/share/:id/image.png', async (req, res) => {
  const share = getShare(req.params.id);
  if (!share) return res.status(404).end();
  try {
    const png = await leaderShareImage(share, 'wide');
    res.set('Content-Type', 'image/png');
    res.set('Cache-Control', 'public, max-age=300');
    res.end(png);
  } catch (err) {
    console.error('Leader share image error:', err);
    res.status(500).end();
  }
});

// The Download button: the card itself, portrait, at 2×.
app.get('/api/leaders/share/:id/card.png', async (req, res) => {
  const share = getShare(req.params.id);
  if (!share) return res.status(404).end();
  try {
    const png = await leaderShareImage(share, 'card');
    const slug = `${share.category_id}-${share.mode}`.toLowerCase().replace(/[^a-z0-9-]+/g, '-');
    res.set('Content-Type', 'image/png');
    res.set('Cache-Control', 'public, max-age=300');
    if (req.query.dl) res.set('Content-Disposition', `attachment; filename="wknd-${slug}.png"`);
    res.end(png);
  } catch (err) {
    console.error('Leader card download error:', err);
    res.status(500).end();
  }
});

// ── MVP / Best Defender card shares ──────────────────────────────────────────
// Share / Download on every /mvp and /dpoy card. Stored in leader_shares (category + mode =
// the race key, 'mvp' or 'dpoy', one row per player per season) with the card's snapshot
// (views/mvp.js mvpSnapshot) frozen as shared; /<race>/share/:id shows the case, the images
// are drawn from the same snapshot.
for (const raceKey of ['mvp', 'dpoy']) {
  app.post(`/api/${raceKey}/share`, express.json(), (req, res) => {
    const race = RACE_DATA[raceKey];
    const season = String(req.body?.season || '');
    const pid = String(req.body?.player_id || '');
    if (!season || !pid) return res.status(400).json({ error: 'Missing season or player.' });
    if (isMvpLocked(season)) return res.status(404).json({ error: `The ${race.name} is under wraps until Finals Game 2.` });
    const top = mvpRaceTop(season, raceKey);
    const i = top.findIndex(c => String(c.player.id) === pid);
    if (i === -1) return res.status(404).json({ error: `Not in the ${race.name}.` });
    const c = top[i];
    c.writeup = race.getWriteup(c.player.id, season, raceWriteupKey(race, c, i + 1)) || race.getWriteup(c.player.id, season, race.statsKey(c.stats)) || '';
    const snap = mvpSnapshot(c, i + 1, top, { season, week: getSeasonLatestWeek(season)?.week ?? null, playoffsStarted: isPlayoffStarted(season), race: raceKey });
    const team = String(c.stats.team_name || '');
    const id = upsertShare({
      id: randomBytes(4).toString('hex'),
      season, category_id: raceKey, mode: raceKey, player_id: pid, player_name: c.player.name,
      team_id: c.stats.team_id || '', team_name: team, team_color: teamColor(team),
      stat_label: race.short, stat_title: race.name, stat_value: Number(snap.lead.value), stat_fmt: snap.lead.value,
      top10: [], player_picture_url: c.player.picture_url || '', created_at: Date.now(), card: snap,
    });
    res.json({ id, url: `${getRequestOrigin(req)}/${raceKey}/share/${id}` });
  });

  app.get(`/${raceKey}/share/:id`, (req, res) => {
    const race = RACE_DATA[raceKey];
    const found = mvpShareOf(req.params.id, raceKey);
    if (!found) return res.status(404).send(renderPage(req, { title: 'Not Found', currentPath: `/${raceKey}`, body: '<p style="padding:40px;color:var(--text-muted)">Share link not found.</p>' }));
    const { share, snap } = found;
    const origin = getRequestOrigin(req);
    const name = displayPlayerName(snap.lead.name);
    const place = snap.rank === 1 ? 'leads' : `is #${snap.rank} in`;
    const title = `${name} · #${snap.rank} in the ${race.name} (Season ${snap.season}) — WKND Basketball`;
    const desc = `${name} ${place} the Season ${snap.season} ${race.nameLower} with ${race.scoreArticle} ${race.scoreLabel} of ${snap.lead.value}${snap.gap ? ` (${snap.gap})` : ''}${snap.asOf && snap.asOf !== 'Final' ? `, ${snap.asOf.toLowerCase()}` : ''}.`;
    const imageUrl = `${origin}/api/${raceKey}/share/${share.id}/image.png`;
    const pageUrl = `${origin}/${raceKey}/share/${share.id}`;
    const metaTags = [
      `<meta name="description" content="${escAttr(desc)}">`,
      `<meta property="og:type" content="website">`,
      `<meta property="og:site_name" content="WKND Basketball">`,
      `<meta property="og:title" content="${escAttr(title)}">`,
      `<meta property="og:description" content="${escAttr(desc)}">`,
      `<meta property="og:url" content="${escAttr(pageUrl)}">`,
      `<meta property="og:image" content="${escAttr(imageUrl)}">`,
      `<meta property="og:image:type" content="image/png">`,
      `<meta property="og:image:width" content="1200">`,
      `<meta property="og:image:height" content="630">`,
      `<meta name="twitter:card" content="summary_large_image">`,
      `<meta name="twitter:title" content="${escAttr(title)}">`,
      `<meta name="twitter:description" content="${escAttr(desc)}">`,
      `<meta name="twitter:image" content="${escAttr(imageUrl)}">`,
    ].join('\n  ');
    res.send(renderPage(req, { title, currentPath: `/${raceKey}`, metaTags, body: mvpSharePage(snap) }));
  });

  app.get(`/api/${raceKey}/share/:id/image.png`, async (req, res) => {
    const found = mvpShareOf(req.params.id, raceKey);
    if (!found) return res.status(404).end();
    try {
      const png = await mvpShareImage(found, 'wide');
      res.set('Content-Type', 'image/png');
      res.set('Cache-Control', 'public, max-age=300');
      res.end(png);
    } catch (err) {
      console.error(`${raceKey} share image error:`, err);
      res.status(500).end();
    }
  });

  // The Download button: the card, portrait, at 2×.
  app.get(`/api/${raceKey}/share/:id/card.png`, async (req, res) => {
    const found = mvpShareOf(req.params.id, raceKey);
    if (!found) return res.status(404).end();
    try {
      const png = await mvpShareImage(found, 'card');
      res.set('Content-Type', 'image/png');
      res.set('Cache-Control', 'public, max-age=300');
      if (req.query.dl) res.set('Content-Disposition', `attachment; filename="${RACE_DATA[raceKey].dl}"`);
      res.end(png);
    } catch (err) {
      console.error(`${raceKey} card download error:`, err);
      res.status(500).end();
    }
  });
}

// Shares made before the MVP reveal lock still carry a rank and score, so every share route
// (page, preview image, download) 404s while that season is locked.
const mvpShareOf = (id, raceKey = 'mvp') => {
  const share = getShare(id);
  if (!share || share.mode !== raceKey) return null;
  if (isMvpLocked(share.season)) return null;
  try { return { share, snap: JSON.parse(share.card_json) }; } catch { return null; }
};

async function mvpShareImage(found, kind) {
  const { share, snap } = found;
  const footer = ['WKNDBASKETBALL.COM', `SEASON ${snap.season}`, snap.week ? `WEEK ${snap.week}` : ''].filter(Boolean).join(' · ');
  const key = `${share.id}|mvp-${kind}|${createHash('sha1').update(share.card_json + footer).digest('hex')}`;
  if (leaderCardCache.has(key)) return leaderCardCache.get(key);
  const fonts = { text: OG_TEXT, num: OG_NUM };
  const png = kind === 'wide'
    ? await renderMvpWidePng(snap, { loadPhoto: leaderCardPhoto, fonts, logo: await leaderCardLogoPng(), scopeLine: `Season ${snap.season}` })
    : await renderMvpCardPng(snap, { loadPhoto: leaderCardPhoto, fonts, footer });
  if (leaderCardCache.size > 200) leaderCardCache.delete(leaderCardCache.keys().next().value);
  leaderCardCache.set(key, png);
  return png;
}

// ── MVP Race ──────────────────────────────────────────────────────────────────
// SEASON_GAMES_PER_TEAM (6, double round robin) lives in lib/mvp-lock.js with the final-week lock rule.

function computeMvpScore(s) {
  const gp  = s.gp;
  const ppg = s.pts / gp, rpg = s.reb / gp, apg = s.ast / gp;
  const spg = s.stl / gp, bpg = s.blk / gp, tpg = s.tov / gp;
  const base = ppg + rpg*0.8 + apg*0.9 + spg*1.5 + bpg*2.0 - tpg*1.0;

  const tsDenom = 2 * (s.fga + 0.44 * s.fta);
  const tsPct   = tsDenom > 0 ? s.pts / tsDenom : 0;
  let effMult = 1.00;
  if (tsDenom > 0) {
    if      (tsPct >= 0.70) effMult = 1.20;
    else if (tsPct >= 0.60) effMult = 1.10;
    else if (tsPct >= 0.50) effMult = 1.00;
    else if (tsPct >= 0.40) effMult = 0.85;
    else                    effMult = 0.70;
  }
  const winRate = (s.wins + s.losses) > 0 ? s.wins / (s.wins + s.losses) : 0.5;
  const winMult = 0.80 + winRate * 0.40;
  const gpRatio = Math.min(1, gp / SEASON_GAMES_PER_TEAM);
  return base * effMult * winMult * gpRatio;
}

function mvpStatsKey(s) {
  return `v2_${s.gp}_${s.pts}_${s.reb}_${s.ast}_${s.fgm}_${s.fga}_${s.ftm}_${s.fta}_${s.wins}_${s.losses}`;
}

// Best Defender race (/dpoy). The box score only has steals, blocks, rebounds (not split
// offensive/defensive) and fouls, so: stocks weighted like the MVP score's, a small nod to
// rebounding, a small cost per foul, then the same team-win and games-played scaling.
function computeDpoyScore(s) {
  const gp = s.gp;
  const base = (s.stl / gp) * 1.5 + (s.blk / gp) * 2.0 + (s.reb / gp) * 0.3 - ((s.pf || 0) / gp) * 0.3;
  const winRate = (s.wins + s.losses) > 0 ? s.wins / (s.wins + s.losses) : 0.5;
  const winMult = 0.80 + winRate * 0.40;
  const gpRatio = Math.min(1, gp / SEASON_GAMES_PER_TEAM);
  return Math.max(0, base) * winMult * gpRatio;
}
function dpoyStatsKey(s) {
  return `d1_${s.gp}_${s.stl}_${s.blk}_${s.reb}_${s.pf || 0}_${s.wins}_${s.losses}`;
}

// The two races /mvp's machinery serves (views/mvp.js RACES has the wording on the page side).
// Both rank regular-season candidates (getMvpCandidates) and share the MVP reveal lock.
const RACE_DATA = {
  mvp: {
    key: 'mvp', name: 'MVP Race', nameLower: 'MVP race', short: 'MVP', scoreLabel: 'MVP score', scoreArticle: 'an', unit: 'MVP points',
    score: computeMvpScore, statsKey: mvpStatsKey, dl: 'wknd-mvp-race.png',
    getWriteup: getMvpWriteup, setWriteup: setMvpWriteup, recentWriteups: getMvpWriteupsForSeason,
    deleteWriteup: deleteMvpWriteupForPlayer, clearWriteups: clearMvpWriteupSeason,
  },
  dpoy: {
    key: 'dpoy', name: 'Best Defender Race', nameLower: 'Best Defender race', short: 'Best Defender', scoreLabel: 'defense score', scoreArticle: 'a', unit: 'defense points',
    score: computeDpoyScore, statsKey: dpoyStatsKey, dl: 'wknd-best-defender-race.png',
    getWriteup: getDpoyWriteup, setWriteup: setDpoyWriteup, recentWriteups: getDpoyWriteupsForSeason,
    deleteWriteup: deleteDpoyWriteupForPlayer, clearWriteups: clearDpoyWriteupSeason,
  },
};

// Returns { playerId: rank } for the race as it stood before the latest game week, or null
// when there is no earlier week to compare against. Players outside last week's pool are
// absent from the map (rendered as NEW).
function mvpPrevRanks(season, completedGames, score = computeMvpScore) {
  const dates = completedGames
    .filter(g => String(g.season) === String(season) && g.game_type === 'regular' && g.status === 'complete' && g.date)
    .map(g => String(g.date).slice(0, 10))
    .sort();
  if (!dates.length) return null;
  const latest = new Date(dates[dates.length - 1] + 'T00:00:00Z');
  latest.setUTCDate(latest.getUTCDate() - ((latest.getUTCDay() + 6) % 7)); // back to Monday
  const weekStart = latest.toISOString().slice(0, 10);
  if (!dates.some(d => d < weekStart)) return null;

  const prev = getMvpCandidates(season, weekStart)
    .filter(s => s.gp >= 1)
    .map(s => ({ id: s.id, score: score(s) }))
    .sort((a, b) => b.score - a.score);
  return Object.fromEntries(prev.map((p, i) => [p.id, i + 1]));
}

// The top 10 as /mvp (or /dpoy) shows it (score, stats, prevRank). The page builds its own
// copy with league ranks and writeups; this one feeds shares and the section Regenerate.
// mvpScore holds the race's own score (the defense score on /dpoy).
function mvpRaceTop(season, raceKey = 'mvp') {
  const score = RACE_DATA[raceKey].score;
  const completed = byDate(getAllGames()).filter(isPlayedGame);
  const prev = mvpPrevRanks(season, completed, score);
  return getMvpCandidates(season)
    .filter(s => s.gp >= 1)
    .map(s => ({ player: s, stats: s, mvpScore: score(s), prevRank: prev ? (prev[s.id] ?? null) : undefined }))
    .sort((a, b) => b.mvpScore - a.mvpScore)
    .slice(0, 10);
}

// Who led the race after each game week (Mon–Sun), replayed like mvpPrevRanks.
function mvpWeeklyLeaders(season, score = computeMvpScore) {
  const mondays = [...new Set(getAllGames()
    .filter(g => String(g.season) === String(season) && g.game_type === 'regular' && g.status === 'complete' && !g.under_review && g.date)
    .map(g => { const d = new Date(String(g.date).slice(0, 10) + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7)); return d.toISOString().slice(0, 10); }))]
    .sort();
  return mondays.map((mon, i) => {
    const next = new Date(mon + 'T00:00:00Z'); next.setUTCDate(next.getUTCDate() + 7);
    const top = getMvpCandidates(season, next.toISOString().slice(0, 10)).filter(s => s.gp >= 1)
      .map(s => ({ s, score: score(s) })).sort((a, b) => b.score - a.score)[0];
    return top ? { week: i + 1, name: displayPlayerName(top.s.name) } : null;
  }).filter(Boolean);
}

// /mvp and /dpoy section writeups: "race" under the page header, "chase" under The chase
// (#4–10). top: the page's top 10 (mvpRaceTop shape). Gaps come pre-computed (the number
// guard). The MVP wording is unchanged from before /dpoy existed, so its cached summaries
// (keyed on these facts) stay valid.
function mvpSectionFacts({ season, week, playoffsStarted, top, race: raceKey = 'mvp' }) {
  const isMvp = raceKey === 'mvp';
  const race = RACE_DATA[raceKey];
  // No AI race summary while the MVP reveal lock is on: it would name the leader. An empty
  // map also stops a cached summary rendering and the admin Regenerate ("Nothing to summarise").
  if (top.length < 2 || isMvpLocked(season)) return {};
  const T = titleCase;
  const one = n => (Math.round(n * 10) / 10).toFixed(1);
  const asOf = playoffsStarted ? `Season ${season} · final` : `After week ${week}`;
  const where = `${race.name} page`;
  const move = (c, r) => (c.prevRank === undefined ? '' : c.prevRank === null ? 'new to the top 10 this week'
    : c.prevRank === r ? `held #${r} from last week` : `${c.prevRank > r ? 'up' : 'down'} from #${c.prevRank} last week`);
  const line = (c, r) => {
    const s = c.stats, gp = s.gp || 1;
    const d = 2 * ((s.fga || 0) + 0.44 * (s.fta || 0));
    const perGame = isMvp
      ? `${one(s.pts / gp)} points, ${one(s.reb / gp)} rebounds, ${one(s.ast / gp)} assists per game${d > 0 ? `, ${Math.round(s.pts / d * 100)}% true shooting` : ''}`
      : `${one(s.stl / gp)} steals, ${one(s.blk / gp)} blocks, ${one(s.reb / gp)} rebounds, ${one((s.pf || 0) / gp)} fouls per game`;
    return `- #${r} ${displayPlayerName(c.player.name)} (${T(s.team_name)}): ${isMvp ? 'MVP score' : 'Defense score'} ${one(c.mvpScore)}${move(c, r) ? `, ${move(c, r)}` : ''}; ${perGame}; team record ${s.wins}-${s.losses}; ${plural(s.gp, 'game')} played`;
  };
  const head = isMvp
    ? `Season ${season} MVP race, ${playoffsStarted ? 'final regular-season standings' : `after week ${week} of the regular season`}. The MVP score is per-game production (points, rebounds, assists, steals, blocks, minus turnovers) scaled by true shooting, team win rate and games played.`
    : `Season ${season} Best Defender race, ${playoffsStarted ? 'final regular-season standings' : `after week ${week} of the regular season`}. The defense score is per-game steals and blocks, plus a little for rebounds and minus a little for fouls, scaled by team win rate and games played. Rebounds are not split into offensive and defensive.`;
  const out = {};
  const leaders = mvpWeeklyLeaders(season, race.score);
  const [a, b, c] = top;
  out.race = {
    kicker: `The race · ${asOf}`, section: `${race.name} (the whole race, at the top of the page)`, where,
    facts: [head, 'Top 5:', ...top.slice(0, 5).map((x, i) => line(x, i + 1)),
      `#1 leads #2 by ${one(a.mvpScore - b.mvpScore)} ${race.unit}${c ? `; #2 leads #3 by ${one(b.mvpScore - c.mvpScore)}` : ''}.`,
      leaders.length > 1 ? `Leader of the race after each week: ${leaders.map(l => `week ${l.week} ${l.name}`).join(', ')}.` : ''].filter(Boolean).join('\n'),
    focus: `Sum up the ${race.nameLower}: who leads and by how much, who climbed or slipped this week, and how the top spot has changed hands over the weeks. Name at most three players and don't recite stat lines. The facts don't say how any gap changed since last week, so never say a gap closed, narrowed, shrank or widened.`,
  };
  if (top.length > 3) {
    out.chase = {
      kicker: `The chase · ${asOf}`, section: `The chase (${race.nameLower} places #4 to #10)`, where,
      facts: [head, `#3 is ${displayPlayerName(c.player.name)} on ${race.scoreArticle} ${race.scoreLabel} of ${one(c.mvpScore)}.`, 'Places #4 to #10:',
        ...top.slice(3).map((x, i) => `${line(x, i + 4)}; ${one(c.mvpScore - x.mvpScore)} ${race.unit} behind #3`)].join('\n'),
      focus: 'Pick the one or two most interesting stories among places #4 to #10: who is closest to the top three, and who climbed or slipped this week. Don\'t go through every player. The facts don\'t say how any gap changed since last week, so never say anyone closed in, closed a gap or fell further back.',
    };
  }
  return sectionFactsMap(raceKey, season, out);
}

// The locked page's writeup under The ten (mvpLockTen shape). The facts list the ten A–Z
// with no score, rank or movement, so the copy can't leak the order; A–Z also keeps the
// facts key stable across the per-visit shuffle.
function mvpLockSectionFacts(season, ten, raceKey = 'mvp') {
  if (ten.length < 2) return {};
  const isMvp = raceKey === 'mvp';
  const race = RACE_DATA[raceKey];
  const T = titleCase;
  const one = n => (Math.round(n * 10) / 10).toFixed(1);
  const forecast = ten.some(c => c.mode === 'forecast');
  const line = c => {
    const a = c.avg;
    const perGame = isMvp
      ? `${one(a.pts)} points, ${one(a.reb)} rebounds, ${one(a.ast)} assists per game${c.ts != null ? `, ${c.ts}% true shooting` : ''}`
      : `${one(a.stl)} steals, ${one(a.blk)} blocks, ${one(a.reb)} rebounds, ${one(a.pf)} fouls per game`;
    // No single-game lines (the cards show them): drafts kept passing them off as averages.
    const next = c.mode === 'forecast' && c.opp ? `; plays ${T(c.opp)} in the final week` : '';
    return `- ${displayPlayerName(c.player.name)} (${T(c.team)}, team record ${c.record.w}-${c.record.l}): season averages of ${perGame}; ${plural(c.stats.gp, 'game')} played${next}`;
  };
  // Everything below comes off the A–Z list, never the shuffled one, or the key would change.
  const sorted = [...ten].sort((a, b) => displayPlayerName(a.player.name).localeCompare(displayPlayerName(b.player.name)));
  const byTeam = {};
  for (const c of sorted) byTeam[T(c.team)] = (byTeam[T(c.team)] || 0) + 1;
  // Each final-week game once (both teams' players name it, and drafts counted it twice).
  // With how many of the ten play in each, so the writer doesn't count them up itself.
  const gameKey = c => [T(c.team), T(c.opp)].sort().join(' vs ');
  const games = [...new Set(sorted.filter(c => c.mode === 'forecast' && c.opp).map(gameKey))].map(g => {
    const inIt = sorted.filter(c => c.mode === 'forecast' && c.opp && gameKey(c) === g).map(c => displayPlayerName(c.player.name));
    return `${g}, with ${inIt.length} of the ten in it (${inIt.join(', ')})`;
  });
  const facts = [
    `Season ${season} ${race.name}: the ten (10) players still in the race, ${forecast ? 'with one regular-season week left' : 'with the regular season finished'}. The order and the scores are hidden until the award is given at Finals Game 2. Listed A to Z; the list order means nothing.`,
    `Players per team among the ten: ${Object.entries(byTeam).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([t, n]) => `${t} ${n}`).join(', ')}.`,
    games.length ? `Final-week games (one game each): ${games.join('; ')}.` : '',
    'The ten:', ...sorted.map(line),
  ].filter(Boolean).join('\n');
  return sectionFactsMap(raceKey, season, {
    ten: {
      kicker: `The ten · ${forecast ? 'Final week' : 'Regular season done'}`,
      section: `The ten (the hidden ${race.nameLower}, shuffled, no ranks)`, where: `${race.name} page`,
      facts,
      focus: `Set the scene for the ten hidden ${isMvp ? 'MVP' : 'Best Defender'} cases in one angle only: ${forecast ? 'the final-week game with the most of the ten in it, and one or two of the players in that game' : 'how the ten split across the teams, with one or two contrasting cases'}. Every per-game number is a season average: say so, never tie it to one game. Never rank them, never say or hint who leads, is ahead, is the favourite, should win, or is on the podium, and never guess the order. Name at most three players. The body is 1-2 short sentences, nothing more.`,
    },
  });
}

// After an AI failure (usually provider quota), /mvp stops generating for a while so every
// page view doesn't re-hit an exhausted quota across all fallback models.
const MVP_AI_COOLDOWN_MS = 10 * 60 * 1000;
let mvpAiCooldownUntil = 0;

// Promise.all over items with at most `limit` callbacks running at once; preserves order.
async function mapWithConcurrency(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  const worker = async () => { while (next < items.length) { const i = next++; out[i] = await fn(items[i], i); } };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

function isPlayoffStarted(season) {
  return getPlayoffGames(String(season)).length > 0;
}

// ── Homepage "Coming up" section ─────────────────────────────────────────────
// Four cards that give people a reason to come back during the week: League (next
// scheduled game day, or the latest results when nothing is scheduled yet) and Papawis
// (next open run) are fixed; the other two are admin-picked on /admin/site
// (home_nextup_card_1 / _2, default Marketplace + Birthdays). A picked card with nothing to
// show this week (no listings, no birthdays…) is swapped for the next card in
// HOME_NEXTUP_CARDS that does have content, so the row is never left with an empty card.
const HOME_NEXTUP_CARDS = [
  { key: 'marketplace', label: 'Marketplace drops' },
  { key: 'birthdays',   label: 'Birthdays this week' },
  { key: 'new_members', label: 'New in the community' },
  { key: 'poll',        label: 'Players are voting' },
  { key: 'video',       label: 'Latest game video' },
];
const HOME_NEXTUP_DEFAULTS = ['marketplace', 'birthdays'];

function homeNextUpLeague(season, games) {
  const today = manilaTodayStr();
  const records = Object.fromEntries((season ? getSeasonStandings(season) : []).map(t => [t.name, `${t.wins}-${t.losses}`]));
  const scheduled = games
    .filter(g => g.scheduled === 1 && !g.under_review && String(g.date).slice(0, 10) >= today)
    .sort((a, b) => String(a.date).localeCompare(String(b.date)));
  if (scheduled.length) {
    const day = String(scheduled[0].date).slice(0, 10);
    return {
      mode: 'upcoming', date: day, season,
      games: scheduled.filter(g => String(g.date).slice(0, 10) === day)
        .map(g => ({ a: g.team_a_name, b: g.team_b_name, recA: records[g.team_a_name] || '', recB: records[g.team_b_name] || '', type: g.game_type, tip: g.tip_time || '' })),
    };
  }
  const played = games
    .filter(g => String(g.season) === String(season) && !g.scheduled && !g.under_review && (Number(g.team_a_score) + Number(g.team_b_score)) > 0)
    .sort((a, b) => String(b.date).localeCompare(String(a.date)));
  if (!played.length) return null;
  const day = String(played[0].date).slice(0, 10);
  return {
    mode: 'results', date: day, season,
    games: played.filter(g => String(g.date).slice(0, 10) === day)
      .map(g => ({ id: g.id, a: g.team_a_name, b: g.team_b_name, scoreA: Number(g.team_a_score), scoreB: Number(g.team_b_score) })),
  };
}

function homeNextUpPapawis() {
  if (getSetting('papawis_enabled', '0') !== '1') return null;
  const today = manilaTodayStr();
  const next = getPapawisGames()
    .filter(g => g.status !== 'cancelled' && g.status !== 'completed' && String(g.date) >= today)
    .sort((a, b) => `${a.date}T${a.start_time || '00:00'}`.localeCompare(`${b.date}T${b.start_time || '00:00'}`))[0];
  if (!next) return { empty: true };
  // Who's in — same confirmed list /papawis shows publicly (guests appear as their
  // sponsoring player's avatar there too). Only the first few are drawn; the rest are "+N".
  const confirmedSignups = getPapawisSignups(next.id).filter(s => s.status === 'confirmed');
  return {
    faces: confirmedSignups.slice(0, 7).map(s => ({ id: s.player_id, name: s.player_name, team: s.team_name || '' })),
    date: next.date, time: formatTimeRange(next.start_time, next.end_time) || next.time_label || '',
    location: next.location || '', maxSlots: Number(next.max_slots) || 0,
    confirmed: Number(next.confirmed_count) || 0, waitlist: Number(next.waitlist_count) || 0,
    price: next.price_per_player ?? next.min_per_player ?? null, hasReferee: !!next.has_referee,
  };
}

// Homepage hero slide for the next Papawis run (leads the carousel while one is posted).
// Same court photo / map, per-head estimate and AI headline the /papawis banner uses; the
// slot count stays hidden while sign-ups haven't opened (held-back rosters stay private).
// A run's picture, as the site picks it: the run's own cover (admin upload), else the court's
// photo, else the map of the address. The homepage hero, the app's Papawis tab and feed card.
function papawisCoverUrl(g, court = getPapawisCourtByName(g.location)) {
  if (g.cover_ver) return `/api/papawis-cover/${encodeURIComponent(g.id)}?v=${g.cover_ver}`;
  if (court?.image_url) return `/api/papawis-court/${encodeURIComponent(court.id)}/photo`;
  const mapQuery = court?.address?.trim() || g.location || '';
  if (mapQuery && getPapawisLocationGeocode(mapQuery)?.map_image) return `/api/papawis-map/photo?loc=${encodeURIComponent(mapQuery)}`;
  return null;
}
function homeHeroPapawis() {
  if (getSetting('papawis_enabled', '0') !== '1') return null;
  const today = manilaTodayStr();
  const games = getPapawisGames();
  const next = games
    .filter(g => g.status !== 'cancelled' && g.status !== 'completed' && String(g.date) >= today)
    .sort((a, b) => `${a.date}T${a.start_time || '00:00'}`.localeCompare(`${b.date}T${b.start_time || '00:00'}`))[0];
  if (!next) return null;
  const court = getPapawisCourtByName(next.location);
  const imgUrl = papawisCoverUrl(next, court);
  const confirmed = getPapawisConfirmedCount(next.id);
  const maxSlots = Number(next.max_slots) || 0;
  const courtRateFallback = next.court_rate_per_hour ? null : (court?.price_per_hour || null);
  const summary = teamsSummary('papawis_summary', 'papawis', papawisSummaryFacts(games));
  return {
    id: next.id, date: next.date, time: formatTimeRange(next.start_time, next.end_time) || next.time_label || '',
    location: next.location || '', imgUrl, isMap: !next.cover_ver && !court?.image_url && !!imgUrl,
    signupsOpen: isPapawisSignupOpenNow(next), opensAt: papawisSignupOpensAtMs(next),
    confirmed, maxSlots, waitlist: Number(next.waitlist_count) || 0,
    price: estimatedPapawisPrice(next, Math.max(confirmed, maxSlots), courtRateFallback),
    headline: summary?.headline || '', body: summary?.body || '',
  };
}

function homeNextUpCardData(key, { players, games, isLoggedIn }) {
  const today = manilaTodayStr();
  if (key === 'marketplace') {
    if (getSetting('marketplace_enabled', '0') !== '1') return null;
    const listings = getMarketplaceListings({ status: 'active' })
      .slice(0, 3)
      .map(l => {
        let photos = [];
        try { photos = JSON.parse(l.photos || '[]'); } catch {}
        return { id: l.id, title: l.title, price: Number(l.price) || 0, compareAt: Number(l.compare_at_price) || 0, hasPhoto: photos.length > 0 };
      });
    return listings.length ? { listings } : null;
  }
  if (key === 'birthdays') {
    // Next 7 days including today, by month-day (year is never shown or used).
    const [ty, tm, td] = today.split('-').map(Number);
    const base = Date.UTC(ty, tm - 1, td);
    const upcoming = [];
    for (const p of players) {
      if (p.status === 'inactive' || !/^\d{4}-\d{2}-\d{2}/.test(String(p.birthday || ''))) continue;
      const [, m, d] = String(p.birthday).slice(0, 10).split('-').map(Number);
      let next = Date.UTC(ty, m - 1, d);
      if (next < base) next = Date.UTC(ty + 1, m - 1, d);
      const inDays = Math.round((next - base) / 86400000);
      if (inDays <= 6) upcoming.push({ id: p.id, name: p.name, team: p.team_name || '', inDays, monthDay: `${m}-${d}` });
    }
    if (!upcoming.length) return null;
    upcoming.sort((a, b) => a.inDays - b.inDays);
    // Birthdays are treated as personal data elsewhere (lib/sensitive-mask.js), so guests
    // only get the count — names and days are for logged-in members.
    return isLoggedIn ? { people: upcoming.slice(0, 5), total: upcoming.length } : { people: [], total: upcoming.length, locked: true };
  }
  if (key === 'new_members') {
    const { members, total } = getRecentlyApprovedMembers(30, 6);
    return members.length ? { members: members.map(m => ({ name: m.full_name, playerId: m.player_id || '' })), total } : null;
  }
  if (key === 'poll') {
    const poll = getAllLeaguePolls().find(p => p.status === 'open');
    if (!poll) return null;
    // Polls carry their own visibility tier — guests only learn that a vote is happening,
    // never the question or options.
    const votes = getLeaguePollVotes(poll.id).length;
    return isLoggedIn
      ? { question: poll.question, options: poll.options, votes, locked: false }
      : { question: '', options: [], votes, locked: true };
  }
  if (key === 'video') {
    const g = games
      .filter(x => x.youtube_url && !x.under_review && (Number(x.team_a_score) + Number(x.team_b_score)) > 0)
      .sort((a, b) => String(b.date).localeCompare(String(a.date)))[0];
    const vid = g && (String(g.youtube_url).match(/(?:youtu\.be\/|[?&]v=|embed\/|shorts\/)([\w-]{11})/) || [])[1];
    if (!vid) return null;
    return { gameId: g.id, date: String(g.date).slice(0, 10), a: g.team_a_name, b: g.team_b_name, scoreA: Number(g.team_a_score), scoreB: Number(g.team_b_score), videoId: vid };
  }
  return null;
}

function buildHomeNextUp({ season, players, games, isLoggedIn }) {
  const league  = homeNextUpLeague(season, games);
  const papawis = homeNextUpPapawis();
  const fixed = [league && { kind: 'league', data: league }, papawis && { kind: 'papawis', data: papawis }].filter(Boolean);

  const valid  = new Set(HOME_NEXTUP_CARDS.map(c => c.key));
  const picked = [1, 2].map((n, i) => {
    const v = getSetting(`home_nextup_card_${n}`, HOME_NEXTUP_DEFAULTS[i]);
    return valid.has(v) ? v : HOME_NEXTUP_DEFAULTS[i];
  });
  const slots = 4 - fixed.length;
  const order = [...new Set([...picked, ...HOME_NEXTUP_CARDS.map(c => c.key)])];
  const extras = [];
  for (const key of order) {
    if (extras.length >= slots) break;
    const data = homeNextUpCardData(key, { players, games, isLoggedIn });
    if (data) extras.push({ kind: key, data });
  }
  const cards = [...fixed, ...extras];
  return cards.length ? { cards, isLoggedIn } : null;
}

// ── Homepage standings block ─────────────────────────────────────────────────
// Same table and tiebreaks as /standings (getSeasonStandings: regular season, complete, not
// under review), plus each team's last-5 form, current streak, a one-line flag when there's
// a story (long streak, record vs point differential), and an auto headline for the race.
function buildHomeStandings(season, games) {
  if (!season) return null;
  const rows = getSeasonStandings(season);
  if (!rows.some(r => r.wins + r.losses > 0)) return null;

  const played = games
    .filter(g => String(g.season) === String(season) && g.game_type === 'regular' && (g.status === 'complete' || g.status === 'final') && !g.under_review && Number(g.team_a_score) + Number(g.team_b_score) > 0)
    .sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const results = {};
  for (const g of played) {
    const sa = Number(g.team_a_score), sb = Number(g.team_b_score);
    if (sa === sb) continue;
    (results[g.team_a_id] ||= []).push(sa > sb ? 'W' : 'L');
    (results[g.team_b_id] ||= []).push(sb > sa ? 'W' : 'L');
  }

  // Avatar stack on each tile: the team's top five this season by MVP score (so it doubles
  // as "who's carrying this team"), topped up in roster order with players who haven't
  // logged a game yet. Count = everyone currently on the roster.
  // While the MVP reveal lock is on, order by PPG instead so the stack can't hint at the race.
  const mvpLocked = isMvpLocked(season);
  const mvpScoreById = Object.fromEntries(getMvpCandidates(season).filter(s => s.gp >= 1).map(s => [s.id, mvpLocked ? s.pts / s.gp : computeMvpScore(s)]));
  const rosterByTeam = {};
  for (const p of getAllPlayers()) if (p.team_id && p.status === 'active') (rosterByTeam[p.team_id] ||= []).push(p);
  const leader = rows[0];

  const teams = rows.map((r, i) => {
    const res = results[r.id] || [];
    const roster = (rosterByTeam[r.id] || [])
      .map((p, k) => ({ p, k, score: mvpScoreById[p.id] ?? -1 }))
      .sort((a, b) => b.score - a.score || a.k - b.k)
      .map(x => ({ id: x.p.id, name: displayPlayerName(x.p.name) }));
    const gp = r.wins + r.losses;
    let streak = 0;
    for (let k = res.length - 1; k >= 0 && res[k] === res[res.length - 1]; k--) streak++;
    const streakType = res[res.length - 1] || '';
    let flag = '';
    if (streak >= 3) flag = streakType === 'W' ? `Won ${streak} straight` : `Lost ${streak} straight`;
    else if (r.wins < r.losses && r.point_diff > 0) flag = 'Better than their record';
    else if (r.wins > r.losses && r.point_diff < 0) flag = 'Winning the close ones';
    else if (streak === 2) flag = streakType === 'W' ? 'Won 2 straight' : 'Lost 2 straight';
    return {
      rank: i + 1, id: r.id, name: r.name, wins: r.wins, losses: r.losses, diff: r.point_diff,
      form: res.slice(-5), flag,
      gb: ((leader.wins - r.wins) + (r.losses - leader.losses)) / 2,
      pct: gp ? r.wins / gp : 0,
      roster: roster.slice(0, 5), rosterCount: roster.length,
    };
  });

  // Headline: the single most interesting fact about the race right now.
  const [first, second] = teams;
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  for (const t of teams) t.safeName = esc(t.name);
  const unbeaten = teams.filter(t => t.losses === 0 && t.wins > 0);
  const rest = teams.slice(1);
  const restTied = rest.length > 1 && rest.every(t => t.wins === rest[0].wins && t.losses === rest[0].losses);
  const rec = t => `${t.wins}-${t.losses}`;
  let headline;
  if (unbeaten.length === 1 && unbeaten[0] === first) {
    headline = `<em>${first.safeName}</em> is the last unbeaten team${restTied ? `, and the other ${rest.length === 3 ? 'three' : rest.length} are tied at ${rec(rest[0])}` : ''}.`;
  } else if (second && first.wins === second.wins && first.losses === second.losses) {
    const tied = teams.filter(t => t.wins === first.wins && t.losses === first.losses);
    headline = `${tied.map(t => `<em>${t.safeName}</em>`).join(tied.length === 2 ? ' and ' : ', ')} are tied for first at ${rec(first)}.`;
  } else if (second) {
    const gb = ((first.wins - second.wins) + (second.losses - first.losses)) / 2;
    headline = `<em>${first.safeName}</em> leads at ${rec(first)}, ${gb} game${gb === 1 ? '' : 's'} ahead of ${second.safeName}.`;
  } else {
    headline = `<em>${first.safeName}</em> leads at ${rec(first)}.`;
  }
  const winless = teams.filter(t => t.wins === 0 && t.losses > 0);
  if (winless.length === 1 && !restTied) headline += ` ${winless[0].safeName} is still looking for its first win.`;

  return { season, headline, teams };
}

// ── Homepage AI summaries ─────────────────────────────────────────────────────
// A generated headline + a sentence or two above Game headlines, Season race and League
// leaders (views/home.js summaryPanel). Each block's facts reduce to a key; the stored
// summary (site setting home_summary_<block>) is only shown while its key still matches,
// so a new result makes it disappear rather than show stale claims. A missing/stale one is
// regenerated in the background — never awaited by the page — at most one call in flight
// per block, with a cooldown after an AI failure. Admins can force it from the homepage.
const HOME_SUMMARY_BLOCKS = new Set(['headlines', 'standings', 'leaders', 'picks', 'comingup']);
const homeSummaryInFlight = new Set();
let homeSummaryCooldownUntil = 0;
const HOME_SUMMARY_COOLDOWN_MS = 10 * 60 * 1000;
// Bump when the prompt changes so every stored summary is rewritten with the new one.
const HOME_SUMMARY_VERSION = 7;

// picksW = homePicksWidget(games, null) and nextUp = buildHomeNextUp({ isLoggedIn: false }):
// both built for a logged-out viewer, since the summary is the same for everyone (so no
// birthday names, poll questions or anyone's own picks can reach the copy).
function homeSummaryContext({ season, games, standings, boards, picksW = null, nextUp = null }) {
  const completed = games
    .filter(g => !g.scheduled && !g.under_review && (Number(g.team_a_score) + Number(g.team_b_score)) > 0)
    .sort((a, b) => String(b.date).localeCompare(String(a.date)));
  return { season, week: season ? (getSeasonLatestWeek(season)?.week ?? null) : null, completed, standings, boards, picksW, nextUp };
}

const summaryDay = ymd => new Date(`${String(ymd).slice(0, 10)}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

// "Who wins?" block facts — the next game day's picks, or the last game day's results.
function picksSummaryFacts(w) {
  const title = s => String(s || '').toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
  const leaderLine = w.leader
    ? `Pickmaster race (net points: +1 per correct pick, −1 per miss): ${w.leader.name} leads on ${fmtPts(w.leader.net)} (${w.leader.correct}–${w.leader.wrong})${w.leader.tied > 1 ? `, tied with ${w.leader.tied - 1} other${w.leader.tied > 2 ? 's' : ''}` : ''}.`
    : 'Pickmaster race: nobody is on the board yet (no picks have settled).';
  if (w.mode === 'open') {
    const leanOf = g => {
      const t = g.counts.a + g.counts.b;
      if (t < 5 || g.counts.a === g.counts.b) return '';
      return title(g.counts.a > g.counts.b ? g.a : g.b);
    };
    const lines = w.games.map(g => {
      const parts = [`${title(g.a)} (${g.recA.w}-${g.recA.l} this season) vs ${title(g.b)} (${g.recB.w}-${g.recB.l} this season)`];
      parts.push(g.h2h.meetings ? `all-time head to head ${title(g.a)} ${g.h2h.a}, ${title(g.b)} ${g.h2h.b}` : 'first ever meeting');
      if (g.odds?.fav) parts.push(`the odds favour ${title(g.odds.fav === 'a' ? g.a : g.b)} at ${g.odds.fav === 'a' ? g.odds.pctA : g.odds.pctB}%`);
      const lean = leanOf(g);
      if (lean) parts.push(`most pickers so far are taking ${lean}`);
      if (g.closed) parts.push('picks are closed');
      return `- ${parts.join('; ')}`;
    });
    const close = fmtCloseTime(w.closeTime);
    return {
      key: `v${HOME_SUMMARY_VERSION}|p|open|${w.ymd}|${w.games.map(g => `${g.id}:${g.odds?.pctA ?? '-'}:${leanOf(g)}:${g.recA.w}-${g.recA.l}:${g.recB.w}-${g.recB.l}:${g.closed ? 1 : 0}`).join(',')}|${w.leader ? `${w.leader.name}:${w.leader.correct}/${w.leader.picks}` : '-'}`,
      kicker: `Who wins? · ${summaryDay(w.ymd)}`,
      section: 'Who wins? (fan picks for the next game day)',
      facts: `"Who wins?" is the league's pick-em: logged-in players pick the winner of each game. Picks close at ${close} on game day, ${summaryDay(w.ymd)}.\nGames:\n${lines.join('\n')}\n${leaderLine}`,
      focus: 'Preview the picks for this game day: frame each matchup with the odds and the head to head, mention which way pickers lean only where the facts say so, and nudge readers to make their picks before the cut-off. Call the people who pick "pickers", never fans.',
    };
  }
  const lines = w.cards.map(s => {
    const g = s.game;
    const win = g.winner === 'a' ? g.a : g.b, lose = g.winner === 'a' ? g.b : g.a;
    const parts = [`${title(win)} beat ${title(lose)} ${Math.max(g.sa, g.sb)}-${Math.min(g.sa, g.sb)}`];
    if (g.odds?.fav) parts.push(`the odds had favoured ${title(g.odds.fav === 'a' ? g.a : g.b)} at ${g.odds.fav === 'a' ? g.odds.pctA : g.odds.pctB}%${s.upset ? ', so this was an upset' : ''}`);
    parts.push(`${s.calledIt.length} of ${s.total} pickers called it`);
    return `- ${parts.join('; ')}`;
  });
  return {
    key: `v${HOME_SUMMARY_VERSION}|p|res|${w.ymd}|${w.cards.map(s => `${s.game.id}:${s.game.sa}-${s.game.sb}:${s.total}:${s.calledIt.length}`).join(',')}|${w.leader ? `${w.leader.name}:${w.leader.correct}/${w.leader.picks}` : '-'}`,
    kicker: `Who called it? · ${summaryDay(w.ymd)}`,
    section: 'Who called it? (how the fan picks went)',
    facts: `"Who wins?" is the league's pick-em: logged-in players pick the winner of each game. Results of the picks for ${summaryDay(w.ymd)}:\n${lines.join('\n')}\n${leaderLine}`,
    focus: 'Sum up how the picks went: which games the pickers called, any upset against the odds, and the Pickmaster race. Call the people who pick "pickers", never fans.',
  };
}

// "Coming up" block facts — one line per card actually on the homepage, public details only.
function comingUpSummaryFacts(nextUp) {
  if (!nextUp?.cards?.length) return null;
  const title = s => String(s || '').toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
  const lines = [];
  for (const c of nextUp.cards) {
    const d = c.data;
    if (c.kind === 'league') {
      if (d.mode === 'upcoming') lines.push(`- Next league game day, ${summaryDay(d.date)}: ${d.games.map(g => `${title(g.a)}${g.recA ? ` (${g.recA})` : ''} vs ${title(g.b)}${g.recB ? ` (${g.recB})` : ''}${g.type === 'playoff' ? ' (playoffs)' : ''}`).join('; ')}. Records are this season's.`);
      else lines.push(`- No league games scheduled yet. Latest results, ${summaryDay(d.date)}: ${d.games.map(g => (g.scoreA > g.scoreB ? `${title(g.a)} beat ${title(g.b)} ${g.scoreA}-${g.scoreB}` : `${title(g.b)} beat ${title(g.a)} ${g.scoreB}-${g.scoreA}`)).join('; ')}.`);
    } else if (c.kind === 'papawis') {
      if (d.empty) lines.push('- Papawis (open pickup runs): no run scheduled yet.');
      else lines.push(`- Next Papawis run (open pickup game, sign up on the site): ${summaryDay(d.date)}${d.time ? `, ${d.time}` : ''}${d.location ? ` at ${d.location}` : ''}. ${d.maxSlots && d.confirmed >= d.maxSlots ? 'Every slot is already taken, but players can join the waitlist right now (the waitlist is already open; the date is when the run itself happens).' : 'Slots are still open, sign-ups are open now.'}${d.hasReferee ? ' There will be a referee.' : ''}`);
    } else if (c.kind === 'marketplace') {
      lines.push(`- Marketplace (group buys): ${d.listings.map(l => `"${l.title}"`).join(', ')} open for orders.`);
    } else if (c.kind === 'birthdays') {
      lines.push(`- ${d.total === 1 ? 'One player has a birthday' : `${d.total} players have birthdays`} this week (names are only shown to logged-in members).`);
    } else if (c.kind === 'new_members') {
      lines.push(`- New members joined the community in the last 30 days.`);
    } else if (c.kind === 'poll') {
      lines.push('- A players\x27 poll is open for voting (logged-in members only).');
    } else if (c.kind === 'video') {
      lines.push(`- Latest game video is up: ${title(d.a)} ${d.scoreA}-${d.scoreB} ${title(d.b)}, ${summaryDay(d.date)}.`);
    }
  }
  if (!lines.length) return null;
  const facts = `What's coming up around the WKND community:\n${lines.join('\n')}`;
  return {
    key: `v${HOME_SUMMARY_VERSION}|n|${createHash('sha1').update(facts).digest('hex').slice(0, 16)}`,
    kicker: 'Coming up · This week',
    section: 'Coming up (what\x27s next around the community)',
    facts,
    focus: 'Preview the week ahead: lead with the next league game day or the next Papawis run, whichever comes first, then one more thing worth knowing. Point readers to what they can do (sign up, join the waitlist, vote, shop) — only actions the facts mention. Every date is the day the event itself happens; never attach a date to anything else (like when a waitlist or sign-up opens).',
  };
}

function homeSummaryFacts(block, ctx) {
  const after = ctx.week ? `AFTER WEEK ${ctx.week}` : `SEASON ${ctx.season}`;
  const title = s => String(s || '').toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
  if (block === 'headlines') {
    const day = ctx.completed[0] ? String(ctx.completed[0].date).slice(0, 10) : null;
    if (!day) return null;
    const dayGames = ctx.completed.filter(g => String(g.date).slice(0, 10) === day);
    const dayLabel = new Date(`${day}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase();
    const lines = dayGames.map(g => {
      const t = parseWriteup(g.game_writeup || '').title;
      const aWin = Number(g.team_a_score) > Number(g.team_b_score);
      const [w, l, ws, ls] = aWin ? [g.team_a_name, g.team_b_name, g.team_a_score, g.team_b_score] : [g.team_b_name, g.team_a_name, g.team_b_score, g.team_a_score];
      return `- ${title(w)} beat ${title(l)} ${ws}-${ls}${g.game_type === 'playoff' ? ' (playoffs)' : ''}${t ? ` (recap headline: "${t}")` : ''}`;
    });
    const records = ctx.standings?.teams?.map(t => `${title(t.name)} ${t.wins}-${t.losses}${t.flag ? ` (${t.flag.toLowerCase()})` : ''}`).join(', ');
    // The day's major highlights (records, big nights, drama), so a league record reaches the
    // homepage even when the recap headline didn't say it. Up to 2 musts for 1-2 sentences.
    const dayHl = dayGames.flatMap(g => cachedGameHighlights(g)).filter(h => h.tier === 'major');
    const musts = mustMentions(dayHl, 2);
    return {
      key: `v${HOME_SUMMARY_VERSION}|h|${day}|${dayGames.map(g => `${g.id}:${g.team_a_score}-${g.team_b_score}`).join(',')}|h${sig(dayHl.map(h => h.text))}`,
      kicker: `The story · After ${dayLabel} games`,
      section: 'Game headlines',
      // Two sentences can't hold the day's ten career highs: the musts plus three others.
      facts: `Results on ${day}:\n${lines.join('\n')}${records ? `\nTeam records now: ${records}` : ''}${dayHl.length ? `\n\n${highlightsBlock(dayHl, musts, { maxRest: 3 })}` : ''}`,
      musts,
      focus: `Sum up what happened on this game day, leading with ${musts.length ? 'the biggest MAJOR HIGHLIGHT' : 'the most important result'}. Each game is a separate event — never connect one game\x27s result to another team\x27s streak or record.`,
    };
  }
  if (block === 'standings') {
    const teams = ctx.standings?.teams;
    if (!teams?.length) return null;
    const lines = teams.map(t => `- ${t.rank}. ${title(t.name)} ${t.wins}-${t.losses}, ${t.gb > 0 ? `${t.gb} games back` : 'first place'}, point differential ${t.diff > 0 ? '+' : ''}${t.diff}, last results ${t.form.join('') || 'none'}${t.flag ? `, ${t.flag.toLowerCase()}` : ''}`);
    // Settled standings are said as such, so the block doesn't sell a race that's over.
    const lock = seasonLockLine(ctx.season);
    return {
      key: `v${HOME_SUMMARY_VERSION}|s|${ctx.season}|${teams.map(t => `${t.name}:${t.wins}-${t.losses}:${t.diff}`).join(',')}${lock ? '|locked' : ''}`,
      kicker: `The race · ${after}`,
      section: 'Season race (standings)',
      facts: `Season ${ctx.season} standings:\n${lines.join('\n')}${lock ? `\n${lock}` : ''}`,
      focus: lock
        ? 'The regular-season order is settled: say who finished where and what it sets up for the playoffs. There is no race left; never talk about anyone still climbing or catching up.'
        : 'Describe the state of the standings race: who leads and by how much, and the most interesting story further down.',
      notesFor: teams.map(t => title(t.name)),
    };
  }
  if (block === 'leaders') {
    const boards = ctx.boards || [];
    if (!boards.length) return null;
    const lines = boards.map(c => `- ${c.title} (${c.label}): ${c.top.map((p, i) => `${i + 1}. ${displayPlayerName(p.name)} (${title(p.team)}) ${p.value}`).join(', ')}`);
    // The same facts regrouped per player, so "who shows up where" doesn't have to be
    // inferred (that's where the model went wrong without it).
    const byPlayer = new Map();
    for (const c of boards) c.top.forEach((p, i) => {
      const k = p.id;
      if (!byPlayer.has(k)) byPlayer.set(k, { name: displayPlayerName(p.name), team: title(p.team), spots: [] });
      byPlayer.get(k).spots.push(`#${i + 1} ${c.title.toLowerCase()}`);
    });
    const playerLines = [...byPlayer.values()].sort((a, b) => b.spots.length - a.spots.length)
      .map(p => `- ${p.name} (${p.team}): ${p.spots.join(', ')}`);
    return {
      key: `v${HOME_SUMMARY_VERSION}|l|${ctx.season}|${boards.map(c => `${c.label}:${c.top.map(p => `${p.id}=${p.value}`).join('/')}`).join(',')}`,
      kicker: `The leaders · ${after}`,
      section: 'League leaders',
      facts: `Season ${ctx.season} league leaders, per game, top 3 in each category:\n${lines.join('\n')}\n\nThe same, per player (only these placings exist):\n${playerLines.join('\n')}`,
      focus: 'Pick the one or two most interesting leaderboard stories (e.g. who leads scoring, or a player who shows up in several categories). A player only "leads" a category where they are #1.',
    };
  }
  if (block === 'picks') return ctx.picksW ? picksSummaryFacts(ctx.picksW) : null;
  if (block === 'comingup') return comingUpSummaryFacts(ctx.nextUp);
  return null;
}

// ── Headline + body copy: the one writer for every page ─────────────────────────────────
// Every "headline over a short body" on the site goes through writeHeadlineCopy: homepage
// blocks, /teams, the section writeups (standings, playoffs, picks, MVP/DPOY, game page), the
// Papawis summary and the matchup storyline. A page only describes what differs:
//
//   f:    { facts, focus, section, key, kicker?, notesFor?, musts?, highlights? }
//         — facts are built in code first (the analysis); musts = MAJOR highlights to cover
//   opts: label        log name
//         where        the page named in the prompt ('homepage', '/teams', …)
//         intro        replaces the opening line ("You write …") when the piece isn't a
//                      section header (the storyline)
//         headline     { max: 70, period: false, bold: 'names' | 'key' }
//         body         { sentences: '1-2', words: 45 }
//         highsOk      career/season highs and double-/triple-doubles may be named when the
//                      facts give them (records always need a record highlight)
//         strict       2 sentences max, digits only, no cause-and-effect (strictSummaryIssue)
//         rules        extra prompt lines for this page
//         checks       extra code checks (text → problems), e.g. comparisonProblems
//         banned       a page's own banned regex on top of the shared list
//         voice        ai-voices feature (default 'home'), temperature cap, maxTokens, tries
//         factCheck    the temperature-0 AI fact check (default on)
//         save(out)    stores the copy; returns nothing
// Throws when no draft passes (callers keep their cooldowns / "no summary" fallbacks).
async function writeHeadlineCopy(f, opts = {}) {
  const hl = { max: 70, period: false, bold: 'names', ...(opts.headline || {}) };
  const bd = { sentences: '1-2', words: 45, ...(opts.body || {}) };
  const musts = f.musts || [];
  const voice = pickVoice(opts.voice || 'home', { date: new Date().toISOString().slice(0, 10) });
  const intro = opts.intro || `You write the short headline and summary that sits above the "${f.section}" section on the WKND Basketball ${opts.where || 'homepage'} — a recreational league whose players read every word.`;
  const rules = [
    hl.bold === 'key'
      ? `- headline: one sentence, at most ${hl.max} characters${hl.period ? ', ending with a period' : ', no trailing period'}. Wrap the one or two key phrases (a team name or the deciding number) in **double asterisks**. Team names in title case.`
      : `- headline: at most ${hl.max} characters${hl.period ? ', ending with a period' : ', no trailing period'}. Wrap every team or player name in **double asterisks**, e.g. **White** or **Vin Salenga**. Team names in title case.`,
    `- body: ${bd.sentences} sentences, at most ${bd.words} words, plain text — no asterisks, markdown or emoji.${bd.extra ? ` ${bd.extra}` : ''}`,
    musts.length ? `- MAJOR HIGHLIGHTS in the facts must all appear (headline or body), each with its player or team named, its number, and the word that makes it special (record, streak, career high…). The biggest one leads.` : '',
    `- Every number, record, ranking or streak must come straight from the facts, copied exactly. Never calculate a difference, total or percentage of your own. Don't invent stats, comparisons or history. Only mention a streak if the facts state it, and say whose streak it is exactly as the facts do.`,
    `- If two facts seem to disagree, leave that detail out rather than guess.`,
    opts.highsOk
      ? '- Only call something a career high, a season high, a double-double or a triple-double where the facts say so, exactly as they say it. Never call anything a record, a first or a best-ever unless a highlight says so.'
      : '- Never call anything a record, a first, a best-ever or a career high unless a highlight in the facts says so, in its words.',
    `- Season totals (record, point differential, per-game averages) describe the whole season; never attach them to a single game.`,
    `- Write finished copy only: no questions to yourself, no corrections, no notes or alternatives.`,
    `- Banned (rejected in code): ${BANNED_HINT}.`,
    `- Write numbers as digits, copied from the facts.`,
    opts.strict ? `- Never claim one stat causes or explains another (no "because", "explains", "drives", "thanks to", "fuels" — and no "kasi" or "kaya" between two stats either). State the numbers side by side and let the reader connect them.\n- Write every number as digits, never as a word.` : '',
    ...(opts.rules || []),
    // Season race also gets one short note per team card (f.notesFor = the team names).
    f.notesFor ? `- notes: exactly one note per team (${f.notesFor.join(', ')}), each one sentence of at most 12 words, plain text, about that team only — the most telling fact about its season so far. Don't start with the team's name.` : '',
  ].filter(Boolean).join('\n');
  // The voice sits at the top and again as the last word (the model obeys the tail), with this
  // piece's flavour line; "how to say it" keeps the numbers English while the voice shapes
  // the rest.
  const flavor = voiceFlavor(voice, f.key || f.section || '', bd.words || 45);
  // Brief, facts, focus, rules, then the voice last and once (the model obeys the tail).
  const prompt = `${intro}
Voice: ${voice.name} — the guide is at the end; headline and body are both written in it.

FACTS (the only things you may state):
${f.facts}

${f.focus || ''}

Rules:
${rules}

VOICE — ${voice.name}: ${voice.guide}${flavor ? `\n${flavor}` : ''}${voice.sample ? `\nA taste of the voice (style only; its words and events are not facts): "${voice.sample}"` : ''}
HOW TO SAY IT: numbers, names and stat words come from the facts in English digits; everything around them is in the voice. The voice is in the sentence shape, not in added words. A short aside of 4 words or fewer doesn't count as a sentence.`;
  // A voice that needs heat (conyo) gets 0.85 where these blocks are usually capped at 0.6;
  // the number and claim checks catch what extra heat invents.
  const tempCap = voiceTraits(voice).hot ? Math.max(opts.temperature ?? 0.6, 0.85) : (opts.temperature ?? 0.6);
  const schema = {
    type: 'object',
    properties: {
      headline: { type: 'string' },
      body: { type: 'string' },
      // One required field per team (not a free-form list — models skipped that).
      ...(f.notesFor ? { notes: { type: 'object', properties: Object.fromEntries(f.notesFor.map(t => [t, { type: 'string' }])), required: f.notesFor } } : {}),
    },
    required: ['headline', 'body', ...(f.notesFor ? ['notes'] : [])],
  };
  // The draft as stored: trimmed fields, notes keyed by upper-case team name (a team the
  // model skipped keeps its automatic label on the card).
  const shape = data => {
    const notes = {};
    for (const t of f.notesFor || []) {
      const note = String(data?.notes?.[t] || '').replace(/\*\*/g, '').trim().slice(0, 140);
      if (note) notes[t.toUpperCase()] = note;
    }
    return { headline: String(data?.headline || '').trim().slice(0, hl.max + 50), body: String(data?.body || '').replace(/\*\*/g, '').trim(), notes };
  };
  const noteText = d => Object.entries(d.notes).map(([t, n]) => `${t}: ${n}`).join('\n');
  const label = opts.label || `Summary (${f.section})`;
  const out = await runWriter({
    prompt, label, tries: opts.tries || 3,
    generate: async p => shape((await generateJson(p, schema, { tier: opts.tier || (bd.words > 90 ? 'medium' : 'short'), temperature: Math.min(aiTemperature(), tempCap), maxTokens: opts.maxTokens || (f.notesFor ? 800 : 600) })).data),
    text: d => `${d.headline.replace(/\*\*/g, '')}. ${d.body}${d.notes && Object.keys(d.notes).length ? `\n${noteText(d)}` : ''}`,
    checks: [
      (t, d) => (!d.headline ? ['the headline is empty'] : []),
      (t, d) => (d.headline.replace(/\*\*/g, '').length > hl.max + 10 ? [`the headline is ${d.headline.replace(/\*\*/g, '').length} characters (at most ${hl.max})`] : []),
      (t, d) => (bd.words && d.body.split(/\s+/).filter(Boolean).length > bd.words + 15 ? [`the body is ${d.body.split(/\s+/).length} words (at most ${bd.words})`] : []),
      (t, d) => (f.notesFor && !Object.keys(d.notes).length ? ['it returned no team notes'] : []),
      t => missingHighlights(t, musts).map(m => `it leaves out a MAJOR HIGHLIGHT: ${m}`),
      t => numberProblems(t, f.facts, { pairs: false, spelled: !opts.strict }),
      t => claimProblems(t, f.facts),
      t => storyProblems(t, f.facts),
      { style: true, fn: t => bannedProblems(t) },
      { style: true, fn: t => (opts.banned && t.match(opts.banned) ? [`it uses the word "${t.match(opts.banned)[0]}"`] : []) },
      (t, d) => (opts.strict ? [strictSummaryIssue(d.headline, d.body, f.facts)].filter(Boolean) : []),
      { style: true, fn: t => voiceProblems(t, voice) },
      ...(opts.checks || []),
      // Second opinion at temperature 0, only once every free check passes.
      ...(opts.factCheck === false ? [] : [{ costly: true, fn: async (t, d) => factCheckHomeSummary(f, d.headline, d.body, noteText(d)) }]),
    ],
  });
  // Only fatal leftovers (facts, format, highlights) reject the piece: a true 45-word section
  // whose last slip is a voice-density note is kept, not thrown away (a game page with no
  // section at all is worse than a slightly flat one).
  const styleOnly = out.problems.length && !out.fatal;
  if (out.problems.length && !styleOnly) {
    // code 'checks': every draft failed the checks (callers back off longer than for an outage).
    const err = new Error(`${label}: no draft passed the checks (${out.problems.join('; ')})`);
    err.code = 'checks';
    err.problems = out.problems;
    throw err;
  }
  if (styleOnly) console.warn(`${label}: kept with style notes (${out.problems.join('; ')})`);
  const copy = out.draft;
  if (opts.save) opts.save(copy);
  return copy;
}

// Homepage blocks, /teams, the section writeups and Papawis: writeHeadlineCopy saved under
// opts.settingKey (default home_summary_<block>). where / strict / highsOk as above.
async function generateHomeSummary(block, f, opts = {}) {
  return writeHeadlineCopy(f, {
    ...opts, label: `Summary (${block})`,
    save: ({ headline, body, notes }) => setSetting(opts.settingKey || `home_summary_${block}`, JSON.stringify({ key: f.key, kicker: f.kicker, headline, body, notes, at: Date.now() })),
  });
}

// The teams summaries' extra checks — each one a slip the fact check let through when the
// mockup copy was generated (2026-10-11): a 3-sentence body, "Nine players…" dodging the
// digits-only number guard, and "That gap explains why…". Returns a reason, or ''.
const SPELLED_NUMBERS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty'];
function strictSummaryIssue(headline, body, facts) {
  // A short aside ("Grabe lang.") rides with the sentence before it (lib/writer.js).
  const sentences = countSentences(String(body).replace(/\*\*/g, ''));
  if (sentences > 2) return `the body has ${sentences} sentences (at most 2)`;
  const text = `${headline} ${body}`.replace(/\*\*/g, '');
  const factNums = new Set(String(facts).match(/\d+(?:\.\d+)?/g) || []);
  // zero to three are skipped: "one of", "the two teams", "from three" read as words.
  for (const w of text.toLowerCase().match(/[a-z]+/g) || []) {
    const n = SPELLED_NUMBERS.indexOf(w);
    if (n > 3 && !factNums.has(String(n))) return `it spells out a number ("${w}") that isn't in the facts`;
  }
  // Taglish "because" too (the conyo voice): kasi, dahil, kaya ("that's why").
  if (/\b(explains?|because|thanks to|drives?|driven by|fuels?|fueled by|powered by|leads? to|kasi|dahil|kaya)\b/i.test(text)) return 'it claims one stat causes or explains another (in any language: no "because", "kasi", "kaya")';
  return '';
}

// The temperature-0 second opinion for any longer copy (the recap): every claim in `text`
// against `facts`. Returns the problems ([] = all supported). Run as a { costly } check in
// runWriter, so it only fires once the free code checks pass.
async function factCheckCopy(facts, text, what = 'game recap') {
  const prompt = `Check this ${what} for a recreational basketball league against the facts it was written from.

COPY
${text}

FACTS
${facts}

Go through the copy sentence by sentence and list every statement the facts do not directly support. Look hard for these, each seen in a real draft:
- who won and who lost mixed up, or a team said to "drop"/"fall" after a win;
- a streak described as still going when the facts say it ENDED, or a streak the facts don't give;
- a margin or total called a "run" (runs are only the "N unanswered points" the facts give), or a run, lead or comeback bigger than the facts say;
- a team said to have led, blown a lead or come back when the facts don't say so;
- a previous record holder, season or date that differs from the facts (e.g. "in Season 3" when the facts say Season 4);
- "a Season 3 record" when the facts say "the most since Season 3";
- a career high described as "matching" a previous best when the facts give a NEW one (or the other way round), or a career/season high, record or first place the facts don't state;
- a stat given to the wrong player or team, wrong numbers or scores, or numbers calculated rather than copied;
- a play the play-by-play doesn't show, or details copied from a style example rather than the facts.
Not problems: opinions, tone, slang, voice and wording; "league record" / "record" for what the facts call the most since Season 3 (box scores start there), as long as the copy doesn't say "ever" or "all-time"; a season average "through this game" next to a lower average "coming in" (both are true). Only list a statement whose content the facts contradict or don't contain. If everything is supported, return accurate=true and an empty problems list.`;
  const schema = {
    type: 'object',
    properties: { accurate: { type: 'boolean' }, problems: { type: 'array', items: { type: 'string' } } },
    required: ['accurate', 'problems'],
  };
  const { data } = await generateJson(prompt, schema, { tier: 'check', temperature: 0, maxTokens: 600, openaiModel: FACT_CHECK_MODEL });
  if (data?.accurate) return [];
  const raw = (data?.problems || []).map(p => String(p).slice(0, 200)).filter(Boolean);
  const problems = realFactProblems(raw);
  // Every complaint was an omission → the copy is accurate.
  if (raw.length && !problems.length) return [];
  return problems.length ? problems.map(p => `fact check: ${p}`) : ['fact check: unspecified inaccuracy'];
}

// A Regenerate button's error: what the drafts got wrong when they failed the checks (so the
// admin knows it wasn't the AI provider), else the provider message.
function writerError(res, err) {
  if (err?.code === 'checks') {
    const list = (err.problems || []).slice(0, 2).map(p => String(p).replace(/^it /, '').replace(/^fact check: /, '').slice(0, 140));
    return res.status(422).json({ error: `No draft passed the checks after 3 tries${list.length ? `: ${list.join('; ')}` : ''}. Try again, or it rewrites itself after the next result.` });
  }
  return res.status(502).json({ error: 'The AI provider failed — try again in a bit.' });
}

// The fact checkers (small models) keep flagging things the copy simply LEFT OUT ("Maroon is
// 3-3, but the facts say 1.5 games back, which is not mentioned"), even when told omissions
// are fine — and that rejected every draft of the homepage standings block (2026-10-20).
// Short copy can't say everything; only a statement the facts contradict is a problem.
const OMISSION_COMPLAINT = /\b(not mentioned|isn'?t mentioned|is not mentioned|no mention|does(?: not|n'?t) (?:mention|clarify|specify|include|state|say|note|explain|address|reference)|without (?:specifying|mentioning|clarifying|noting|stating|including)|fails? to (?:mention|include|specify|note|clarify)|omit(?:s|ted|ting)?|leaves? out|left out|missing from the copy|not (?:stated|included|specified|clarified) in the copy|could (?:also )?(?:mention|include))\b/i;
// Complaints that admit the statement is right, or only object to wording, tone or opinion
// ("Correct, but the phrasing is subjective", "accurate, but it lacks context").
const NOT_AN_ERROR = /\b(correct,? but|is (?:accurate|correct)(?:,| but)|accurate,? but|subjective|lacks? context|without context|could be (?:seen as )?misleading|is misleading|may be misleading|implies|phrasing|tone|opinion|not a factual statement|vague)\b/i;
function realFactProblems(list) {
  return list.filter(p => !OMISSION_COMPLAINT.test(p) && !NOT_AN_ERROR.test(p));
}
// The model the fact checks run on (OpenAI): a stronger one than the writers — gpt-4o-mini
// judging gpt-4o-mini flagged correct lines ("WWWLL… not lost 2 straight"). Short calls, so
// the cost stays at a fraction of a cent. Override with FACT_CHECK_MODEL.
const FACT_CHECK_MODEL = process.env.FACT_CHECK_MODEL || 'gpt-4.1-mini';

// Returns the problems found ([] = every claim is supported by the facts).
async function factCheckHomeSummary(f, headline, body, notes = '') {
  const prompt = `Check this homepage copy for a basketball league against the facts.

COPY
Headline: ${headline.replace(/\*\*/g, '')}
Body: ${body}${notes ? `\nPer-team notes:\n${notes}` : ''}

FACTS
${f.facts}

List every statement in the copy that the facts do not directly support: wrong numbers, wrong rankings, a player "leading" something they are not #1 in, streaks and links between games that the facts don't state, a "record" / "first" / "best-ever" / "career high" no highlight gives, or a season total presented as if it came from one game.
Not problems: opinions, tone, slang and wording; leaving a fact out (short copy can't say everything); "league record" / "team record" / "record" for what a highlight calls the most since Season 3 (box scores start there), as long as the copy doesn't say "ever" or "all-time". Only list a statement whose content the facts contradict or don't contain. If everything is supported, return accurate=true and an empty problems list.`;
  const schema = {
    type: 'object',
    properties: { accurate: { type: 'boolean' }, problems: { type: 'array', items: { type: 'string' } } },
    required: ['accurate', 'problems'],
  };
  const { data } = await generateJson(prompt, schema, { tier: 'check', temperature: 0, maxTokens: 500, openaiModel: FACT_CHECK_MODEL });
  if (data.accurate) return [];
  const raw = (data.problems || []).map(p => String(p).slice(0, 200)).filter(Boolean);
  const problems = realFactProblems(raw);
  if (raw.length && !problems.length) return [];
  return problems.length ? problems : ['unspecified inaccuracy'];
}

// Current summaries for the page; kicks off background generation for any that are stale.
function getHomeSummaries(ctx) {
  const out = {};
  for (const block of HOME_SUMMARY_BLOCKS) {
    const s = homeSummaryBlock(block, ctx);
    if (s) out[block] = s;
  }
  return out;
}

// One homepage summary block: the stored copy when it matches the current facts, else null
// (and a background rewrite starts). Also used on its own by /picks, which shows the
// homepage's "Who wins?" writeup above its Open picks.
function homeSummaryBlock(block, ctx) {
  const f = homeSummaryFacts(block, ctx);
  if (!f) return null;
  let stored = null;
  try { stored = JSON.parse(getSetting(`home_summary_${block}`, '') || 'null'); } catch {}
  if (stored && stored.key === f.key) {
    return { kicker: stored.kicker, headline: stored.headline, body: stored.body, notes: stored.notes || {} };
  }
  if (aiAvailable() && !homeSummaryInFlight.has(block) && Date.now() >= homeSummaryCooldownUntil) {
    homeSummaryInFlight.add(block);
    generateHomeSummary(block, f)
      .catch(err => { console.error(`Home summary (${block}) failed:`, err.message); homeSummaryCooldownUntil = Date.now() + HOME_SUMMARY_COOLDOWN_MS; })
      .finally(() => homeSummaryInFlight.delete(block));
  }
  return null;
}

app.post('/admin/home-summary/regenerate', requireAuth, express.json(), async (req, res) => {
  const block = String(req.body?.block || '');
  if (!HOME_SUMMARY_BLOCKS.has(block)) return res.status(400).json({ error: 'Unknown block' });
  if (!aiAvailable()) return res.status(400).json({ error: 'No AI API key configured.' });
  const season = getPortalCurrentSeason();
  const games = getAllGames();
  const showRosterMoves = getSetting('home_show_roster_moves', '0') === '1';
  const ctx = homeSummaryContext({
    season, games,
    standings: buildHomeStandings(season, games),
    boards: showRosterMoves ? [] : leaderBoards(buildLeaderPlayers(season)),
    picksW: block === 'picks' ? homePicksWidget(byDate(games), null) : null,
    nextUp: block === 'comingup' ? buildHomeNextUp({ season, players: getAllPlayers(), games, isLoggedIn: false }) : null,
  });
  const f = homeSummaryFacts(block, ctx);
  if (!f) return res.status(400).json({ error: 'Nothing to summarise yet.' });
  try {
    await generateHomeSummary(block, f);
    res.json({ ok: true });
  } catch (err) {
    console.error(`Home summary (${block}) regenerate failed:`, err.message);
    writerError(res, err);
  }
});

// Homepage MVP Race sidebar (stands in for Player Highlights while mvp_race_enabled is on).
// Same scoring, ordering and week-over-week movement as /mvp, but read-only on writeups:
// only an already-cached one is shown for the leader — the homepage never triggers AI
// generation, that stays on /mvp itself. Returns null when there's no race to show yet.
function buildHomeMvpRace(season, completedGames, viewerId = null) {
  if (!season) return null;
  // MVP reveal lock: the ten cases shuffled (mvpLockTen) with cached forecasts only, and the
  // viewer's podium ballot. No score, rank or movement reaches the card.
  if (isMvpLocked(season)) {
    const ten = mvpLockTen(season).map(c => cachedLockWriteup(c, season));
    return ten.length ? { season, locked: true, ten, ballot: mvpBallotState(season, viewerId) } : null;
  }
  settleMvpPodium(season); // the podium result notifications, once, after the reveal
  const top = getMvpCandidates(season)
    .filter(s => s.gp >= 1)
    .map(s => ({ player: s, stats: s, mvpScore: computeMvpScore(s) }))
    .sort((a, b) => b.mvpScore - a.mvpScore)
    .slice(0, 6); // frontrunner + a #2–6 ladder in the homepage sidebar
  if (!top.length) return null;

  const prevRanks = mvpPrevRanks(season, completedGames);
  for (const c of top) c.prevRank = prevRanks ? (prevRanks[c.player.id] ?? null) : undefined;
  top[0].writeup = getMvpWriteup(top[0].player.id, season, mvpStatsKey(top[0].stats));

  const week = new Set(completedGames
    .filter(g => String(g.season) === String(season) && g.game_type === 'regular' && g.date)
    .map(g => String(g.date).slice(0, 10))).size;
  return { season, week, final: isPlayoffStarted(season), candidates: top };
}

app.get('/awards', (req, res) => {
  const currentSeason = getPortalCurrentSeason();
  const season = Number(req.query.season) || Number(currentSeason) || 3;
  const awards = getSeasonAwards(season);
  // awards_enabled hides the page while a new season has nothing decided yet, but a season
  // that already has awards (e.g. a Facebook-shared link to a past season) should stay reachable.
  if (getSetting('awards_enabled', '1') === '0' && !awards.length) return res.status(404).send(
    renderPage(req, { title: 'Not Found', currentPath: '/awards', body: '<div class="container"><p style="padding:40px;color:var(--text-muted)">Page not found.</p></div>' })
  );
  const availableSeasons = getAwardSeasons();
  const visibleSections = new Set(AWARD_SECTION_KEYS.filter(k => getSetting(`award_show_${k}`, '0') !== '0'));
  const articles = Object.fromEntries(AWARD_SECTION_KEYS.map(k => [k, getSetting(`award_article_${k}_${season}`, '')]));
  for (const award of awards) {
    if (['all_wknd_1', 'all_wknd_2', 'all_wknd_def', 'champion'].includes(award.award_type)) {
      const key = `${award.award_type}_${award.player_id}`;
      articles[key] = getSetting(`award_article_${key}_${season}`, '');
    }
  }
  res.send(renderPage(req, {
    title: `Season ${season} Awards — WKND Basketball`,
    currentPath: '/awards',
    body: awardsPage({ awards, season, availableSeasons, visibleSections, articles }),
  }));
});

