app.get('/admin/mvp/photo-options', requireAuth, (req, res) => {
  const season = Number(req.query.season);
  const pid = String(req.query.player_id || '');
  if (!season || !pid) return res.status(400).json({ error: 'Missing season or player' });
  const enc = encodeURIComponent(pid);
  const options = [{ key: 'profile', label: 'Profile photo', url: playerPhotoUrl(pid) }];
  if (getPlayerPhotoOriginal(pid)) options.push({ key: 'original', label: 'Profile photo (uncropped)', url: `/admin/player-photo-original/${enc}` });
  for (const r of getPlayerAwardPhotoKeys(pid)) {
    if (r.award_type === 'mvp_race') continue;
    options.push({
      key: `award:${r.season}:${r.award_type}:${r.slot}`,
      label: `S${r.season} ${(AWARD_OG_BADGE[r.award_type]?.label || r.award_type).toLowerCase().replace(/\b\w/g, c => c.toUpperCase())}${r.slot ? ` #${r.slot + 1}` : ''}`,
      url: `/admin/award-photo/${r.season}/${encodeURIComponent(r.award_type)}/${enc}/${r.slot}`,
    });
  }
  const rows = getAwardPhotoOverridesForPlayer(season, 'mvp_race', pid);
  const d = rows[0] || null, m = rows[1] || null;
  const isData = (u) => typeof u === 'string' && u.startsWith('data:');
  const now = Date.now();
  const desktop = d
    ? { source: isData(d.photo_url) ? 'current' : 'profile', currentUrl: isData(d.photo_url) ? `/api/mvp/${season}/${enc}/photo?v=${now}` : null, offset_x: d.offset_x, offset_y: d.offset_y, zoom: d.zoom }
    : { source: 'profile', currentUrl: null, offset_x: 50, offset_y: 50, zoom: 1 };
  const phone = m
    ? { set: true, source: isData(m.photo_url) ? 'current' : m.photo_url === 'profile' ? 'profile' : 'same', currentUrl: isData(m.photo_url) ? `/api/mvp/${season}/${enc}/photo?slot=1&v=${now}` : null, offset_x: m.offset_x, offset_y: m.offset_y, zoom: m.zoom }
    : { set: false, source: 'same', currentUrl: null, offset_x: desktop.offset_x, offset_y: Math.min(desktop.offset_y, MVP_PHONE_DEFAULT_Y), zoom: desktop.zoom };
  res.json({ options, desktop, phone });
});

// Body: { season, player_id, desktop: {...}, phone: {...} | 'reset' | null }. Each side is
// { source, dataUrl?, offset_x, offset_y, zoom } where source is 'current' (keep that
// slot's saved photo, re-crop only) | 'profile' | 'original' |
// 'award:<season>:<type>:<slot>' (copy that graphic's photo) | 'upload' (dataUrl), plus
// 'same' (phone only: whatever photo desktop shows). phone null = leave it as it is;
// 'reset' = drop it so phones go back to following desktop.
app.post('/admin/mvp/photo', requireAuth, express.json({ limit: '40mb' }), async (req, res) => {
  const season = Number(req.body?.season);
  const pid = String(req.body?.player_id || '');
  if (!season || !pid) return res.status(400).json({ error: 'Missing season or player' });
  const existing = getAwardPhotoOverridesForPlayer(season, 'mvp_race', pid);
  const clamp = (v, lo, hi, d) => (Number.isFinite(Number(v)) ? Math.min(hi, Math.max(lo, Number(v))) : d);

  async function resolvePhoto(side, slot) {
    const source = String(side?.source || 'current');
    if (source === 'current') return existing[slot]?.photo_url || '';
    if (source === 'same') return '';
    if (source === 'profile') return slot === 1 ? 'profile' : '';
    if (source === 'original') return getPlayerPhotoOriginal(pid) || '';
    if (source.startsWith('award:')) {
      const [, s, type, sl] = source.split(':');
      const url = getAwardPhotoOverridesForPlayer(Number(s), type, pid)[Number(sl) || 0]?.photo_url || '';
      if (!url) throw new Error('That photo no longer exists.');
      return url;
    }
    if (source === 'upload') {
      const buf = parseDataUrl(side?.dataUrl);
      if (!buf) throw new Error('No image received.');
      try { return await compressSourceImage(buf); }
      catch (err) { console.error('MVP photo compress error:', err); throw new Error('Could not read that image.'); }
    }
    return '';
  }

  try {
    const desk = req.body?.desktop || {};
    const photo_url = await resolvePhoto(desk, 0);
    const offset_x = clamp(desk.offset_x, 0, 100, 50);
    const offset_y = clamp(desk.offset_y, 0, 100, 50);
    const zoom = clamp(desk.zoom, 1, 3, 1);
    if (!photo_url && Math.abs(offset_x - 50) < 0.5 && Math.abs(offset_y - 50) < 0.5 && Math.abs(zoom - 1) < 0.01) {
      deleteAwardPhotoOverride(season, 'mvp_race', pid, 0);
    } else {
      upsertAwardPhotoOverride({ season, award_type: 'mvp_race', player_id: pid, slot: 0, offset_x, offset_y, zoom, photo_url });
    }

    const phone = req.body?.phone;
    if (phone === 'reset') {
      deleteAwardPhotoOverride(season, 'mvp_race', pid, 1);
    } else if (phone && typeof phone === 'object') {
      upsertAwardPhotoOverride({
        season, award_type: 'mvp_race', player_id: pid, slot: 1,
        offset_x: clamp(phone.offset_x, 0, 100, 50),
        offset_y: clamp(phone.offset_y, 0, 100, MVP_PHONE_DEFAULT_Y),
        zoom: clamp(phone.zoom, 1, 3, 1),
        photo_url: await resolvePhoto(phone, 1),
      });
    }
  } catch (err) {
    return res.status(400).json({ error: err.message || 'Save failed.' });
  }
  res.json({ ok: true });
});

// Admin ↺ on /mvp and /dpoy: drop one player's writeup (or the season's) so the next view
// regenerates it.
for (const raceKey of ['mvp', 'dpoy']) {
  app.post(`/admin/${raceKey}/regenerate`, requireAuth, express.json(), (req, res) => {
    const race = RACE_DATA[raceKey];
    const { player_id, season } = req.body || {};
    const targetSeason = season || getCurrentSeason()?.season;
    // While the reveal lock is on, /mvp shows the forecast cards: ↺ regenerates those instead.
    if (isMvpLocked(targetSeason)) {
      const del = raceKey === 'mvp' ? deleteMvpLockWriteup : deleteDpoyLockWriteup;
      const clear = raceKey === 'mvp' ? clearMvpLockWriteups : clearDpoyLockWriteups;
      if (player_id) del(player_id, targetSeason);
      else clear(targetSeason);
      mvpAiCooldownUntil = 0;
      return res.json({ ok: true });
    }
    if (isPlayoffStarted(targetSeason) || isMvpLocked(targetSeason)) {
      return res.status(403).json({ error: 'Season locked — playoffs have started' });
    }
    if (player_id) race.deleteWriteup(player_id, season);
    else           race.clearWriteups(season);
    mvpAiCooldownUntil = 0; // an explicit admin regenerate always gets a fresh attempt
    res.json({ ok: true });
  });
}

// One player's AI case for /mvp (the original MVP prompt, unchanged) or /dpoy. c: the
// candidate (mvpScore = the race's score); ranks: league ranks by stat key; total: players
// ranked; field: how many are on the page.
// A race writeup's cache key: the player's stats plus their race position (the text says it).
const raceWriteupKey = (race, c, rank) => `${race.statsKey(c.stats)}|r${rank}`;
// Race writeups whose drafts failed every check, held back until this time (in memory).
const raceWriteupFailUntil = new Map();

// Returns { prompt, facts }: facts = the stat lines alone, what the output checks read.
function raceWriteupPrompt(raceKey, { c, rank, ranks, total, field, teamRec, voice, recentOpenings }) {
  const gp  = c.stats.gp;
  const per = k => ((c.stats[k] || 0) / gp).toFixed(1);
  const wl  = `${teamRec.w}W-${teamRec.l}L`;
  const name = displayPlayerName(c.player.name);
  const pid  = c.player.id;
  const lr = k => `league rank #${ranks[k][pid]} of ${total} players`;
  const movement = c.prevRank === undefined ? ' (first week of rankings)'
    : c.prevRank === null    ? ' (new to the race this week, was outside the rankings last week)'
    : c.prevRank === rank    ? ` (unchanged from last week's #${c.prevRank})`
    : ` (last week: #${c.prevRank}, ${c.prevRank > rank ? 'up' : 'down'} ${Math.abs(c.prevRank - rank)} spot${Math.abs(c.prevRank - rank) === 1 ? '' : 's'})`;
  const openings = recentOpenings.length ? `
- OPENING SENTENCES FROM OTHER ${raceKey === 'mvp' ? 'MVP' : 'BEST DEFENDER'} WRITEUPS (yours must not resemble these):
${recentOpenings.map(t => `  "${t}"`).join('\n')}` : '';
  const reminder = `FINAL REMINDER — write it in the ${voice.name} voice.${voice.sample ? ` Example of the voice (style only — do not copy its words or facts): "${voice.sample}"` : ''}`;

  if (raceKey === 'dpoy') {
    const rankLines = [
      `Steals per game: ${per('stl')} (${lr('spg')})`,
      `Blocks per game: ${per('blk')} (${lr('bpg')})`,
      `Steals + blocks per game: ${(((c.stats.stl || 0) + (c.stats.blk || 0)) / gp).toFixed(1)} (${lr('stk')})`,
      `Rebounds per game: ${per('reb')} (${lr('rpg')})`,
      `Fouls per game: ${per('pf')}, Team record: ${wl}, GP: ${gp}, Defense Score: ${c.mvpScore.toFixed(1)}`,
      `Best Defender Race position: #${rank} of ${field}${movement}`,
    ].join('\n');
    return { facts: `${name} stats:\n${rankLines}`, prompt: `You are covering the Best Defender race for WKND Basketball, a recreational league whose players read every word. ${rank <= 3 ? 'Write a 2-3 sentence Best Defender case' : 'Write exactly 2 short sentences (under 45 words in total) on the Best Defender case'} for ${name} (${String(c.stats.team_name).toUpperCase()}). Be specific with numbers — the energy comes from the details, not adjectives. Focus solely on what makes THIS player a real Best Defender candidate — steals, blocks, rebounding, staying out of foul trouble, and winning.

THIS WEEK'S VOICE — ${voice.name}: ${voice.guide}${voiceFlavor(voice, pid, 60) ? `
${voiceFlavor(voice, pid, 60)}` : ''}

Rules:
- Do NOT mention any other player by name or by comparison (no "unlike X", "while others", "leads over").
- Do NOT start with their name.
- Do NOT open with "With a" or "With an" — vary the sentence structure completely.
- Lead with the most interesting or unusual thing about this player's defense.
- This is about defense only: never mention points, scoring, shooting or assists.
- The stats are steals, blocks, total rebounds and fouls only. Never claim anything they can't show (lockdown matchups, contested shots, deflections, charges taken, defensive rebounds).
- No filler phrases like "impressive", "stellar", "remarkable", or "dominant".
- ONLY make league-ranking claims (e.g. "leads the league in X", "top-3 in Y") if the rank data below supports it. Do not invent or assume rankings.
- Work in their Best Defender Race position and how it moved since last week (climbing, slipping, holding steady, or newly entering) using the exact numbers below. Do not say who they passed or who passed them.
- Never call them the best or the most at anything unless a rank line below says #1 for it, and never say they deserve, should win, or are the favourite for Best Defender.
- Plain text only. No markdown.
- Celebrate the case — skip any stat that undercuts it (a tiny block number, a high foul rate); never call a number weak, meager, or "room for improvement." Do NOT mention the crowd, fans, or spectators.${openings}

${name} stats:\n${rankLines}

${reminder}` };
  }

  const tsDenom = 2 * (c.stats.fga + 0.44 * c.stats.fta);
  const ts  = tsDenom > 0 ? Math.round(c.stats.pts / tsDenom * 100) + '%' : '—';
  const fg  = c.stats.fga > 0 ? Math.round(c.stats.fgm / c.stats.fga * 100) + '%' : '—';
  const rankLines = [
    `PPG: ${per('pts')} (${lr('ppg')})`,
    `RPG: ${per('reb')} (${lr('rpg')})`,
    `APG: ${per('ast')} (${lr('apg')})`,
    `SPG: ${per('stl')} (${lr('spg')})`,
    `TS%: ${ts} (${lr('ts')})`,
    `FG%: ${fg}, Record: ${wl}, GP: ${gp}, MVP Score: ${c.mvpScore.toFixed(1)}`,
    `MVP Race position: #${rank} of ${field}${movement}`,
  ].join('\n');
  return { facts: `${name} stats:\n${rankLines}`, prompt: `You are covering the MVP race for WKND Basketball, a recreational league whose players read every word. ${rank <= 3 ? 'Write a 2-3 sentence MVP case' : 'Write exactly 2 short sentences (under 45 words in total) on the MVP case'} for ${name} (${String(c.stats.team_name).toUpperCase()}). Be specific with numbers — the energy comes from the details, not adjectives. Focus solely on what makes THIS player a real MVP candidate — production, efficiency, winning.

THIS WEEK'S VOICE — ${voice.name}: ${voice.guide}${voiceFlavor(voice, pid, 60) ? `
${voiceFlavor(voice, pid, 60)}` : ''}

Rules:
- Do NOT mention any other player by name or by comparison (no "unlike X", "while others", "leads over").
- Do NOT start with their name.
- Do NOT open with "With a" or "With an" — vary the sentence structure completely.
- Lead with the most interesting or unusual thing about this player's case.
- No filler phrases like "impressive", "stellar", "remarkable", or "dominant".
- ONLY make league-ranking claims (e.g. "leads the league in X", "top-3 in Y") if the rank data below supports it. Do not invent or assume rankings.
- Work in their MVP Race position and how it moved since last week (climbing, slipping, holding steady, or newly entering) using the exact numbers below. Do not say who they passed or who passed them.
- Never call them the best or the most at anything (e.g. "the league's most efficient scorer") unless a rank line below says #1 for it, and never say they deserve, should win, or are the favourite for the MVP.
- Plain text only. No markdown.
- Celebrate the case — skip any stat that undercuts it (a low 3P%, a tiny assist number, a weak FT%); never call a number weak, meager, or "room for improvement." Do NOT mention the crowd, fans, or spectators.${openings}

${name} stats:\n${rankLines}

${reminder}` };
}

// ── MVP reveal lock: the ten cases + "Call the podium" ─────────────────────────
// While the race is locked (lib/mvp-lock.js), /mvp and the homepage MVP card show the top ten
// SHUFFLED, with no score, rank or movement. Each case carries forecast facts: Sunday's
// opponent (the team's next regular game; before it's on the schedule, the one opponent it
// has met only once in the double round robin) and the player's line from their earlier
// meeting. With no regular game left the facts fall back to his latest game ('final' mode).
// The Best Defender race (/dpoy) gets the same lock with defensive bars and writeups, and no
// ballot. Bars per race: [key, label, scale max, inv]; inv = more is worse (fouls), so its
// delta reads the other way.
const LOCK_BARS = {
  mvp: [['pts', 'PTS', 25], ['reb', 'REB', 16], ['ast', 'AST', 8], ['stl', 'STL', 6]],
  dpoy: [['stl', 'STL', 6], ['blk', 'BLK', 4], ['reb', 'REB', 16], ['pf', 'PF', 5, true]],
};

function shuffled(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

// One box-score row → the card's numbers. 4-pointers count as field goals.
function lockLine(row) {
  const fgm = (row.fg2m || 0) + (row.fg3m || 0) + (row.fg4m || 0);
  const fga = fgm + (row.fg2m_miss || 0) + (row.fg3m_miss || 0) + (row.fg4m_miss || 0);
  const tpa = (row.fg3m || 0) + (row.fg3m_miss || 0), fta = (row.ftm || 0) + (row.ft_miss || 0);
  const notes = [`${fgm}-${fga} FG`];
  if (tpa >= 4) notes.push(`${row.fg3m || 0}-${tpa} 3PT`);
  if (fta >= 4) notes.push(`${row.ftm || 0}-${fta} FT`);
  if ((row.turnover || 0) >= 3) notes.push(`${row.turnover} TO`);
  if ((row.blk || 0) >= 2) notes.push(`${row.blk} BLK`);
  return {
    pts: row.pts || 0, reb: row.reb || 0, ast: row.ast || 0, stl: row.stl || 0, blk: row.blk || 0, tov: row.turnover || 0, pf: row.pf || 0,
    fgm, fga, tpm: row.fg3m || 0, tpa, ftm: row.ftm || 0, fta, shot: notes.slice(0, 3).join(' · '),
  };
}

function mvpLockTen(season, raceKey = 'mvp') {
  const dpoy = raceKey === 'dpoy';
  const s = String(season);
  const seasonGames = byDate(getAllGames()).filter(g => String(g.season) === s);
  const regular = seasonGames.filter(g => (g.game_type || 'regular') === 'regular');
  const done = g => g.status === 'complete' || g.status === 'final';
  const publicDone = regular.filter(g => done(g) && !g.under_review);
  const teamName = {};
  for (const g of seasonGames) { teamName[g.team_a_id] = g.team_a_name; teamName[g.team_b_id] = g.team_b_name; }
  const teamIds = Object.keys(teamName);
  const recs = {};
  for (const g of publicDone) {
    const a = Number(g.team_a_score), b = Number(g.team_b_score);
    for (const [t, us, them] of [[g.team_a_id, a, b], [g.team_b_id, b, a]]) {
      recs[t] ||= { w: 0, l: 0 };
      if (us > them) recs[t].w++; else if (them > us) recs[t].l++;
    }
  }
  const nextOpp = tid => {
    const up = regular.filter(g => !done(g) && (g.team_a_id === tid || g.team_b_id === tid) && g.date)
      .sort((x, y) => String(x.date).localeCompare(String(y.date)))[0];
    if (up) return up.team_a_id === tid ? up.team_b_id : up.team_a_id;
    const played = regular.filter(done);
    const mine = played.filter(g => g.team_a_id === tid || g.team_b_id === tid);
    if (mine.length >= SEASON_GAMES_PER_TEAM) return null;
    const short = teamIds.filter(o => o !== tid && mine.filter(g => g.team_a_id === o || g.team_b_id === o).length < 2);
    return short.length === 1 ? short[0] : null;
  };
  const rowFor = (g, pid) => getGameStats(g.id).find(r => r.player_id === pid) || null;
  const result = (g, tid) => {
    const us = g.team_a_id === tid ? Number(g.team_a_score) : Number(g.team_b_score);
    const them = g.team_a_id === tid ? Number(g.team_b_score) : Number(g.team_a_score);
    return `${us > them ? 'W' : us < them ? 'L' : 'T'} ${us}-${them}`;
  };
  const dateLbl = g => new Date(`${String(g.date).slice(0, 10)}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' }).toUpperCase();

  const score = dpoy ? computeDpoyScore : computeMvpScore;
  const top = getMvpCandidates(season).filter(c => c.gp >= 1)
    .map(c => ({ c, score: score(c) }))
    .sort((a, b) => b.score - a.score).slice(0, 10).map(x => x.c);

  return shuffled(top).map(st => {
    const tid = st.team_id, gp = st.gp;
    const avg = { pts: st.pts / gp, reb: st.reb / gp, ast: st.ast / gp, stl: st.stl / gp, blk: (st.blk || 0) / gp, pf: (st.pf || 0) / gp };
    const tsDenom = 2 * (st.fga + 0.44 * st.fta);
    const opp = nextOpp(tid);
    const upGame = opp && regular.filter(g => !done(g) && g.date && (g.team_a_id === tid || g.team_b_id === tid)).sort((x, y) => String(x.date).localeCompare(String(y.date)))[0];
    let mode = opp ? 'forecast' : 'final', meetGame = null, row = null;
    if (opp) {
      meetGame = publicDone.filter(g => (g.team_a_id === tid && g.team_b_id === opp) || (g.team_b_id === tid && g.team_a_id === opp)).pop() || null;
      row = meetGame && rowFor(meetGame, st.id);
    } else {
      for (const g of [...publicDone].reverse()) {
        if (g.team_a_id !== tid && g.team_b_id !== tid) continue;
        row = rowFor(g, st.id);
        if (row) { meetGame = g; break; }
      }
    }
    const line = row ? lockLine(row) : null;
    // /dpoy's footnote is the defensive line, not the shooting one.
    if (line && dpoy) line.shot = `${line.stl + line.blk} stocks · ${line.pf} foul${line.pf === 1 ? '' : 's'}`;
    const meetOpp = meetGame ? (meetGame.team_a_id === tid ? meetGame.team_b_id : meetGame.team_a_id) : opp;
    const bars = LOCK_BARS[raceKey].map(([k, label, max, inv]) => {
      const v = line ? line[k] : null, a = avg[k];
      const pct = x => `${Math.min(100, Math.round((x / max) * 100))}%`;
      const d = v == null ? null : v - a;
      return { key: k, label, v, inv: !!inv, avg: a.toFixed(1), w: v == null ? '0%' : pct(v), m: pct(a), d: d == null ? '' : `${d > 0.05 ? '+' : d < -0.05 ? '−' : '±'}${Math.abs(d).toFixed(1)}` };
    });
    return {
      player: st, stats: st, mode,
      team: String(st.team_name || '').toUpperCase(),
      record: recs[tid] || { w: 0, l: 0 },
      opp: opp ? String(teamName[opp] || '').toUpperCase() : null,
      nextDay: upGame ? new Date(`${String(upGame.date).slice(0, 10)}T00:00:00Z`).toLocaleDateString('en-US', { weekday: 'short', timeZone: 'UTC' }).toUpperCase() : 'SUN',
      oppRecord: opp ? (recs[opp] || { w: 0, l: 0 }) : null,
      meet: meetGame ? { opp: String(teamName[meetOpp] || '').toUpperCase(), date: dateLbl(meetGame), res: result(meetGame, tid), played: !!row } : null,
      line, bars, avg,
      ts: tsDenom > 0 ? Math.round((st.pts / tsDenom) * 100) : null,
      foot: dpoy ? ['Season fouls', `${avg.pf.toFixed(1)}/g`] : (tsDenom > 0 ? ['Season TS', `${Math.round((st.pts / tsDenom) * 100)}%`] : null),
      // Sort keys (views/mvp.js lockSorts): per game, then the last game's headline number.
      sort: dpoy
        ? { spg: avg.stl, bpg: avg.blk, rpg: avg.reb, last: line ? line.stl + line.blk : -1 }
        : { ppg: avg.pts, rpg: avg.reb, apg: avg.ast, last: line ? line.pts : -1 },
    };
  });
}

// The facts block the forecast prompt sees, and the key it's cached on.
function lockFacts(c) {
  const name = displayPlayerName(c.player.name);
  const one = n => (Math.round(n * 10) / 10).toFixed(1);
  const lines = [
    `Player: ${name} (${c.team}), ${c.stats.gp} games played this regular season.`,
    `Season per game: ${one(c.avg.pts)} points, ${one(c.avg.reb)} rebounds, ${one(c.avg.ast)} assists, ${one(c.avg.stl)} steals${c.ts != null ? `, ${c.ts}% true shooting` : ''}.`,
    `${c.team} record: ${c.record.w}-${c.record.l}.`,
  ];
  if (c.mode === 'forecast') {
    lines.push(`Next game (the last of the regular season): vs ${c.opp} (${c.oppRecord.w}-${c.oppRecord.l}).`);
    if (c.meet) lines.push(`Their earlier meeting this season (${c.meet.date}): ${c.team} ${c.meet.res.startsWith('W') ? 'won' : 'lost'} ${c.meet.res.slice(2)}.`);
  } else if (c.meet) {
    lines.push(`The regular season is over. His last game: ${c.meet.date} vs ${c.meet.opp}, ${c.team} ${c.meet.res.startsWith('W') ? 'won' : 'lost'} ${c.meet.res.slice(2)}.`);
  }
  if (c.line) {
    const L = c.line, diff = (v, a) => { const d = v - a; return Math.abs(d) < 0.05 ? 'level with his average' : `${one(Math.abs(d))} ${d > 0 ? 'over' : 'under'} his average`; };
    lines.push(`His line in that game: ${L.pts} points (${diff(L.pts, c.avg.pts)}), ${L.reb} rebounds (${diff(L.reb, c.avg.reb)}), ${L.ast} assists (${diff(L.ast, c.avg.ast)}), ${L.stl} steals, ${L.blk} blocks, ${L.tov} turnovers; ${L.fgm}-of-${L.fga} from the field, ${L.tpm}-of-${L.tpa} from three, ${L.ftm}-of-${L.fta} at the line.`);
  } else if (c.meet && !c.meet.played) {
    lines.push('He did not play in that game.');
  }
  return lines.join('\n');
}

// The one thing each forecast is about, chosen in code so the model only has to phrase it
// (left to itself it told a 4-of-16 shooter to "repeat" that line). In order: a stat well
// under his average, a cold shooting night, a stat well over his average, else the result.
function lockAngle(c) {
  const L = c.line;
  if (c.mode !== 'forecast' || !L || !c.meet) return null;
  const one = n => (Math.round(n * 10) / 10).toFixed(1);
  const word = { pts: 'points', reb: 'rebounds', ast: 'assists' };
  // Swings weighted like the MVP score (points 1, rebounds 0.8, assists 0.9), so a 1.8-assist
  // dip doesn't outrank a 6-point one just because the assist average is small.
  const weight = { pts: 1, reb: 0.8, ast: 0.9 };
  const rel = ['pts', 'reb', 'ast'].map(k => ({ k, v: L[k], a: c.avg[k], r: (L[k] - c.avg[k]) * weight[k] }));
  const low = rel.reduce((m, x) => (x.r < m.r ? x : m)), high = rel.reduce((m, x) => (x.r > m.r ? x : m));
  const fg = L.fga ? L.fgm / L.fga : null, seasonFg = c.stats.fga ? c.stats.fgm / c.stats.fga : null;
  const won = c.meet.res.startsWith('W');
  const result = `${c.team} ${won ? 'won' : 'lost'} that game ${c.meet.res.slice(2)}`;
  if (low.r <= -3) return `FIX: his ${word[low.k]}. He had ${low.v}, ${one(low.a - low.v)} under his average of ${one(low.a)}. ${result}. Getting the ${word[low.k]} back up is Sunday's job.`;
  if (fg != null && seasonFg != null && L.fga >= 8 && fg <= seasonFg - 0.1) return `FIX: his shooting. He went ${L.fgm}-of-${L.fga} from the field. ${result}. A cleaner shooting night is Sunday's job.`;
  if (high.r >= 3) return `REPEAT: his ${word[high.k]}. He had ${high.v}, ${one(high.v - high.a)} over his average of ${one(high.a)}. ${result}. Doing that again is Sunday's job.`;
  return `RESULT: ${result}, with ${L.pts} points, ${L.reb} rebounds and ${L.ast} assists from him. ${won ? 'Doing it again' : 'Flipping that result'} is Sunday's job.`;
}

function lockPrompt(c, facts, voice, openings) {
  const forecast = c.mode === 'forecast';
  const angle = lockAngle(c);
  return `You write one card on WKND Basketball's MVP page, a recreational league whose players read every word. The MVP race is LOCKED: its order, scores and gaps are secret until the award.

Return JSON with two fields:
- "job": ${forecast ? `"Sunday's job", 1–2 sentences, at most 40 words: what his earlier game against ${c.opp} says he needs to do in Sunday's rematch.` : '"The final case", 1–2 sentences, at most 40 words: what his regular season and his last game say about his MVP case.'}
- "question": one short question, at most 14 words, ending with "?", ${forecast ? 'on how he wins Sunday or makes his case in it' : 'on whether he has done enough'}.

THIS WEEK'S VOICE — ${voice.name}: ${voice.guide}${voiceFlavor(voice, c.player.id, 50) ? `\n${voiceFlavor(voice, c.player.id, 50)}` : ''}
Numbers, names and stat words stay in English digits exactly as the facts give them; everything around them is in the voice.

${angle ? `THE ANGLE (decided for you; the job and the question are about this and nothing else):
${angle}
Example of the shape (other facts): "Six under his scoring average last time, on 5-of-19. Get the points back and the win follows." Question example: "Do the points come back on Sunday?"` : 'Shape: name the one or two things from his season and last game that make his case, then ask whether it is enough.'}

Rules:
- Use ONLY the facts below. Every number you write must appear in them.
- No vague coaching ("shoot better", "be more consistent", "make more shots", "boost his FG%"): point at the exact number instead.
- Season figures describe his season, never a target for one game (don't say he must shoot his season true shooting % on Sunday).
- No streaks, no shot types or locations beyond what the line shows (threes vs the rest), no "contested", "open", "rim" or "paint" claims as facts. A question may ask about them.
- Copy shooting lines exactly as written ("5-of-19"); never recompute them. Write every number as digits, never as words.
- Never mention the MVP race, ranks, positions, scores, gaps, leading, trailing, frontrunner, favourite, "in the running", or who deserves the award.
- Never mention any other player.
- Never claim anything a box score can't show: no tactics, defensive schemes, matchups, intentions, effort, injuries, crowd or mood.
- No league rankings and no season-best or season-worst claims.
- Do not start with his name. No filler words like "impressive", "stellar", "remarkable" or "dominant". Plain text, no markdown.${openings.length ? `
- Don't echo these openings from other cards: ${openings.map(t => `"${String(t).split(/(?<=[.!?])\s/)[0].slice(0, 90)}"`).join('; ')}` : ''}

Facts:
${facts}`;
}

// ── The Best Defender versions (/dpoy): defense only, same guard and cache rules ──────────
function dpoyLockFacts(c) {
  const name = displayPlayerName(c.player.name);
  const one = n => (Math.round(n * 10) / 10).toFixed(1);
  const lines = [
    `Player: ${name} (${c.team}), ${c.stats.gp} games played this regular season.`,
    `Season per game: ${one(c.avg.stl)} steals, ${one(c.avg.blk)} blocks, ${one(c.avg.reb)} rebounds, ${one(c.avg.pf)} fouls.`,
    `${c.team} record: ${c.record.w}-${c.record.l}.`,
  ];
  if (c.mode === 'forecast') {
    lines.push(`Next game (the last of the regular season): vs ${c.opp} (${c.oppRecord.w}-${c.oppRecord.l}).`);
    if (c.meet) lines.push(`Their earlier meeting this season (${c.meet.date}): ${c.team} ${c.meet.res.startsWith('W') ? 'won' : 'lost'} ${c.meet.res.slice(2)}.`);
  } else if (c.meet) {
    lines.push(`The regular season is over. His last game: ${c.meet.date} vs ${c.meet.opp}, ${c.team} ${c.meet.res.startsWith('W') ? 'won' : 'lost'} ${c.meet.res.slice(2)}.`);
  }
  if (c.line) {
    const L = c.line, diff = (v, a) => { const d = v - a; return Math.abs(d) < 0.05 ? 'level with his average' : `${one(Math.abs(d))} ${d > 0 ? 'over' : 'under'} his average`; };
    lines.push(`His line in that game: ${L.stl} steals (${diff(L.stl, c.avg.stl)}), ${L.blk} blocks (${diff(L.blk, c.avg.blk)}), ${L.reb} rebounds (${diff(L.reb, c.avg.reb)}), ${L.pf} fouls (${diff(L.pf, c.avg.pf)}).`);
  } else if (c.meet && !c.meet.played) {
    lines.push('He did not play in that game.');
  }
  return lines.join('\n');
}

// Weighted like the defense score (steals 1.5, blocks 2, rebounds 0.3); a foul-heavy night
// (2+ over his average) is its own thing to fix.
function dpoyLockAngle(c) {
  const L = c.line;
  if (c.mode !== 'forecast' || !L || !c.meet) return null;
  const one = n => (Math.round(n * 10) / 10).toFixed(1);
  const word = { stl: 'steals', blk: 'blocks', reb: 'rebounds' };
  const weight = { stl: 1.5, blk: 2, reb: 0.3 };
  const rel = ['stl', 'blk', 'reb'].map(k => ({ k, v: L[k], a: c.avg[k], r: (L[k] - c.avg[k]) * weight[k] }));
  const low = rel.reduce((m, x) => (x.r < m.r ? x : m)), high = rel.reduce((m, x) => (x.r > m.r ? x : m));
  const won = c.meet.res.startsWith('W');
  const result = `${c.team} ${won ? 'won' : 'lost'} that game ${c.meet.res.slice(2)}`;
  if (L.pf - c.avg.pf >= 2) return `FIX: his fouls. He had ${L.pf}, ${one(L.pf - c.avg.pf)} over his average of ${one(c.avg.pf)}. ${result}. Staying out of foul trouble is Sunday's job.`;
  if (low.r <= -1.5) return `FIX: his ${word[low.k]}. He had ${low.v}, ${one(low.a - low.v)} under his average of ${one(low.a)}. ${result}. Getting the ${word[low.k]} back up is Sunday's job.`;
  if (high.r >= 1.5) return `REPEAT: his ${word[high.k]}. He had ${high.v}, ${one(high.v - high.a)} over his average of ${one(high.a)}. ${result}. Doing that again is Sunday's job.`;
  return `RESULT: ${result}, with ${L.stl} steals, ${L.blk} blocks and ${L.reb} rebounds from him. ${won ? 'Doing it again' : 'Flipping that result'} is Sunday's job.`;
}

function dpoyLockPrompt(c, facts, voice, openings) {
  const forecast = c.mode === 'forecast';
  const angle = dpoyLockAngle(c);
  return `You write one card on WKND Basketball's Best Defender page, a recreational league whose players read every word. The Best Defender race is LOCKED: its order, scores and gaps are secret until the award.

Return JSON with two fields:
- "job": ${forecast ? `"Sunday's job", 1–2 sentences, at most 40 words: what his earlier game against ${c.opp} says he needs to do on defense in Sunday's rematch.` : '"The final case", 1–2 sentences, at most 40 words: what his regular season and his last game say about his Best Defender case.'}
- "question": one short question, at most 14 words, ending with "?", ${forecast ? 'on how he wins Sunday on defense' : 'on whether he has done enough'}.

THIS WEEK'S VOICE — ${voice.name}: ${voice.guide}${voiceFlavor(voice, c.player.id, 50) ? `\n${voiceFlavor(voice, c.player.id, 50)}` : ''}
Numbers, names and stat words stay in English digits exactly as the facts give them; everything around them is in the voice.

${angle ? `THE ANGLE (decided for you; the job and the question are about this and nothing else):
${angle}
Example of the shape (other facts): "Just 1 steal last time, 1.8 under his average. Get his hands back in the passing lanes and the win follows." Question example: "Do the steals come back on Sunday?"` : 'Shape: name the one or two defensive numbers from his season and last game that make his case, then ask whether it is enough.'}

Rules:
- This is about defense only: never mention points, scoring, shooting, assists or turnovers.
- The stats are steals, blocks, total rebounds and fouls only. Never claim anything they can't show: no contested shots, deflections, charges, lockdown matchups, defensive rebounds or who he guarded.
- Use ONLY the facts below. Every number you write must appear in them. Write every number as digits, never as words.
- Season figures describe his season, never a target for one game.
- Never mention the Best Defender race, ranks, positions, scores, gaps, leading, trailing, frontrunner, favourite, "in the running", or who deserves the award.
- Never mention any other player. No league rankings and no season-best or season-worst claims.
- Do not start with his name. No filler words like "impressive", "stellar", "remarkable" or "dominant". Plain text, no markdown.${openings.length ? `
- Don't echo these openings from other cards: ${openings.map(t => `"${String(t).split(/(?<=[.!?])\s/)[0].slice(0, 90)}"`).join('; ')}` : ''}

Facts:
${facts}`;
}

function dpoyLockFallback(c) {
  const L = c.line;
  const n = (v, w) => `${v} ${v === 1 ? w : `${w}s`}`;
  if (!c.meet || !L) {
    return { job: `${n(c.stats.gp, 'game')} in, at ${c.avg.stl.toFixed(1)} steals and ${c.avg.blk.toFixed(1)} blocks a game.`, question: c.mode === 'forecast' ? 'What does he bring to the last one?' : 'Has he done enough?' };
  }
  const line = `${n(L.stl, 'steal')}, ${n(L.blk, 'block')} and ${n(L.reb, 'rebound')} in the ${c.meet.res.slice(2)} ${c.meet.res.startsWith('W') ? 'win' : 'loss'}`;
  return c.mode === 'forecast'
    ? { job: `Last time against ${titleCase(c.opp)}: ${line}.`, question: 'What does he bring to the rematch?' }
    : { job: `His last game: ${line}.`, question: 'Has he done enough?' };
}

// The number guard: every number in the text must appear in the facts, every "5-of-17" and
// score must appear exactly, and every "13 points"-style pair must match a pair in the facts
// (a "5-of-19" passed the loose check once because 19 was his scoring average).
const LOCK_STAT_WORD = { points: 'points', rebounds: 'rebounds', boards: 'rebounds', assists: 'assists', steals: 'steals', blocks: 'blocks', turnovers: 'turnovers', fouls: 'fouls' };
// Models sometimes write "5‑of‑19" with a non-breaking hyphen, which hid it from the check.
const lockDashes = s => String(s).replace(/[‐-―−]/g, '-');
function lockNumbersOk(text, facts) {
  const t = lockDashes(text).toLowerCase(), f = lockDashes(facts).toLowerCase();
  const have = new Set(f.match(/\d+(?:\.\d+)?/g) || []);
  if (!(t.match(/\d+(?:\.\d+)?/g) || []).every(n => have.has(n))) return false;
  if (!(t.match(/\d+-of-\d+|\d+-\d+/g) || []).every(p => f.includes(p))) return false;
  // Numbers must be digits so the checks above see them ("three" stays: it's a shot type).
  if (/\b(two|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty)\b/.test(t)) return false;
  const pairs = new Set([...f.matchAll(/(\d+(?:\.\d+)?) (points|rebounds|assists|steals|blocks|turnovers|fouls)/g)].map(m => `${m[1]} ${m[2]}`));
  return [...t.matchAll(/(\d+(?:\.\d+)?)[- ](points?|rebounds?|boards?|assists?|steals?|blocks?|turnovers?|fouls?)\b/g)]
    .every(m => pairs.has(`${m[1]} ${LOCK_STAT_WORD[m[2].replace(/s?$/, 's')]}`));
}

function lockFallback(c) {
  const L = c.line;
  if (!c.meet || !L) {
    return c.mode === 'forecast'
      ? { job: `${c.stats.gp} games in, at ${(c.avg.pts).toFixed(1)} points and ${(c.avg.reb).toFixed(1)} rebounds a game. One regular-season game left.`, question: 'What does he bring to the last one?' }
      : { job: `A regular season of ${(c.avg.pts).toFixed(1)} points, ${(c.avg.reb).toFixed(1)} rebounds and ${(c.avg.ast).toFixed(1)} assists a game.`, question: 'Has he done enough?' };
  }
  const n = (v, w) => `${v} ${v === 1 ? w : `${w}s`}`;
  const line = `${n(L.pts, 'point')}, ${n(L.reb, 'rebound')} and ${n(L.ast, 'assist')} in the ${c.meet.res.slice(2)} ${c.meet.res.startsWith('W') ? 'win' : 'loss'}`;
  return c.mode === 'forecast'
    ? { job: `Last time against ${titleCase(c.opp)}: ${line}.`, question: 'What does he bring to the rematch?' }
    : { job: `His last game: ${line}.`, question: 'Has he done enough?' };
}

// v4 (2026-10-20): full voice + the shared checks — every card rewrites once on /mvp.
const lockKey = (c, facts) => createHash('sha1').update(`v4|${c.mode}|${facts}`).digest('hex').slice(0, 16);

// Cached writeup or the plain fallback, never an AI call (the homepage card).
function cachedLockWriteup(c, season) {
  const hit = getMvpLockWriteup(c.player.id, season, lockKey(c, lockFacts(c) + (lockAngle(c) || '')));
  return hit ? { ...c, job: hit.job, question: hit.question, ai: true } : { ...c, ...lockFallback(c), ai: false };
}

// Writeups for the ten: cached ones, else (generate=true, /mvp only) one AI call each, at most
// three in flight; a failed number guard retries once, then the plain fallback is shown (and
// not stored, so the next view tries again). The homepage passes generate=false.
// Per race: the facts, angle, prompt and fallback, and where its writeups are cached.
const LOCK_WRITERS = {
  mvp: { facts: lockFacts, angle: lockAngle, prompt: lockPrompt, fallback: lockFallback, get: getMvpLockWriteup, set: setMvpLockWriteup, openings: getMvpLockOpenings },
  dpoy: { facts: dpoyLockFacts, angle: dpoyLockAngle, prompt: dpoyLockPrompt, fallback: dpoyLockFallback, get: getDpoyLockWriteup, set: setDpoyLockWriteup, openings: getDpoyLockOpenings },
};

async function mvpLockWriteups(ten, season, { generate = false, race = 'mvp' } = {}) {
  const W = LOCK_WRITERS[race];
  const latest = getAllGames().filter(g => String(g.season) === String(season) && (g.game_type || 'regular') === 'regular' && g.date)
    .map(g => String(g.date).slice(0, 10)).sort().pop();
  const voice = pickVoice('mvp', { date: latest || manilaTodayStr() });
  const openings = W.openings(season);
  const lockFacts = W.facts, lockAngle = W.angle, lockPrompt = W.prompt, lockFallback = W.fallback;
  const getMvpLockWriteup = W.get, setMvpLockWriteup = W.set;
  return mapWithConcurrency(ten, 3, async c => {
    const facts = lockFacts(c);
    const key = lockKey(c, facts + (lockAngle(c) || ''));
    const cached = getMvpLockWriteup(c.player.id, season, key);
    if (cached) return { ...c, job: cached.job, question: cached.question, ai: true };
    if (!generate || !aiAvailable() || Date.now() < mvpAiCooldownUntil) return { ...c, ...lockFallback(c), ai: false };
    const schema = { type: 'object', properties: { job: { type: 'string' }, question: { type: 'string' } }, required: ['job', 'question'] };
    try {
      // Write → check → rewrite (lib/writer.js), 2 tries: the cards' own strict number check
      // (lockNumbersOk: pairs, shooting lines, digits only) plus the shared claim, banned-word
      // and voice checks. The voice gets its heat (0.85 for conyo); a card that still fails
      // shows the plain fallback.
      const allFacts = `${facts}\n${lockAngle(c) || ''}`;
      const { first: fn, last: ln } = (n => { const i = n.indexOf(','); return { first: n.slice(i + 1).trim().split(' ')[0].toLowerCase(), last: n.slice(0, i).trim().toLowerCase() }; })(String(c.player.name));
      const startsWithName = new RegExp(`^(${[fn, ln].filter(Boolean).map(x => x.replace(/[^a-z]/g, '')).join('|')})\\b`, 'i');
      const out = await runWriter({
        prompt: lockPrompt(c, facts, voice, openings), label: `${race.toUpperCase()} lock card (${c.player.id})`, tries: 2,
        generate: async p => {
          const { data } = await generateJson(p, schema, { tier: 'medium', temperature: Math.min(aiTemperature(), voiceTraits(voice).hot ? 0.85 : 0.7), maxTokens: 260 });
          return { job: lockDashes(data?.job || '').trim(), question: lockDashes(data?.question || '').trim() };
        },
        text: d => `${d.job} ${d.question}`,
        checks: [
          (t, d) => (!d.job ? ['the job is empty'] : startsWithName.test(d.job) ? ["the job starts with the player's name"] : []),
          (t, d) => (!d.question.endsWith('?') ? ['the question must end with "?"'] : []),
          t => (lockNumbersOk(t, allFacts) ? [] : ['a number is not in the facts, is spelled out, or is paired with the wrong stat — copy every number and "N points"-style pair exactly as the facts give it']),
          t => claimProblems(t, allFacts),
          { style: true, fn: t => bannedProblems(t) },
          { style: true, fn: t => voiceProblems(t, voice) },
        ],
      });
      if (!out.problems.length) {
        setMvpLockWriteup(c.player.id, season, key, out.draft.job, out.draft.question);
        return { ...c, job: out.draft.job, question: out.draft.question, ai: true };
      }
      console.warn(`${race.toUpperCase()} lock card for ${c.player.id} not kept: ${out.problems.join(' | ')}`);
    } catch (err) {
      console.error(`${race.toUpperCase()} lock writeup failed for ${c.player.id}:`, err.message);
      mvpAiCooldownUntil = Date.now() + MVP_AI_COOLDOWN_MS;
    }
    return { ...c, ...lockFallback(c), ai: false };
  });
}

const mvpPodiumEnabled = () => getSetting('mvp_podium_enabled', '1') !== '0';

// The viewer's ballot + the two cut-offs. viewerId = the logged-in player's id (or null).
function mvpBallotState(season, viewerId) {
  const games = getAllGames();
  const closeTime = picksCloseTime();
  const bonusAt = bonusCutoff(games, season, closeTime, getSetting('mvp_bonus_close', ''));
  const closeAt = ballotClose(games, season, closeTime);
  const today = manilaTodayStr(), hm = manilaHmNow();
  const ballot = viewerId ? getMvpBallot(season, viewerId) : null;
  const bonus = viewerId ? getMvpBonusBallot(season, viewerId) : null;
  return {
    enabled: mvpPodiumEnabled(),
    loggedIn: !!viewerId,
    picks: ballot ? [ballot.p1, ballot.p2, ballot.p3] : [null, null, null],
    bonusPicks: bonus ? [bonus.p1, bonus.p2, bonus.p3] : null,
    bonusOpen: !isPast(bonusAt, today, hm),
    bonusAt: fmtMoment(bonusAt),
    // Epoch ms of the cut-off (Manila = UTC+8), for the live countdown.
    bonusAtMs: bonusAt ? Date.UTC(...bonusAt.ymd.split('-').map((v, i) => Number(v) - (i === 1 ? 1 : 0)), ...bonusAt.hm.split(':').map(Number)) - 8 * 3600 * 1000 : null,
    closed: isPast(closeAt, today, hm),
    closeAt: fmtMoment(closeAt),
    count: countMvpBallots(season),
  };
}

// The ten, light (id, name, team, PPG, Sunday's opponent) for the bar, /picks and the pick
// cards. mvpLockTen reads ten box scores, so this is cached for a minute (one shuffle for
// everyone in that minute; the pickers reshuffle client-side).
let _lockLite = { key: '', at: 0, list: [] };
function mvpLockLite(season) {
  const key = String(season);
  if (_lockLite.key === key && Date.now() - _lockLite.at < 60_000) return _lockLite.list;
  const list = mvpLockTen(season).map(c => ({ id: String(c.player.id), name: c.player.name, team: c.team, ppg: c.avg.pts.toFixed(1), opp: c.opp }));
  _lockLite = { key, at: Date.now(), list };
  return list;
}

// The site-wide podium bar: a logged-in player with no complete ballot who hasn't closed it,
// while the bonus is open. Not on /mvp itself (the ballot is right there).
function podiumBarFor(req, path = '') {
  const pid = req.session?.playerPlayerId;
  if (!pid || !req.session?.playerRegId || String(path).startsWith('/mvp')) return '';
  if (!mvpPodiumEnabled()) return '';
  const season = getPortalCurrentSeason();
  if (!season || !isMvpLocked(season) || isMvpBarDismissed(season, pid)) return '';
  const st = mvpBallotState(season, pid);
  if (st.closed || !st.bonusOpen || st.picks.every(Boolean)) return '';
  if (st.bonusAtMs && st.bonusAtMs <= Date.now()) return '';
  return podiumBarHtml({ deadline: st.bonusAtMs, faces: mvpLockLite(season) });
}

app.post('/api/mvp/bar/dismiss', (req, res) => {
  const pid = req.session?.playerPlayerId;
  const season = getPortalCurrentSeason();
  if (pid && season) dismissMvpBar(season, pid);
  res.json({ ok: true });
});

// A race's real standings (regular season, by its score): [{ id, rank, score }] best first.
// Admin pages show them to the super admin only, even while the race is locked.
function raceStandings(season, raceKey = 'mvp') {
  const score = raceKey === 'dpoy' ? computeDpoyScore : computeMvpScore;
  return getMvpCandidates(season).filter(c => c.gp >= 1)
    .map(c => ({ id: String(c.id), name: c.name, team: String(c.team_name || '').toUpperCase(), score: score(c) }))
    .sort((a, b) => b.score - a.score)
    .map((c, i) => ({ ...c, rank: i + 1 }));
}

// The official podium (top three by the MVP score, regular season) once the race is revealed.
function mvpTop3(season) {
  return getMvpCandidates(season).filter(c => c.gp >= 1)
    .map(c => ({ id: String(c.id), score: computeMvpScore(c) }))
    .sort((a, b) => b.score - a.score).slice(0, 3).map(x => x.id);
}

// /picks: the season-pick strip for the current season (the ballot while locked, your score
// after the reveal), or nothing. top: lead the page while the bonus is open (it closes once
// and is worth up to +3); after the cut-off it sits under Open picks.
function picksPodiumStrip(season, viewerId) {
  const cur = getPortalCurrentSeason();
  if (!mvpPodiumEnabled() || String(season) !== String(cur)) return { html: '', top: false };
  if (isMvpLocked(cur)) {
    const ballot = mvpBallotState(cur, viewerId);
    return { html: podiumStrip({ ballot, ten: mvpLockLite(cur) }), top: ballot.bonusOpen && !ballot.closed };
  }
  const called = mvpPodiumReveal(cur, mvpTop3(cur), viewerId);
  return { html: called ? podiumStrip({ scored: called }) : '', top: false };
}

// ── /admin/mvp-podium: who voted who, totals, and the one-off reminder ─────────────────────
function mvpPodiumMissing(season) {
  const voted = new Set(listMvpBallots(season).filter(b => b.p1 && b.p2 && b.p3).map(b => b.player_id));
  const { recipients } = selectBroadcastRecipients(undefined, { optOutColumn: 'picks_email_optout', exclude: id => voted.has(id) });
  return recipients;
}
// Already has a podium reminder email (email_log, last 60 days). Once a reminder has gone
// out, the button only resends — bell + email — to the emailable ones without one, i.e.
// the sends that failed (e.g. Resend quota). Bell-only players already had their bell.
const podiumEmailed = regId => (getLatestEmailForRef(['podium_reminder'], regId, { sentOnly: true })?.sent_at || 0) > Date.now() - 60 * 86400000;
const podiumMissedEmail = missing => missing.filter(r => r.emailable && !podiumEmailed(r.reg.id));

app.get('/admin/mvp-podium',requireAuth, (req, res) => res.redirect(301, '/admin/awards/podium'));
app.get('/admin/awards/podium', requireAuth, (req, res) => {
  const season = getPortalCurrentSeason();
  const locked = isMvpLocked(season);
  const people = Object.fromEntries(getAllPlayers().map(p => [String(p.id), p]));
  const teams = Object.fromEntries(getAllTeams().map(t => [String(t.id), t.name]));
  const who = id => { const p = id && people[id]; return p ? { id, name: p.name, team: teams[p.team_id] || '' } : null; };
  const ballots = listMvpBallots(season);
  const bonus = Object.fromEntries(listMvpBonusBallots(season).map(b => [b.player_id, b]));
  const complete = ballots.filter(b => b.p1 && b.p2 && b.p3);
  const podium = locked ? null : mvpTop3(season);
  const tallied = tallyBallots(complete);
  // The league's call: 3 points per 1st-place vote, 2 per 2nd, 1 per 3rd, ranked by points
  // (then 1st-place votes, then 2nd). Equal points and votes share a rank. Admin only.
  const tally = Object.entries(tallied).map(([id, votes]) => ({ ...who(id), id, votes, pts: votes[0] * 3 + votes[1] * 2 + votes[2], place: podium ? podium.indexOf(id) + 1 : 0 }))
    .sort((a, b) => b.pts - a.pts || b.votes[0] - a.votes[0] || b.votes[1] - a.votes[1]);
  tally.forEach((t, i) => {
    const prev = tally[i - 1];
    t.rank = prev && prev.pts === t.pts && prev.votes[0] === t.votes[0] && prev.votes[1] === t.votes[1] ? prev.rank : i + 1;
  });
  tally.forEach(t => { t.tied = tally.filter(x => x.rank === t.rank).length > 1; });
  // Actual rank vs fan rank, super admin only: a player-admin seeing the real order and gaps
  // while the race is locked is exactly what the lock exists to stop. The ten with no votes
  // are listed too, so every case is compared.
  const superAdmin = !req.session?.isElevatedPlayer;
  if (superAdmin) {
    const actual = raceStandings(season, 'mvp');
    for (const a of actual.slice(0, 10)) {
      if (!tally.some(t => t.id === a.id)) tally.push({ ...who(a.id), id: a.id, votes: [0, 0, 0], pts: 0, rank: null, tied: false, place: podium ? podium.indexOf(a.id) + 1 : 0 });
    }
    const byId = Object.fromEntries(actual.map(a => [a.id, a]));
    for (const t of tally) t.actual = byId[t.id] || null;
    tally.sort((a, b) => (a.actual?.rank ?? 999) - (b.actual?.rank ?? 999));
  }
  const st = mvpBallotState(season, null);
  const missing = locked ? mvpPodiumMissing(season) : [];
  let reminded = null;
  try { reminded = JSON.parse(getSetting(`mvp_podium_reminded_${season}`, '') || 'null'); } catch { reminded = null; }
  res.send(renderAdminPage(req, {
    title: 'MVP podium ballot',
    currentPath: '/admin/awards/podium',
    settings: podiumSettingsPanel(),
    body: adminMvpPodiumBody({
      season, locked, enabled: st.enabled, bonusAt: st.bonusAt, closeAt: st.closeAt, bonusOpen: st.bonusOpen,
      totals: {
        complete: complete.length, partial: ballots.length - complete.length,
        bonus: Object.values(bonus).filter(b => b.p1 && b.p2 && b.p3).length,
        dismissed: countMvpBarDismissed(season),
        perfect: podium ? complete.filter(b => podiumPoints(b, podium) === 3).length : 0,
      },
      tally,
      ballots: ballots.map(b => {
        const bb = bonus[b.player_id];
        return {
          voter: who(b.player_id) || { id: b.player_id, name: b.player_id, team: '' },
          picks: [b.p1, b.p2, b.p3].map(who), updatedAt: b.updated_at,
          bonus: bb ? [bb.p1, bb.p2, bb.p3].map(who) : null,
          bonusSame: !!bb && bb.p1 === b.p1 && bb.p2 === b.p2 && bb.p3 === b.p3,
          points: podium && bb ? podiumPoints(bb, podium) : null,
        };
      }),
      missing: (() => {
        const toSend = new Set(podiumMissedEmail(missing));
        const names = list => list.map(r => displayPlayerName(r.player.name));
        return {
          count: missing.length, reachable: missing.length, emailable: missing.filter(r => r.emailable).length,
          names: names(missing),
          resend: names([...toSend]),
          emailed: names(missing.filter(r => r.emailable && !toSend.has(r))),
          bellOnly: names(missing.filter(r => !r.emailable)),
        };
      })(),
      podium: podium ? podium.map(who) : null,
      reminded,
      msg: req.query.reminded ? `Reminder sent: ${req.query.reminded} bell notification${req.query.reminded === '1' ? '' : 's'}${req.query.emailing ? `, ${req.query.emailing} email${req.query.emailing === '1' ? '' : 's'} going out now` : ''}.` : '',
    }),
  }));
});

app.post(['/admin/awards/podium/remind', '/admin/mvp-podium/remind'], requireAuth, express.urlencoded({ extended: false }), (req, res) => {
  const season = getPortalCurrentSeason();
  const st = mvpBallotState(season, null);
  const home = req.body?.back === 'home';
  if (!st.enabled || !isMvpLocked(season) || st.closed) return res.redirect(home ? `/admin?toast=${encodeURIComponent('The podium ballot isn’t open.')}` : '/admin/awards/podium');
  let prev = null;
  try { prev = JSON.parse(getSetting(`mvp_podium_reminded_${season}`, '') || 'null'); } catch { prev = null; }
  const recipients = prev ? podiumMissedEmail(mvpPodiumMissing(season)) : mvpPodiumMissing(season);
  const emailable = prev ? recipients : req.body?.email === '1' ? recipients.filter(r => r.emailable) : [];
  const bell = {
    title: 'Call the MVP podium: up to +3 Pickmaster points',
    body: st.bonusOpen && st.bonusAt ? `Bonus closes ${st.bonusAt}` : 'Pick who finishes 1st, 2nd and 3rd',
    link: '/mvp#ballot',
  };
  const campaignId = startCampaign({
    kind: prev ? 'mvp_podium_resend' : 'mvp_podium_reminder', ...bell, segment: prev ? `missed_email:${season}` : `no_ballot:${season}`,
    channels: emailable.length ? 'bell+email' : 'bell', createdBy: req.session?.playerName || 'admin',
  });
  for (const r of recipients) createNotification({ playerId: r.player.id, type: 'mvp_podium_reminder', ...bell, broadcastId: campaignId });
  finishCampaign(campaignId, { bells: recipients.length });
  // A resend keeps the first reminder's record and notes the resend beside it.
  setSetting(`mvp_podium_reminded_${season}`, JSON.stringify(prev
    ? { ...prev, resent: { at: Date.now(), count: recipients.length } }
    : { at: Date.now(), bell: recipients.length, email: req.body?.email === '1' ? emailable.length : null }));
  if (emailable.length) setImmediate(() => sendPodiumEmails(emailable, st, { campaignId, bells: recipients.length }).catch(e => console.error('[podium email] send failed:', e.message)));
  if (home) return res.redirect(`/admin?toast=${encodeURIComponent(`Podium reminder sent: ${recipients.length} bell${recipients.length === 1 ? '' : 's'}${emailable.length ? `, ${IS_DEV ? 1 : emailable.length} email${(IS_DEV ? 1 : emailable.length) === 1 ? '' : 's'} going out now` : ''}`)}`);
  res.redirect(`/admin/awards/podium?reminded=${recipients.length}${emailable.length ? `&emailing=${emailable.length}` : ''}`);
});

// Same pacing and dev rule as sendPicksEmails: outside production only the first one goes
// (and lib/mailer.js redirects it to the admin inbox).
async function sendPodiumEmails(list, st, { campaignId = '', bells = 0 } = {}) {
  const season = getPortalCurrentSeason();
  const faces = shuffled(mvpLockLite(season)).map(p => ({ name: displayPlayerName(p.name), color: teamColor(p.team) }));
  const url = `${(process.env.LIVE_URL || 'https://wkndbasketball.com').replace(/\/$/, '')}/mvp#ballot`;
  let first = true, sent = 0;
  for (const { player, reg, email } of IS_DEV ? list.slice(0, 1) : list) {
    if (!first) await new Promise(r => setTimeout(r, 600));
    first = false;
    const unsub = picksUnsubscribeUrl(reg.id);
    try {
      const ok = await sendMail({
        to: email, ...podiumReminderEmail({ name: player.name, faces, closeLabel: st.bonusOpen ? st.bonusAt : '', url, unsubscribeUrl: unsub }), ref: reg.id, broadcastId: campaignId,
        headers: { 'List-Unsubscribe': `<${unsub}>`, 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' },
      });
      if (ok) sent++;
    } catch (e) {
      console.error(`[podium email] ${email}: ${e.message}`);
    }
  }
  finishCampaign(campaignId, { bells, emails: sent });
}

// Once per season, when the race is revealed: a bell notification for every complete ballot
// ("You called 2 of 3" + the bonus). The flag is set before sending, so a crash mid-loop
// can't double-send. Called from /mvp and the homepage, whichever renders first.
function settleMvpPodium(season) {
  if (!mvpPodiumEnabled() || isMvpLocked(season)) return;
  const key = `mvp_podium_notified_${season}`;
  if (getSetting(key, '')) return;
  const ballots = listMvpBallots(season).filter(b => b.p1 && b.p2 && b.p3);
  if (!ballots.length) return;
  const podium = mvpTop3(season);
  if (podium.length < 3) return;
  setSetting(key, String(Date.now()));
  const bonus = Object.fromEntries(listMvpBonusBallots(season).map(b => [b.player_id, b]));
  for (const b of ballots) {
    const spots = podiumPoints(b, podium);
    const bb = bonus[b.player_id];
    const pts = bb ? podiumPoints(bb, podium) : null;
    createNotification({
      playerId: b.player_id, type: 'mvp_podium',
      title: spots === 3 ? 'Perfect podium! You called the MVP top 3 in order' : `You called ${spots} of 3 on the MVP podium`,
      body: pts != null ? (pts ? `+${pts} Pickmaster bonus` : 'No bonus points this time') : 'Your bonus ballot wasn’t in before the cut-off',
      link: '/mvp#mvr-h',
    });
  }
}

// After the reveal: "Who called it" on /mvp. podium = the official top three ids. The final
// ballots (mvp_ballots) feed the league's call; the points come from the bonus copies.
function mvpPodiumReveal(season, podium, viewerId) {
  if (podium.length < 3 || isMvpLocked(season)) return null;
  const ballots = listMvpBallots(season).filter(b => b.p1 && b.p2 && b.p3);
  if (!ballots.length) return null;
  const people = Object.fromEntries(getAllPlayers().map(p => [String(p.id), p]));
  const teams = Object.fromEntries(getAllTeams().map(t => [String(t.id), t.name]));
  const who = id => { const p = people[id]; return p ? { id, name: p.name, team: teams[p.team_id] || '' } : { id, name: '', team: '' }; };
  const n = ballots.length;
  const firstTally = tallyBallots(ballots);
  const firsts = Object.entries(firstTally).filter(([, t]) => t[0] > 0)
    .map(([id, t]) => ({ ...who(id), n: t[0], pct: Math.round((t[0] / n) * 100), place: podium.indexOf(id) + 1 }))
    .sort((a, b) => b.n - a.n);
  const top3 = new Set(podium);
  const perfect = ballots.filter(b => podiumPoints(b, podium) === 3).map(b => who(String(b.player_id)));
  const mine = viewerId ? ballots.find(b => b.player_id === viewerId) : null;
  const bonus = viewerId ? getMvpBonusBallot(season, viewerId) : null;
  return {
    total: n,
    podium: podium.map(who),
    firsts: firsts.slice(0, 4),
    othersPct: firsts.slice(4).reduce((s, f) => s + f.pct, 0),
    perfect,
    pickedMvp: Math.round((ballots.filter(b => b.p1 === podium[0]).length / n) * 100),
    rightThree: Math.round((ballots.filter(b => ['p1', 'p2', 'p3'].every(k => top3.has(b[k]))).length / n) * 100),
    mine: mine ? { picks: [mine.p1, mine.p2, mine.p3].map(who), exact: [mine.p1, mine.p2, mine.p3].map((id, i) => id === podium[i]), spots: podiumPoints(mine, podium) } : null,
    bonus: bonus ? podiumPoints(bonus, podium) : null,
  };
}

app.post('/api/mvp/ballot', express.json(), (req, res) => {
  const playerId = req.session?.playerPlayerId;
  if (!playerId) return res.status(401).json({ error: 'Log in to call the podium.' });
  const season = getPortalCurrentSeason();
  if (!mvpPodiumEnabled() || !isMvpLocked(season)) return res.status(404).json({ error: 'The podium ballot is closed.' });
  const state = mvpBallotState(season, playerId);
  if (state.closed) return res.status(400).json({ error: 'Ballots closed when the MVP was awarded.' });
  const ids = new Set(mvpLockTen(season).map(c => String(c.player.id)));
  const picks = ['p1', 'p2', 'p3'].map(k => (req.body?.[k] ? String(req.body[k]) : null));
  const chosen = picks.filter(Boolean);
  if (chosen.some(id => !ids.has(id)) || new Set(chosen).size !== chosen.length) {
    return res.status(400).json({ error: 'Pick three different players from the ten.' });
  }
  saveMvpBallot(season, playerId, { p1: picks[0], p2: picks[1], p3: picks[2] }, state.bonusOpen);
  res.json({ ok: true, ...mvpBallotState(season, playerId) });
});

// /mvp and /dpoy: the same page, scoring and writeup flow (RACE_DATA + views/mvp.js RACES).
async function renderRacePage(req, res, raceKey) {
  const race = RACE_DATA[raceKey];
  const currentSeason = getPortalCurrentSeason();
  const season = Number(req.query.season) || Number(currentSeason) || 3;
  const playoffsStarted = isPlayoffStarted(season);
  const raw = getMvpCandidates(season);
  const totalGames = getTotalSeasonGamesForMvp(season);
  // mvp_race_enabled hides /mvp while a new season has no candidates yet, but a season
  // that already has games played (e.g. a Facebook-shared link to a past season) should stay reachable.
  if (raceKey === 'mvp' && getSetting('mvp_race_enabled', '1') === '0' && !raw.length) return res.status(404).send(
    renderPage(req, { title: 'Not Found', currentPath: '/mvp', body: '<div class="container"><p style="padding:40px;color:var(--text-muted)">Page not found.</p></div>' })
  );

  const allGames   = byDate(getAllGames());
  const completedGames = allGames.filter(g =>
    !g.scheduled && !g.under_review && (Number(g.team_a_score) + Number(g.team_b_score)) > 0
  );

  // Team records from regular complete games — used in AI writeups so the W-L is the team's
  // actual record, not the individual player's personal participation record.
  const teamRecords = {};
  for (const g of completedGames.filter(g => g.game_type === 'regular' && String(g.season) === String(season))) {
    const a = g.team_a_id, b = g.team_b_id;
    if (!teamRecords[a]) teamRecords[a] = { w: 0, l: 0 };
    if (!teamRecords[b]) teamRecords[b] = { w: 0, l: 0 };
    if (Number(g.team_a_score) > Number(g.team_b_score)) { teamRecords[a].w++; teamRecords[b].l++; }
    else if (Number(g.team_b_score) > Number(g.team_a_score)) { teamRecords[b].w++; teamRecords[a].l++; }
  }

  // mvpScore holds the race's own score (the defense score on /dpoy).
  const allQualified = raw
    .map(s => ({ player: s, stats: s, mvpScore: race.score(s) }))
    .filter(c => c.stats.gp >= 1);

  // MVP reveal lock (lib/mvp-lock.js): the top 3 A–Z as finalists. Scores, ranks, movement,
  // writeups (they state the race position), section summaries and share links never reach
  // the page; the candidates handed to the view carry no score at all.
  if (isMvpLocked(season)) {
    // The ten cases, shuffled, with forecast writeups (mvpLockTen); /mvp also has the podium
    // ballot, /dpoy doesn't.
    const ten = await mvpLockWriteups(mvpLockTen(season, raceKey), season, { generate: true, race: raceKey });
    const photoMeta = getMvpPhotoMeta(season);
    const current = String(season) === String(getPortalCurrentSeason());
    return res.send(renderPage(req, {
      title: raceKey === 'mvp' ? `Season ${season} MVP Race — Call the podium | WKND Basketball` : `Season ${season} Best Defender Race | WKND Basketball`,
      currentPath: req.path,
      metaTags: buildMvpOgTags(req, ten, season, { locked: true, race: raceKey }),
      body: mvpLockPage({
        race: raceKey,
        ten: ten.map(c => ({ ...c, photo: mvpPhoto(season, c.player.id, photoMeta[c.player.id]) })),
        season,
        totalGames,
        seasonGames: SEASON_GAMES_PER_TEAM,
        isAdmin: !!req.session?.isAdmin,
        ballot: current && raceKey === 'mvp' ? mvpBallotState(season, req.session?.playerPlayerId || null) : null,
        viewerId: req.session?.playerPlayerId || null,
        sections: sectionSummaries(mvpLockSectionFacts(season, ten, raceKey)),
      }),
    }));
  }
  if (isMvpLocked(season)) {
    const finalists = mvpFinalists(allQualified, c => c.mvpScore, c => c.player.name)
      .map(c => ({ player: c.player, stats: c.stats }));
    const photoMeta = getMvpPhotoMeta(season);
    return res.send(renderPage(req, {
      title: `Season ${season} ${raceKey === 'mvp' ? 'MVP' : 'Best Defender'} Finalists | WKND Basketball`,
      currentPath: req.path,
      metaTags: buildMvpOgTags(req, finalists, season, { locked: true, race: raceKey }),
      body: mvpPage({
        race: raceKey,
        locked: true,
        candidates: finalists.map(c => ({ ...c, photo: mvpPhoto(season, c.player.id, photoMeta[c.player.id]) })),
        season,
        isAdmin: !!req.session?.isAdmin,
      }),
    }));
  }

  // Pre-compute per-game league ranks for every stat either race shows or prompts with.
  function leagueRank(arr, fn) {
    const sorted = [...arr].sort((a, b) => fn(b) - fn(a));
    return Object.fromEntries(sorted.map((c, i) => [c.player.id, i + 1]));
  }
  const pg = k => c => (c.stats[k] || 0) / c.stats.gp;
  const ranks = {
    ppg: leagueRank(allQualified, pg('pts')),
    rpg: leagueRank(allQualified, pg('reb')),
    apg: leagueRank(allQualified, pg('ast')),
    spg: leagueRank(allQualified, pg('stl')),
    bpg: leagueRank(allQualified, pg('blk')),
    stk: leagueRank(allQualified, c => ((c.stats.stl || 0) + (c.stats.blk || 0)) / c.stats.gp),
    ts:  leagueRank(allQualified, c => {
      const d = 2 * (c.stats.fga + 0.44 * c.stats.fta);
      return d > 0 ? c.stats.pts / d : 0;
    }),
  };
  const total = allQualified.length;

  const scored = allQualified
    .sort((a, b) => b.mvpScore - a.mvpScore)
    .slice(0, 10);

  // Last week's ranks for the up/down arrows: replay the race with every game from the
  // latest game week (Mon–Sun) excluded. No prior week → no arrows.
  const prevRanks = mvpPrevRanks(season, completedGames, race.score);
  for (const c of scored) c.prevRank = prevRanks ? (prevRanks[c.player.id] ?? null) : undefined;

  // Fetch or generate writeups for top candidates (locked once playoffs begin). At most 3
  // AI calls in flight — firing all 10 at once after "Regenerate All" tripped Gemini's
  // rate limit and pushed calls onto fallback models.
  // Same weekly voice as that week's recaps/POTG, keyed on the season's latest game date
  // (both races use the 'mvp' voice feature).
  const latestGameDate = completedGames
    .filter(g => String(g.season) === String(season) && g.game_type === 'regular')
    .map(g => String(g.date).slice(0, 10)).sort().pop();
  const voice = pickVoice('mvp', { date: latestGameDate || new Date().toISOString().slice(0, 10) });
  const recentOpenings = race.recentWriteups(season)
    .map(w => (String(w).split(/(?<=[.!?])\s/)[0] || '').trim().slice(0, 140))
    .filter(Boolean).slice(0, 10);

  const withWriteups = await mapWithConcurrency(scored, 3, async (c, i) => {
    const rank     = i + 1;
    // Keyed on stats and race position: the text states the position, so a rank change
    // rewrites it (it used to stay "#4" after the player moved). Frozen seasons fall back to
    // the stats-only key the writeups were stored under before 2026-10-20.
    const statsKey = raceWriteupKey(race, c, rank);
    const cached   = race.getWriteup(c.player.id, season, statsKey) || (playoffsStarted ? race.getWriteup(c.player.id, season, race.statsKey(c.stats)) : null);
    if (cached) return { ...c, writeup: cached };
    if (playoffsStarted) return { ...c, writeup: null };
    if (Date.now() < mvpAiCooldownUntil) return { ...c, writeup: null };
    // A draft that failed every check isn't retried on each view: 6 hours, then again.
    const failKey = `${raceKey}|${c.player.id}|${statsKey}`;
    if ((raceWriteupFailUntil.get(failKey) || 0) > Date.now()) return { ...c, writeup: null };

    try {
      const { prompt, facts } = raceWriteupPrompt(raceKey, {
        c, rank, ranks, total, field: scored.length, voice, recentOpenings,
        teamRec: teamRecords[c.stats.team_id] ?? { w: c.stats.wins, l: c.stats.losses },
      });
      // Write → check → rewrite (lib/writer.js), 2 tries (it runs on page views). A draft
      // that still fails is never shown or stored.
      const out = await runWriter({
        prompt, label: `${race.short} writeup (${c.player.id})`, tries: 2,
        generate: async p => (await generateText(p, { tier: rank <= 3 ? 'medium' : 'short', maxTokens: rank <= 3 ? 300 : 160, temperature: aiTemperature() })).text.trim(),
        checks: [
          t => numberProblems(t, facts),
          t => claimProblems(t, facts),
          { style: true, fn: t => bannedProblems(t) },
          t => (/^\s*(with an?\b)/i.test(t) ? ['it opens with "With a"'] : []),
          { style: true, fn: t => voiceProblems(t, voice) },
        ],
      });
      if (out.problems.length) {
        raceWriteupFailUntil.set(failKey, Date.now() + 6 * 60 * 60 * 1000);
        console.warn(`${race.short} writeup for ${c.player.id} not kept: ${out.problems.join(' | ')}`);
        return { ...c, writeup: null };
      }
      race.setWriteup(c.player.id, season, statsKey, out.draft);
      return { ...c, writeup: out.draft };
    } catch (err) {
      console.error(`${race.short} writeup failed for ${c.player.id}:`, err.message);
      mvpAiCooldownUntil = Date.now() + MVP_AI_COOLDOWN_MS;
      return { ...c, writeup: null };
    }
  });

  const photoMeta = getMvpPhotoMeta(season);
  const week = getSeasonLatestWeek(season)?.week ?? null;
  res.send(renderPage(req, {
    title: playoffsStarted
      ? `Season ${season} ${race.name} — Final | WKND Basketball`
      : `${race.name} | WKND Basketball`,
    currentPath: req.path,
    metaTags: buildMvpOgTags(req, withWriteups, season, { race: raceKey }),
    body: mvpPage({
      race: raceKey,
      candidates: withWriteups.map(c => ({
        ...c,
        ranks: Object.fromEntries(Object.keys(ranks).map(k => [k, ranks[k][c.player.id]])),
        photo: mvpPhoto(season, c.player.id, photoMeta[c.player.id]),
      })),
      leagueSize: total,
      sections: sectionSummaries(mvpSectionFacts({ season, week, playoffsStarted, top: scored, race: raceKey }), { keep: playoffsStarted }),
      season,
      week,
      totalGames,
      seasonGames: SEASON_GAMES_PER_TEAM,
      isAdmin: !!req.session?.isAdmin,
      playoffsStarted,
      called: raceKey === 'mvp' ? (settleMvpPodium(season), mvpPodiumReveal(season, scored.slice(0, 3).map(c => String(c.player.id)), req.session?.playerPlayerId || null)) : null,
    }),
  }));
}

app.get('/mvp', (req, res) => renderRacePage(req, res, 'mvp'));
app.get('/dpoy', (req, res) => renderRacePage(req, res, 'dpoy'));

// ── /leaders and /roast (views/leaders.js, views/roast.js) ───────────────────
// One view per URL: ?stats=pg|tot|rec|po & ?season=N|alltime. The page's dropdowns fetch
// the same URL with ?partial=1 and swap the content in place (no full reload).
function leaderSeasonsDesc() {
  return [...new Set(getLeaderSeasons().map(Number))].filter(Boolean).sort((a, b) => b - a);
}
function pickLeadersSeason(q, seasons, current) {
  if (q === 'alltime') return 'alltime';
  if (seasons.includes(Number(q))) return Number(q);
  if (seasons.includes(Number(current))) return Number(current);
  return seasons[0] ?? 'alltime';
}
function leadersKicker(season, current) {
  if (season === 'alltime') return 'All-time';
  const week = getSeasonLatestWeek(season)?.week ?? null;
  return `Season ${season}${week && String(season) === String(current) ? ` · After week ${week}` : ''}`;
}

// ── Section writeups (one short paragraph under each section header) ─────────
// Only the default view of each page (current season, per game) gets AI copy; every other
// view, and any section the writer gets wrong, shows the model's code-built fallback.
// Same lifecycle as the homepage summaries: the stored copy is keyed by a hash of its
// facts, a stale key renders fallbacks and writes fresh copy in the background.
const PAGE_WRITEUPS_VERSION = 2;
// This page's own list, on top of the shared one (lib/writer.js BANNED_WORDS).
const WRITEUP_BANNED = /\b(clash\w*|showdown|impressive|stellar|remarkable|dominat\w*|showcase\w*|intrigu\w*|epic|crowd|fans|spectators)\b/i;
const WRITEUP_MAX_WORDS = 45;
const pageWriteupsInFlight = new Set();
let pageWriteupsCooldownUntil = 0;

function pageWriteupFacts(model, { season, currentSeason }) {
  const scopeLabel = season === 'alltime' ? 'all seasons' : `Season ${season}`;
  const out = {};
  for (const sec of model.sections) {
    const f = sectionFacts(sec, { scopeLabel, currentSeason });
    if (f) out[sec.id] = f;
  }
  return out;
}

// The Roast ribs players, so it keeps one gentle voice unless an admin overrides it at
// /admin/ai-writing ("The Roast writeups").
function roastVoice() {
  const cfg = getVoiceConfig();
  if (cfg.overrides.roast) return pickVoice('roast');
  return cfg.voices.find(v => v.id === 'barbershop' && v.enabled) || pickVoice('roast');
}

async function factCheckPageWriteups(facts, texts) {
  const ids = Object.keys(texts);
  const prompt = `Check these short section writeups for a basketball league stats page against each section's facts.

${ids.map(id => `SECTION ${id}\nFacts:\n${facts[id]}\nCopy: ${texts[id]}`).join('\n\n')}

For each section, list every statement in its copy that its facts do not directly support: wrong numbers, wrong rankings, a player "leading" something they are not #1 in, a tie described as a lead, numbers that were calculated rather than taken from the facts, a team or player mixed up, the wrong season (an earlier season's record called "this season's"), history or streaks the facts don't state, or something called a record that the facts don't call a record. Opinions, jokes and tone are fine. Return an empty list for a section with no problems.`;
  const schema = {
    type: 'object',
    properties: Object.fromEntries(ids.map(id => [id, { type: 'array', items: { type: 'string' } }])),
    required: ids,
  };
  const { data } = await generateJson(prompt, schema, { tier: 'check', temperature: 0, maxTokens: 500, openaiModel: FACT_CHECK_MODEL });
  return Object.fromEntries(ids.map(id => [id, realFactProblems((Array.isArray(data?.[id]) ? data[id] : ['no verdict']).map(p => String(p).slice(0, 200)).filter(Boolean))]));
}

async function generatePageWriteups(page, facts, key) {
  const isRoast = page === 'roast';
  const voice = isRoast ? roastVoice() : pickVoice('home', { date: new Date().toISOString().slice(0, 10) });
  const ids = Object.keys(facts);
  const base = `You write the short paragraph that sits under each section heading on the WKND Basketball ${isRoast ? '"The Roast" page — the playful flip side of the league leaders board' : 'League Leaders page'}. It's a recreational league whose players read every word.

THIS WEEK'S VOICE — ${voice.name}: ${voice.guide}${voiceFlavor(voice, key, 40) ? `\n${voiceFlavor(voice, key, 40)}` : ''}

Write one paragraph per section. Each: 1–2 sentences (a short aside of 3 words or fewer doesn't count), at most 40 words, plain text (no markdown, asterisks or emoji). Tell ONE story from that section's facts — a close race, a tie, a big gap, a player on several boards. Mention at most two or three players; never walk through every board.${isRoast ? ' Make it funny: a wry line or light joke in the voice, not a dry recap of the numbers.' : ''}

SECTIONS
${ids.map(id => `[${id}]\n${facts[id]}`).join('\n\n')}

Rules:
- Every number must be copied from that section's facts. Never calculate new numbers (differences, sums, percentages) — if a gap matters, use the gap the facts give.
- A player only "leads" a board where they are #1. A tie is a tie, not a lead.
- Write player names in normal case exactly as the facts spell them (e.g. Vin Salenga); team names in title case.
- Only call something a record if the facts call it one. Records list the season they were set in; only say "this season" for one the facts mark "set this season". The facts list today's top marks, not what they replaced, so never say a mark broke, beat or surpassed anyone's earlier best. Don't invent history, streaks or comparisons.
- Don't mention fans, the crowd or spectators. No filler like "impressive", "stellar", "remarkable", "dominant", "showcase", "clash" or "epic".${isRoast ? `
- This is friendly ribbing about the numbers only — never about looks, background, effort, character or anyone's life off the court. Nothing mean; it should be something the player laughs at too.` : ''}
- Write finished copy only: no notes, alternatives or questions.

FINAL REMINDER — one story per section, at most 40 words, in the ${voice.name} voice.${voice.sample ? ` Example of the voice (style only — do not copy its words or facts): "${voice.sample}"` : ''}`;

  const accepted = {};
  let notes = '';
  for (let attempt = 1; attempt <= 3; attempt++) {
    const todo = ids.filter(id => !accepted[id]);
    if (!todo.length) break;
    const schema = { type: 'object', properties: Object.fromEntries(todo.map(id => [id, { type: 'string' }])), required: todo };
    const prompt = base + (todo.length < ids.length ? `\n\nOnly write these sections this time: ${todo.join(', ')}.` : '') + notes;
    const { data } = await generateJson(prompt, schema, { tier: 'short', temperature: Math.min(aiTemperature(), 0.7), maxTokens: 900 });
    const drafts = {};
    for (const id of todo) {
      const text = String(data?.[id] || '').replace(/\*\*/g, '').replace(/\s+/g, ' ').trim().slice(0, 400);
      if (!text) continue;
      // Code-side guards first — the shared writer checks (lib/writer.js) per section: every
      // number (digits and spelled) from this section's facts, no claim they don't back, the
      // shared banned list plus this page's own, and the length.
      const words = text.split(/\s+/).length;
      const sentences = countSentences(text);
      const banned = text.match(WRITEUP_BANNED);
      const problems = [
        ...numberProblems(text, facts[id], { pairs: false }),
        ...claimProblems(text, facts[id]),
        ...bannedProblems(text),
        ...(banned ? [`it uses the word "${banned[0]}"`] : []),
        ...voiceProblems(text, voice),
        ...(words > WRITEUP_MAX_WORDS || sentences > 2 ? [`it is too long (${words} words, ${sentences} sentences; the limit is 2 sentences and 40 words, so tell ONE story)`] : []),
      ];
      if (problems.length) {
        console.warn(`${page} writeup [${id}] attempt ${attempt} rejected: ${problems.join(' | ')}`);
        notes += `\n\nA previous [${id}] draft was rejected — fix every point: ${problems.join('; ')}.`;
        continue;
      }
      drafts[id] = text;
    }
    if (!Object.keys(drafts).length) continue;
    const problems = await factCheckPageWriteups(facts, drafts);
    for (const [id, text] of Object.entries(drafts)) {
      if (problems[id].length) {
        console.warn(`${page} writeup [${id}] attempt ${attempt} failed the fact check: ${problems[id].join(' | ')}`);
        notes += `\n\nA previous [${id}] draft was rejected for these errors — avoid them: ${problems[id].join('; ')}`;
      } else accepted[id] = text;
    }
  }
  if (!Object.keys(accepted).length) throw new Error('No writeup passed the checks');
  setSetting(`${page}_writeups`, JSON.stringify({ key, texts: accepted, voice: voice.id, at: Date.now() }));
  return accepted;
}

function pageWriteupsKey(page, season, facts) {
  return `v${PAGE_WRITEUPS_VERSION}|${page}|${season}|${createHash('sha1').update(JSON.stringify(facts)).digest('hex').slice(0, 12)}`;
}

// Stored AI copy when it matches today's facts; otherwise {} (fallbacks) + background refresh.
function getPageWriteups(page, facts, season) {
  if (!Object.keys(facts).length) return {};
  const key = pageWriteupsKey(page, season, facts);
  let stored = null;
  try { stored = JSON.parse(getSetting(`${page}_writeups`, '') || 'null'); } catch {}
  if (stored && stored.key === key) return stored.texts || {};
  if (aiAvailable() && !pageWriteupsInFlight.has(page) && Date.now() >= pageWriteupsCooldownUntil) {
    pageWriteupsInFlight.add(page);
    generatePageWriteups(page, facts, key)
      .catch(err => { console.error(`${page} writeups failed:`, err.message); pageWriteupsCooldownUntil = Date.now() + HOME_SUMMARY_COOLDOWN_MS; })
      .finally(() => pageWriteupsInFlight.delete(page));
  }
  return {};
}

function leadersDefaultModel(current) {
  const seasons = leaderSeasonsDesc();
  const season = pickLeadersSeason('', seasons, current);
  if (season === 'alltime') return null;
  const model = buildLeadersModel({
    stats: 'pg', season, currentSeason: current, seasons,
    players: buildLeaderPlayers(season), careerPlayers: buildLeaderPlayersAllTime(), gameRecords: getGameRecords(),
  });
  return { model, season };
}
function roastDefaultModel(current) {
  const seasons = leaderSeasonsDesc();
  const season = pickLeadersSeason('', seasons, current);
  if (season === 'alltime') return null;
  return { model: buildRoastModel({ season, players: buildLeaderPlayers(season), gameRecords: getGameRecords(), currentSeason: current }), season };
}

app.post('/admin/leaders/writeups/regenerate', requireAuth, express.json(), async (req, res) => {
  const page = req.body?.page === 'roast' ? 'roast' : 'leaders';
  if (!aiAvailable()) return res.status(400).json({ error: 'No AI API key configured.' });
  const current = getPortalCurrentSeason();
  const d = page === 'roast' ? roastDefaultModel(current) : leadersDefaultModel(current);
  if (!d) return res.status(400).json({ error: 'Nothing to write about yet.' });
  const facts = pageWriteupFacts(d.model, { season: d.season, currentSeason: current });
  try {
    await generatePageWriteups(page, facts, pageWriteupsKey(page, d.season, facts));
    res.json({ ok: true });
  } catch (err) {
    console.error(`${page} writeups regenerate failed:`, err.message);
    res.status(502).json({ error: 'The AI couldn’t write copy that passed the fact check — try again in a bit.' });
  }
});

app.get('/leaders', (req, res) => {
  const current  = getPortalCurrentSeason();
  const seasons  = leaderSeasonsDesc();
  const stats    = ['pg', 'tot', 'rec', 'po'].includes(req.query.stats) ? req.query.stats : 'pg';
  const season   = pickLeadersSeason(String(req.query.season || ''), seasons, current);
  const isAll    = season === 'alltime';
  const isAdmin  = !!req.session?.isAdmin;

  let players = [];
  if (stats === 'po') players = isAll ? [] : getPlayoffLeaders(season);
  else if (stats !== 'rec') players = isAll ? buildLeaderPlayersAllTime() : buildLeaderPlayers(season);
  const model = buildLeadersModel({
    stats, season, currentSeason: current, seasons, players,
    careerPlayers: stats === 'pg' && !isAll ? buildLeaderPlayersAllTime() : [],
    gameRecords: stats === 'pg' || stats === 'rec' ? getGameRecords() : [],
  });

  const isDefault = stats === 'pg' && !isAll && String(season) === String(current);
  const writeups = isDefault ? getPageWriteups('leaders', pageWriteupFacts(model, { season, currentSeason: current }), season) : {};
  // Page summary = the homepage's stored "leaders" summary, while it's for this season.
  let summary = null;
  if (isDefault) {
    try {
      const s = JSON.parse(getSetting('home_summary_leaders', '') || 'null');
      if (s && String(s.key || '').split('|')[2] === String(season)) summary = s;
    } catch {}
  }
  const n = players.length;
  const maxGp = players.reduce((m, p) => Math.max(m, p.games_played || 0), 0);
  const meta = stats === 'rec'
    ? 'The best single-game lines, regular season and playoffs.'
    : n ? `${n} players${!isAll && maxGp ? ` · up to ${maxGp} game${maxGp === 1 ? '' : 's'} each` : ''}${stats === 'pg' ? ` · per-game boards need ${isAll ? `${CAREER_MIN_GP}+ games` : "two thirds of their team's games"}` : ''} · shooting boards need minimum attempts` : '';
  const html = leadersPage({
    model, seasons, currentSeason: current,
    kicker: stats === 'rec' ? `Single-game records · ${isAll ? 'All seasons' : `Season ${season}`}` : stats === 'po' ? `Playoffs · ${isAll ? 'All-time' : `Season ${season}`}` : leadersKicker(season, current),
    meta,
    summaryHtml: isDefault && (summary || isAdmin) ? summaryPanel(summary, 'leaders', isAdmin) : '',
    writeups,
    showDownload: true, // open to everyone, like Share
    asOfLabel: isAll ? 'ALL TIME' : leadersKicker(season, current).toUpperCase(),
    emptyMsg: stats === 'po'
      ? (isAll ? 'Playoff leaders are kept per season — pick a season.' : `No playoff games in Season ${season} yet.`)
      : 'No games played yet for this selection.',
  });
  if (req.query.partial === '1') return res.type('html').send(html);
  res.send(renderPage(req, {
    title: 'League Leaders | WKND Basketball',
    currentPath: req.path,
    body: `<div class="page-content">${html}</div>${leadersScript({
      isAdmin,
      regen: [{ url: '/admin/home-summary/regenerate', body: { block: 'leaders' } }, { url: '/admin/leaders/writeups/regenerate', body: { page: 'leaders' } }],
    })}`,
  }));
});

app.get('/roast', (req, res) => {
  const current = getPortalCurrentSeason();
  const seasons = leaderSeasonsDesc();
  const season  = pickLeadersSeason(String(req.query.season || ''), seasons, current);
  const isAll   = season === 'alltime';
  const isAdmin = !!req.session?.isAdmin;
  const players = isAll ? buildLeaderPlayersAllTime() : buildLeaderPlayers(season);
  const model   = buildRoastModel({ season, players, gameRecords: getGameRecords(), currentSeason: current });
  const isDefault = !isAll && String(season) === String(current);
  const writeups = isDefault ? getPageWriteups('roast', pageWriteupFacts(model, { season, currentSeason: current }), season) : {};
  const html = roastPage({
    model, seasons,
    kicker: leadersKicker(season, current),
    meta: 'The flip side of the <a href="/leaders">leaders board</a> · all in good fun · 3+ games to qualify',
    // Admins get a Regenerate for the section writeups (the roast has no page summary).
    summaryHtml: isDefault && isAdmin ? `<div class="ld-admin"><button type="button" class="hs-summary__regen">↺ Regenerate writeups</button></div>` : '',
    writeups,
    showDownload: true, // open to everyone, like Share
    asOfLabel: isAll ? 'ALL TIME' : leadersKicker(season, current).toUpperCase(),
  });
  if (req.query.partial === '1') return res.type('html').send(html);

  const roastUrl  = `${SITE_ORIGIN}/roast`;
  const roastDesc = `The flip side of the leaders board. Season ${current || ''} worst performers, funniest stat disasters, and dubious awards — only on WKND Basketball.`;
  const roastMetaTags = [
    `<meta name="description" content="${escAttr(roastDesc)}">`,
    `<link rel="canonical" href="${escAttr(roastUrl)}">`,
    `<meta property="og:type" content="website">`,
    `<meta property="og:site_name" content="WKND Basketball">`,
    `<meta property="og:locale" content="en_US">`,
    `<meta property="og:title" content="The Roast | WKND Basketball">`,
    `<meta property="og:description" content="${escAttr(roastDesc)}">`,
    `<meta property="og:url" content="${escAttr(roastUrl)}">`,
    `<meta name="twitter:card" content="summary">`,
    `<meta name="twitter:title" content="The Roast | WKND Basketball">`,
    `<meta name="twitter:description" content="${escAttr(roastDesc)}">`,
  ].join('\n  ');
  res.send(renderPage(req, {
    title: 'The Roast | WKND Basketball',
    currentPath: req.path,
    metaTags: roastMetaTags,
    body: `<div class="page-content">${html}</div>${leadersScript({
      isAdmin, regen: [{ url: '/admin/leaders/writeups/regenerate', body: { page: 'roast' } }],
    })}`,
  }));
});

// ── /teams + /teams/:slug (rebuilt 2026-10-11 from the "WKND Teams Redesign" canvas) ──────
// views/teams.js (index) and views/team-detail.js (team page), styles in public/teams.css.
// Both pages carry AI summaries written by generateHomeSummary with { strict: true } — the
// same prompt, number guard and fact check as the homepage blocks, plus the stricter
// code-side checks. Stored in settings (teams_summary_*), shown only while their key still
// matches the facts, regenerated in the background (never awaited) or by an admin.
const TEAMS_SUMMARY_VERSION = 1;
const teamsSummaryInFlight = new Set();
const TEAM_AWARD_LABELS = {
  mvp: 'MVP', finals_mvp: 'Finals MVP', dpoy: 'Defensive POY', scoring_champ: 'Scoring champ',
  assists_leader: 'Assists leader', rebounds_leader: 'Rebounds leader', steals_leader: 'Steals leader',
  blocks_leader: 'Blocks leader', three_pm_leader: '3PM leader', four_pm_leader: '4PM leader',
  all_wknd_1: 'All-WKND 1st team', all_wknd_2: 'All-WKND 2nd team', all_wknd_def: 'All-WKND Defense',
};
const ordinalOf = n => { const s = ['th', 'st', 'nd', 'rd'], v = n % 100; return n + (s[(v - 20) % 10] || s[v] || s[0]); };
const fmt1 = n => (Number.isFinite(n) ? n.toFixed(1) : '—');
const signed1 = n => `${n > 0 ? '+' : n < 0 ? '−' : ''}${Math.abs(n).toFixed(1)}`;
const teamSide = (g, teamId) => (g.team_a_id === teamId ? 'a' : g.team_b_id === teamId ? 'b' : null);
function teamResult(g, teamId) {
  const side = teamSide(g, teamId);
  const my = Number(side === 'a' ? g.team_a_score : g.team_b_score);
  const opp = Number(side === 'a' ? g.team_b_score : g.team_a_score);
  return { won: my > opp, my, opp, oppName: side === 'a' ? g.team_b_name : g.team_a_name, oppId: side === 'a' ? g.team_b_id : g.team_a_id };
}
const resultTitle = (g, teamId) => { const r = teamResult(g, teamId); return `${r.won ? 'W' : 'L'} ${r.my}–${r.opp} ${r.oppName}`; };
const gameTypeLabel = g => (g.game_type === 'finals' ? 'Finals' : g.game_type === 'playoff' ? 'Playoffs' : '');

// Consecutive results from the newest game back (games newest first).
function streakOf(games, teamId) {
  if (!games.length) return null;
  const won = teamResult(games[0], teamId).won;
  let count = 0;
  for (const g of games) { if (teamResult(g, teamId).won === won) count++; else break; }
  return { won, count };
}

// The champion of each finished season (awards: 'champion' rows carry the team), newest first,
// with the Finals series line and the MVPs for the Past champions rows / history.
function teamsChampions(teams) {
  const out = [];
  const teamById = Object.fromEntries(teams.map(t => [t.id, t]));
  for (const season of getGameSeasons()) {
    const awards = getSeasonAwards(season);
    const champ = awards.find(a => a.award_type === 'champion' && a.team_id && teamById[a.team_id]);
    if (!champ) continue;
    const team = teamById[champ.team_id];
    const finals = getPlayoffGames(season).filter(g => g.game_type === 'finals' && (Number(g.team_a_score) + Number(g.team_b_score)) > 0);
    let line = '', dateLabel = '', oppName = '', series = '';
    if (finals.length) {
      const wins = finals.filter(g => teamResult(g, team.id).won).length;
      const last = finals[finals.length - 1];
      const r = teamResult(last, team.id);
      oppName = r.oppName;
      series = `${wins}–${finals.length - wins}`;
      line = `Beat ${oppName} ${series} in the Finals${finals.length > 1 ? ` · ${r.my}–${r.opp} in Game ${finals.length}` : ` · ${r.my}–${r.opp}`}`;
      dateLabel = new Date(`${gameYmd(last.date)}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    }
    const person = type => { const a = awards.find(x => x.award_type === type && x.player_id); const p = a ? getPlayerById(a.player_id) : null; return p ? displayPlayerName(p.name) : ''; };
    out.push({
      season: String(season), teamId: team.id, team: team.name, line, dateLabel, oppName, series, finals,
      mvp: person('mvp'), finalsMvp: person('finals_mvp'), scoringChamp: person('scoring_champ'),
      championIds: awards.filter(a => a.award_type === 'champion' && a.team_id === team.id).map(a => a.player_id),
    });
  }
  return out;
}

// Stored summary while its key matches; otherwise kick off a background rewrite.
// The stored write-up when it still matches the facts; never starts a new one (the players
// app reads it this way: no side effects on an app GET).
function storedTeamsSummary(settingKey, f) {
  if (!f) return null;
  let stored = null;
  try { stored = JSON.parse(getSetting(settingKey, '') || 'null'); } catch {}
  if (!stored || stored.key !== f.key) return null;
  // The writer sometimes drops the **name** markers; then the team names get the amber
  // highlight anyway, so every panel reads the same.
  let headline = String(stored.headline || '');
  if (!headline.includes('**')) {
    const names = getAllTeams().map(t => t.name).sort((a, b) => b.length - a.length);
    headline = headline.replace(new RegExp(`\\b(${names.map(n => n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})\\b`, 'gi'), '**$1**');
  }
  return { kicker: stored.kicker, headline, body: stored.body };
}
function teamsSummary(settingKey, block, f) {
  if (!f) return null;
  const stored = storedTeamsSummary(settingKey, f);
  if (stored) return stored;
  if (aiAvailable() && !teamsSummaryInFlight.has(settingKey) && Date.now() >= homeSummaryCooldownUntil) {
    teamsSummaryInFlight.add(settingKey);
    generateHomeSummary(block, f, { where: f.where, settingKey, strict: true })
      .catch(err => { console.error(`Teams summary (${settingKey}) failed:`, err.message); homeSummaryCooldownUntil = Date.now() + HOME_SUMMARY_COOLDOWN_MS; })
      .finally(() => teamsSummaryInFlight.delete(settingKey));
  }
  return null;
}
const factsKey = (tag, facts) => `v${TEAMS_SUMMARY_VERSION}|${tag}|${createHash('sha1').update(facts).digest('hex').slice(0, 16)}`;

// Seasons with at least one played game, newest first; the current season leads when it has one.
function teamsSeasonList() {
  const played = new Set(getAllGames().filter(isPlayedGame).map(g => String(g.season)));
  return getGameSeasons().map(String).filter(s => played.has(s));
}

// ── /teams data ──────────────────────────────────────────────────────────────
// Stack-up categories, best first. "Allowed" and "Turnovers" rank low-to-high.
const STACKUP_CATS = [
  { id: 'pts', title: 'Points', note: 'PPG', fact: 'Points scored', v: t => t.ppg },
  { id: 'opp', title: 'Allowed', note: 'fewer is better', fact: 'Points allowed (fewer is better)', low: true, v: t => t.opp },
  { id: 'reb', title: 'Rebounds', note: 'RPG', fact: 'Rebounds', v: t => t.box?.gp ? t.box.reb / t.box.gp : null },
  { id: 'ast', title: 'Assists', note: 'APG', fact: 'Assists', v: t => t.box?.gp ? t.box.ast / t.box.gp : null },
  { id: 'stl', title: 'Steals', note: 'SPG', fact: 'Steals', v: t => t.box?.gp ? t.box.stl / t.box.gp : null },
  { id: 'to', title: 'Turnovers', note: 'fewer is better', fact: 'Turnovers (fewer is better)', low: true, v: t => t.box?.gp ? t.box.turnover / t.box.gp : null },
  { id: 'fg', title: 'Field goal %', note: 'FG%', fact: 'Field goal percentage', pct: true, v: t => t.box?.fga ? t.box.fgm / t.box.fga * 100 : null },
  { id: 'tp', title: 'Three-point %', note: '3P%', fact: 'Three-point percentage', pct: true, v: t => t.box?.fg3a ? t.box.fg3m / t.box.fg3a * 100 : null },
];
// "Known for": the categories a team ranks 1st in (else 2nd), in this order.
const KNOWN_FOR = [['pts', 'scoring'], ['opp', 'defense'], ['reb', 'rebounding'], ['ast', 'assists'], ['stl', 'steals'], ['to', 'ball security'], ['fg', 'FG%'], ['tp', '3P%']];

function buildTeamsIndex(season) {
  const currentSeason = String(getPortalCurrentSeason());
  const isCurrent = String(season) === currentSeason;
  const teams = getAllTeams();
  const allGames = byDate(getAllGames());
  const standings = getSeasonStandings(season);
  const seeded = computeSeeds(standings, buildSeasonH2HMap(standings, season));
  const order = [...seeded, ...standings.filter(s => !seeded.includes(s))];
  const boxById = Object.fromEntries(getTeamSeasonStats(season).map(s => [s.team_id, s]));
  const seasonPlayers = getSeasonPlayerStats(season);
  const teamGameCounts = getTeamGameCounts(season);
  const heads = getAllTeamHeads();
  const champions = teamsChampions(teams);
  const reigning = champions.find(c => Number(c.season) <= Number(season)) || null;
  const upcoming = isCurrent ? getUpcomingGames(allGames) : [];
  const active = getPlayersWithRatings('').filter(p => p.status === 'active');
  const dayLabel = ymd => new Date(`${ymd}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

  const rows = order.map((row, i) => {
    const t = teams.find(x => x.id === row.id) || row;
    const gp = (row.wins || 0) + (row.losses || 0);
    const games = allGames.filter(g => String(g.season) === String(season) && g.game_type === 'regular' && isPlayedGame(g) && teamSide(g, t.id));
    const next = upcoming.find(g => teamSide(g, t.id));
    const stars = seasonPlayers.filter(p => p.team_id === t.id && meetsLeaderRule(p.games_played, teamGameCounts[t.id]))
      .map(p => ({ p, ppg: (p.pts || 0) / p.games_played }))
      .sort((a, b) => b.ppg - a.ppg).slice(0, 3)
      .map(({ p, ppg }) => ({ id: p.id, name: displayPlayerName(p.name), short: String(p.name).split(',')[0].trim().toUpperCase(), team: t.name, ppg: fmt1(ppg) }));
    return {
      id: t.id, slug: teamSlug(t), name: t.name, place: gp ? ordinalOf(i + 1) : '', rank: i + 1, gp,
      wins: row.wins || 0, losses: row.losses || 0, record: `${row.wins || 0}–${row.losses || 0}`,
      ppg: gp ? fmt1(row.pf / gp) : null, opp: gp ? fmt1(row.pa / gp) : null,
      ppgNum: gp ? row.pf / gp : null, oppNum: gp ? row.pa / gp : null, diff: gp ? row.point_diff / gp : null, diffTotal: row.point_diff || 0,
      streak: streakOf(games, t.id),
      form: games.slice(0, 5).reverse().map(g => ({ r: teamResult(g, t.id).won ? 'W' : 'L', title: resultTitle(g, t.id) })),
      chip: reigning && reigning.teamId === t.id ? `S${reigning.season} champions` : '',
      box: boxById[t.id] || null, stars,
      next: next ? `vs ${teamResult(next, t.id).oppName} · ${dayLabel(gameYmd(next.date))}${gameTipLabel(next) ? ` · ${gameTipLabel(next)}` : ''}` : '',
      head: heads.filter(h => h.team_id === t.id).map(h => displayPlayerName(h.player_name)).join(', '),
      rosterCount: isCurrent
        ? active.filter(p => String(p.team_name || '').toUpperCase() === String(t.name).toUpperCase()).length
        : seasonPlayers.filter(p => p.team_id === t.id).length,
    };
  });

  // Category rankings (teams that have played only), shared by the cards' "known for" line.
  const played = rows.filter(t => t.gp > 0);
  const cats = STACKUP_CATS.map(c => {
    const list = played.map(t => ({ t, num: c.v({ ...t, ppg: t.ppgNum, opp: t.oppNum }) })).filter(x => x.num != null);
    list.sort((a, b) => (c.low ? a.num - b.num : b.num - a.num));
    const rankOf = {};
    list.forEach((x, i) => { rankOf[x.t.id] = i > 0 && x.num.toFixed(1) === list[i - 1].num.toFixed(1) ? rankOf[list[i - 1].t.id] : i + 1; });
    return { ...c, rankOf, rows: list.map(x => ({ team: x.t.name, num: x.num, value: `${fmt1(x.num)}${c.pct ? '%' : ''}` })), lowBetter: !!c.low };
  }).filter(c => c.rows.length >= 2);
  for (const t of rows) {
    const at = rank => KNOWN_FOR.filter(([id]) => cats.find(c => c.id === id)?.rankOf[t.id] === rank).map(([, label]) => label);
    const first = at(1), second = at(2);
    t.knownFor = first.length ? `1st in ${first.slice(0, 2).join(' and ')}` : second.length ? `2nd in ${second.slice(0, 2).join(' and ')}` : '';
    t.ranks = Object.fromEntries(cats.map(c => [c.id, c.rankOf[t.id]]));
  }

  const nextDay = upcoming[0] ? `next games ${dayLabel(gameYmd(upcoming[0].date))}` : '';
  const week = isCurrent ? getSeasonLatestWeek(season)?.week ?? null : null;
  return {
    season: String(season), isCurrent, week, teams: rows, cats, champions,
    playerCount: rows.reduce((n, t) => n + t.rosterCount, 0), nextLabel: nextDay,
  };
}

function teamsIndexSummaryFacts(d) {
  const title = s => titleCase(s);
  const played = d.teams.filter(t => t.gp > 0);
  if (!played.length) return null;
  const after = d.week ? `AFTER WEEK ${d.week}` : `SEASON ${d.season}`;
  const catLabel = { pts: 'scoring', opp: 'points allowed (fewest)', reb: 'rebounding', ast: 'assists', stl: 'steals', to: 'turnovers (fewest)', fg: 'field goal percentage', tp: 'three-point percentage' };
  const lines = played.map(t => {
    const best = d.cats.filter(c => c.rankOf[t.id] === 1).map(c => `${catLabel[c.id]} (${c.rows[0].value})`);
    const worst = d.cats.filter(c => c.rankOf[t.id] === c.rows.length).map(c => `${catLabel[c.id]} (${c.rows[c.rows.length - 1].value})`);
    const parts = [`${t.rank}. ${title(t.name)} ${t.wins}-${t.losses}`, `scores ${t.ppg} and allows ${t.opp} per game`, `point differential ${t.diffTotal > 0 ? '+' : ''}${t.diffTotal} for the season`];
    if (t.streak) parts.push(`${t.streak.won ? 'won' : 'lost'} its last ${t.streak.count === 1 ? 'game' : `${t.streak.count} games`}`);
    if (best.length) parts.push(`1st in the league in ${best.join(', ')}`);
    if (worst.length) parts.push(`last in ${worst.join(', ')}`);
    if (t.stars[0]) parts.push(`top scorer ${t.stars[0].name} ${t.stars[0].ppg}`);
    if (t.chip) parts.push(`reigning ${t.chip.replace(/^S(\d+) /, 'Season $1 ')}`);
    return `- ${parts.join(', ')}`;
  });
  const facts = `Season ${d.season} teams, per game averages, standings order:\n${lines.join('\n')}`;
  return {
    key: factsKey('index', facts), kicker: `The teams · ${after}`, section: 'Teams (one card per team)', where: 'Teams page', facts,
    focus: 'This sits on the Teams page, not the standings: tell what makes one or two teams stand out — what each is best or worst at — rather than recapping the standings order.',
  };
}

function teamsStackupSummaryFacts(d) {
  if (d.cats.length < 3) return null;
  const after = d.week ? `AFTER WEEK ${d.week}` : `SEASON ${d.season}`;
  const facts = `Season ${d.season} team rankings, per game, best first:\n${d.cats.map(c => `- ${c.fact}: ${c.rows.map(r => `${titleCase(r.team)} ${r.value}`).join(', ')}`).join('\n')}`;
  return {
    key: factsKey('stackup', facts), kicker: `How they stack up · ${after}`, section: 'How they stack up (team stat rankings)', where: 'Teams page', facts,
    focus: 'Pick the one or two most telling stat stories across these rankings — the biggest gap at the top or bottom of a category, or a team that ranks first in some categories and last in others. Don\'t list every category.',
  };
}

function teamsChampionsSummaryFacts(champions) {
  const c = champions[0];
  if (!c) return null;
  const title = s => titleCase(s);
  const standings = getSeasonStandings(c.season);
  const playoffs = getPlayoffGames(c.season).filter(g => g.game_type === 'playoff' && (Number(g.team_a_score) + Number(g.team_b_score)) > 0);
  const day = g => new Date(`${gameYmd(g.date)}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  const beat = g => { const aw = Number(g.team_a_score) > Number(g.team_b_score); return `${title(aw ? g.team_a_name : g.team_b_name)} beat ${title(aw ? g.team_b_name : g.team_a_name)} ${Math.max(g.team_a_score, g.team_b_score)}-${Math.min(g.team_a_score, g.team_b_score)} (${day(g)})`; };
  const active = getPlayersWithRatings('').filter(p => p.status === 'active' && String(p.team_name || '').toUpperCase() === String(c.team).toUpperCase());
  const back = active.filter(p => c.championIds.includes(p.id)).length;
  const lines = [
    `Season ${c.season} regular season records: ${standings.map(s => `${title(s.name)} ${s.wins}-${s.losses}`).join(', ')}.`,
    playoffs.length ? `Playoff games: ${playoffs.map(beat).join('; ')}.` : '',
    c.finals.length ? `Finals, ${title(c.team)} vs ${title(c.oppName)}: ${c.finals.map((g, i) => `Game ${i + 1}: ${beat(g)}`).join('; ')}. ${title(c.team)} won the Finals ${c.series.replace('–', '-')} and the Season ${c.season} championship.` : `${title(c.team)} won the Season ${c.season} championship.`,
    [c.mvp && `Season ${c.season} MVP: ${c.mvp}`, c.finalsMvp && `Finals MVP: ${c.finalsMvp}`, c.scoringChamp && `Scoring champion: ${c.scoringChamp}`].filter(Boolean).join('. ') + '.',
    back ? `${back} players from ${title(c.team)}'s Season ${c.season} championship team are on ${title(c.team)}'s roster this season.` : '',
  ].filter(x => x && x !== '.');
  const facts = `${champions.length === 1 ? `Season ${c.season} (the only completed season on record)` : `Season ${c.season} (the most recent completed season)`}:\n${lines.map(l => `- ${l}`).join('\n')}`;
  return {
    key: factsKey('champions', facts), kicker: `Champions · Season ${c.season}`, section: 'Past champions', where: 'Teams page', facts,
    focus: 'Sum up the last champion: how they won it, the deciding game, and who carried them. One closing beat may connect to this season only through the roster fact given.',
  };
}

app.get('/teams', (req, res) => {
  const seasons = teamsSeasonList();
  const currentSeason = String(getPortalCurrentSeason());
  const fallback = seasons.includes(currentSeason) ? currentSeason : (seasons[0] || currentSeason);
  const season = seasons.includes(String(req.query.season)) ? String(req.query.season) : fallback;
  const d = buildTeamsIndex(season);
  const isAdmin = !!req.session?.isAdmin;
  const summaries = {
    index: d.isCurrent ? teamsSummary('teams_summary_index', 'teams', teamsIndexSummaryFacts(d)) : null,
    stackup: d.isCurrent ? teamsSummary('teams_summary_stackup', 'teams_stackup', teamsStackupSummaryFacts(d)) : null,
    champions: teamsSummary('teams_summary_champions', 'teams_champions', teamsChampionsSummaryFacts(d.champions)),
  };
  res.send(renderPage(req, {
    title: `${d.isCurrent ? '' : `Season ${season} `}Teams | WKND Basketball`,
    currentPath: req.path,
    metaTags: `<link rel="stylesheet" href="/teams.css?v=${TEAMS_CSS_VER}">`,
    body: teamsBody({ ...d, seasons, summaries, isAdmin }),
  }));
});

// ── /teams/:slug data ────────────────────────────────────────────────────────
function buildTeamPage(team, viewerId) {
  const currentSeason = String(getPortalCurrentSeason());
  const seasons = teamsSeasonList();
  // Numbers come from whichever season actually has games — the current one, or the latest
  // played season in the gap before a new season's first game.
  const statsSeason = seasons.includes(currentSeason) ? currentSeason : (seasons[0] || currentSeason);
  const isCurrent = statsSeason === currentSeason;
  const teams = getAllTeams();
  const allGames = byDate(getAllGames());
  const played = allGames.filter(g => isPlayedGame(g) && teamSide(g, team.id));
  const dayLabel = ymd => new Date(`${ymd}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const shortDayOf = g => new Date(`${gameYmd(g.date)}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

  // Standings place + record (regular season), every team's index row for the ranks.
  const index = buildTeamsIndex(statsSeason);
  const me = index.teams.find(t => t.id === team.id) || { gp: 0, wins: 0, losses: 0, record: '0–0', rank: null };
  const champions = index.champions;
  const titles = champions.filter(c => c.teamId === team.id);

  // Streak across every game (all seasons, playoffs too) — the facts name its span.
  const streak = streakOf(played, team.id);
  const streakSeasonSplit = streak ? played.slice(0, streak.count).reduce((m, g) => { m[g.season] = (m[g.season] || 0) + 1; return m; }, {}) : {};
  const chips = [];
  if (titles.length) chips.push({ kind: 'title', label: titles.length === 1 ? `Season ${titles[0].season} champions` : `${titles.length}× champions` });
  if (streak && streak.count >= 3) chips.push({ kind: streak.won ? 'streak' : 'slump', label: `${streak.won ? 'Won' : 'Lost'} ${streak.count} straight` });
  const form = played.slice(0, 5).reverse().map(g => ({
    r: teamResult(g, team.id).won ? 'W' : 'L',
    title: `${String(g.season) !== statsSeason ? `S${g.season} ${gameTypeLabel(g) || 'regular season'} · ` : gameTypeLabel(g) ? `${gameTypeLabel(g)} · ` : ''}${resultTitle(g, team.id)}`,
  }));
  const allTimeW = played.filter(g => teamResult(g, team.id).won).length;
  const allTime = `${allTimeW}–${played.length - allTimeW}`;

  // Where they rank — the same 6 cards as before (lib/team-ranks.js), now with a meter.
  const pfPaByTeam = Object.fromEntries(getTeamPointsForAgainst(statsSeason).map(r => [r.team_id, r]));
  const allTeamsStats = getTeamSeasonStats(statsSeason).map(s => ({ ...s, ...(pfPaByTeam[s.team_id] || { points_for: 0, points_against: 0 }) }));
  const ranks = computeTeamRankCards(team.id, allTeamsStats).map(c => ({ ...c, place: ordinalOf(c.rank) }));
  const rankOf = id => ranks.find(c => c.id === id)?.rank;

  const kpis = me.gp ? [
    { value: me.ppg, label: `PPG${rankOf('scoring') ? ` · ${ordinalOf(rankOf('scoring'))}` : ''}` },
    { value: me.opp, label: `Allowed${rankOf('defense') ? ` · ${ordinalOf(rankOf('defense'))}` : ''}` },
    { value: signed1(me.diff), label: 'Diff / game', tone: me.diff > 0 ? 'pos' : me.diff < 0 ? 'neg' : '' },
    { value: allTime, label: 'All-time' },
    ...(titles.length ? [{ value: String(titles.length), label: titles.length === 1 ? 'Title' : 'Titles', tone: 'amber' }] : []),
  ] : [{ value: allTime, label: 'All-time' }, ...(titles.length ? [{ value: String(titles.length), label: titles.length === 1 ? 'Title' : 'Titles', tone: 'amber' }] : [])];

  // Up next: the shared Who wins? card while picks are on, else a plain matchup card.
  let openPick = null, nextGame = null;
  const upcomingGame = getUpcomingGames(allGames).find(g => teamSide(g, team.id));
  if (upcomingGame && picksEnabled()) {
    openPick = openPicks(allGames, buildPicksContext(allGames), viewerId).find(o => o.id === upcomingGame.id) || null;
  }
  const h2hMeetings = oppId => played.filter(g => teamResult(g, team.id).oppId === oppId).slice().reverse(); // oldest first
  if (upcomingGame && !openPick) {
    const r = teamResult(upcomingGame, team.id);
    const ms = h2hMeetings(r.oppId);
    const w = ms.filter(g => teamResult(g, team.id).won).length;
    const last = ms[ms.length - 1];
    const oppRow = index.teams.find(t => t.id === r.oppId);
    nextGame = {
      opp: r.oppName, oppRecord: oppRow?.gp ? oppRow.record : '', dateLabel: [dayLabel(gameYmd(upcomingGame.date)), gameTipLabel(upcomingGame)].filter(Boolean).join(' · '), href: previewHref(upcomingGame),
      series: ms.length ? `${team.name} ${w}–${ms.length - w}` : 'First meeting',
      last: last ? `${teamResult(last, team.id).won ? 'W' : 'L'} ${teamResult(last, team.id).my}–${teamResult(last, team.id).opp} · ${shortDayOf(last)}` : '',
    };
  }

  // Team leaders: PPG, RPG, APG, 3PM — top 3 inside the team; the leader's league rank. Same
  // attendance rule as /leaders (lib/qualification.js).
  const statsTeamGames = getTeamGameCounts(statsSeason);
  const seasonPlayers = getSeasonPlayerStats(statsSeason).filter(p => meetsLeaderRule(p.games_played, statsTeamGames[p.team_id]));
  const per = (p, k) => (p[k] || 0) / p.games_played;
  const leagueRank = (k, value) => {
    const vals = seasonPlayers.map(p => +per(p, k).toFixed(1));
    const better = vals.filter(v => v > +value.toFixed(1)).length;
    const tied = vals.filter(v => v === +value.toFixed(1)).length;
    return `${tied > 1 ? 'tied ' : ''}${ordinalOf(better + 1)} in league`;
  };
  const splitName = raw => { const s = String(raw || ''); const i = s.indexOf(','); return i === -1 ? { first: '', last: s.toUpperCase() } : { first: s.slice(i + 1).trim(), last: s.slice(0, i).trim().toUpperCase() }; };
  const mine = seasonPlayers.filter(p => p.team_id === team.id);
  const leaders = [
    { k: 'pts', title: 'Scoring', key: 'PPG' }, { k: 'reb', title: 'Rebounds', key: 'RPG' },
    { k: 'ast', title: 'Assists', key: 'APG' }, { k: 'fg3m', title: '3-pointers', key: '3PM' },
  ].map(c => {
    const top = [...mine].sort((a, b) => per(b, c.k) - per(a, c.k) || b.games_played - a.games_played).slice(0, 3);
    if (!top.length || !(per(top[0], c.k) > 0)) return null;
    const p = top[0], v = per(p, c.k);
    const note = c.k === 'fg3m'
      ? `${p.fg3m} of ${(p.fg3m || 0) + (p.fg3m_miss || 0)}`
      : `${p.games_played} GP`;
    return { ...c, id: p.id, number: p.number ?? '', rank: leagueRank(c.k, v), name: displayPlayerName(p.name), ...splitName(p.name), value: fmt1(v), note,
      rest: top.slice(1).filter(x => per(x, c.k) > 0).map(x => ({ id: x.id, name: displayPlayerName(x.name), value: fmt1(per(x, c.k)) })) };
  }).filter(Boolean);

  // Roster: active players on the team, this season's line, highs from the box scores.
  const seasonTeamGames = played.filter(g => String(g.season) === statsSeason);
  const statsByGame = Object.fromEntries(seasonTeamGames.map(g => [g.id, getGameStats(g.id)]));
  const highs = {};
  for (const rows of Object.values(statsByGame)) for (const s of rows) if (s.team_id === team.id) highs[s.player_id] = Math.max(highs[s.player_id] ?? 0, +s.pts || 0);
  const seasonById = Object.fromEntries(mine.map(p => [p.id, p]));
  const prevSeason = seasons.find(s => Number(s) < Number(statsSeason)) || null;
  const prevTeamOf = prevSeason ? Object.fromEntries(getSeasonPlayerStats(prevSeason).map(p => [p.id, p.team_name])) : {};
  const prevAwards = prevSeason ? getSeasonAwards(prevSeason) : [];
  const lastChamp = champions.find(c => Number(c.season) < Number(statsSeason) || (!isCurrent && c.season === statsSeason)) || null;
  const ringSeasons = {};
  for (const c of champions) for (const pid of c.championIds) (ringSeasons[pid] ||= []).push(c.season);
  const headIds = new Set(getAllTeamHeads().filter(h => h.team_id === team.id).map(h => h.player_id));
  const awardTag = pid => {
    const a = prevAwards.find(x => x.player_id === pid && ['mvp', 'finals_mvp', 'scoring_champ'].includes(x.award_type));
    return a ? `S${prevSeason} ${TEAM_AWARD_LABELS[a.award_type] === 'Scoring champ' ? 'scoring champ' : TEAM_AWARD_LABELS[a.award_type]}` : '';
  };
  const parsePos = raw => { try { return JSON.parse(raw || '[]'); } catch { return []; } };
  const pct = (m, x) => { const att = (m || 0) + (x || 0); return att > 0 ? (m / att) * 100 : null; };
  const teamUpper = String(team.name).toUpperCase();
  const roster = getPlayersWithRatings('')
    .filter(p => p.status === 'active' && String(p.team_name || '').toUpperCase() === teamUpper)
    .map(p => {
      const s = seasonById[p.id];
      const gp = s?.games_played || 0;
      const v = gp ? {
        pts: s.pts / gp, reb: s.reb / gp, ast: s.ast / gp, stl: s.stl / gp, blk: s.blk / gp, to: s.turnover / gp, high: highs[p.id] ?? null,
        fgp: pct((s.fg2m || 0) + (s.fg3m || 0) + (s.fg4m || 0), (s.fg2m_miss || 0) + (s.fg3m_miss || 0) + (s.fg4m_miss || 0)),
        tpp: pct(s.fg3m, s.fg3m_miss), ftp: pct(s.ftm, s.ft_miss),
      } : null;
      const prevTeam = prevTeamOf[p.id];
      const isNew = prevSeason && prevTeam && String(prevTeam).toUpperCase() !== teamUpper;
      const tag = headIds.has(p.id) ? 'Team head' : isNew ? `New · from ${prevTeam}` : awardTag(p.id);
      const rings = ringSeasons[p.id] || [];
      return {
        id: p.id, name: displayPlayerName(p.name), num: p.number != null && p.number !== '' ? String(p.number) : '',
        pos: parsePos(p.positions).slice(0, 3).join(' · '), gp, v, tag, isNew: !!isNew,
        ring: rings.length ? `Season ${rings.join(', ')} champion` : '',
      };
    })
    .sort((a, b) => (b.v?.pts ?? -1) - (a.v?.pts ?? -1) || a.name.localeCompare(b.name));
  const back = lastChamp && lastChamp.teamId === team.id ? roster.filter(p => lastChamp.championIds.includes(p.id)).length : 0;
  const newCount = roster.filter(p => p.isNew).length;
  const rosterSub = [`${roster.length} player${roster.length === 1 ? '' : 's'}`, back ? `${back} back from the title team` : '', newCount ? `${newCount} new` : ''].filter(Boolean).join(' · ');

  // Schedule & results: the /games result cards for this season's games.
  const games = seasonTeamGames.filter(g => g.status === 'final' || g.status === 'complete');
  const playerMap = Object.fromEntries(getAllPlayers().map(p => [p.id, p]));
  const { commentsEnabled, socialByGame, oddsByGame, topScorerByGame } = gameCardExtras(games, allGames, { viewerId, playerMap, statsByGame });

  // Head to head, every opponent, all seasons with playoffs.
  const nextOppId = upcomingGame ? teamResult(upcomingGame, team.id).oppId : null;
  const lastFinals = champions.find(c => c.finals.length && (c.teamId === team.id || c.finals.some(g => teamSide(g, team.id))));
  const h2h = teams.filter(t => t.id !== team.id).map(t => {
    const ms = h2hMeetings(t.id);
    if (!ms.length) return null;
    const w = ms.filter(g => teamResult(g, team.id).won).length;
    const thisSeason = ms.filter(g => String(g.season) === statsSeason);
    const sw = thisSeason.filter(g => teamResult(g, team.id).won).length;
    const margin = ms.reduce((n, g) => { const r = teamResult(g, team.id); return n + (r.my - r.opp); }, 0) / ms.length;
    const last = ms[ms.length - 1], lr = teamResult(last, team.id);
    let tag = '';
    if (t.id === nextOppId) tag = 'Up next';
    else if (lastFinals && lastFinals.finals.some(g => teamResult(g, team.id).oppId === t.id)) tag = lastFinals.teamId === team.id ? `Beat them in the S${lastFinals.season} Finals` : `Lost the S${lastFinals.season} Finals`;
    return {
      opp: t.name, n: ms.length, series: `${w}–${ms.length - w}`, season: `${sw}–${thisSeason.length - sw}`,
      marginNum: margin, margin: signed1(margin), tag,
      games: ms.map(g => ({ r: teamResult(g, team.id).won ? 'W' : 'L', title: `S${g.season}${gameTypeLabel(g) ? ` ${gameTypeLabel(g)}` : ''} · ${shortDayOf(g)} · ${resultTitle(g, team.id)}` })),
      last: `${lr.won ? 'W' : 'L'} ${lr.my}–${lr.opp} · ${shortDayOf(last)}`,
    };
  }).filter(Boolean).sort((a, b) => b.n - a.n);

  // Season by season.
  const history = seasons.filter(s => played.some(g => String(g.season) === s)).map(s => {
    const st = getSeasonStandings(s);
    const sd = computeSeeds(st, buildSeasonH2HMap(st, s));
    const ord = [...sd, ...st.filter(x => !sd.includes(x))];
    const i = ord.findIndex(x => x.id === team.id);
    const row = ord[i] || { wins: 0, losses: 0 };
    const champ = champions.find(c => c.season === s);
    const won = champ?.teamId === team.id;
    const post = played.filter(g => String(g.season) === s && g.game_type !== 'regular');
    const inFinals = post.some(g => g.game_type === 'finals');
    const result = won ? 'Champions'
      : inFinals ? 'Lost in the Finals'
      : post.length ? 'Playoffs'
      : s === currentSeason && !champ ? `${ordinalOf(i + 1)} · in progress` : `${ordinalOf(i + 1)} in the standings`;
    let line = '';
    if (post.length) {
      const semis = post.filter(g => g.game_type === 'playoff');
      const parts = [];
      if (semis.length) {
        const sw = semis.filter(g => teamResult(g, team.id).won).length;
        const opp = teamResult(semis[0], team.id).oppName;
        parts.push(semis.length === 1 ? `${sw ? 'Beat' : 'Lost to'} ${opp} ${teamResult(semis[0], team.id).my}–${teamResult(semis[0], team.id).opp} in the semis` : `${sw > semis.length - sw ? 'Beat' : 'Lost to'} ${opp} ${sw}–${semis.length - sw} in the semis`);
      }
      if (champ && champ.finals.some(g => teamSide(g, team.id))) {
        const fw = champ.finals.filter(g => teamResult(g, team.id).won).length;
        parts.push(`${won ? 'beat' : 'lost to'} ${teamResult(champ.finals[0], team.id).oppName} ${fw}–${champ.finals.length - fw} in the Finals`);
      }
      line = parts.join(', then ');
      line = line.charAt(0).toUpperCase() + line.slice(1);
    }
    const awards = getSeasonAwards(s).filter(a => a.team_id === team.id && TEAM_AWARD_LABELS[a.award_type] && a.player_id);
    const nameOfId = id => { const p = playerMap[id]; return p ? displayPlayerName(p.name) : ''; };
    const chipsOut = [];
    for (const type of Object.keys(TEAM_AWARD_LABELS)) {
      const ofType = awards.filter(a => a.award_type === type);
      if (!ofType.length) continue;
      const names = [...new Set(ofType.map(a => nameOfId(a.player_id)).filter(Boolean))];
      if (names.length) chipsOut.push(`${TEAM_AWARD_LABELS[type]} · ${names.join(', ')}`);
    }
    return { season: s, record: `${row.wins || 0}–${row.losses || 0}`, result, champion: won, line, awards: chipsOut };
  });

  const coverGame = played.find(g => g.has_cover);
  return {
    team, slug: teamSlug(team), season: statsSeason, isCurrent, index, me, titles, streak, streakSeasonSplit,
    kicker: me.gp ? `Season ${statsSeason} · ${ordinalOf(me.rank)} in the standings` : `Season ${statsSeason}`,
    record: me.record, chips, form, kpis, coverId: coverGame?.id || null, openPick, nextGame, upcomingGame,
    ranks, leaders, roster, rosterSub, back, newCount, lastChamp,
    ringLabel: Object.keys(ringSeasons).some(id => roster.some(p => p.id === id)) ? 'Won a title' : '',
    games, topScorerByGame, socialByGame, oddsByGame, commentsEnabled, h2h, history, allTime,
  };
}

function teamPageSummaryFacts(d) {
  const T = titleCase(d.team.name);
  if (!d.me.gp) return null;
  const week = d.isCurrent ? getSeasonLatestWeek(d.season)?.week : null;
  const results = d.games.slice().reverse().map(g => { const r = teamResult(g, d.team.id); return `${r.won ? 'beat' : 'lost to'} ${titleCase(r.oppName)} ${r.my}-${r.opp}${g.overtime ? ' in overtime' : ''} (${new Date(`${gameYmd(g.date)}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })})`; });
  const lines = [
    `Record ${d.me.wins}-${d.me.losses}, ${ordinalOf(d.me.rank)} in the standings. Results in order: ${results.join(', ')}.`,
  ];
  if (d.streak && d.streak.count >= 2) {
    const split = Object.entries(d.streakSeasonSplit);
    const span = split.length > 1
      ? ` (${split.map(([s, n]) => `${n} in Season ${s}${String(s) !== d.season ? ', counting playoff and Finals games' : ''}`).join(' and ')})`
      : String(split[0]?.[0]) === d.season ? ', all this season' : '';
    lines.push(`${T} has ${d.streak.won ? 'won' : 'lost'} ${d.streak.count} straight games${span}.`);
  }
  if (d.ranks.length) lines.push(`Per game, among ${d.ranks[0].totalTeams} teams: ${d.ranks.map(c => `${c.label.toLowerCase()} ${c.valueDisplay}${c.unit ? ` ${c.unit}` : ''} (${ordinalOf(c.rank)})`).join(', ')}.`);
  if (d.leaders.length) lines.push(`Team leaders per game: ${d.leaders.map(c => `${c.name} ${c.value} ${c.key}`).join(', ')}.`);
  lines.push(`Roster: ${d.roster.length} players${d.back ? `, ${d.back} of them from the Season ${d.lastChamp.season} championship team` : ''}${d.newCount ? `, ${d.newCount} new this season` : ''}.`);
  if (d.titles.length) lines.push(`${T} won the championship in Season ${d.titles.map(t => t.season).join(' and Season ')}.`);
  if (d.upcomingGame) {
    const r = teamResult(d.upcomingGame, d.team.id);
    const h = d.h2h.find(x => x.opp === r.oppName);
    const oppRow = d.index.teams.find(t => t.id === r.oppId);
    lines.push(`Next game: ${titleCase(r.oppName)}${oppRow?.gp ? ` (${oppRow.wins}-${oppRow.losses})` : ''} on ${new Date(`${gameYmd(d.upcomingGame.date)}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}.${h ? ` All-time ${T} is ${h.series.replace('–', '-')} against ${titleCase(r.oppName)}; this season ${h.season.replace('–', '-')}.` : ' First ever meeting.'}`);
  }
  const facts = `${T}, Season ${d.season}:\n${lines.map(l => `- ${l}`).join('\n')}`;
  return {
    key: factsKey(`team:${d.team.id}`, facts), kicker: `${T} · ${week ? `AFTER WEEK ${week}` : `SEASON ${d.season}`}`, section: `${T} (team page)`, where: 'team page', facts,
    focus: 'Sum up this team\'s season so far for its own page: where it stands, what it does best, who carries it, and what is next. Lead with the most telling fact.',
  };
}

app.get('/teams/:ref', (req, res) => {
  const resolved = resolveRef('team', req.params.ref,
    ref => getTeamById(ref),
    t   => teamSlug(t)
  );
  if (!resolved) return res.status(404).send(renderPage(req, {
    title: 'Not Found', currentPath: '/teams',
    body: comingSoonPage({ label: 'Team Not Found', description: 'This team could not be found.' })
  }));
  if (resolved.slug) return res.redirect(301, `/teams/${resolved.slug}`);

  const team = getTeamById(resolved.id);
  const d = buildTeamPage(team, req.session?.playerPlayerId || null);
  const summary = d.isCurrent ? teamsSummary(`teams_summary_team_${team.id}`, `team:${team.id}`, teamPageSummaryFacts(d)) : null;
  res.send(renderPage(req, {
    title: `${titleCase(team.name)} Team — Roster & Stats | WKND Basketball`,
    currentPath: '/teams',
    metaTags: `${buildTeamOgTags(req, team)}\n  <link rel="stylesheet" href="/teams.css?v=${TEAMS_CSS_VER}">`,
    body: teamDetailPage({ ...d, summary, isAdmin: !!req.session?.isAdmin, isPlayer: !!req.session?.playerPlayerId }),
  }));
});

// Admin: rewrite one teams-page summary now. block: teams | teams_stackup | teams_champions | team:<id>
app.post('/admin/teams-summary/regenerate', requireAuth, express.json(), async (req, res) => {
  const block = String(req.body?.block || '');
  if (!aiAvailable()) return res.status(400).json({ error: 'No AI API key configured.' });
  let f = null, settingKey = '';
  if (block === 'teams' || block === 'teams_stackup' || block === 'teams_champions') {
    const seasons = teamsSeasonList();
    const cur = String(getPortalCurrentSeason());
    const d = buildTeamsIndex(seasons.includes(cur) ? cur : (seasons[0] || cur));
    if (block === 'teams') { f = teamsIndexSummaryFacts(d); settingKey = 'teams_summary_index'; }
    else if (block === 'teams_stackup') { f = teamsStackupSummaryFacts(d); settingKey = 'teams_summary_stackup'; }
    else { f = teamsChampionsSummaryFacts(d.champions); settingKey = 'teams_summary_champions'; }
  } else if (block.startsWith('team:')) {
    const team = getTeamById(block.slice(5));
    if (!team) return res.status(404).json({ error: 'Unknown team' });
    f = teamPageSummaryFacts(buildTeamPage(team, null));
    settingKey = `teams_summary_team_${team.id}`;
  } else return res.status(400).json({ error: 'Unknown block' });
  if (!f) return res.status(400).json({ error: 'Nothing to summarise yet.' });
  try {
    await generateHomeSummary(block, f, { where: f.where, settingKey, strict: true });
    res.json({ ok: true });
  } catch (err) {
    console.error(`Teams summary (${block}) regenerate failed:`, err.message);
    writerError(res, err);
  }
});

// ── Section writeups ──────────────────────────────────────────────────────────
// The same summary panel as the homepage and /teams, under the section headers of
// /standings, /playoffs, /picks and every final's game page. Same writer, number guard,
// strict checks and fact check as the teams summaries (generateHomeSummary). One site
// setting per section (section_summary_<block>), shown only while its facts key still
// matches; otherwise it's rewritten in the background, never awaited by the page.
// block = "<page>_<section>:<season or game id>", e.g. standings_h2h:4, game_perf:<id>.
// Finished games and past seasons are archives (keep): written on the first view when
// missing, then kept as written even if their facts change; an admin Regenerate is the only
// way to replace one.
const SECTION_SUMMARY_VERSION = 1;
// At most this many writes at once across every section — a page with four sections
// shouldn't fire four AI calls in parallel; the rest are picked up on a later view.
const SECTION_SUMMARY_MAX_IN_FLIGHT = 2;
const sectionSummaryInFlight = new Set();
// Own cooldowns, so a section never pauses the homepage summaries: a section whose drafts
// all fail the checks waits 6 hours before its next try (others carry on); any other error
// (the AI provider) pauses every section for 10 minutes.
const SECTION_SUMMARY_RETRY_MS = 6 * 60 * 60 * 1000;
const sectionSummaryFailedAt = new Map();
let sectionSummaryCooldownUntil = 0;
const sectionFactsKey = (block, facts) => `s${SECTION_SUMMARY_VERSION}|${block}|${createHash('sha1').update(facts).digest('hex').slice(0, 16)}`;

// factsMap: { [section]: facts with .block } → { [section]: { kicker, headline, body } } for
// the ones whose stored copy is current; a missing or stale one is written in the background.
// keep=true is for archives (finished games, past seasons): once written, the stored copy —
// kicker, headline and body — stays as it was even if the facts later change (a stat
// correction, a newer career high). Only an admin Regenerate replaces it.
function sectionSummaries(factsMap, { keep = false } = {}) {
  const out = {};
  for (const [name, f] of Object.entries(factsMap || {})) {
    if (!f) continue;
    const settingKey = `section_summary_${f.block}`;
    let stored = null;
    try { stored = JSON.parse(getSetting(settingKey, '') || 'null'); } catch {}
    if (stored && (keep || stored.key === f.key)) {
      // The writer sometimes drops the **name** markers; then team names get the amber
      // highlight anyway, like the teams panels.
      let headline = String(stored.headline || '');
      if (!headline.includes('**')) {
        const names = getAllTeams().map(t => t.name).sort((a, b) => b.length - a.length);
        if (names.length) headline = headline.replace(new RegExp(`\\b(${names.map(n => n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})\\b`, 'gi'), '**$1**');
      }
      // Live pages take the live kicker (it's only the "as of" label, so a wording change shows
      // without rewriting every summary); archives keep the one saved with the writeup.
      out[name] = { kicker: keep ? (stored.kicker || f.kicker) : (f.kicker || stored.kicker), headline, body: stored.body };
      continue;
    }
    if (!aiAvailable() || sectionSummaryInFlight.has(settingKey)) continue;
    if (sectionSummaryInFlight.size >= SECTION_SUMMARY_MAX_IN_FLIGHT || Date.now() < sectionSummaryCooldownUntil) continue;
    if (Date.now() - (sectionSummaryFailedAt.get(settingKey) || 0) < SECTION_SUMMARY_RETRY_MS) continue;
    sectionSummaryInFlight.add(settingKey);
    generateHomeSummary(f.block, f, { where: f.where, settingKey, strict: true, highsOk: !!f.highsOk })
      .catch(err => {
        console.error(`Section summary (${f.block}) failed:`, err.message);
        // Drafts that failed the checks: this section backs off 6h. Anything else (an AI
        // outage) pauses every section for the short cooldown.
        if (err.code === 'checks') sectionSummaryFailedAt.set(settingKey, Date.now());
        else sectionSummaryCooldownUntil = Date.now() + HOME_SUMMARY_COOLDOWN_MS;
      })
      .finally(() => sectionSummaryInFlight.delete(settingKey));
  }
  return out;
}

// Stamps block + key onto each section's facts.
function sectionFactsMap(page, param, sections) {
  const out = {};
  for (const [name, f] of Object.entries(sections)) {
    if (!f) continue;
    const block = `${page}_${name}:${param}`;
    // The number guard rejects any figure not in the facts, and drafts kept failing on sums
    // and margins they worked out themselves — the facts give margins where they matter.
    const focus = `${f.focus} Use every number exactly as the facts give it: never add, subtract or average numbers yourself.`;
    out[name] = { ...f, focus, block, key: sectionFactsKey(block, f.facts) };
  }
  return out;
}

const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;

// /standings: playoff picture, head to head, the road so far, team stats.
function standingsSectionFacts(sd) {
  const m = standingsModel(sd);
  if (!m.table.length || !m.played.length) return {};
  const T = titleCase;
  // Title-cases just the team names inside a sentence the view built (tiebreak notes, week headlines).
  const teamsTc = s => m.table.reduce((x, t) => x.split(t.name).join(T(t.name)), String(s));
  const rec = t => `${t.wins}-${t.losses}`;
  const asOf = sd.isCurrent ? `After week ${m.week}` : `Season ${sd.season} · final`;
  const where = 'Standings page';
  const out = {};

  if (m.table.length >= 4) {
    const [s1, s2, s3, s4] = m.table;
    const gap = ((s2.wins - s3.wins) + (s3.losses - s2.losses)) / 2;
    // Settled (every game played, or no result left can change the order): said as final.
    const lock = sd.isCurrent ? seasonLockLine(sd.season) : '';
    const live = sd.isCurrent && !lock;
    const lines = [
      'Format: the top 4 teams make the semifinals, 1st vs 4th and 2nd vs 3rd. The higher seed in each semifinal is "twice to beat": it advances with 1 win, while the lower seed has to win 2 games. The Finals are best of 3.',
      live ? `Seeding if the regular season ended today (after week ${m.week}):` : `${lock ? 'Settled' : 'Final'} regular-season seeding, Season ${sd.season}:`,
      `- Semifinal A: 1st ${T(s1.name)} (${rec(s1)}) vs 4th ${T(s4.name)} (${rec(s4)})`,
      `- Semifinal B: 2nd ${T(s2.name)} (${rec(s2)}) vs 3rd ${T(s3.name)} (${rec(s3)})`,
      ...m.table.slice(4).map((t, i) => `- ${i + 5}th ${T(t.name)} (${rec(t)}) is outside the top 4`),
      gap > 0 ? `${T(s2.name)} (2nd) is ${gap} game${gap === 1 ? '' : 's'} ahead of ${T(s3.name)} (3rd) for the last twice-to-beat spot.` : `${T(s2.name)} and ${T(s3.name)} have the same record; the tiebreak gives ${T(s2.name)} the last twice-to-beat spot.`,
      ...m.notes.map(n => `Tiebreak: ${teamsTc(n)}.`),
      sd.isCurrent ? (m.sched.length ? `${plural(m.sched.length, 'regular-season game')} left on the schedule.` : 'No regular-season games left on the schedule.') : '',
      lock,
    ].filter(Boolean);
    out.playoffs = {
      kicker: `Playoff picture · ${asOf}`, section: live ? 'Playoff picture (the semifinal matchups if the season ended now)' : 'Playoff picture (the settled semifinal matchups)', where,
      facts: lines.join('\n'),
      focus: live
        ? 'Describe the playoff picture: who holds the twice-to-beat spots, how tight the race for them is, and the semifinal matchups as they stand. Don\'t recap the whole table.'
        : 'Describe how the regular season set up the playoffs: who earned twice to beat and the semifinal matchups it produced.',
    };
  }

  // Head to head: one line per pairing, in order of first meeting.
  const key = (a, b) => [a, b].sort().join('|');
  const pairs = [];
  for (let i = 0; i < m.table.length; i++) for (let j = i + 1; j < m.table.length; j++) pairs.push([m.table[i], m.table[j]]);
  const h2hLines = pairs.map(([a, b]) => {
    const k = key(a.id, b.id);
    const pg = m.played.filter(g => key(g.team_a_id, g.team_b_id) === k);
    const next = m.sched.find(g => key(g.team_a_id, g.team_b_id) === k);
    if (!pg.length) return `- ${T(a.name)} vs ${T(b.name)}: haven't played yet${next ? `; first meeting is in week ${next.week}` : ''}`;
    const wins = { [a.id]: 0, [b.id]: 0 };
    const games = pg.map(g => { const w = winnerOf(g); wins[w.id]++; return `week ${g.week}: ${T(w.name)} won ${w.pts}-${w.oppPts}, by ${plural(w.pts - w.oppPts, 'point')}`; });
    const aw = wins[a.id], bw = wins[b.id];
    const series = aw === bw ? `season series tied ${aw}-${bw}` : `${T(aw > bw ? a.name : b.name)} leads the season series ${Math.max(aw, bw)}-${Math.min(aw, bw)}`;
    return `- ${T(a.name)} vs ${T(b.name)}: ${games.join('; ')}. ${series}${next ? `; next meeting in week ${next.week}` : ''}`;
  });
  const tri = findTriangle(m.table, m.played);
  if (tri) {
    const ids = [...new Set([...tri].flatMap(k => k.split('|')))];
    h2hLines.push(`Loop: ${ids.map(id => T(m.table.find(t => t.id === id)?.name || '')).join(', ')} each lead one of their series against each other and trail another, so no one of the three has the edge over both others.`);
  }
  out.h2h = {
    kicker: `Head to head · ${asOf}`, section: 'Head to head (every pairing\'s season series)', where,
    facts: `Season ${sd.season} regular-season meetings, by pairing:\n${h2hLines.join('\n')}`,
    focus: 'Pick the one or two most interesting rivalries: a one-sided series, a split one, the loop if there is one, or a meeting still to come. Don\'t go through every pairing.',
  };

  // The road so far: each week's results and the table after it.
  const roadLines = m.weeks.map(w => `- Week ${w.n} (${w.dates.map(d => summaryDay(d)).join(' and ')}): ${w.games.map(g => `${T(g.w)} beat ${T(g.l)} ${g.ws}-${g.ls}`).join('; ')}. Table after: ${w.table.map((t, k) => `${k + 1}. ${T(t.name)} ${t.rec}`).join(', ')}.${w.n > 1 && w.headline ? ` Biggest change: ${teamsTc(w.headline)}.` : ''}`);
  out.road = {
    kicker: `The road so far · ${asOf}`, section: 'The road so far (what each week did to the table)', where,
    facts: `Season ${sd.season}, week by week:\n${roadLines.join('\n')}`,
    focus: 'Tell the arc of the season in one or two beats: how the top of the table took shape and the biggest swing along the way. Don\'t walk through every week.',
  };

  // Team stats: per game (percentages as they are), best first.
  const byId = Object.fromEntries((sd.teamStats || []).map(t => [t.team_id, t]));
  const teams = m.table.filter(t => byId[t.id]);
  if (teams.length >= 2) {
    const statLines = TEAM_STAT_CATS.map(c => {
      const vals = teams.map(t => ({ t, v: teamStatVal(c, byId[t.id], 'pg') })).sort((x, y) => (c.low ? x.v - y.v : y.v - x.v));
      return `- ${c.title}${c.pct ? '' : ' per game'}${c.low ? ' (fewest is best)' : ''}: ${vals.map(x => `${T(x.t.name)} ${teamStatFmt(c, x.v, 'pg')}`).join(', ')}`;
    });
    out.stats = {
      kicker: `Team stats · ${asOf}`, section: 'Team stats (every team\'s per-game numbers)', where,
      facts: `Season ${sd.season} team stats, best first in each category:\n${statLines.join('\n')}`,
      focus: 'Pick the one or two most telling stat stories: the biggest gap at the top or bottom of a category, or a team that ranks first in one category and last in another. Don\'t list every category.',
    };
  }
  return sectionFactsMap('standings', sd.season, out);
}

// /playoffs: the bracket and every playoff game.
function playoffsSectionFacts(pd) {
  const m = playoffsModel(pd);
  if (m.seeds.length < 4) return {};
  const T = titleCase;
  const rec = t => `${t.wins}-${t.losses}`;
  const where = 'Playoffs page';
  const out = {};
  const format = 'Format: semifinals 1st vs 4th and 2nd vs 3rd; the higher seed is "twice to beat" (advances with 1 win, the lower seed needs 2). The Finals are best of 3.';
  const beat = g => {
    const aw = Number(g.team_a_score) > Number(g.team_b_score);
    const hi = Math.max(g.team_a_score, g.team_b_score), lo = Math.min(g.team_a_score, g.team_b_score);
    return `${T(aw ? g.team_a_name : g.team_b_name)} beat ${T(aw ? g.team_b_name : g.team_a_name)} ${hi}-${lo}, by ${plural(hi - lo, 'point')}${Number(g.overtime) ? ', in overtime' : ''} (${summaryDay(g.date)})`;
  };
  const series = (label, hi, hiN, lo, loN, st, need) => {
    const head = `${label}: ${hiN ? `${hiN}. ` : ''}${T(hi?.name || 'TBD')} vs ${loN ? `${loN}. ` : ''}${T(lo?.name || 'TBD')}`;
    if (!st.played.length) return `- ${head}: not played yet.`;
    const result = st.winner ? `${T(st.winner.name)} won the series ${Math.max(st.hw, st.lw)}-${Math.min(st.hw, st.lw)}` : `in progress, ${T(hi.name)} ${st.hw}, ${T(lo.name)} ${st.lw} (${need})`;
    return `- ${head}: ${st.played.map((g, i) => `Game ${i + 1}: ${beat(g)}`).join('; ')}. ${result}.`;
  };
  let facts;
  if (m.projected) {
    facts = `${format}\n${pd.isCurrent ? `Projected bracket if the regular season ended today (${pd.regular.played} of ${pd.regular.expected} regular-season games played)` : `Season ${pd.season} final seeding`}:\n- Semifinal 1: 1st ${T(m.s1.name)} (${rec(m.s1)}) vs 4th ${T(m.s4.name)} (${rec(m.s4)})\n- Semifinal 2: 2nd ${T(m.s2.name)} (${rec(m.s2)}) vs 3rd ${T(m.s3.name)} (${rec(m.s3)})`;
  } else {
    const fin = m.fHigh && m.fLow ? series('Finals', m.fHigh, m.seedOf(m.fHigh), m.fLow, m.seedOf(m.fLow), m.fin, 'first to 2 wins') : '- Finals: waiting on the semifinals.';
    facts = `${format}\nSeason ${pd.season} playoffs:\n${series('Semifinal 1', m.s1, 1, m.s4, 4, m.st1, 'the 4th seed needs 2 wins')}\n${series('Semifinal 2', m.s2, 2, m.s3, 3, m.st2, 'the 3rd seed needs 2 wins')}\n${fin}${m.champ ? `\n${T(m.champ.name)} are the Season ${pd.season} champions.` : ''}${pd.awards.finalsMvp ? `\nFinals MVP: ${pd.awards.finalsMvp.name}.` : ''}${pd.awards.mvp ? `\nSeason MVP: ${pd.awards.mvp.name}.` : ''}`;
  }
  // The playoff games' highlights (lib/highlights.js, cached per game): series results for the
  // bracket (clinch, title, upset, forced decider), records and big nights for the games list.
  const poHl = m.projected ? [] : (pd.games || []).filter(g => Number(g.team_a_score) + Number(g.team_b_score) > 0).flatMap(g => cachedGameHighlights(g));
  const seriesHl = poHl.filter(h => /^(CHAMPIONS|SERIES WON|UPSET|SERIES TIED):/.test(h.text));
  const seriesMusts = mustMentions(seriesHl, 2);
  if (seriesHl.length) facts += `\n\n${highlightsBlock(seriesHl, seriesMusts)}`;
  out.bracket = {
    musts: seriesMusts,
    kicker: `${m.projected ? 'Projected bracket' : 'The bracket'} · Season ${pd.season}`, section: m.projected ? 'Projected bracket' : 'Bracket', where, facts,
    focus: m.projected
      ? 'Preview the bracket as it stands: who has twice to beat and the matchups it sets up. Don\'t predict winners.'
      : m.champ
        ? 'Tell how the bracket played out: the path each finalist took and how the Finals were decided.'
        : 'Say where the bracket stands: who has advanced, what is still to be decided, and what each side needs.',
  };

  if (m.tableRows.length) {
    const lines = m.tableRows.map(r => `- ${r.round.replace(/ · G(\d)/, ', Game $1')}, ${summaryDay(r.date)}: ${T(r.w)} beat ${T(r.l)} ${r.ws}-${r.ls}, by ${plural(r.ws - r.ls, 'point')}${r.ot ? ', in overtime' : ''}${r.potg ? `. ${r.potgShared ? 'Co-players' : 'Player'} of the game: ${r.potg}${r.potgLine ? ` (${r.potgLine})` : ''}` : ''}${r.recap ? `. Recap headline: "${r.recap}"` : ''}`);
    const gameHl = poHl.filter(h => !seriesHl.includes(h) && /^(LEAGUE RECORD|TIED LEAGUE RECORD|TEAM RECORD|TRIPLE-DOUBLE|BIG NIGHT|HOT HAND|GAME-WINNER|COMEBACK|OVERTIME):/.test(h.text));
    const gameMusts = mustMentions(gameHl, 2);
    out.games = {
      kicker: `Every playoff game · Season ${pd.season}`, section: 'Every playoff game (results and players of the game)', where,
      facts: `Season ${pd.season} playoff games, in order:\n${lines.join('\n')}${gameHl.length ? `\n\n${highlightsBlock(gameHl, gameMusts)}` : ''}`,
      musts: gameMusts,
      focus: `${gameMusts.length ? 'Lead with the biggest MAJOR HIGHLIGHT of these playoffs.' : 'Pick the standout game or performance of these playoffs: the closest game, the biggest margin, or the best player-of-the-game line.'} Don't recap every game.`,
    };
  }
  return sectionFactsMap('playoffs', pd.season, out);
}

// /picks: game days and the Pickmaster race.
function picksSectionFacts(pd) {
  const T = titleCase;
  const where = 'Who wins? picks page';
  const out = {};
  const pct = (g, side) => (side === 'a' ? g.odds.pctA : g.odds.pctB);
  if (pd.days.length) {
    const dayLines = pd.days.slice(0, 3).map(d => `${summaryDay(d.ymd)}:\n${d.games.map(s => {
      const g = s.game;
      const win = g.winner === 'a' ? g.a : g.b, lose = g.winner === 'a' ? g.b : g.a;
      const parts = [`${T(win)} beat ${T(lose)} ${Math.max(g.sa, g.sb)}-${Math.min(g.sa, g.sb)}`];
      if (pd.oddsOn && g.odds?.fav) parts.push(`the odds had favoured ${T(g.odds.fav === 'a' ? g.a : g.b)} at ${pct(g, g.odds.fav)}%${s.upset ? ', so this was an upset' : ''}`);
      parts.push(`${s.calledIt.length} of ${s.total} pickers called it`);
      return `- ${parts.join('; ')}`;
    }).join('\n')}`);
    const season = [
      pd.oddsOn && pd.callers.odds.of ? `The odds' favourite has won ${pd.callers.odds.called} of ${pd.callers.odds.of} games this season.` : '',
      pd.callers.fans.of ? `The side most pickers took has won ${pd.callers.fans.called} of ${pd.callers.fans.of} games this season.` : '',
      pd.oddsOn ? `${plural(pd.upsets.length, 'upset')} this season.` : '',
    ].filter(Boolean).join(' ');
    out.days = {
      kicker: `Game days · Latest ${summaryDay(pd.days[0].ymd)}`, section: 'Game days (how each game day\'s picks went)', where,
      facts: `"Who wins?" is the league's pick-em: logged-in players pick the winner of each game. Season ${pd.season} game days, newest first:\n${dayLines.join('\n')}${season ? `\n${season}` : ''}`,
      focus: 'Sum up how the picks went, leading with the newest game day: which games the pickers called and any upset. Then at most one season-long note about the odds or the majority pick. Call the people who pick "pickers", never fans.',
    };
  }
  // No Pickmaster race writeup: the leaderboard speaks for itself (dropped 2026-10-13).
  return sectionFactsMap('picks', pd.season, out);
}

// A final's game page: top performers and team stats. data: { stats, dc, won } as the route
// builds them (gameSectionData rebuilds them for the admin regenerate).
function gameSectionData(game) {
  const stats = getGameDetailStats(game.id);
  if (!stats.length) return { stats, dc: null, won: [] };
  const history = playerHistory(stats.map(s => s.player_id), game);
  const A = teamTotals(stats, game.team_a_name, game.team_a_to_team), B = teamTotals(stats, game.team_b_name, game.team_b_to_team);
  return { stats, dc: duelAndCast(stats, game, history, potgIdsFor(game, stats)), won: howItWasWon(game, A, B) };
}

function gameSectionFacts(game, { stats, dc, won }) {
  if (!stats?.length) return {};
  const T = titleCase;
  const n = v => Number(v) || 0;
  const sa = n(game.team_a_score), sb = n(game.team_b_score);
  const aWin = sa > sb;
  const result = `Final: ${T(aWin ? game.team_a_name : game.team_b_name)} beat ${T(aWin ? game.team_b_name : game.team_a_name)} ${Math.max(sa, sb)}-${Math.min(sa, sb)} (${summaryDay(game.date)}, Season ${game.season}${game.game_type === 'regular' ? '' : `, ${game.game_type === 'finals' ? 'Finals' : 'playoffs'}`}).`;
  const where = 'game page';
  const kick = label => `${label} · ${T(game.team_a_name)} ${sa}–${sb} ${T(game.team_b_name)}`;
  const out = {};
  // This game's highlights (lib/highlights.js), cached per game.
  const hl = cachedGameHighlights(game);
  if (dc) {
    const line = s => {
      const fgm = n(s.fg2m) + n(s.fg3m) + n(s.fg4m), fga = fgm + n(s.fg2m_miss) + n(s.fg3m_miss) + n(s.fg4m_miss);
      const parts = [`${n(s.pts)} points`, `${n(s.reb)} rebounds`, `${n(s.ast)} assists`, `${n(s.stl)} steals`, `${n(s.blk)} blocks`, `${n(s.turnover)} turnovers`, `${fgm} of ${fga} from the field`];
      if (n(s.fg3m) + n(s.fg3m_miss)) parts.push(`${n(s.fg3m)} of ${n(s.fg3m) + n(s.fg3m_miss)} from three`);
      if (n(s.ftm) + n(s.ft_miss)) parts.push(`${n(s.ftm)} of ${n(s.ftm) + n(s.ft_miss)} free throws`);
      return `${displayPlayerName(s.name || '')} (${T(s.team_name)}): ${parts.join(', ')}${s.badge ? `. Note: ${s.badge.replace(/^(\d+) & (\d+)$/, '$1 points and $2 rebounds')}` : ''}`;
    };
    const cast = [...dc.castA, ...dc.castB];
    // The players' major highlights (records, triple-doubles, big nights): up to 2 must be
    // said here, right above the box score.
    const playerIds = new Set(stats.map(s => s.player_id));
    const pHl = hl.filter(h => playerIds.has(h.subject));
    const pMusts = mustMentions(pHl, 2);
    out.perf = {
      kicker: kick('Top performers'), section: 'Top performers (the best player on each side, head to head, then other standouts)', where, highsOk: true,
      facts: `${result}\nThe best player on each team (by game score):\n- ${line(dc.a)}\n- ${line(dc.b)}${cast.length ? `\nOther standouts:\n${cast.map(s => `- ${line(s)}`).join('\n')}` : ''}\nCareer and season highs count league games only. A note like "Career-high 25" means 25 points is the most that player has scored in a league game.${pHl.length ? `\n\n${highlightsBlock(pHl, pMusts)}` : ''}`,
      musts: pMusts,
      focus: `${pMusts.length ? 'Lead with the biggest MAJOR HIGHLIGHT, then tell' : 'Tell'} the duel between the two best players and how it lined up with the result, then at most one other standout. Pick the telling numbers; don\'t list every stat.`,
    };
  }
  const A = teamTotals(stats, game.team_a_name, game.team_a_to_team), B = teamTotals(stats, game.team_b_name, game.team_b_to_team);
  const pc = (m, a) => (a ? `${(m / a * 100).toFixed(1)}%` : '—');
  const team = (name, x) => `- ${T(name)}: ${x.fgm} of ${x.fga} from the field (${pc(x.fgm, x.fga)}), ${x.fg3m} of ${x.fg3a} from three (${pc(x.fg3m, x.fg3a)})${x.fg4a ? `, ${x.fg4m} of ${x.fg4a} four-pointers` : ''}, ${x.ftm} of ${x.fta} free throws (${pc(x.ftm, x.fta)}), ${x.reb} rebounds, ${x.ast} assists, ${x.stl} steals, ${x.blk} blocks, ${x.to} turnovers`;
  const edges = (won || []).map(w => `- ${w.label}: ${w.team} by ${w.n}${['3pt', 'ft', '2pt', '4pt'].includes(w.key) ? ' points' : ''} (${w.detail})`);
  // Team-level highlights (a team scoring record, overtime, a comeback, a rout): 1 must here.
  const tHl = hl.filter(h => /^(TEAM RECORD|OVERTIME|COMEBACK|ROUT):/.test(h.text));
  const tMusts = mustMentions(tHl, 1);
  out.stats = {
    kicker: kick('Team stats'), section: 'Team stats (the two teams side by side)', where,
    facts: `${result}\nTeam totals:\n${team(game.team_a_name, A)}\n${team(game.team_b_name, B)}${edges.length ? `\nWhere the teams differed most:\n${edges.join('\n')}` : ''}${tHl.length ? `\n\n${highlightsBlock(tHl, tMusts)}` : ''}`,
    musts: tMusts,
    focus: `${tMusts.length ? 'Lead with the MAJOR HIGHLIGHT, then name' : 'Name'} the one or two team stats that separated the two sides, with the numbers side by side. One short sentence of body is enough; this sits in a narrow column.`,
  };
  return sectionFactsMap('game', game.id, out);
}

// Admin: rewrite one section writeup now. block as above.
app.post('/admin/section-summary/regenerate', requireAuth, express.json(), async (req, res) => {
  const block = String(req.body?.block || '');
  const m = block.match(/^(standings|playoffs|picks|mvp|dpoy|game)_([a-z0-9]+):(.+)$/);
  if (!m) return res.status(400).json({ error: 'Unknown block' });
  if (!aiAvailable()) return res.status(400).json({ error: 'No AI API key configured.' });
  const [, page, section, param] = m;
  let facts = {};
  if (page === 'standings') facts = standingsSectionFacts(standingsSectionData(param));
  else if (page === 'playoffs') facts = playoffsSectionFacts(playoffsSectionData(param));
  else if (page === 'picks') facts = picksSectionFacts(buildPicksPageData(param));
  else if ((page === 'mvp' || page === 'dpoy') && isMvpLocked(param)) facts = mvpLockSectionFacts(param, mvpLockTen(param, page), page);
  else if (page === 'mvp' || page === 'dpoy') facts = mvpSectionFacts({ season: param, week: getSeasonLatestWeek(param)?.week ?? null, playoffsStarted: isPlayoffStarted(param), top: mvpRaceTop(param, page), race: page });
  else {
    const game = getGameById(param);
    if (!game || game.under_review) return res.status(404).json({ error: 'Unknown game' });
    facts = gameSectionFacts(game, gameSectionData(game));
  }
  const f = facts[section];
  if (!f) return res.status(400).json({ error: 'Nothing to summarise yet.' });
  try {
    await generateHomeSummary(f.block, f, { where: f.where, settingKey: `section_summary_${f.block}`, strict: true, highsOk: !!f.highsOk });
    res.json({ ok: true });
  } catch (err) {
    console.error(`Section summary (${f.block}) regenerate failed:`, err.message);
    writerError(res, err);
  }
});

app.get('/players', (req, res) => {
  const isAdmin = !!req.session?.isAdmin;
  // Public directory only — an inactive (archived) player shouldn't appear here, matching
  // every other roster view (/teams, team-head roster, awards picker, etc). Admins still
  // see everyone, since they're the ones who'd need to find and reactivate one.
  const visible = p => isAdmin || p.status !== 'inactive';
  const all = getAllPlayers();
  const byId = new Map(all.map(p => [p.id, p]));
  const teamIds = new Set(getAllTeams().map(t => t.id));
  const seasons = getLeaderSeasons().map(Number).filter(Boolean).sort((a, b) => b - a);
  const season = seasons[0] || null;
  const linesOf = {};
  for (const r of getPlayerSeasonTotalsLite()) (linesOf[r.player_id] ||= []).push(r);
  // Rookie = no regular-season games before the current season.
  const isRookie = id => !!season && !(linesOf[id] || []).some(r => Number(r.season) < season);
  const positionsOf = p => { try { return JSON.parse(p.positions || '[]'); } catch { return []; } };
  const names = p => ({ first: String(p.first_name || '').trim(), last: String(p.last_name || '').trim().toUpperCase(), firstName: p.first_name, lastName: p.last_name });
  const fullName = p => { const n = names(p); return `${n.first} ${n.last}`.trim(); };

  // getAllPlayers' totals are the latest completed regular season — the same `season`.
  const spark = season ? getSeasonPointsByGame(season) : {};
  // qualified: meets the /leaders attendance rule (lib/qualification.js), so the page's per-game
  // leaders, top card and amber column bests rank the same players /leaders does.
  const teamGamesOf = s => s === 'career' || !s ? {} : getTeamGameCounts(s);
  const rosterTeamGames = teamGamesOf(season);
  const roster = all.filter(p => visible(p) && teamIds.has(p.team_id)).map(p => ({
    id: p.id, ...names(p), team: String(p.team_name || '').toUpperCase(), number: p.number, positions: positionsOf(p),
    status: p.status, banned: !!p.banned_at, photo: !!p.picture_url, gp: p.games_played || 0, pts: p.pts, reb: p.reb, ast: p.ast,
    spark: spark[p.id] || [], rookie: isRookie(p.id), qualified: meetsLeaderRule(p.games_played, rosterTeamGames[p.team_id]),
  }));
  const unrostered = all.filter(p => visible(p) && !teamIds.has(p.team_id));
  const alumni = unrostered.filter(p => linesOf[p.id]?.length).map(p => {
    const last = [...linesOf[p.id]].sort((a, b) => Number(b.season) - Number(a.season))[0];
    return { id: p.id, name: fullName(p), season: Number(last.season), gp: last.games_played, pts: last.pts };
  }).sort((a, b) => b.season - a.season || b.gp - a.gp || a.name.localeCompare(b.name));
  const papawis = getPapawisPlayedCounts();
  const community = unrostered.filter(p => !linesOf[p.id]?.length).map(p => ({ id: p.id, name: fullName(p), papawis: papawis[p.id] || 0 }))
    .sort((a, b) => b.papawis - a.papawis || a.name.localeCompare(b.name));

  const view = req.query.view === 'stats' ? 'stats' : 'rosters';
  let stats = null;
  if (view === 'stats') {
    const qs = String(req.query.season || '');
    const statSeason = qs === 'career' ? 'career' : (seasons.includes(Number(qs)) ? Number(qs) : season);
    const statTeamGames = teamGamesOf(statSeason);
    const teamGamesByName = Object.fromEntries(getAllTeams().map(t => [String(t.name).toUpperCase(), statTeamGames[t.id]]));
    const rows = getPlayerSeasonLines(statSeason === 'career' ? null : statSeason)
      .filter(r => byId.has(r.id) && visible(byId.get(r.id)))
      .map(r => {
        const p = byId.get(r.id);
        return { ...r, ...names(p), gp: r.games_played, team: String(r.team_name || p.team_name || '').toUpperCase(), number: p.number,
          positions: positionsOf(p), status: p.status, banned: !!p.banned_at, photo: !!p.picture_url, rookie: statSeason === season && isRookie(p.id),
          qualified: statSeason === 'career' ? r.games_played >= CAREER_MIN_GP : meetsLeaderRule(r.games_played, teamGamesByName[String(r.team_name || '').toUpperCase()]) };
      });
    stats = { rows, season: statSeason ?? 'career', seasons, mode: req.query.mode === 'totals' ? 'totals' : 'pg' };
  }

  res.send(renderPage(req, {
    title: 'Players | WKND Basketball',
    currentPath: req.path,
    metaTags: `<link rel="stylesheet" href="/players.css?v=${PLAYERS_CSS_VER}">`,
    body: playersPage({ view, season, week: season ? (getSeasonLatestWeek(season)?.week ?? null) : null, roster, alumni, community, stats, isAdmin }),
  }));
});

