// Registered before the /:id route below — otherwise Express would match this path as
// POST /admin/papawis/courts/:id with id="reorder" (the same class of bug the marketplace
// route ordering was fixed for earlier). body.order is every court id (active + inactive —
// the admin Courts page lists both) in its new order, validated as an exact permutation of
// the current full set before writing.
app.post('/admin/papawis/courts/reorder', requireAuth, express.json(), (req, res) => {
  const currentIds = getAllPapawisCourts().map(c => c.id);
  const order = Array.isArray(req.body.order) ? req.body.order.map(String) : [];
  const isValidPermutation = order.length === currentIds.length
    && new Set(order).size === currentIds.length
    && order.every(id => currentIds.includes(id));
  if (!isValidPermutation) return res.status(400).json({ error: 'Invalid court order.' });
  reorderPapawisCourts(order);
  res.json({ ok: true });
});
// ── Admin: one court's public page (views/admin/papawis-court.js) ─────────────────────────
// Everyone who played at a court (Papawis runs + league games), split by where they stand on
// rating it: already rated, already asked (once per court), or still to ask.
function courtRateAskCounts(court, p) {
  const ids = [...new Set(p.raterIds)];
  let rated = 0, asked = 0;
  for (const id of ids) { if (getMyCourtRating(court.id, id)) rated++; else if (wasAskedToRateCourt(court.id, id)) asked++; }
  return { played: ids.length, rated, asked, toAsk: ids.length - rated - asked };
}

app.get('/admin/papawis/courts/:id', requireAuth, (req, res) => {
  const court = getPapawisCourtById(req.params.id);
  if (!court) return res.status(404).send(renderAdminPage(req, { title: 'Not Found', currentPath: '/admin/papawis/courts', body: '<p class="aui-muted" style="padding:40px">Court not found.</p>' }));
  if (!court.slug) court.slug = ensurePapawisCourtSlug(court.id);
  const { p } = courtPageData(court);
  const today = manilaTodayStr();
  res.send(renderAdminPage(req, {
    title: p.name, currentPath: '/admin/papawis/courts',
    body: adminPapawisCourtBody({
      court, p, info: normalizeCourtInfo(parseCourtJson(court.info_json, {})), aiOn: aiAvailable(), flags: courtFlags(), rateAsk: courtRateAskCounts(court, p),
      ratings: getCourtRatings(court.id), slots: getCourtOpenSlots(court.id).filter(x => x.date >= today), requests: getCourtRequests(court.id),
      runs: getPapawisGames().filter(g => String(g.date).slice(0, 10) >= today && g.status !== 'cancelled' && g.status !== 'completed'),
    }),
  }));
});

// "Ask everyone who played here to rate": the same ask a new game sends (bell + email, once
// per player per court, never to someone who rated, email opt-outs respected), for everyone
// who played here before ratings were on. Papawis players get the Papawis wording.
app.post('/admin/papawis/courts/:id/rate-ask', requireAuth, express.json(), async (req, res) => {
  const court = getPapawisCourtById(req.params.id);
  if (!court) return res.status(404).json({ error: 'Court not found.' });
  if (!courtRatingsOn()) return res.status(400).json({ error: 'Turn on court ratings first (Court page features).' });
  if (!court.slug || court.page_hidden) return res.status(400).json({ error: 'The court page is hidden, so there is nothing to rate yet.' });
  const { p } = courtPageData(court);
  const runners = new Set(p.memberIds);
  const a = await askToRateCourt({ court, playerIds: [...runners], kind: 'papawis', ref: 'admin-ask' });
  const b = await askToRateCourt({ court, playerIds: p.raterIds.filter(id => !runners.has(id)), kind: 'league', ref: 'admin-ask' });
  const asked = a.asked + b.asked, emailed = a.emailed + b.emailed;
  res.json({ ok: true, message: asked ? `Asked ${asked} player${asked === 1 ? '' : 's'} (${emailed} by email, all by notification).` : 'Everyone who played here has already rated or been asked.' });
});

app.post('/admin/papawis/courts/:id/page', requireAuth, express.json(), (req, res) => {
  const court = getPapawisCourtById(req.params.id);
  if (!court) return res.status(404).json({ error: 'Court not found.' });
  const b = req.body || {};
  const clean = (v, n = 300) => String(v ?? '').replace(/\s+$/g, '').slice(0, n);
  const info = {};
  if (COURT_TYPES.some(([k]) => k === b.info_setting)) info.setting = b.info_setting;
  if (COURT_FLOORS.some(([k]) => k === b.info_floor)) info.floor = b.info_floor;
  const featureKeys = new Set(COURT_FEATURES.flatMap(g => g.items.map(([k]) => k)));
  info.features = [].concat(b.features || []).map(String).filter(k => featureKeys.has(k));
  for (const f of COURT_TEXT_FIELDS) { const v = clean(b[`info_${f.key}`], 400).trim(); if (v) info[f.key] = v; }
  if (b.info_contact_public) info.contact_public = true;
  const links = {};
  for (const f of COURT_LINK_FIELDS) { const v = clean(b[`link_${f.key}`], 300).trim(); if (/^https?:\/\/\S+$/i.test(v)) links[f.key] = v; }
  if (Object.keys(links).length) info.links = links;
  const rate = clean(b.info_rate, 100).trim(); if (rate) info.rate = rate;
  const { p } = courtPageData(court);
  const show = new Set([].concat(b['gallery_show[]'] || b.gallery_show || []).map(String));
  updatePapawisCourtPage(court.id, {
    city: COURT_CITIES.includes(b.city) ? b.city : '',
    info_json: JSON.stringify(info),
    writeup: clean(b.writeup, 4000).trim(),
    page_hidden: b.page_on === '0' ? 1 : 0,
    gallery_hidden_json: JSON.stringify(p.allPhotos.map(x => x.key).filter(k => !show.has(k))),
    gallery_main: String(b.gallery_main || ''),
    seo_title: clean(b.seo_title, 120).trim(),
    seo_description: clean(b.seo_description, 300).trim(),
    extra_facts: String(b.extra_facts || '').split('\n').map(s => s.trim().slice(0, 160)).filter(Boolean).slice(0, 20).join('\n'),
    map_lat: parseMapPin(b.map_pin)?.lat ?? null,
    map_lng: parseMapPin(b.map_pin)?.lng ?? null,
    partner: b.partner_on === '1' ? 1 : 0,
    partner_email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(b.partner_email || '').trim()) ? String(b.partner_email).trim().slice(0, 120) : '',
  });
  liveCourtsCache = null;
  res.json({ ok: true });
});

// "About this court" AI draft: facts from lib/court-page.js only, and every number in the
// draft has to appear in them (same guard as the section writeups), else it retries.
app.post('/admin/papawis/courts/:id/writeup/generate', requireAuth, express.json(), async (req, res) => {
  const court = getPapawisCourtById(req.params.id);
  if (!court) return res.status(404).json({ error: 'Court not found.' });
  if (!aiAvailable()) return res.status(400).json({ error: 'No AI provider is set up.' });
  const { p } = courtPageData(court);
  const factsText = p.facts.join('\n');
  const allowed = new Set(factsText.match(/\d+(?:[.,]\d+)?/g) || []);
  const voice = pickVoice('home', { date: manilaTodayStr() });
  const flavor = voiceFlavor(voice, court.id, 200);
  // Write → check → rewrite (lib/writer.js), 3 tries, the same voice as every other writer:
  // numbers from the facts, the shared claim/banned/voice checks, length, then the AI fact
  // check once the free ones pass.
  {
    const prompt = `You write the "About this court" paragraph on a basketball court's page for WKND Basketball, a weekend basketball league and pickup community ("Papawis" = our pickup runs) in Makati, Mandaluyong and Pasig, Philippines.

Voice: ${voice.name}. ${voice.guide}${flavor ? `\n${flavor}` : ''}
It also has to read well to someone who found the page on Google: the court name, city and directions stay plain and clear; the voice lives in the sentences around them.

FACTS (the only facts you may use):
${factsText}

Write 3 paragraphs, 150 to 220 words in total, plain text, no headings, no bullet points, no emoji, no hashtags.
- Paragraph 1: what and where the court is (court name and city in the first sentence) and how to get there.
- Paragraph 2: what the venue is like: the court and its features, and what else is there, using only the facts.
- Paragraph 3: what playing here with WKND is like (run length, players, referee, if the facts say so) and a closing line inviting people to play.
- Do NOT say how many times WKND has played here or how many runs, games, players, members or sign-ups there have been. The page shows those stats elsewhere.
- Use digits for numbers. Never invent a number, a feature of the court, a price or a date that is not in the facts.
- Do not say how often runs happen ("every Saturday", "weekly", "monthly") unless a fact says exactly that.
- No claims of fame or rank ("legendary", "the best", "the hotspot", "always packed") unless a fact supports them.
- Separate the paragraphs with one blank line.
- Banned (rejected in code): ${BANNED_HINT}.

FINAL REMINDER — write it in the ${voice.name} voice.${voice.sample ? ` Example of the voice (style only — do not copy its words or facts): "${voice.sample}"` : ''}`;
    let out;
    try {
      out = await runWriter({
        prompt, label: `Court writeup (${court.id})`, tries: 3,
        generate: async p => String((await generateText(p, { tier: 'medium', maxTokens: 700, temperature: Math.min(aiTemperature(), voiceTraits(voice).hot ? 0.85 : 0.8) })).text || '').replace(/^["“]|["”]$/g, '').replace(/\*\*/g, '').trim(),
        checks: [
          t => { const bad = (t.match(/\d+(?:[.,]\d+)?/g) || []).filter(n => !allowed.has(n)); return bad.length ? [`it used numbers not in the facts (${bad.join(', ')})`] : []; },
          t => numberProblems(t, factsText, { pairs: false }).filter(p => p.startsWith('it spells')),
          t => { const w = t.split(/\s+/).length; return w < 120 || w > 260 ? [`it was ${w} words, aim for 150 to 220`] : []; },
          t => claimProblems(t, factsText),
          { style: true, fn: t => bannedProblems(t) },
          { style: true, fn: t => voiceProblems(t, voice) },
          { costly: true, fn: async t => (await factCheckCourtWriteup(factsText, t)).map(p => `a fact check found a claim the facts don't support: ${p}`) },
        ],
      });
    } catch (e) {
      console.error('[court writeup]', e.message);
      return res.status(502).json({ error: 'The AI provider failed. Try again in a minute.' });
    }
    if (out.problems.length) return res.status(422).json({ error: `Couldn't get a clean draft (${out.problems.join('; ')}). Try again, or write it by hand.` });
    updatePapawisCourtPage(court.id, { writeup_draft: out.draft, writeup_at: Date.now() });
    return res.json({ ok: true, message: 'Draft ready. Read it, then use it or edit it.' });
  }
});
// Second pass at temperature 0: every claim in the draft must be backed by the facts.
async function factCheckCourtWriteup(factsText, text) {
  const prompt = `Check this "About this court" text for a basketball court page against the facts.

TEXT
${text}

FACTS
${factsText}

List every statement in the text that the facts do not directly support: wrong or invented numbers, counts of how many runs, games, players or members there have been, how often runs happen ("every Saturday", "weekly", "3 runs a month"), a "typical" or "usual" time or day that no fact states, court features or amenities not in the facts (food, drinks, a mall), descriptions of quality the facts do not state ("clean", "new", "spacious"), "always" claims, and claims of fame or rank ("legendary", "best", "hotspot", "always packed"). Friendly tone and an invitation to play are fine. If everything is supported, return accurate=true and an empty problems list.`;
  const schema = { type: 'object', properties: { accurate: { type: 'boolean' }, problems: { type: 'array', items: { type: 'string' } } }, required: ['accurate', 'problems'] };
  const { data } = await generateJson(prompt, schema, { tier: 'check', temperature: 0, maxTokens: 300, openaiModel: FACT_CHECK_MODEL });
  if (data.accurate) return [];
  const raw = (data.problems || []).map(x => String(x).slice(0, 200)).filter(Boolean);
  const problems = realFactProblems(raw);
  if (raw.length && !problems.length) return [];
  return problems.length ? problems : ['unspecified inaccuracy'];
}
// Extra facts helper: an admin pastes notes (e.g. Google reviews they read, the court's own
// page) and gets candidate facts back to tick. Nothing is saved here; ticked facts go into the
// Extra facts box, which the admin saves. Facts only: no opinions, praise, quotes or names.
app.post('/admin/papawis/courts/:id/facts/suggest', requireAuth, express.json({ limit: '200kb' }), async (req, res) => {
  const court = getPapawisCourtById(req.params.id);
  if (!court) return res.status(404).json({ error: 'Court not found.' });
  if (!aiAvailable()) return res.status(400).json({ error: 'No AI provider is set up.' });
  const text = String(req.body?.text || '').slice(0, 12000).trim();
  if (text.length < 20) return res.status(400).json({ error: 'Paste some notes or reviews first.' });
  const prompt = `From the notes below about the basketball venue "${courtDisplayName(court)}", list concrete, checkable facts about the venue itself.

Include only things a visitor could verify: facilities and amenities (air-conditioning, scoreboard, lockers, showers, restrooms, parking and how it works, food or drinks on site, number of courts, floor type, seating, lights), how to get there (nearby stations, landmarks, entrances), and rules a visitor needs (shoes, booking). Keep numbers only if the notes state them.
Leave out: opinions and quality words ("great", "clean", "best", "well-maintained"), anything about specific people, staff names, quotes, complaints, prices that may change, and anything you are unsure of.
Each fact is one short plain sentence, under 15 words, in neutral wording. At most 12 facts. If there are none, return an empty list.

NOTES
${text}`;
  const schema = { type: 'object', properties: { facts: { type: 'array', items: { type: 'string' } } }, required: ['facts'] };
  try {
    const { data } = await generateJson(prompt, schema, { tier: 'check', temperature: 0, maxTokens: 500 });
    const have = new Set(courtExtraFacts(court).map(f => f.toLowerCase()));
    const facts = [...new Set((data.facts || []).map(f => String(f).replace(/\s+/g, ' ').trim().slice(0, 160)).filter(f => f && !have.has(f.toLowerCase())))].slice(0, 12);
    res.json({ ok: true, facts });
  } catch (e) {
    console.error('[court facts suggest]', e.message);
    res.status(502).json({ error: 'The AI provider failed. Try again in a minute.' });
  }
});

// Open times on a court page (players vote for a run in them).
app.post('/admin/papawis/courts/:id/slots', requireAuth, express.json(), (req, res) => {
  const court = getPapawisCourtById(req.params.id);
  if (!court) return res.status(404).json({ error: 'Court not found.' });
  const b = req.body || {};
  const date = String(b.slot_date || ''), start = String(b.slot_start || ''), end = String(b.slot_end || '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date < manilaTodayStr()) return res.status(400).json({ error: 'Pick a date from today on.' });
  if (!/^\d{2}:\d{2}$/.test(start) || !/^\d{2}:\d{2}$/.test(end) || end <= start) return res.status(400).json({ error: 'Set a start and an end time.' });
  addCourtOpenSlot({ courtId: court.id, date, start, end, threshold: b.slot_threshold });
  res.json({ ok: true, message: 'Open time added.' });
});
app.post('/admin/papawis/court-slots/:id/delete', requireAuth, express.json(), (req, res) => {
  if (!getCourtOpenSlot(req.params.id)) return res.status(404).json({ error: 'Not found.' });
  deleteCourtOpenSlot(req.params.id);
  res.json({ ok: true });
});
// Link the Papawis run made for an open time: every voter gets a bell notification.
app.post('/admin/papawis/court-slots/:id/run', requireAuth, express.json(), (req, res) => {
  const slot = getCourtOpenSlot(req.params.id);
  if (!slot) return res.status(404).json({ error: 'Not found.' });
  const run = getPapawisGame(String(req.body?.run_id || ''));
  if (!run) return res.status(400).json({ error: 'Pick a run.' });
  const firstLink = !slot.run_id;
  setCourtSlotRun(slot.id, run.id);
  if (firstLink) {
    const court = getPapawisCourtById(slot.court_id);
    const when = new Date(`${String(run.date).slice(0, 10)}T00:00:00`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
    for (const pid of getCourtSlotVoterIds(slot.id)) {
      createNotification({ playerId: pid, type: 'court_vote_run', title: `Your vote worked: a run at ${court ? courtDisplayName(court) : 'the court'} is up`, body: `${when}. Sign-ups are on the Papawis page.`, link: `/papawis#pw-game-${encodeURIComponent(run.id)}` });
    }
  }
  res.json({ ok: true, message: firstLink ? 'Run linked. Voters were notified.' : 'Run updated.' });
});
// Ratings: approve or reject a written review, hide or show a rating, reply as the court.
app.post('/admin/papawis/court-ratings/:id', requireAuth, express.json(), (req, res) => {
  const b = req.body || {};
  const opts = {};
  if (b.action === 'approve') opts.bodyStatus = 'approved';
  if (b.action === 'reject') opts.bodyStatus = 'rejected';
  if (b.action === 'hide') opts.hidden = true;
  if (b.action === 'show') opts.hidden = false;
  if (typeof b.reply === 'string') opts.ownerReply = b.reply.slice(0, 500);
  if (!moderateCourtRating(req.params.id, opts)) return res.status(404).json({ error: 'Not found.' });
  // Rate & Win: a player's first written review of a court earns a bonus once it's approved.
  if (b.action === 'approve') {
    const r = getCourtRating(req.params.id);
    const rules = parseCourtJson(ensureRateAndWin().rules_json, {});
    if (r && String(r.body || '').length >= (rules.review_min_chars || 50)) awardTicket({ playerId: r.player_id, source: 'first_court_review', ref: r.court_id });
  }
  res.json({ ok: true });
});
