// ── Marketplace: player-facing (Phase 1: browsing + committing to group buys) ───────
app.get('/marketplace', (req, res) => {
  if (getSetting('marketplace_enabled', '0') !== '1') return res.status(404).send(renderPage(req, {
    title: 'Not Found', currentPath: '/marketplace', body: comingSoonPage({ label: 'Marketplace', description: 'Not available yet.' }),
  }));
  const listings = getMarketplaceListings({ type: 'group_buy', status: 'open' })
    .concat(getMarketplaceListings({ type: 'group_buy', status: 'active' }));
  const viewerPlayerId = req.session?.playerPlayerId || null;
  // Full committed rows (player name/photo/team, plus each row's own variant selections) —
  // fetched once per listing and reused for both the committed count (its own .length, no
  // separate COUNT query needed) and the card avatar stack below. A listing sharing a
  // goal_group_id pools these with every other listing in the group instead (see
  // getGroupCommittedPlayers) — its own min_buyers is 0 in that case (enforced at save time),
  // so the effective listing rendered downstream gets the group's threshold swapped in.
  const groupCache = {};
  const effectiveListings = listings.map(l => {
    if (!l.goal_group_id) return l;
    if (!(l.goal_group_id in groupCache)) groupCache[l.goal_group_id] = getMarketplaceListingGroupById(l.goal_group_id);
    const group = groupCache[l.goal_group_id];
    return group ? { ...l, min_buyers: group.min_buyers } : l;
  });
  const committedPlayersById = Object.fromEntries(effectiveListings.map(l => [
    l.id, l.goal_group_id ? getGroupCommittedPlayers(l.goal_group_id) : getMarketplaceCommitments(l.id, 'committed'),
  ]));
  const countsById = Object.fromEntries(effectiveListings.map(l => [l.id, (committedPlayersById[l.id] || []).length]));
  // Sort operates on listings, not the exploded per-variant cards — "most committed"/"most
  // viewed" are inherently properties of the underlying group buy, not any one design pulled
  // out of it, so this decides which listing's cluster of cards leads, not the order within it.
  const sort = String(req.query.sort || '');
  if (sort === 'commits') effectiveListings.sort((a, b) => (countsById[b.id] || 0) - (countsById[a.id] || 0));
  else if (sort === 'views') effectiveListings.sort((a, b) => (b.view_count || 0) - (a.view_count || 0));
  else if (sort === 'price_asc') effectiveListings.sort((a, b) => a.price - b.price);
  else if (sort === 'price_desc') effectiveListings.sort((a, b) => b.price - a.price);
  const committedById = viewerPlayerId
    ? Object.fromEntries(effectiveListings.map(l => [l.id, !!getActiveMarketplaceCommitment(l.id, viewerPlayerId)]))
    : {};
  // A photo-backed listing explodes into one grid card per option, all sharing the same
  // listing.id — committedById above can only say "this player has some commitment on this
  // listing," which would light up every exploded card at once. This instead collects the
  // actual option value(s) they've committed to per listing, so each card's "You're In" only
  // lights up for the specific variant it represents. (Unrelated to goal-group pooling —
  // this is always about this one listing's own options, group or no group.)
  const committedOptsById = {};
  if (viewerPlayerId) {
    for (const l of effectiveListings) {
      const rows = getActiveMarketplaceCommitmentsForPlayer(l.id, viewerPlayerId);
      if (!rows.length) continue;
      const opts = new Set();
      for (const row of rows) {
        let selections = {};
        try { selections = JSON.parse(row.variant || '{}'); } catch { selections = {}; }
        for (const v of Object.values(selections)) {
          if (Array.isArray(v)) v.forEach(x => opts.add(x));
          else if (v) opts.add(v);
        }
      }
      committedOptsById[l.id] = opts;
    }
  }
  const listingIds = effectiveListings.map(l => l.id);
  const commentCountsById = getMarketplaceCommentCounts(listingIds);
  const reactionCountsById = getMarketplaceListingReactionCounts(listingIds);
  res.send(renderPage(req, {
    title: 'Marketplace | WKND Basketball',
    currentPath: req.path,
    body: marketplacePage({ listings: effectiveListings, countsById, committedById, committedOptsById, committedPlayersById, commentCountsById, reactionCountsById, isLoggedIn: !!req.session?.playerRegId, sort }),
  }));
});

app.get('/marketplace/:id', (req, res) => {
  if (getSetting('marketplace_enabled', '0') !== '1') return res.status(404).send(renderPage(req, {
    title: 'Not Found', currentPath: '/marketplace', body: comingSoonPage({ label: 'Marketplace', description: 'Not available yet.' }),
  }));
  const listing = getMarketplaceListingById(req.params.id);
  if (!listing) return res.status(404).send(renderPage(req, {
    title: 'Not Found', currentPath: '/marketplace', body: comingSoonPage({ label: 'Listing Not Found', description: 'This listing could not be found.' }),
  }));
  incrementMarketplaceListingViews(listing.id);
  const viewerPlayerId = req.session?.playerPlayerId || null;
  const commitments = (viewerPlayerId ? getActiveMarketplaceCommitmentsForPlayer(listing.id, viewerPlayerId) : [])
    .map(c => ({ ...c, variantLabel: formatVariantSelections(c.variant) }));
  // A listing sharing a goal_group_id pools its committed roster/threshold with every other
  // listing in the group (see /marketplace above) — its own min_buyers is 0 in that case
  // (enforced at save time), so the group's threshold is swapped in for display here too.
  const group = listing.goal_group_id ? getMarketplaceListingGroupById(listing.goal_group_id) : null;
  const effectiveListing = group ? { ...listing, min_buyers: group.min_buyers } : listing;
  const committedPlayers = listing.goal_group_id
    ? getGroupCommittedPlayers(listing.goal_group_id)
    : getMarketplaceCommitments(listing.id, 'committed');
  const committedCount = committedPlayers.length;
  const comments = getMarketplaceListingComments(listing.id);
  const reactedIds = getReactedMarketplaceCommentIdsForPlayer(comments.map(c => c.id), viewerPlayerId);
  const listingReaction = getMarketplaceListingReactionState(listing.id, viewerPlayerId);
  // ?g=<group>&o=<option> arrives from a photo-backed variant card exploded out on the
  // /marketplace grid (see photoVariantOptions in views/marketplace.js) — the view itself
  // re-validates both against the listing's actual variant groups before trusting them.
  const preselect = (req.query.g && req.query.o) ? { group: String(req.query.g), opt: String(req.query.o) } : null;
  res.send(renderPage(req, {
    title: `${listing.title} — Marketplace`,
    currentPath: '/marketplace',
    metaTags: buildMarketplaceOgTags(req, listing),
    body: marketplaceListingPage({
      listing: effectiveListing, committedCount, commitments, committedPlayers, isLoggedIn: !!req.session?.playerRegId,
      comments, reactedIds, listingReaction, preselect,
      isPlayer: !!req.session?.playerRegId, isAdmin: isAdminWithSection(req, 'marketplace'),
    }),
  }));
});

app.post('/marketplace/:id/commit', express.json(), (req, res) => {
  if (getSetting('marketplace_enabled', '0') !== '1') return res.status(404).json({ error: 'Not available.' });
  const playerId = req.session?.playerPlayerId;
  if (!req.session?.playerRegId || !playerId) return res.status(401).json({ error: 'Please log in to commit.' });
  const listing = getMarketplaceListingById(req.params.id);
  if (!listing || listing.type !== 'group_buy') return res.status(404).json({ error: 'Not found.' });
  if (listing.status !== 'open' && listing.status !== 'active') return res.status(400).json({ error: 'This listing is no longer accepting commitments.' });
  // No cap on how many times a player commits to the same listing — a photo-backed group
  // (see photoVariantOptions in views/marketplace.js) explodes each design into its own
  // grid card specifically so a buyer can order more than one, e.g. a Bucks jersey AND a
  // Chicago jersey, each landing as its own line item/commitment row.
  let variantGroups = [];
  try { variantGroups = JSON.parse(listing.variant_options || '[]'); } catch { variantGroups = []; }
  // One required selection per group — e.g. a jersey listing needs both "Jersey Size" and
  // "Shorts Size" picked, not just one flat option.
  const selections = (req.body && typeof req.body.variants === 'object' && req.body.variants) || {};
  const resolved = {};
  for (const group of variantGroups) {
    if (group.multiSelect) {
      // Picking N photos here means "I want N of these" — the price multiplies by however
      // many, so this needs at least 1 (never a silent free commitment) and no more than
      // MAX_MULTI_SELECT (a "commit" isn't meant to become an unbounded bulk order).
      const picked = Array.isArray(selections[group.label]) ? selections[group.label].map(String) : [];
      const unique = [...new Set(picked)];
      if (!unique.length) return res.status(400).json({ error: `Please pick at least one ${group.label}.` });
      if (unique.length > MAX_MULTI_SELECT) return res.status(400).json({ error: `You can pick at most ${MAX_MULTI_SELECT} for ${group.label}.` });
      if (!unique.every(v => group.options.includes(v))) return res.status(400).json({ error: `Please pick a valid ${group.label}.` });
      resolved[group.label] = unique;
    } else {
      const picked = String(selections[group.label] || '');
      if (!group.options.includes(picked)) return res.status(400).json({ error: `Please pick a ${group.label}.` });
      resolved[group.label] = picked;
    }
  }
  // A "top"-kind group is a jersey — anyone ordering one needs their name and number
  // printed on it. Required alongside the size pick, not optional, since there's no way
  // to fulfill a blank jersey; an optional note covers anything else (fit, placement, etc).
  const isJerseyOrder = variantGroups.some(g => g.sizeChartKind === 'top');
  let customName = '', customNumber = '', notes = '';
  if (isJerseyOrder) {
    customName   = String(req.body?.customName || '').trim().slice(0, 20);
    customNumber = String(req.body?.customNumber || '').trim().slice(0, 2);
    notes        = String(req.body?.notes || '').trim().slice(0, 200);
    if (!customName)   return res.status(400).json({ error: 'Please enter the name for your jersey.' });
    if (!customNumber) return res.status(400).json({ error: 'Please enter your jersey number.' });
  }
  // Multiple commitments per player are allowed on purpose (see above), but an exact repeat —
  // same options AND same name/number — is almost always an accidental double-add rather than
  // a real second order, so it gets a confirm-to-proceed warning instead of a silent duplicate
  // or a hard block. Two different people wanting the identical size/design is fine and never
  // blocked, since their name/number won't match.
  if (!req.body?.confirmDuplicate) {
    const existing = getActiveMarketplaceCommitmentsForPlayer(listing.id, playerId);
    const isDuplicate = existing.some(c => {
      let sel = {};
      try { sel = JSON.parse(c.variant || '{}'); } catch { sel = {}; }
      return variantSelectionsEqual(sel, resolved)
        && String(c.custom_name || '').trim().toLowerCase() === customName.toLowerCase()
        && String(c.custom_number || '').trim() === customNumber;
    });
    if (isDuplicate) {
      return res.status(409).json({ duplicate: true, error: "You already have an identical order on this listing — same options and name/number." });
    }
  }
  commitToMarketplaceListing(listing.id, playerId, JSON.stringify(resolved), { customName, customNumber, notes });
  res.json({ ok: true });
});

app.post('/marketplace/:id/cancel-commitment', express.json(), (req, res) => {
  if (getSetting('marketplace_enabled', '0') !== '1') return res.status(404).json({ error: 'Not available.' });
  const playerId = req.session?.playerPlayerId;
  if (!req.session?.playerRegId || !playerId) return res.status(401).json({ error: 'Please log in.' });
  const listing = getMarketplaceListingById(req.params.id);
  if (!listing) return res.status(404).json({ error: 'Not found.' });
  // A player can hold several commitments on the same listing now, so the one to cancel
  // must be named explicitly — falls back to "the" one for old clients/requests with no
  // commitmentId, matching the pre-multi-commit behavior when a player only ever had one.
  const requestedId = req.body?.commitmentId ? String(req.body.commitmentId) : null;
  const commitment = requestedId ? getMarketplaceCommitmentById(requestedId) : getActiveMarketplaceCommitment(listing.id, playerId);
  if (!commitment || commitment.listing_id !== listing.id || commitment.player_id !== playerId || commitment.status !== 'committed') {
    return res.status(400).json({ error: "You don't have an active commitment matching that." });
  }
  if (listing.status === 'charged') return res.status(400).json({ error: 'This listing has already been charged — contact an admin.' });
  cancelMarketplaceCommitment(commitment.id);
  res.json({ ok: true });
});

// ── Marketplace comments + reactions ─────────────────────────────────────────────
// Exact parallel of the /games/:id/comments routes above — no @mention pool here since
// marketplace listings don't have a "who played" list to mention. New-comment notifications
// go to everyone with an active commitment on the listing (the marketplace analog of
// "everyone who played in this game"), not the whole site.
app.post('/marketplace/:id/comments', express.json(), (req, res) => {
  if (getSetting('marketplace_enabled', '0') !== '1') return res.status(404).json({ error: 'Not available.' });
  const playerId = req.session?.playerPlayerId;
  if (!req.session?.playerRegId || !playerId) return res.status(401).json({ error: 'Log in to comment.' });
  const listing = getMarketplaceListingById(req.params.id);
  if (!listing) return res.status(404).json({ error: 'Not found.' });
  const body = String(req.body?.body || '').trim().slice(0, 500);
  if (!body) return res.status(400).json({ error: "Comment can't be empty." });
  const id = addMarketplaceComment({ listingId: listing.id, playerId, body });
  const saved = getMarketplaceCommentWithMeta(id);
  broadcastToMarketplaceListing(listing.id, {
    type: 'comment:new',
    comment: {
      id: saved.id,
      player_id: saved.player_id,
      body: saved.body,
      created_at: saved.created_at,
      displayName: displayPlayerName(saved.player_name),
      initials: initials(saved.player_name),
      photoUrl: `/api/player/${encodeURIComponent(saved.player_id)}/photo?w=96`,
      color: teamColor(saved.team_name || ''),
    },
  });

  const commenterName = displayPlayerName(saved.player_name);
  const listingLink = `/marketplace/${listing.id}`;
  const committedPlayerIds = new Set(getMarketplaceCommitments(listing.id, 'committed').map(c => c.player_id));
  committedPlayerIds.forEach(pid => {
    if (pid === playerId) return;
    createNotification({
      playerId: pid,
      type: 'marketplace_comment',
      title: `New comment on ${listing.title}`,
      body: `${commenterName}: ${body.length > 100 ? body.slice(0, 100) + '…' : body}`,
      link: listingLink, actorId: playerId,
    });
  });

  res.json({ ok: true, id });
});

app.post('/marketplace/:id/comments/:commentId/react', express.json(), (req, res) => {
  if (getSetting('marketplace_enabled', '0') !== '1') return res.status(404).json({ error: 'Not available.' });
  const playerId = req.session?.playerPlayerId;
  if (!req.session?.playerRegId || !playerId) return res.status(401).json({ error: 'Log in to react.' });
  const comment = getMarketplaceCommentById(req.params.commentId);
  if (!comment || comment.listing_id !== req.params.id) return res.status(404).json({ error: 'Not found.' });
  const result = toggleMarketplaceCommentReaction(comment.id, playerId);
  broadcastToMarketplaceListing(comment.listing_id, { type: 'comment:react', id: comment.id, count: result.count });
  res.json({ ok: true, ...result });
});

