app.post('/admin/team-heads', requireAuth, express.json(), (req, res) => {
  const { teamId, playerId } = req.body || {};
  if (!teamId || !playerId) return res.status(400).json({ error: 'Pick a team and a player.' });
  const team = getAllTeams().find(t => t.id === String(teamId));
  if (!team) return res.status(400).json({ error: 'That team wasn’t found.' });
  const player = getPlayerWithTeam(String(playerId));
  if (!player) return res.status(400).json({ error: 'That player wasn’t found.' });
  if (getAllTeamHeads().some(h => h.team_id === team.id && h.player_id === player.id)) {
    return res.status(400).json({ error: `${displayPlayerName(player.name)} already heads ${team.name}.` });
  }
  addTeamHead(team.id, player.id);
  res.json({ ok: true, message: `${displayPlayerName(player.name)} now heads ${team.name}.` });
});
app.post('/admin/team-heads/:id/revoke', requireAuth, (req, res) => {
  removeTeamHead(req.params.id);
  res.json({ ok: true });
});

// Rate & Win admin (views/admin/raffle.js).
app.get('/admin/raffle', requireAuth, (req, res) => {
  const raffle = ensureRateAndWin();
  const round = raffle.status === 'active' && raffleOn() ? currentRound(raffle) : getOpenRound(raffle.id);
  const entries = round ? roundTally(round.id).map(t => {
    const reason = exclusionReason(raffle, t.player_id);
    return { name: getPlayerById(t.player_id)?.name || t.player_id, n: t.n, reason: reason ? EXCLUSION_LABEL[reason] : '' };
  }).sort((a, b) => b.n - a.n) : [];
  const rounds = getRounds(raffle.id, 30).map(o => ({ ...o, winner: o.winner_player_id ? getPlayerById(o.winner_player_id)?.name || '' : '' }));
  res.send(renderAdminPage(req, {
    title: 'Rate & Win raffle', currentPath: '/admin/raffle',
    body: adminRaffleBody({ on: raffleOn(), settingsHtml: raffleSettingsPanel(), raffle, schedule: parseCourtJson(raffle.schedule_json, {}), round, entries, rounds, vouchers: getAllVouchers(),
      announce: { sent: getBroadcastByDedupe(raffleLaunchKey(raffle)), reach: raffleOn() ? selectBroadcastRecipients(undefined, { optOutColumn: 'league_email_optout' }).recipients : [] } }),
  }));
});
// The one-time launch announcement: a bell for every active member and one email (league
// update emails, so that unsubscribe applies, and the usual group-email caps). Only once the
// raffle is on, and only once ever (dedupe key).
const raffleLaunchKey = raffle => `raffle_launch:${raffle.id}`;
function raffleLaunchMessage(raffle) {
  const round = currentRound(raffle);
  const when = new Date(round.draws_at).toLocaleString('en-US', { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZone: 'Asia/Manila' });
  const rules = parseCourtJson(raffle.rules_json, {});
  return {
    title: 'New: Rate & Win', body: `Rate your games, win a free Papawis run. First draw ${when}.`, subject: 'New on WKND: rate your games, win a free run',
    heading: 'Rate your games, win a free run, {name}',
    lines: [
      'After every Papawis run and league game you get a quick link to rate the court and the players you played with. Finish it and you get one raffle ticket for that game.',
      `Every other Sunday at 8 PM, one player wins a free Papawis run. The first draw is ${when}. The more games you rate, the better your odds. A first review of a court that we approve is +${rules.first_court_review || 2} more tickets.`,
      'Your ratings stay anonymous to other players, and the answers you give never change your tickets. Skip counts too.',
    ],
  };
}
app.post('/admin/raffle/announce', requireAuth, express.json(), async (req, res) => {
  const raffle = ensureRateAndWin();
  if (!raffleOn() || raffle.status !== 'active') return res.status(400).json({ error: 'Turn the raffle on (and running) first.' });
  if (getBroadcastByDedupe(raffleLaunchKey(raffle))) return res.status(400).json({ error: 'The announcement already went out.' });
  const m = raffleLaunchMessage(raffle);
  const { recipients } = selectBroadcastRecipients(undefined, { optOutColumn: 'league_email_optout' });
  const result = await sendBroadcast({
    kind: 'raffle_launch', dedupeKey: raffleLaunchKey(raffle), segment: 'active_players', createdBy: req.session?.playerName || 'admin',
    title: m.title, body: m.body, link: '/raffle', recipients,
    email: async r => ({
      ...leagueNudgeEmail({ name: r.player.name, subject: m.subject, heading: m.heading, lines: m.lines, cta: 'See Rate & Win', url: `${SITE_ORIGIN}/raffle`, unsubscribeUrl: leagueUnsubscribeUrl(r.reg.id), label: 'Rate & Win' }),
      headers: unsubscribeHeaders(leagueUnsubscribeUrl(r.reg.id)),
    }),
  });
  res.json({ ok: true, message: `Announced: ${result.bell} bell${result.bell === 1 ? '' : 's'}, ${result.email} email${result.email === 1 ? '' : 's'}${result.capped ? ` (${result.capped} over the email limit got the bell only)` : ''}.` });
});
app.post('/admin/raffle/status', requireAuth, express.json(), (req, res) => {
  const status = req.body?.status === 'paused' ? 'paused' : 'active';
  updateRaffle(ensureRateAndWin().id, { status });
  res.json({ ok: true, message: status === 'paused' ? 'Draws paused.' : 'Draws running again.' });
});
app.post('/admin/raffle/skip', requireAuth, express.json(), (req, res) => {
  const raffle = ensureRateAndWin();
  const open = getOpenRound(raffle.id);
  if (!open) return res.status(400).json({ error: 'No open round.' });
  const next = skipRound(open.id, `Skipped by ${req.session?.playerName || 'an admin'}.`);
  res.json({ ok: true, message: `Round ${open.number} skipped. Its tickets moved to Round ${next?.number}.` });
});
app.post('/admin/raffle/schedule', requireAuth, express.json(), (req, res) => {
  const b = req.body || {};
  const firstDraw = String(b.first_draw || '');
  const time = String(b.time || '');
  const minPlayers = Math.round(Number(b.min_players));
  if (firstDraw && !/^\d{4}-\d{2}-\d{2}$/.test(firstDraw)) return res.status(400).json({ error: 'Pick a date for the first draw.' });
  if (time && !/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) return res.status(400).json({ error: 'Use a time like 20:00.' });
  if (b.min_players != null && b.min_players !== '' && !(minPlayers >= 2 && minPlayers <= 200)) return res.status(400).json({ error: 'Minimum players: 2 to 200.' });
  updateRaffle(ensureRateAndWin().id, { firstDraw, time, minPlayers: minPlayers || undefined });
  res.json({ ok: true, message: 'Schedule saved.' });
});

// With "Rate your game" on: the conduct ratings (views/admin/game-ratings.js), open to every
// admin, rater names for the super admin only. Off: the old roast-style list (super admin).
app.get('/admin/ratings', requireAuth, (req, res) => {
  const isSuper = !!req.session?.isAdmin && !req.session?.isElevatedPlayer;
  const legacy = () => {
    const seasons = getPeerRatingSeasons();
    const season  = req.query.season || seasons[0] || getPortalCurrentSeason() || '';
    return adminRatingsBody({ season, seasons, ratings: season ? getAllPeerRatings(season) : [] });
  };
  if (!gameRatingsOn()) {
    if (!isSuper) return requireSuperAdmin(req, res, () => {});
    return res.send(renderAdminPage(req, { title: 'Community Ratings', currentPath: '/admin/ratings', body: legacy() }));
  }
  const tab = ['players', 'all', 'games', 'raters', 'legacy'].includes(req.query.tab) && (req.query.tab !== 'legacy' || isSuper) ? req.query.tab : 'watch';
  const all = getAllGameRatings();
  const live = all.filter(r => !r.ignored);
  const byRatee = {};
  for (const r of live) (byRatee[r.ratee_player_id] ??= []).push(r);
  const teamColor = Object.fromEntries(getAllTeams().map(t => [t.id, t.color]));
  const finesBy = id => {
    const cases = getFineCasesForPlayer(id);
    return { approved: cases.filter(c => c.status === 'approved').length, open: cases.filter(c => c.status === 'open' || c.status === 'pending_admin').length };
  };
  const players = Object.entries(byRatee).map(([id, rows]) => {
    const p = getPlayerById(id);
    return { id, name: p?.name || rows[0].ratee_name, color: teamColor[p?.team_id] || '', linksOff: !!p?.rate_links_off, s: summarizeConduct(rows) };
  }).sort((a, b) => b.s.no - a.s.no || b.s.total - a.s.total);
  const watch = players.filter(p => p.s.watch).map(p => ({ ...p, fines: finesBy(p.id) }));
  const gameLabels = {};
  const label = (kind, ref) => (gameLabels[`${kind}:${ref}`] ??= resolveRateGame(kind, ref)?.title || ref);
  const rounds = getGameRateRounds();
  rounds.forEach(r => label(r.kind, r.ref));
  const playerFilter = String(req.query.player || ''), raterFilter = isSuper ? String(req.query.rater || '') : '';
  const ratings = all.filter(r => (!playerFilter || r.ratee_player_id === playerFilter) && (!raterFilter || r.rater_player_id === raterFilter));
  if (tab === 'all') ratings.slice(0, 500).forEach(r => label(r.kind, r.ref));
  res.send(renderAdminPage(req, {
    title: 'Player ratings', currentPath: '/admin/ratings',
    body: adminGameRatingsBody({
      tab, isSuper, watch, players, ratings, rounds, gameLabels, playerFilter,
      flags: isSuper ? raterFlags(live) : [], counts: { ratings: all.length },
      legacyHtml: tab === 'legacy' ? legacy() : '',
    }),
  }));
});
app.post('/admin/ratings/:id/ignore', requireAuth, express.json(), (req, res) => {
  if (!getGameRating(req.params.id)) return res.status(404).json({ error: 'Rating not found.' });
  setGameRatingIgnored(req.params.id, !!req.body?.ignored);
  res.json({ ok: true, message: req.body?.ignored ? 'Ignored: it no longer counts.' : 'Counting it again.' });
});
app.post('/admin/ratings/:id/delete', requireSuperAdmin, express.json(), (req, res) => {
  if (!getGameRating(req.params.id)) return res.status(404).json({ error: 'Rating not found.' });
  deleteGameRating(req.params.id);
  res.json({ ok: true, message: 'Rating deleted.' });
});
// One-tap email links off for a player (e.g. their email is being misused): they log in to rate.
app.post('/admin/ratings/players/:id/links', requireAuth, express.json(), (req, res) => {
  const p = getPlayerById(req.params.id);
  if (!p) return res.status(404).json({ error: 'Player not found.' });
  setPlayerRateLinksOff(p.id, !!req.body?.off);
  res.json({ ok: true, message: req.body?.off ? `One-tap links off for ${displayPlayerName(p.name)}.` : `One-tap links on for ${displayPlayerName(p.name)}.` });
});

app.get('/admin/fines', requireAuth, (req, res) => {
  const pendingAdmin = getFineCasesByStatus('pending_admin');
  const open     = getFineCasesByStatus('open');
  const resolved = [...getFineCasesByStatus('approved'), ...getFineCasesByStatus('rejected'), ...getFineCasesByStatus('dismissed')]
    .sort((a, b) => (b.resolved_at || 0) - (a.resolved_at || 0));
  res.send(renderAdminPage(req, {
    title: 'Fines', currentPath: '/admin/fines',
    settings: finesSettingsPanel(),
    body: adminFinesListBody({ pendingAdmin, open, resolved, players: getAllPlayers(), categories: getActiveFineCategories(), summary: getFineCollectionSummary() }),
  }));
});
app.post('/admin/fines', requireAuth, express.json(), (req, res) => {
  const actor = currentAdminActor(req);
  const { playerId, gameId = '', categoryId, description = '' } = req.body || {};
  if (!playerId || !categoryId) return res.status(400).json({ error: 'Player and category are required.' });
  const result = createFineCase({ playerId, gameId, categoryId, description, reportedByType: actor.type, reportedById: actor.id, reportedByName: actor.name });
  if (result.error) return res.status(400).json({ error: 'Could not file the report.' });
  res.json({ ok: true, id: result.id });
});
app.get('/admin/fines/:id', requireAuth, (req, res) => {
  const kase = getFineCase(req.params.id);
  if (!kase) return res.status(404).send(renderAdminPage(req, { title: 'Not Found', currentPath: '/admin/fines', body: '<p style="padding:40px;color:var(--text-muted)">Case not found.</p>' }));
  const isSuperAdmin = !!req.session?.isAdmin && !req.session?.isElevatedPlayer;
  res.send(renderAdminPage(req, {
    title: 'Fine Case', currentPath: '/admin/fines',
    body: adminFineCaseBody({
      case: kase, votes: getFineVotesForCase(kase.id), player: getPlayerWithTeam(kase.player_id),
      escalationVotes: getEscalationVotesForCase(kase.id), totalAdmins: getTotalAdminCount(),
      viewerAdminId: currentAdminActor(req).id, isSuperAdmin,
      suspension: getPlayerSuspensionStatus(kase.player_id, kase.season || getPortalCurrentSeason()),
    }),
  }));
});
app.post('/admin/fines/:id/vote', requireAuth, express.json(), (req, res) => {
  const actor = currentAdminActor(req);
  const { vote, comment = '' } = req.body || {};
  if (vote !== 'approve' && vote !== 'reject') return res.status(400).json({ error: 'Invalid vote.' });
  const result = castFineVote({ caseId: req.params.id, voterType: actor.type, voterId: actor.id, voterName: actor.name, vote, comment });
  if (result.error) return res.status(400).json({ error: 'This case is no longer open for voting.' });
  res.json({ ok: true });
});
// Resolution is always a deliberate admin action (see lib/portal-db.js comment on
// resolveFineCase) — the vote tally informs this, it doesn't auto-decide it. Approving
// charges the ledger (category 'Penalty', same mechanism as season fees/Papawis) and
// notifies the player only now, on resolution — never while the case is still open, so a
// player never sees an in-progress accusation, only the outcome.
app.post('/admin/fines/:id/resolve', requireAuth, express.json(), (req, res) => {
  const kase = getFineCase(req.params.id);
  if (!kase || kase.status !== 'open') return res.status(400).json({ error: 'Case is not open.' });
  const actor = currentAdminActor(req);
  const { approved, note = '' } = req.body || {};
  let transactionId = '';
  if (approved) {
    transactionId = randomBytes(6).toString('hex');
    recordTransaction({
      id: transactionId, player_id: kase.player_id, amount: kase.amount, type: 'charge',
      payment_method: '', date: manilaTodayStr(), status: 'confirmed',
      notes: `Fine — ${kase.category_label}${kase.description ? `: ${kase.description}` : ''}`,
      reference_no: kase.id, season: '', category: 'Penalty',
    });
  }
  resolveFineCase(kase.id, { approved: !!approved, resolvedByName: actor.name, note, transactionId });
  createNotification({
    playerId: kase.player_id,
    type: approved ? 'fine_approved' : 'fine_rejected',
    title: approved ? `You've been fined ₱${Number(kase.amount).toLocaleString()}` : 'A conduct report about you was reviewed',
    body: approved ? kase.category_label : 'No fine was issued.',
    link: '/me',
  });
  res.json({ ok: true, approved: !!approved });
});

// Paid tracking, same shape as Papawis' per-signup "Mark Paid" (/admin/papawis/:id/signups/
// :signupId/paid): the shared ledger only rolls up one running balance per player, so it
// can't tell you whether THIS fine specifically got settled if the player has other charges
// too. Marking paid records a real type:'payment' transaction so the ledger/balance stay
// accurate; un-marking voids that exact transaction rather than searching for one to reverse.
app.post('/admin/fines/:id/paid', requireAuth, express.json(), (req, res) => {
  const kase = getFineCase(req.params.id);
  if (!kase) return res.status(404).json({ error: 'Not found.' });
  if (kase.status !== 'approved') return res.status(400).json({ error: 'Only an approved (charged) fine can be marked paid.' });

  const markPaid = req.body?.paid !== false;
  if (markPaid) {
    if (!kase.paid_at) {
      const txId = randomBytes(6).toString('hex');
      const notes = `Fine payment — ${kase.category_label}`;
      recordTransaction({
        id: txId, player_id: kase.player_id, amount: kase.amount, type: 'payment',
        payment_method: '', date: manilaTodayStr(), status: 'confirmed',
        notes, reference_no: kase.id, season: '', category: 'Penalty',
      });
      notifyLedgerEvent({ playerId: kase.player_id, type: 'payment', amount: kase.amount, notes });
      markFineCasePaid(kase.id, txId);
    }
  } else {
    if (kase.paid_tx_id) voidTransaction(kase.paid_tx_id);
    markFineCaseUnpaid(kase.id);
  }
  res.json({ ok: true });
});

// Notifies the reporting player their report didn't move forward — the accused is never
// told a pending_admin/dismissed case existed at all (same "outcome only, never
// in-progress" principle as /admin/fines/:id/resolve above).
function notifyReporterOfDismissal(kase) {
  if (kase.reported_by_type !== 'player' || !kase.reported_by_id) return;
  createNotification({
    playerId: kase.reported_by_id,
    type: 'report_dismissed',
    title: 'Your report was reviewed',
    body: `Admins reviewed your report and it was not escalated further.`,
    link: '/me',
  });
}

// Admin escalation vote — only meaningful on a pending_admin (player-submitted) case.
// Majority math + auto-transition lives in recomputeEscalation (lib/portal-db.js); this
// route just records the vote and lets that run, then notifies the reporter if the
// case just went terminal without ever reaching a head.
app.post('/admin/fines/:id/escalate-vote', requireAuth, express.json(), (req, res) => {
  const kase = getFineCase(req.params.id);
  if (!kase || kase.status !== 'pending_admin') return res.status(400).json({ error: 'This case is not awaiting escalation.' });
  const actor = currentAdminActor(req);
  const { vote, comment = '' } = req.body || {};
  if (vote !== 'escalate' && vote !== 'dismiss') return res.status(400).json({ error: 'Invalid vote.' });
  const result = castEscalationVote({ caseId: kase.id, adminId: actor.id, adminName: actor.name, vote, comment });
  if (result.error) return res.status(400).json({ error: 'This case is no longer awaiting escalation.' });
  recomputeEscalation(kase.id);
  const after = getFineCase(kase.id);
  if (after.status === 'dismissed') notifyReporterOfDismissal(after);
  res.json({ ok: true, status: after.status });
});

// Super-admin-only escape hatch for a pending_admin case whose vote count has stalled —
// see forceEscalationDecision's comment in lib/portal-db.js.
app.post('/admin/fines/:id/force-escalation', requireSuperAdmin, express.json(), (req, res) => {
  const kase = getFineCase(req.params.id);
  if (!kase || kase.status !== 'pending_admin') return res.status(400).json({ error: 'This case is not awaiting escalation.' });
  const actor = currentAdminActor(req);
  const { escalate } = req.body || {};
  const result = forceEscalationDecision(kase.id, { escalate: !!escalate, decidedByName: actor.name });
  if (!result.ok) return res.status(400).json({ error: 'Could not update this case.' });
  if (!escalate) notifyReporterOfDismissal(getFineCase(kase.id));
  res.json({ ok: true });
});

// Papawis pre-game reminders — see lib/papawis-notify.js. "Due" is decided per-signup
// (reminder_sent_at IS NULL + game within PAPAWIS_CUTOFF_DAYS), not per-job-run, so an
// hourly cadence is plenty and this also self-heals: a game already sitting inside the
// window when this job first ships gets caught up on its very first tick.
// Gated behind papawis_reminders_enabled (off by default, admin toggle in /admin/papawis) —
// this runs unconditionally at every boot, so without the gate a plain server restart
// with real credentials loaded would silently mass-email everyone currently due.
const PAPAWIS_REMINDER_CHECK_MS = 60 * 60 * 1000;
// Unattended sends only — nothing an admin deliberately triggers by hand (cancel, location/
// time edits, close-out) is held back by this; those still go out immediately regardless of
// the hour. A signup that goes "due" at 2 AM just waits for the next in-window hourly tick,
// since reminder_sent_at staying NULL means nothing is lost, only delayed.
const PAPAWIS_QUIET_HOURS_START = 9;  // 9:00 AM Manila
const PAPAWIS_QUIET_HOURS_END   = 21; // 9:00 PM Manila
function isPapawisSendWindowOpen() {
  const hour = manilaHourNow();
  return hour >= PAPAWIS_QUIET_HOURS_START && hour < PAPAWIS_QUIET_HOURS_END;
}
function runPapawisReminders() {
  if (getSetting('papawis_reminders_enabled', '0') !== '1') return;
  if (!isPapawisSendWindowOpen()) return;
  sendPapawisReminders(PAPAWIS_CUTOFF_DAYS).then(({ sent, errors }) => {
    if (sent || errors.length) console.log(`[papawis] reminders: ${sent} sent, ${errors.length} failed`);
  }).catch(e => console.error('[papawis] reminder scan failed:', e.message));
}
runPapawisReminders();
setInterval(runPapawisReminders, PAPAWIS_REMINDER_CHECK_MS);

// Birthday emails: hourly, write drafts for the coming week and send today's (see
// runBirthdayAutomation in lib/birthday.js). Sending only happens on production, from 8 AM
// Manila, and can be paused on /admin/birthdays. The first run waits a minute so it
// doesn't compete with startup.
// Daily database backup (production only): data/backups/portal-YYYY-MM-DD.db, the last 14
// days kept. Checked hourly; writes once a day.
function runDailyBackup() {
  if (process.env.NODE_ENV !== 'production') return;
  dailyBackup(path.join(__dirname, 'data', 'backups'), manilaTodayStr(), 14)
    .then(file => { if (file) console.log(`[backup] ${file}`); })
    .catch(e => console.error('[backup] failed:', e.message));
}
setTimeout(runDailyBackup, 2 * 60 * 1000);
setInterval(runDailyBackup, 60 * 60 * 1000);

const BIRTHDAY_AUTOMATION_CHECK_MS = 60 * 60 * 1000;
function runBirthdayJobs() {
  runBirthdayAutomation(manilaTodayStr()).then(({ drafted, sent, failed }) => {
    if (drafted || sent || failed) console.log(`[birthdays] drafted ${drafted}, sent ${sent}, failed ${failed}`);
  }).catch(e => console.error('[birthdays] automation failed:', e.message));
}
setTimeout(runBirthdayJobs, 60 * 1000);
setInterval(runBirthdayJobs, BIRTHDAY_AUTOMATION_CHECK_MS);

// Automatic balance bans and lifts (lib/balance-reminders.js runBanSweep): at start, hourly
// (a warning deadline passing), and after any admin ledger or Papawis change (a confirmed
// payment lifts the ban straight away; see the /admin hook near the admin-action logger).
// No email: bells only.
function runBanJobs() {
  try {
    const { banned, lifted } = runBanSweep();
    if (banned.length || lifted.length) console.log(`[bans] banned ${banned.length}, lifted ${lifted.length}`);
  } catch (e) { console.error('[bans] sweep failed:', e.message); }
}
runBanJobs();
setInterval(runBanJobs, 60 * 60 * 1000);

// Papawis announcements (scheduled for a delayed sign-up open) and slot-opened alerts.
// Every minute, production only (see runPapawisBroadcasts in lib/papawis-broadcast.js).
function runPapawisBroadcastJobs() {
  runPapawisBroadcasts().then(({ announced, alerts }) => {
    if (announced || alerts) console.log(`[papawis] broadcasts: ${announced} announcement(s), ${alerts} slot alert step(s)`);
  }).catch(e => console.error('[papawis] broadcast run failed:', e.message));
}
setInterval(runPapawisBroadcastJobs, 60 * 1000);

// Rate & Win (lib/raffle.js): reminders, the draw when its time passes, the next round.
// Every minute; a draw that was due while the server was down happens on the first tick.
// A player's open games to rate (asked, window still open), each with done = ticket earned.
function raffleGamesToRate(playerId) {
  const raffle = ensureRateAndWin();
  return getRecentGameAsksForPlayer(playerId, Date.now() - (RATE_WINDOW_DAYS + 3) * 86400000)
    .map(a => ({ a, g: resolveRateGame(a.kind, a.ref) })).filter(x => x.g?.open)
    .map(({ a, g }) => ({ kind: a.kind, ref: a.ref, title: g.title, line: g.line, windowEndsAt: g.windowEndsAt, done: hasTicket(raffle.id, 'game_rated', `${a.kind}:${a.ref}`, playerId) }));
}
function runRaffleTick() {
  runRaffleJobs({
    gamesLeft: pid => raffleGamesToRate(pid).filter(x => !x.done).length,
    playersToRemind: () => getRecentlyAskedPlayerIds(Date.now() - (RATE_WINDOW_DAYS + 1) * 86400000),
    sendWinnerEmail: ({ to, name, raffle, round, prize }) => sendMail({ to, ...raffleWinnerEmail({ name, raffleName: raffle.name, prizeLabel: prize?.label || 'a free Papawis run', roundNumber: round.number, url: `${SITE_ORIGIN}/raffle` }) }),
  }).catch(e => console.error('[raffle] job failed:', e.message));
}
setInterval(runRaffleTick, 60 * 1000);

// page_views keeps 180 days (lib/portal-db.js): prune at startup, then daily.
function prunePageViewsJob() {
  try {
    const cutoff = new Date(Date.parse(manilaTodayStr() + 'T00:00:00Z') - 180 * 86400000).toISOString().slice(0, 10);
    prunePageViews(cutoff);
    pruneEntityViews(cutoff);
  } catch (e) { console.error('[page views prune]', e.message); }
}
prunePageViewsJob();
setInterval(prunePageViewsJob, 24 * 60 * 60 * 1000);

// ── Live game-comments WebSocket ────────────────────────────────────────────────
// Scoped to one room per game (not a site-wide socket) — a client on /games/:id only
// gets that game's comment/reaction events. Receive-only for clients: comments are
// already public-read (see commentsTabBody), so no session auth on the socket itself —
// the actual writes still go through the existing authenticated HTTP routes below; this
// channel purely pushes "something changed, here's the update" to open tabs. Purely
// additive — if the socket never connects, every route above still works exactly the
// same via a manual refresh, same as before this existed.
const gameCommentRooms = new Map(); // gameId -> Set<WebSocket>
const wss = new WebSocketServer({ noServer: true });

// How many people have the game's page open (its comments socket): the live chat's
// "watching" count, sent to them all when it changes (at most once a second).
const watchingCount = gameId => new Set([...(gameCommentRooms.get(gameId) || [])].filter(ws => ws.readyState === ws.OPEN).map(ws => ws._viewer)).size;
const presenceTimers = new Map();
function presenceChanged(gameId) {
  if (presenceTimers.has(gameId)) return;
  presenceTimers.set(gameId, setTimeout(() => { presenceTimers.delete(gameId); broadcastToGame(gameId, { type: 'presence', count: watchingCount(gameId) }); }, 1000));
}
function broadcastToGame(gameId, payload) {
  const room = gameCommentRooms.get(gameId);
  if (!room || !room.size) return;
  const msg = JSON.stringify(payload);
  for (const ws of room) {
    if (ws.readyState === ws.OPEN) ws.send(msg);
  }
}

// Same room-per-entity pattern as gameCommentRooms — a third parallel Map rather than a
// generic "comment rooms" abstraction, consistent with this codebase's stated preference
// for parallel per-feature structures over shared/polymorphic ones (see the game_reactions
// comment in lib/portal-db.js).
const marketplaceCommentRooms = new Map(); // listingId -> Set<WebSocket>
function broadcastToMarketplaceListing(listingId, payload) {
  const room = marketplaceCommentRooms.get(listingId);
  if (!room || !room.size) return;
  const msg = JSON.stringify(payload);
  for (const ws of room) {
    if (ws.readyState === ws.OPEN) ws.send(msg);
  }
}

// One room per liveness-check token — the desktop browser that generated the QR code
// connects here and waits; the phone that scanned it never connects to this socket at all,
// it just POSTs the capture over plain HTTP (see /season-signup/liveness/:token/capture)
// and this is what tells the waiting desktop tab it arrived. Rooms are single-listener in
// practice (one token = one desktop tab) but built as a Set for the same reason
// gameCommentRooms is — a stray duplicate connection is a no-op, not a bug.
const livenessRooms = new Map(); // token -> Set<WebSocket>
function broadcastLivenessCaptured(token) {
  const room = livenessRooms.get(token);
  if (!room || !room.size) return;
  const msg = JSON.stringify({ type: 'captured' });
  for (const ws of room) {
    if (ws.readyState === ws.OPEN) ws.send(msg);
  }
}

const server = http.createServer(app);
server.on('upgrade', (req, socket, head) => {
  const { pathname } = new URL(req.url, 'http://localhost');

  const commentsMatch = pathname.match(/^\/ws\/games\/([^/]+)\/comments$/);
  if (commentsMatch) {
    if (getSetting('comments_enabled', '0') !== '1') { socket.destroy(); return; }
    wss.handleUpgrade(req, socket, head, (ws) => {
      const gameId = decodeURIComponent(commentsMatch[1]);
      // Who it is, for the live chat's "watching" count: their sign-in cookie, else their
      // address, so one person with two tabs counts once.
      const sid = /(?:^|;\s*)connect\.sid=([^;]+)/.exec(req.headers.cookie || '');
      ws._viewer = sid ? sid[1] : (req.headers['x-forwarded-for'] || req.socket.remoteAddress || '');
      if (!gameCommentRooms.has(gameId)) gameCommentRooms.set(gameId, new Set());
      gameCommentRooms.get(gameId).add(ws);
      presenceChanged(gameId);
      ws.on('close', () => {
        const room = gameCommentRooms.get(gameId);
        if (room) { room.delete(ws); if (!room.size) gameCommentRooms.delete(gameId); }
        presenceChanged(gameId);
      });
    });
    return;
  }

  // The live score (liveChanged): open to anyone, like the page itself; receive-only.
  const liveMatch = pathname.match(/^\/ws\/games\/([^/]+)\/live$/);
  if (liveMatch) {
    wss.handleUpgrade(req, socket, head, (ws) => {
      const gameId = decodeURIComponent(liveMatch[1]);
      if (!liveRooms.has(gameId)) liveRooms.set(gameId, new Set());
      liveRooms.get(gameId).add(ws);
      ws.on('close', () => {
        const room = liveRooms.get(gameId);
        if (room) { room.delete(ws); if (!room.size) liveRooms.delete(gameId); }
      });
    });
    return;
  }

  const marketplaceCommentsMatch = pathname.match(/^\/ws\/marketplace\/([^/]+)\/comments$/);
  if (marketplaceCommentsMatch) {
    if (getSetting('marketplace_enabled', '0') !== '1') { socket.destroy(); return; }
    wss.handleUpgrade(req, socket, head, (ws) => {
      const listingId = decodeURIComponent(marketplaceCommentsMatch[1]);
      if (!marketplaceCommentRooms.has(listingId)) marketplaceCommentRooms.set(listingId, new Set());
      marketplaceCommentRooms.get(listingId).add(ws);
      ws.on('close', () => {
        const room = marketplaceCommentRooms.get(listingId);
        if (room) { room.delete(ws); if (!room.size) marketplaceCommentRooms.delete(listingId); }
      });
    });
    return;
  }

  const livenessMatch = pathname.match(/^\/ws\/liveness\/([^/]+)$/);
  if (livenessMatch) {
    const token = decodeURIComponent(livenessMatch[1]);
    wss.handleUpgrade(req, socket, head, (ws) => {
      if (!livenessRooms.has(token)) livenessRooms.set(token, new Set());
      livenessRooms.get(token).add(ws);
      ws.on('close', () => {
        const room = livenessRooms.get(token);
        if (room) { room.delete(ws); if (!room.size) livenessRooms.delete(token); }
      });
    });
    return;
  }

  socket.destroy();
});

startMediaWorker();
server.listen(PORT, () => {
  console.log(`WKND Portal → http://localhost:${PORT}`);
  console.log(`DB: portal.db (self-hosted)`);
});
